// Imported symbolic inspiration inputs. See scripts/import-inspiration.py.
(function(root){const data={"schemaVersion":1,"source":"Księga Yagi","sourceTitle":"Czaromarownik","author":"Zofia Rende","interpretation":"astrology","sourceTimeZone":"Europe/Warsaw","sourceFileSha256":"e8051e845ed880e37b4d1404acbcdba1ff79024872a3b6a2240dcd41990e8cae","from":"2026-11-01","to":"2027-12-31","days":[["2026-11-01","creative","☽ w Raku do 05:18, potem we Lwie","III kwadra",false,{"phase":"III kwadra o 21:28","nextPhase":"nów za 8 dni","illumination":55.0,"moonAndBiodynamic":"☽ w Raku do 05:18, potem we Lwie · dzień owocu · ☿ ♀ retro","goodFor":"dobry dzień na twórczość","energy":"Do 05:18 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Wszystkich Świętych","namedays":"Juliana, Łukasza","title":"Światło dla dusz","subtitle":"noc, w której płoną światła","story":"Dziś cmentarze świecą jak niebo odbite w ziemi. Zanim pojawiły się znicze, palono ogniska na rozstajach i przy mogiłach, bo wierzono, że wracające dusze marzną i błądzą w listopadowej mgle. Każdy płomyk to znak: tu jesteś pamiętany, tu trafisz. Ten mały ogień jest starszy niż wszystkie modlitwy, które przy nim szepczemy.","practice":"• Zapal światło dla kogoś, kogo nie możesz odwiedzić.\n• Wypowiedz na głos jego imię.\n• Zanieś na grób coś z ogrodu lub lasu, nie tylko ze sklepu.","extraTitle":"Ciekawostka","extra":"W XIX wieku „zniczem” nazywano święty ogień dawnych pogan. Dopiero później słowo przeszło na lampki stawiane na grobach.","whisper":"Światło zapalone dla zmarłych świeci też żywym.","caution":"","bibliography":"Kalendarz obrzędów ludowych, IZPiTN 2026","bookKey":""},"sourceRow":2}],["2026-11-02","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":44.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu · ☿ ♀ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Skorpionie · ♀ w Wadze · ♂ we Lwie. Pytanie tygodnia: Co jest gotowe do przemiany?","sourceText":{"holiday":"Zaduszki · dziady jesienne","namedays":"Bohdany, Tobiasza","title":"Zaduszki","subtitle":"noc, w której drzwi są uchylone","story":"Dziś nie zamykaj drzwi na głucho. Tej nocy wracają ci, którzy przed tobą chodzili po tej ziemi. Dawniej zostawiano im na stole kaszę, chleb i miód. Nie wylewano wody za próg, żeby nie oblać niewidzialnych gości, i nie przędzono, żeby nie splątać im drogi. Nie bój się ich. Przychodzą sprawdzić, czy pamiętasz.","practice":"• Zapal świecę w oknie.\n• Powiedz na głos imię kogoś, kto odszedł.\n• Opowiedz jedną jego historię, choćby samej sobie.\n• Postaw na stole kromkę chleba i nie sprzątaj jej do rana.","extraTitle":"Zioła tego czasu","extra":"bylica · jałowiec · wrotycz: rośliny, którymi dawniej okadzano izby i strzeżono progów.","whisper":"Ród to rzeka. Ty jesteś tylko jej dzisiejszą wodą.","caution":"","bibliography":"Kalendarz obrzędów ludowych; Śmierć w kulturze ludowej, IZPiTN 2026","bookKey":"Bylica pospolita"},"sourceRow":3}],["2026-11-03","organize","☽ we Lwie do 09:27, potem w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":33.0,"moonAndBiodynamic":"☽ we Lwie do 09:27, potem w Pannie · dzień korzenia · ☿ ♀ retro","goodFor":"dobry dzień na porządki","energy":"Do 09:27 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 01:10 do 09:27: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Huberta, patrona myśliwych","namedays":"Sylwii, Huberta","title":"Pieprz ziołowy dawnych Słowian","subtitle":"przyprawa myśliwych i lasu","story":"W dzień patrona myśliwych sięgnij po to, co znali twoi przodkowie, zanim do Polski dopłynął pieprz. Kminek, kolendra, gorczyca, czosnek, chrzan i jałowiec: zioła z miedzy i ogrodu, zmielone w moździerzu. Każde ziarno pachnie inną porą roku. Razem smakują jak las po deszczu i dym znad ogniska.","practice":"• Upraż 2 łyżki gorczycy, łyżkę kolendry i łyżkę kminku.\n• Zmiel w moździerzu, dodaj łyżkę majeranku i po łyżeczce suszonego czosnku i chrzanu.\n• Przesyp do ciemnego słoika i podpisz datą.","extraTitle":"Ciekawostka","extra":"Klasztory średniowieczne dodały do tej listy rozmaryn i cząber, które przywędrowały z południa.","whisper":"Najlepsze przyprawy rosną tam, gdzie nikt ich nie sadził.","caution":"Gorczyca należy do alergenów oznaczanych na etykietach.","bibliography":"Przyprawy w kuchni ludowej, IZPiTN 2026","bookKey":"Pieprz ziołowy dawnych Słowian"},"sourceRow":4}],["2026-11-04","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":24.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ☿ ♀ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 07:57 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♃ Wenus sekstyl Jowisz (11:31): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.\n☉☌☿ Słońce koniunkcja Merkury (15:24): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"","namedays":"Karola, Olgierda","title":"Kartka ubywającego Księżyca","subtitle":"czas oddawania","story":"Księżyc chudnie z każdą nocą i zabiera ze sobą to, co mu powierzysz. Dawniej przy ubywającym Księżycu odczyniano uroki, wyrywano chwasty i odsyłano choroby. To nie jest czas zaczynania. To czas puszczania z rąk. Pomyśl, co nosisz za długo: urazę, nawyk, cudzą sprawę. Dziś możesz to oddać.","practice":"• Po zachodzie słońca zapal jedną białą świecę.\n• Zapisz na kartce jedną rzecz, którą oddajesz.\n• Powiedz: „Jak Księżyc maleje, tak to ze mnie schodzi”.\n• Podrzyj kartkę i jeszcze dziś wynieś ją z domu.","extraTitle":"Pytanie do dziennika","extra":"Co robię z przyzwyczajenia, a nie z wyboru?","whisper":"Nie wszystko, co niesiesz, jest twoje. Odłóż to, co cudze.","caution":"Świeca na niepalnej podstawce, nigdy bez nadzoru.","bibliography":"Rytuał autorski na motywach wierzeń księżycowych","bookKey":"Rytuał ubywającego Księżyca"},"sourceRow":5}],["2026-11-05","organize","☽ w Pannie, od 15:38 w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":16.0,"moonAndBiodynamic":"☽ w Pannie, od 15:38 w Wadze · dzień korzenia · ☿ ♀ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 15:38 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu do 15:38: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Elżbiety, Sławomira","title":"Nie przędź w czwartek wieczorem","subtitle":"przędza, mara i skórka chleba","story":"W czwartkowy wieczór kołowrotki milkły. Kto przędł po kolacji, mógł zobaczyć, jak nić sama się kręci, bo do pracy przysiadała się mara. Bezpieczna była tylko ta, która trzymała w ustach skórkę chleba, a na koniec kreśliła nad przędzą krzyż. Nocą nie zostawiano niedokończonej roboty. Niedokończone przyciąga tych, którzy chcą skończyć za ciebie.","practice":"• Zrób dziś wieczorem coś ręcznie: zaszyj, zawiąż, zapleć.\n• Zanim zaczniesz, zjedz kawałek chleba w ciszy.\n• Odłóż pracę przed snem, nie zostawiaj jej „na noc”.","extraTitle":"Przysłowie","extra":"„Chcesz mieć kęs płótna dobrego, siej len na świętego Jerzego.”","whisper":"Nie zostawiaj na noc tego, czego nie chcesz, by ktoś za ciebie dokończył.","caution":"","bibliography":"Palenie lnu w medycynie ludowej, IZPiTN 2026","bookKey":"Len, mara i czwartkowe wieczory"},"sourceRow":6}],["2026-11-06","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ☿ ♀ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Feliksa, Leonarda","title":"Przestrzelon","subtitle":"ziele, któremu zazdrościł diabeł","story":"Podnieś liść dziurawca pod światło, a zobaczysz drobne gwiazdki. Mówią, że diabeł przestrzelił je ze złości, bo nie mógł znieść mocy tej rośliny. Roztarte kwiaty barwią palce na czerwono, stąd jego imiona: boża krewka, krew Chrystusa. Zielniki nazywały go ucieczką demonów. Wiszący nad drzwiami pilnował, kto wchodzi.","practice":"• Zawieś suszoną gałązkę dziurawca nad drzwiami.\n• Rozetrzyj kwiat w palcach i zobacz, jak barwi skórę na czerwono.\n• Pomyśl, od czego chcesz dziś chronić swój dom.","extraTitle":"Nazwy ludowe","extra":"przestrzelon, przezorek, krzyżowe ziele, boża krewka, dzwonki Panny Maryi","whisper":"Rośliny, które krwawią, pamiętają więcej niż te, które tylko pachną.","caution":"Dziurawiec osłabia działanie wielu leków (m.in. antykoncepcji) i uwrażliwia skórę na słońce. Do picia tylko po rozmowie z lekarzem.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":"Dziurawiec zwyczajny"},"sourceRow":7}],["2026-11-07","relationships","☽ w Wadze, od 23:39 w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Wadze, od 23:39 w Skorpionie · dzień kwiatu · ☿ ♀ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 23:39 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 14:19 do 23:39: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Antoniego, Żytomira","title":"Ciemne noce przed nowiem","subtitle":"najciemniejsze noce miesiąca","story":"Księżyca prawie nie ma. Noc jest gęsta jak atrament i każde światło widać z daleka. Gospodarze wiedzieli, że w takie dni kopie się korzenie, przycina, kończy rozpoczęte sprawy. Drewno ścięte teraz mniej pęka. Ciemność nie jest przeciwko tobie. Jest czasem, kiedy ziemia odpoczywa, a nasiona w niej czekają na swój znak.","practice":"• Zrób porządek w jednej szafce lub spiżarni.\n• Idź dziś wcześniej spać.\n• Zapisz, co chcesz zacząć po nowiu.","extraTitle":"Fakt czy wiara?","extra":"Fazy Księżyca to astronomia, reguły gospodarskie to wiedza ludowa. Nie wszystkie potwierdzają badania, ale wszystkie każą żyć w rytmie.","whisper":"W ciemności nic nie ginie. Wszystko się tylko przygotowuje.","caution":"","bibliography":"Wierzenia księżycowe; tablice faz Księżyca 2026","bookKey":"Księżyc w kalendarzu ludowym"},"sourceRow":8}],["2026-11-08","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ☿ ♀ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Seweryna, Wiktora","title":"Błędne ogniki","subtitle":"światła, które wołają z bagien","story":"Nad mokradłami tańczą w ciemne noce drżące ogniki. Jedni mówili, że wskazują bezpieczną drogę. Inni, że wiodą na manowce, a to słowo pochodzi od mamić, zwodzić. Jedno światło, dwie drogi. Dopóki nie przejdziesz kawałka, nie wiesz, czy idziesz do domu, czy w głąb bagna. Patrz więc pod nogi, nie tylko w blask.","practice":"• Wyjdź po zmroku na krótki spacer bez latarki w telefonie.\n• Zauważ, za jakim światłem odruchowo idziesz.\n• Wróć do domu i zapal małą lampkę w oknie.","extraTitle":"Pytanie na niedzielę","extra":"Za jakim światłem idę teraz i czy ono prowadzi mnie do domu?","whisper":"Nie każde światło jest latarnią. Niektóre są przynętą.","caution":"","bibliography":"Demony ludowe a przyroda, K. Czepiel, IZPiTN 2026","bookKey":"Błędne ogniki i inne zwodzące duchy"},"sourceRow":9}],["2026-11-09","honesty","☽ w Skorpionie","nów",false,{"phase":"nów o 08:02","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ☿ ♀ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Skorpionie · ♀ w Wadze · ♂ we Lwie. Pytanie tygodnia: Co jest gotowe do przemiany?\n🌑 Nów w Skorpionie (08:02): Czas zasiewu w sprawach: przemiana, wspólne pieniądze, bliskość. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Ursyna, Teodora","title":"Jałowiec","subtitle":"dym, który strzeże","story":"Dziś nów, a jałowiec pachnie jak oczyszczenie. Jego gałązki palono w izbach i oborach, gdy po wsiach chodziło morowe powietrze. Wierzono, że dym jałowca wypędza chorobę i każdą złą moc. Owoce dodawano do kapusty i dziczyzny, bo grzeją od środka. Gdy ciemność jest pełna, dobrze jest przewietrzyć dom i zacząć od czystego powietrza.","practice":"• Rozgnieć kilka owoców jałowca i powąchaj: to zapach starych spiżarni.\n• Przewietrz cały dom na dziesięć minut.\n• Dodaj 3–4 owoce do duszonej kapusty.","extraTitle":"Ciekawostka","extra":"Nie myl jałowca pospolitego z jałowcem sabińskim. Ten drugi jest silnie trujący i w zielnikach miał osobne, ostrzegawcze nazwy.","whisper":"Zanim wpuścisz nowe, wypuść stare przez otwarte okno.","caution":"Owoce jałowca z umiarem; nie w ciąży ani przy chorobach nerek.","bibliography":"Ludowe nazwy ziół; Przyprawy w kuchni ludowej, IZPiTN 2026","bookKey":"Jałowiec pospolity"},"sourceRow":10}],["2026-11-10","travel","☽ w Skorpionie do 09:35, potem w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Skorpionie do 09:35, potem w Strzelcu · dzień owocu · ☿ ♀ retro","goodFor":"dobry dzień na podróże","energy":"Do 09:35 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 00:25 do 09:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀✶♂ Wenus sekstyl Mars (07:47): Dobry dzień na namiętność, randki, taniec i twórczą energię.","sourceText":{"holiday":"","namedays":"Leny, Ludomira","title":"Kiszona marchew","subtitle":"spiżarnia, która żyje","story":"W słoiku z solanką dzieje się cicha magia. Nikt nie gotuje, nikt nie dodaje octu, a warzywa same zmieniają się w coś kwaśnego, żywego i trwałego. Robią to niewidzialni pomocnicy: bakterie, które w dawnej kuchni nazwałoby się po prostu dobrym duchem spiżarni. Wystarczy sól, czas, ciemność i cierpliwość.","practice":"• Pokrój 4–5 marchewek w słupki i ułóż ciasno w słoiku z czosnkiem i koprem.\n• Rozpuść czubatą łyżkę soli niejodowanej w litrze wody i zalej warzywa.\n• Zakręć i odstaw na 5–7 dni w temperaturze pokojowej, potem do chłodu.","extraTitle":"Ciekawostka","extra":"Tak samo ukisisz pietruszkę, seler, kalarepę czy kalafior. Im mniejsze kawałki, tym szybciej zajdzie kiszenie.","whisper":"Najlepsze rzeczy dojrzewają w ciemności, gdy nikt na nie nie patrzy.","caution":"Używaj soli niejodowanej; warzywa muszą być całe pod solanką.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":11}],["2026-11-11","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ☿ ♀ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Narodowe Święto Niepodległości · św. Marcina","namedays":"Marcina, Bartłomieja","title":"Święty Marcin na białym koniu","subtitle":"biały koń i wróżba z gęsiej kości","story":"Na świętego Marcina kończył się rok gospodarski. Pola spały, służba dostawała zapłatę, a w piecach piekły się gęsi. Gdy gęś była zjedzona, oglądano jej mostek pod światło i czytano z niego zimę. Gdy tego dnia spadł śnieg, mówiono, że Marcin przyjechał na białym koniu. Świętuj dziś to, co udało się zebrać.","practice":"• Zjedz dziś coś pieczonego, uroczyście i bez pośpiechu.\n• Zakończ jedną sprawę z tego roku.\n• Pomyśl, czego potrzebujesz na zimę: od siebie i od innych.","extraTitle":"Przysłowie","extra":"„Na świętego Marcina najlepsza gęsina.”","whisper":"Zanim zaczniesz martwić się zimą, policz, co masz w spiżarni.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":12}],["2026-11-12","travel","☽ w Strzelcu, od 21:27 w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Strzelcu, od 21:27 w Koziorożcu · dzień owocu · ☿ ♀ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 21:27 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 12:29 do 21:27: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Renaty, Witolda","title":"Kłobuk","subtitle":"mokry ptak przy piecu","story":"Może kiedyś znajdziesz pod płotem zziębnięte, mokre kurczę. Uważaj. Tak przychodzi kłobuk. Kto go przygarnie i ogrzeje przy piecu, temu kłobuk zacznie znosić do domu ziarno i pieniądze, niekoniecznie własne. Trzeba go jednak karmić i szanować. Obrażony potrafi podpalić dom. Każde bogactwo ma swojego kłobuka i swoją cenę.","practice":"• Postaw dziś przy piecu lub kaloryferze miseczkę z ziarnem.\n• Zastanów się, co w twoim domu wymaga karmienia, a nie tylko „przynosi”.\n• Podziękuj komuś, kto dba o twój dom.","extraTitle":"Ciekawostka","extra":"Kłobuk pojawia się w wierzeniach Mazowsza, Kaszub i Warmii, a jego imię bywa łączone ze słowem „kłobuk”, czyli kaptur.","whisper":"Pytaj nie tylko, co przynosi ci szczęście, ale co za nie płacisz.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":13}],["2026-11-13","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":15.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ☿ ♀ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury rusza naprzód w Skorpionie (16:53): Komunikacja się odblokowuje, choć przez kilka dni sprawy jeszcze się dopinają. Rada: wyślij to, co czekało, ale daj sobie dwa, trzy dni zapasu.","sourceText":{"holiday":"","namedays":"Mikołaja, Stanisława","title":"Zamawianie","subtitle":"słowa, które wiedzą więcej niż ty","story":"Szeptuchy nie leczyły rękami, tylko słowem. Pochylały się nad chorym i szeptały trzy razy, potem dziewięć, przy ubywającym Księżycu, żeby choroba malała razem z nim. Odsyłały ją „na bory, na lasy, na pustą górę”, tam gdzie nie chodzi człowiek. Zamowy przekazywano z ust do ust, jednej osobie. Wypowiedziane byle komu traciły moc.","practice":"• Wybierz jedno zdanie, którego potrzebujesz.\n• Szepnij je trzy razy, wolno, z ręką na sercu.\n• Nie mów nikomu, co to było.","extraTitle":"Ciekawostka","extra":"Zamowy przekazywano ustnie, często tylko jednej osobie. Wierzono, że zapisane albo zdradzone tracą moc.","whisper":"Uważaj, co mówisz do siebie po cichu. Tego słucha się najuważniej.","caution":"Zamawianie to dziedzictwo kulturowe, nie zastępuje leczenia.","bibliography":"Magia słowa; Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":14}],["2026-11-14","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":23.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 19:55 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus rusza naprzód w Wadze (01:27): Koniec przeglądu uczuć i wydatków. Relacje i finanse wracają na zwykły tor. Rada: decyzje o związku i dużych zakupach podejmuj teraz spokojniej.","sourceText":{"holiday":"","namedays":"Rogera, Serafiny","title":"Jarzębina","subtitle":"czerwone korale późnej jesieni","story":"Gdy liście już opadły, jarzębina wciąż płonie na tle szarego nieba. Jej czerwień od wieków uchodziła za kolor ochronny, więc gałązki wieszano przy domach i oborach. Owoce czekają na pierwszy mróz, by stracić gorycz i stać się słodsze. Tak bywa i z ludźmi: niektóre rzeczy dojrzewają dopiero po chłodzie.","practice":"• Nazbieraj kilka gałązek z owocami do wazonu.\n• Nawlecz owoce na nitkę jak korale.\n• Zostaw część owoców ptakom: to ich zimowa spiżarnia.","extraTitle":"Ciekawostka","extra":"Zbyt wiele surowych owoców jarzębiny podrażnia żołądek. Przemrożenie i gotowanie łagodzą ich działanie.","whisper":"Gorycz nie zawsze jest wadą. Czasem to tylko niecierpliwość owocu.","caution":"Owoce jeść tylko po obróbce: zamrożeniu, gotowaniu lub suszeniu.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":15}],["2026-11-15","social","☽ w Koziorożcu do 10:24, potem w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Koziorożcu do 10:24, potem w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 10:24 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu do 10:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Alberta, Leopolda","title":"Mamuny i boginki","subtitle":"te, które czyhają nad wodą","story":"Nad rzekami i stawami mieszkały boginki, mamuny. Stare, brzydkie, cierpliwe. Czyhały na kobiety tuż po porodzie i na niemowlęta, a czasem zamieniały dziecko na własnego odmieńca. Dlatego przy kołyskach wiązano czerwone wstążki, kładziono chleb i sól. Najsłabsi zawsze potrzebowali straży. Pomyśl, kogo dziś ty możesz otoczyć swoją czerwoną nicią.","practice":"• Pomyśl o kimś, kto w twoim życiu potrzebuje ochrony.\n• Zadzwoń albo napisz do niego dziś.\n• Zawiąż czerwoną nitkę na przegubie jako znak troski.","extraTitle":"Pytanie na niedzielę","extra":"Kogo chronię ja i kto chroni mnie?","whisper":"Siła poznaje się po tym, kogo chronisz, a nie kogo pokonasz.","caution":"","bibliography":"Demonologia ludowa a przyroda; Narodziny w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":16}],["2026-11-16","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":40.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Skorpionie · ♀ w Wadze · ♂ we Lwie. Pytanie tygodnia: Co jest gotowe do przemiany?\n♂☌♃ Mars spotyka Jowisza (07:23): Wielki zapał i odwaga. Łatwo zrobić dużo, łatwo też przesadzić. Rada: wykorzystaj energię na sport i ważny projekt. Uwaga: nie obiecuj ponad siły.","sourceText":{"holiday":"","namedays":"Gertrudy, Edmunda","title":"Czosnek","subtitle":"biała tarcza przeciw ciemności","story":"Czosnek był murem przeciw złu. Wieszano go w oknach, wkładano do kołysek, a do trumien tych, którzy mogliby wrócić jako upiory. Jego zapach miał odstraszać czarownice i nocne zjawy. Dziś wiemy więcej: zgnieciony ząbek wytwarza allicynę, która walczy z bakteriami. Stara mądrość i nowa wiedza spotykają się w twojej kuchni.","practice":"• Zgnieć ząbek czosnku i odczekaj 10 minut przed jedzeniem.\n• Zrób miód czosnkowy: posiekane ząbki zalej płynnym miodem.\n• Zawieś warkocz czosnku w kuchni.","extraTitle":"Ciekawostka","extra":"Czosnek był jedną z przypraw już we wczesnym średniowieczu, razem z kminkiem, kolendrą i chrzanem.","whisper":"Co odstrasza upiory, to i przeziębienie wystraszy.","caution":"Duże ilości czosnku mogą nasilać działanie leków przeciwkrzepliwych.","bibliography":"Przyprawy w kuchni ludowej, IZPiTN 2026","bookKey":""},"sourceRow":17}],["2026-11-17","social","☽ w Wodniku, od 22:19 w Rybach","I kwadra",false,{"phase":"I kwadra o 12:47","nextPhase":"pełnia za 7 dni","illumination":50.0,"moonAndBiodynamic":"☽ w Wodniku, od 22:19 w Rybach · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 22:19 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 15:25 do 22:19: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Grzegorza, Salomei","title":"Oksymel tymiankowy","subtitle":"miód i ocet, słodycz i ostrość","story":"Starzy zielarze wiedzieli, że lekarstwo potrzebuje dwóch dusz: ostrej i słodkiej. Ocet otwiera roślinę i wyciąga z niej moc, miód ją łagodzi i przechowuje. Tak powstaje oksymel, jedno z najstarszych połączeń w ziołolecznictwie. Z tymiankiem staje się zimowym towarzyszem gardła. Słodycz bez ostrości mdli, ostrość bez słodyczy rani.","practice":"• Garść tymianku zalej w słoiku szklanką octu jabłkowego.\n• Dodaj 3 szklanki płynnego miodu i dokładnie wymieszaj.\n• Odstaw na 2 tygodnie, codziennie potrząsając, potem przecedź.","extraTitle":"Jak stosować","extra":"łyżeczka rozpuszczona w ciepłej (nie gorącej) wodzie","whisper":"Mów prawdę jak oksymel: ostro, ale z miodem.","caution":"Miód nie dla dzieci poniżej 1. roku życia. Kwas szkodzi szkliwu, więc po wypiciu przepłucz usta wodą.","bibliography":"Miody, żywe octy, oleje, oksymele, IZPiTN 2026","bookKey":""},"sourceRow":18}],["2026-11-18","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉□♃ Słońce kwadratura Jowisz (10:38): Napięcie między planetami. Można je wykorzystać na optymizm, prośby, oferty, naukę i podróże. Uważaj na przesadę i obietnice ponad siły.","sourceText":{"holiday":"","namedays":"Romana, Klaudyny","title":"Próg domu","subtitle":"granica między światami","story":"Próg to coś więcej niż deska pod drzwiami. Tu kończy się świat obcy, a zaczyna twój. Pod progiem zakopywano ochronne przedmioty, przez próg nie podawano sobie rąk, a po zmroku nie wymiatano śmieci za drzwi, bo razem z nimi wymiatało się szczęście. Pannę młodą przenoszono przez próg, by nic złego nie weszło z nią.","practice":"• Umyj dziś próg i wycieraczkę.\n• Zamiataj od drzwi do środka domu.\n• Zanim wejdziesz, zatrzymaj się na sekundę i odetchnij.","extraTitle":"Pytanie do dziennika","extra":"Co wnoszę do domu wraz ze sobą każdego dnia?","whisper":"Pilnuj progu, a dom sam się upilnuje.","caution":"","bibliography":"Wierzenia ludowe o domu i progu","bookKey":"Próg domu"},"sourceRow":19}],["2026-11-19","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":71.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉□♂ Słońce kwadratura Mars (18:49): Napięcie między planetami. Można je wykorzystać na odważne decyzje, sport i ruszanie spraw z miejsca. Uważaj na złość, rywalizację i przeforsowanie się.","sourceText":{"holiday":"","namedays":"Elżbiety, Seweryna","title":"Powiedz pszczołom","subtitle":"rodzina, która brzęczy","story":"Pszczoły były w domu jak krewni. Gdy umierał gospodarz, ktoś szedł cicho do uli i im to oznajmiał, czasem przewiązywał je czarną wstążką. Pszczoły nieuprzedzone mogły odlecieć albo zmarnieć. Z ich wosku robiono gromnice, święte świece zapalane w burzę i przy umierających. Słodycz i światło: dwa dary od małych sióstr.","practice":"• Zjedz dziś łyżkę dobrego miodu bardzo powoli.\n• Pomyśl o zwierzętach, które dzielą z tobą dom.\n• Opowiedz im, co się dziś wydarzyło.","extraTitle":"Ciekawostka","extra":"Z wosku pszczelego robiono gromnice, najważniejsze świece domu, palone w czasie burzy i przy umierających.","whisper":"Mów do tych, z którymi dzielisz dom. Nawet jeśli odpowiadają bzyczeniem.","caution":"","bibliography":"Wierzenia ludowe związane z pszczelarstwem","bookKey":""},"sourceRow":20}],["2026-11-20","start","☽ w Rybach do 06:52, potem w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":80.0,"moonAndBiodynamic":"☽ w Rybach do 06:52, potem w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Do 06:52 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Anatola, Sędzimira","title":"Chleb i sól","subtitle":"najprostsza magia domu","story":"Nie potrzebujesz złotych amuletów. Chleb i sól witały gości, nowożeńców i każdy nowy dom. Sól sypano na próg i wkładano do kołyski. Kromkę chleba niesiono w kieszeni w daleką drogę. Upuszczony chleb podnoszono i całowano. To najprostsze dary, a jednak najsilniejsze, bo mówią: tu nikt nie będzie głodny.","practice":"• Upiecz albo kup dobry chleb na zakwasie.\n• Postaw na stole solniczkę i kromkę chleba dla domowników.\n• Podziel się chlebem z sąsiadem.","extraTitle":"Przysłowie","extra":"„Gość w dom, Bóg w dom.”","whisper":"Gdzie jest chleb i sól, tam bieda nie ma krzesła.","caution":"","bibliography":"Magia chleba i pieczywa obrzędowego, IZPiTN 2026","bookKey":""},"sourceRow":21}],["2026-11-21","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":88.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Janusza, Konrada","title":"Władcy wiatrów","subtitle":"imiona wichury","story":"Posłuchaj, jak wieje. Dawni Słowianie znali wiatry po imieniu. Poświst przynosił łagodny powiew, Świstun gwałtowne podmuchy, a groźny Pochwiściel umiał rozpędzić gradowe chmury albo zerwać dach z chaty. Chmury prowadzili płanetnicy, dusze tych, którzy zmarli nagle. Gospodarze składali im dary, prosząc, by grad ominął pola.","practice":"• Wyjdź na wiatr i posłuchaj go przez dwie minuty.\n• Zastanów się, który z wiatrów wieje dziś w tobie.\n• Zabezpiecz w ogrodzie lub na balkonie to, co może porwać wichura.","extraTitle":"Ciekawostka","extra":"Płanetnicy wyglądali jak zwykli ludzie. Wierzono, że mogą nimi zostać dusze zmarłych nagłą śmiercią.","whisper":"Wiatru nie zatrzymasz. Możesz tylko dobrze zawiązać chustę.","caution":"","bibliography":"Demony ludowe a przyroda, K. Czepiel, IZPiTN 2026","bookKey":""},"sourceRow":22}],["2026-11-22","finances","☽ w Baranie do 11:09, potem w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":94.0,"moonAndBiodynamic":"☽ w Baranie do 11:09, potem w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Do 11:09 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 08:38 do 11:09: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉ Słońce wchodzi w Strzelca (08:23): Na miesiąc cały świat nabiera barw znaku Strzelca: czas podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się.","sourceText":{"holiday":"","namedays":"Marka, Cecylii","title":"Wieczornice","subtitle":"wieczory pełne pierza i opowieści","story":"Gdy wieczory robiły się długie, kobiety schodziły się do jednej chaty. Darły pierze, przędły, śpiewały, opowiadały o strachach i swatały młodych. Puch unosił się w świetle łuczywa jak śnieg, który nie chciał spaść. Praca szła szybciej, a zima była mniej samotna. Najwięcej mądrości przekazywano właśnie wtedy, między jedną piosenką a drugą.","practice":"• Zaproś kogoś na wspólne gotowanie lub robótki.\n• Opowiedzcie sobie po jednej rodzinnej historii.\n• Wyłączcie telewizor na cały wieczór.","extraTitle":"Pytanie na niedzielę","extra":"Z kim chcę spędzać długie wieczory tej zimy?","whisper":"Smutek dzielony na kilka rąk waży mniej niż piórko.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":23}],["2026-11-23","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":98.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Skorpionie · ♀ w Wadze · ♂ we Lwie. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?","sourceText":{"holiday":"","namedays":"Adeli, Klemensa","title":"Głóg","subtitle":"krzew, który pilnuje serca","story":"Głóg rośnie na miedzach, kolczasty i cierpliwy. Jego czerwone owoce wiszą na gałęziach długo po tym, jak inne krzewy zrzuciły wszystko. Od wieków był ziołem serca: na kołatanie, niepokój i bezsenne noce. Kolce głogu strzegły obejść jak żywy płot. Może żyć kilkaset lat. Wie coś o wytrwałości.","practice":"• Zaparz łyżkę suszonych owoców głogu w szklance wody na 15 minut.\n• Wypij powoli, z ręką na sercu.\n• Wypisz trzy rzeczy, które dziś cię uspokoiły.","extraTitle":"Ciekawostka","extra":"Głóg potrafi żyć kilkaset lat. W Europie rosną krzewy starsze niż wiele kościołów.","whisper":"Serce, które ma kolce, nie zawsze jest złe. Czasem po prostu się broni.","caution":"Przy lekach nasercowych lub na ciśnienie głóg tylko po konsultacji z lekarzem.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":"Głóg"},"sourceRow":24}],["2026-11-24","finances","☽ w Byku, od 12:09 w Bliźniętach","pełnia",true,{"phase":"pełnia o 15:53","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Byku, od 12:09 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 12:09 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 11:09 do 12:09: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉△♆ Słońce trygon Neptun (01:07): Dobry dzień na intuicję, sztukę, medytację i pomoc innym.\n🌕 Pełnia w Bliźniętach (15:53): Kulminacja w sprawach: rozmowy, nauka, rodzeństwo i sąsiedzi. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Flory, Emmy","title":"Syrop z dzikiej róży","subtitle":"pełnia i owoce mrozu","story":"Dziś superpełnia: Księżyc jest blisko Ziemi, wielki i jasny nad nagimi drzewami. Na krzakach dzikiej róży czekają owoce, które po przymrozku zmiękły i osłodziły się. Mają w sobie wielokrotnie więcej witaminy C niż cytryna. Zbieraj je, gotuj, przecedzaj. W ich czerwieni jest zapas lata na najciemniejsze miesiące.","practice":"• Przekrój owoce, wydrąż pestki i włoski.\n• Zalej wodą, gotuj 10 minut, przecedź przez gazę.\n• Wymieszaj z miodem lub cukrem 1:1 i przelej do butelek.","extraTitle":"Ciekawostka","extra":"Włoski z wnętrza owoców dzikiej róży drażnią skórę. Dzieci dawniej używały ich jako „proszku do swędzenia”.","whisper":"Kto w listopadzie zbiera czerwień, ten w lutym ma słońce w butelce.","caution":"Dokładnie przecedź syrop przez gazę, żeby usunąć włoski.","bibliography":"Zdrowe słodycze – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":25}],["2026-11-25","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉✶♇ Słońce sekstyl Pluton (18:27): Dobry dzień na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna.\n☉☍♅ Słońce naprzeciw Urana (23:41): Inni zaskakują. Plany mogą się nagle zmienić. Uwaga: zostaw sobie margines czasu.","sourceText":{"holiday":"św. Katarzyny · wróżby kawalerów","namedays":"Katarzyny, Erazma","title":"Katarzynki","subtitle":"noc, w której śnią kawalerowie","story":"Przed świętą Katarzyną wróżyli chłopcy. Pod poduszkę kładli kawałek damskiej garderoby i czekali, aż we śnie pokaże się twarz przyszłej żony. Wypisywali imiona dziewcząt na karteczkach i rano losowali jedną. Wróżby mówią mniej o przyszłości, a więcej o tym, za czym tęskni serce, gdy nikt nie patrzy.","practice":"• Zapisz na karteczce, czego szukasz w relacjach: cech, nie imion.\n• Połóż ją pod poduszką.\n• Rano przeczytaj i sprawdź, co się zmieniło.","extraTitle":"Przysłowie","extra":"„Święta Katarzyna adwent zaczyna.”","whisper":"Sen pokazuje nie to, co będzie, ale to, czego szukasz.","caution":"","bibliography":"Kalendarz obrzędów ludowych, IZPiTN 2026","bookKey":""},"sourceRow":26}],["2026-11-26","home","☽ w Bliźniętach do 11:51, potem w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":95.0,"moonAndBiodynamic":"☽ w Bliźniętach do 11:51, potem w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Do 11:51 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 06:23 do 11:51: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♂ Mars wchodzi w Pannę (00:37): Na kilka tygodni energia i działanie płyną w rytmie porządku, zdrowia, codziennej pracy i szczegółu. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów. Uważaj na krytykanctwo i przemęczenie.","sourceText":{"holiday":"","namedays":"Delfiny, Sylwestra","title":"Kot w izbie","subtitle":"stróż progu między światami","story":"Kot widzi to, czego ty nie widzisz. Tak wierzono. Patrzy w pusty kąt i nagle jeży sierść, śpi tam, gdzie ziemia oddaje dziwne ciepło. Mówiono, że czarownica potrafi w niego się wcielić. W czasie burzy wynoszono go z izby, bo piorun go szukał. Kot myjący się łapą zapowiadał gości. Śpiący na piecu przepowiadał mróz.","practice":"• Popatrz dziś na kota, swojego albo cudzego, dłużej niż zwykle.\n• Zauważ, gdzie lubi siedzieć w twoim domu.\n• Odpocznij tak jak on, bez wyrzutów sumienia.","extraTitle":"Na wesoło","extra":"Kot z naszego kociołka zna wszystkie te przesądy i nic sobie z nich nie robi. Zwłaszcza z tego o burzy.","whisper":"Kto umie odpoczywać jak kot, ten zawsze spada na cztery łapy.","caution":"","bibliography":"Wierzenia ludowe o zwierzętach domowych","bookKey":""},"sourceRow":27}],["2026-11-27","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":89.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Waleriana, Wilgiusza","title":"Magia węzła","subtitle":"czerwona nić","story":"Węzeł zatrzymuje. Dlatego zawiązywano supły na chorobę i na urok. Przy porodzie w całym domu rozplatano warkocze i otwierano zamki, żeby nic nie wiązało rodzącej. Czerwona wstążka przy kołysce i nitka na przegubie dziecka do dziś mają strzec przed złym okiem. Najstarsza magia mieści się w kawałku sznurka.","practice":"• Weź czerwoną nitkę i zawiąż na niej trzy supły.\n• Przy każdym pomyśl, co chcesz zatrzymać przy sobie.\n• Noś ją przy sobie do pełni lub zawieś przy łóżku.","extraTitle":"Ciekawostka","extra":"Przy rozpoczęciu porodu rozplatano kobiecie warkocz i otwierano zamki w domu, by nic jej nie „wiązało”.","whisper":"Wiąż tylko to, co chcesz zatrzymać. Resztę rozwiąż.","caution":"","bibliography":"Narodziny w kulturze ludowej; Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":28}],["2026-11-28","home","☽ w Raku, od 12:20 we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":81.0,"moonAndBiodynamic":"☽ w Raku, od 12:20 we Lwie · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 12:20 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 06:40 do 12:20: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀✶♃ Wenus sekstyl Jowisz (13:05): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.","sourceText":{"holiday":"","namedays":"Lesława, Zdzisława","title":"Lipa","subtitle":"drzewo, w które nie bije piorun","story":"Lipa była drzewem świętym. Pod nią radzono, na niej wieszano kapliczki, a wokół niej budowano domy, bo wierzono, że piorun lipy nie tknie. Latem jej kwiaty brzęczą od pszczół, a zimą, zaparzone, przynoszą sen i ulgę w przeziębieniu. Z jej łyka plecono łapcie. Lipa daje wszystko, o nic nie prosząc.","practice":"• Zaparz herbatę z suszonego kwiatu lipy.\n• Przytul dziś jakieś stare drzewo, jeśli możesz.\n• Dowiedz się, jakie drzewo rośnie najbliżej twojego domu.","extraTitle":"Ciekawostka","extra":"Z łyka lipowego plecono łapcie, czyli tanie obuwie wiejskie, a z drewna lipy rzeźbiono święte figurki.","whisper":"Bądź jak lipa: dawaj cień, nie licząc, kto pod nim stoi.","caution":"","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":29}],["2026-11-29","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":71.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♅△♇ Uran w harmonii z Plutonem (12:25): Pokoleniowy układ sprzyjający przełomom i odnowie, zwłaszcza w technologii i społeczeństwie. Rada: nie bój się zmiany, która od dawna dojrzewa.","sourceText":{"holiday":"andrzejki · wigilia św. Andrzeja · I niedziela Adwentu","namedays":"Błażeja, Saturnina","title":"Andrzejki","subtitle":"wosk, cień i obierka jabłka","story":"W wigilię świętego Andrzeja dziewczęta leją gorący wosk przez ucho klucza do zimnej wody. Z figury i jej cienia na ścianie czytają przyszłość. Ustawiają buty od ściany do progu: która pierwsza dotknie drzwi, ta pierwsza wyjdzie z domu za mąż. Obierka jabłka rzucona za siebie układa się w literę imienia.","practice":"• Przelej wosk ze świecy przez klucz do miski z wodą.\n• Obejrzyj figurę w świetle, a potem jej cień na ścianie.\n• Zapisz, co zobaczyłaś, bez interpretowania na siłę.","extraTitle":"Przysłowie","extra":"„Na świętego Andrzeja dziewkom z wróżby nadzieja.”","whisper":"Wosk pokazuje kształt. Znaczenie nadajesz mu sama.","caution":"Gorący wosk lej powoli i nad miską, z dala od dzieci.","bibliography":"Kalendarz obrzędów ludowych, IZPiTN 2026","bookKey":"Andrzejki"},"sourceRow":30}],["2026-11-30","creative","☽ we Lwie, od 15:12 w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":59.0,"moonAndBiodynamic":"☽ we Lwie, od 15:12 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 15:12 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 11:10 do 15:12: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Skorpionie · ♀ w Wadze · ♂ w Pannie. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☉△♄ Słońce trygon Saturn (07:05): Dobry dzień na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach.","sourceText":{"holiday":"św. Andrzeja","namedays":"Maury, Andrzeja","title":"Lubczyk","subtitle":"ziele, które sprawia, że cię kochają","story":"Lubczyk ma w imieniu swoje zadanie. Dziewczęta kąpały się w jego naparze, wplatały liście w warkocze i wianki, żeby być lubianymi i kochanymi. Gospodynie znały go lepiej jako zioło do rosołu, o smaku przypominającym seler. Może to jest jego największy sekret: miłość też zaczyna się od dobrej zupy.","practice":"• Dodaj suszony lubczyk do zupy.\n• Wsyp garść do woreczka i zawieś pod kranem przy kąpieli.\n• Powiedz dziś komuś, za co go lubisz.","extraTitle":"Ciekawostka","extra":"Lubczyk przywędrował do Europy Środkowej z południa, ale tak zadomowił się w polskich ogrodach, że uważano go za swojski.","whisper":"Kto dobrze karmi, ten długo jest kochany.","caution":"Nie w ciąży i przy chorobach nerek.","bibliography":"Afrodyzjaki ludowe, IZPiTN 2026","bookKey":""},"sourceRow":31}],["2026-12-01","organize","☽ w Pannie","III kwadra",false,{"phase":"III kwadra o 07:08","nextPhase":"nów za 8 dni","illumination":48.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Natalii, Eligiusza","title":"Piernik dojrzewający","subtitle":"ciasto, które czeka do Wigilii","story":"Dzisiaj zaczyna się powolna magia. Ciasto z miodem, mąką i korzennymi przyprawami odstawia się w chłodne miejsce i zostawia w spokoju na długie tygodnie. W ciemności dojrzewa, ciemnieje i nabiera głębi. Staropolski piernik był darem, lekarstwem na trawienie i dowodem cierpliwości gospodyni. Niektóre rzeczy trzeba zacząć wcześnie, żeby były gotowe na czas.","practice":"• Podgrzej 0,5 kg miodu z 200 g masła i 250 g cukru, ostudź.\n• Wmieszaj 1 kg mąki, 3 jajka, przyprawę korzenną i łyżeczkę sody.\n• Przełóż do kamionki, przykryj płótnem i odstaw w chłodne miejsce do połowy grudnia.","extraTitle":"Przyprawa korzenna","extra":"cynamon, goździki, imbir, kardamon, gałka muszkatołowa, ziele angielskie","whisper":"Co dojrzewa w ciszy, to w święta smakuje najlepiej.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska (hasło: piernik)","bookKey":""},"sourceRow":32}],["2026-12-02","organize","☽ w Pannie, od 21:03 w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":38.0,"moonAndBiodynamic":"☽ w Pannie, od 21:03 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 21:03 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 10:10 do 21:03: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Balbiny, Bibianny","title":"Światło w Adwencie","subtitle":"czas czuwania","story":"Adwent to czekanie w półmroku. Dawniej przed świtem szło się z lampionem na roraty, a długie wieczory spędzano przy skąpym świetle łuczywa. Wieniec z czterema świecami to zwyczaj młodszy, przyszedł z Niemiec w XIX wieku. Starsza jest sama myśl: z każdym tygodniem przybywa jednego płomienia, aż ciemność ustąpi.","practice":"• Ustaw w domu jedną świecę na każdy tydzień Adwentu.\n• Zapalaj je o zmroku, po kolei.\n• Przez 10 minut nie rób nic, tylko patrz w płomień.","extraTitle":"Ciekawostka","extra":"Roraty to msze o świcie. Nazwa pochodzi od łacińskich słów pieśni „Rorate caeli”, czyli „Spuśćcie rosę, niebiosa”.","whisper":"Nie musisz rozproszyć całej ciemności. Wystarczy jedna świeca na raz.","caution":"Świece na niepalnej podstawce, z dala od firanek.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":33}],["2026-12-03","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":28.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Franciszka, Ksawerego","title":"Adwentowa cisza","subtitle":"gdy cichną skrzypce","story":"W Adwencie milkły wesela, tańce i muzyka. Grajkowie chowali skrzypce, a domy wypełniała praca rąk: przędzenie, darcie pierza, naprawianie sieci. Wierzono, że zbyt wiele hałasu w tym czasie ściąga nieproszonych gości z innego świata. Cisza nie była pustką. Była przestrzenią, w której można usłyszeć to, czego za dnia nie słychać.","practice":"• Spędź dziś godzinę bez muzyki w tle i bez telefonu.\n• Zrób w tym czasie coś rękami.\n• Zauważ, co słyszysz, gdy jest cicho.","extraTitle":"Pytanie do dziennika","extra":"Czego nie słyszę, bo w moim życiu jest za głośno?","whisper":"W ciszy najlepiej słychać to, czego się boisz, i to, czego pragniesz.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":34}],["2026-12-04","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿□♃ Merkury kwadratura Jowisz (08:02): Napięcie między planetami. Można je wykorzystać na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości. Uważaj na obietnice bez pokrycia i przeoczone szczegóły.\n♀ Wenus wchodzi w Skorpiona (09:12): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej. Uważaj na zazdrość i podejrzliwość.\n♂□♅ Mars w napięciu z Uranem (20:28): Nerwowość, nagłe zrywy, ryzyko wypadków i kłótni. Uwaga: zwolnij przy maszynach i na drodze, nie decyduj w złości.","sourceText":{"holiday":"Barbórka · św. Barbary","namedays":"Barbary, Krystiana","title":"Gałązki na Barbórkę","subtitle":"kwiat w środku zimy","story":"W dzień świętej Barbary ścina się gałązkę wiśni i wstawia do wody w ciepłym kącie izby. Potem się czeka. Jeśli zakwitnie na Wigilię, rok będzie szczęśliwy, a panna wkrótce wyjdzie za mąż. Białe kwiaty w środku grudnia to mały cud, który można wyhodować samemu. Wystarczy woda, ciepło i wiara.","practice":"• Zetnij kilka gałązek wiśni, jabłoni lub forsycji.\n• Wstaw je do wody w ciepłym pokoju i zmieniaj wodę co kilka dni.\n• Zapisz życzenie, na które czekają razem z tobą.","extraTitle":"Przysłowie","extra":"„Barbara po lodzie, Boże Narodzenie po wodzie.”","whisper":"Wiosnę można zaprosić do domu, nawet gdy za oknem śnieg.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":"Gałązki świętej Barbary"},"sourceRow":35}],["2026-12-05","honesty","☽ w Wadze do 05:35, potem w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Wadze do 05:35, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 05:35 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Saby, Kryspina","title":"Jemioła","subtitle":"zieleń pomiędzy niebem a ziemią","story":"Jemioła rośnie wysoko, nie dotykając ziemi, i zostaje zielona, gdy całe drzewo śpi. Dla dawnych ludów była rośliną spomiędzy światów. Pocałunek pod jemiołą przyszedł do Polski z Zachodu, ale przyjął się, bo każda kultura potrzebuje miejsca na pojednanie. Gałązka nad drzwiami prosi: wchodź z dobrym sercem.","practice":"• Zawieś gałązkę jemioły pod sufitem lub nad drzwiami.\n• Pocałuj kogoś bliskiego pod jemiołą.\n• Pomyśl, z kim chcesz się dziś pogodzić.","extraTitle":"Ciekawostka","extra":"Jemioła to półpasożyt: sama wytwarza zielony barwnik, ale wodę i sole mineralne pobiera z drzewa, na którym rośnie.","whisper":"Pod jemiołą nie ma wrogów. Jest tylko ten, kto pierwszy podejdzie.","caution":"Owoce jemioły są trujące. Trzymaj ją z dala od dzieci i zwierząt.","bibliography":"Rośliny niebezpieczne w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":36}],["2026-12-06","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":7.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury wchodzi w Strzelca (09:33): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się. Uważaj na przesadę i obietnice bez pokrycia.","sourceText":{"holiday":"Mikołajki","namedays":"Mikołaja, Jaremy","title":"Mikołajki","subtitle":"dar, który przychodzi nocą","story":"Mikołaj z Miry obdarowywał po cichu, tak by nikt nie wiedział, skąd przyszła pomoc. W dawnej Polsce dzieci budziły się tego ranka przy jabłkach, orzechach i piernikach, a rózga przypominała, że rok miał swoje rachunki. Najpiękniejsze dary nie mają podpisu. Zostawiają tylko ciepło i pytanie: kto mnie tak dobrze zna?","practice":"• Zostaw komuś anonimowy drobiazg.\n• Daj dzieciom (albo sobie) jabłko i garść orzechów.\n• Przypomnij sobie najmilszy prezent z dzieciństwa.","extraTitle":"Pytanie na niedzielę","extra":"Komu mogę dać coś, nie oczekując podziękowania?","whisper":"Dar bez podpisu wraca do dającego dwa razy.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":37}],["2026-12-07","honesty","☽ w Skorpionie, od 16:06 w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Skorpionie, od 16:06 w Strzelcu · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 16:06 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 10:07 do 16:06: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Skorpionie · ♂ w Pannie. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☿△♆ Merkury trygon Neptun (11:15): Dobry dzień na pisanie, poezję, muzykę i rozmowy o duchowości.","sourceText":{"holiday":"","namedays":"Marcina, Ambrozego","title":"Kozłek lekarski","subtitle":"ziele, które usypia niepokój","story":"Kozłek, ludowo odolan, ma korzeń, którego zapach ludzie znoszą z trudem, a koty kochają do szaleństwa. W wierzeniach odpędzał złe moce. W ziołolecznictwie od wieków służył tym, których noc nie chciała przyjąć. Grudniowe noce są długie. Pozwól im być dla ciebie łaskawe: ciepły napar, cisza, ciemność i sen.","practice":"• Wieczorem wypij napar z kozłka lub melisy.\n• Wyłącz ekrany godzinę przed snem.\n• Zapisz, co dziś chcesz zostawić za drzwiami sypialni.","extraTitle":"Ciekawostka","extra":"Koty reagują na kozłek podobnie jak na kocimiętkę. To sprawka związków zapachowych w korzeniu.","whisper":"Sen to najstarsze lekarstwo. Nikt nie musi ci go przepisywać.","caution":"Może nasilać senność. Nie łącz z alkoholem ani lekami nasennymi; nie prowadź po nim auta.","bibliography":"Ziołolecznictwo ludowe","bookKey":""},"sourceRow":38}],["2026-12-08","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":0.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿☍♅ Merkury opozycja Uran (11:29): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.\n☿✶♇ Merkury sekstyl Pluton (20:31): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy.","sourceText":{"holiday":"","namedays":"Marii, Światozara","title":"Kompot z suszu","subtitle":"wigilijny napój spiżarni","story":"Kompot z suszu pachnie dymem i latem zamkniętym w owocach. Wędzone śliwki, suszone gruszki i jabłka gotowane z goździkiem stawały na wigilijnym stole, żeby żołądek poradził sobie z obfitą kolacją. Kup susz już dziś i daj mu poleżeć w spiżarni. W grudniu wszystko, co dobre, potrzebuje trochę czasu.","practice":"• Namocz garść wędzonych śliwek, suszonych gruszek i jabłek na noc.\n• Gotuj w 2 litrach wody 30 minut z goździkiem i laską cynamonu.\n• Dosłodź miodem dopiero, gdy przestygnie.","extraTitle":"Ciekawostka","extra":"Wędzone śliwki, czyli węgierki suszone w dymie, to specjalność m.in. Doliny Wisły i Małopolski.","whisper":"Lato nie znika. Chowa się w suszonych owocach i czeka na zimę.","caution":"","bibliography":"Zdrowe słodycze – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":39}],["2026-12-09","travel","☽ w Strzelcu","nów",false,{"phase":"nów o 01:52","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 22:06 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🌑 Nów w Strzelcu (01:51): Czas zasiewu w sprawach: sens, podróże, nauka. Rada: zapisz intencję na ten księżycowy miesiąc.\n☿□♂ Merkury kwadratura Mars (14:40): Napięcie między planetami. Można je wykorzystać na szybkie decyzje, debatę i załatwienie zaległości. Uważaj na kłótnie, ostre słowa i pośpiech w mailach.\n♀□♇ Wenus kwadratura Pluton (19:37): Napięcie między planetami. Można je wykorzystać na głębokie uczucia, intymność i odnowę w relacjach. Uważaj na zazdrość i zaborczość.","sourceText":{"holiday":"","namedays":"Wiesława, Leokadii","title":"Nów przed zimą","subtitle":"ziarno zasiane w ciemności","story":"Dziś w nocy nów, ostatni przed przesileniem. Księżyc zniknął zupełnie, a dzień skurczył się prawie do najkrótszego. To pora ziaren, które leżą w zamarzniętej ziemi i niczego nie udowadniają. Po prostu czekają. Zasiej dziś jedną intencję na zimę: cicho, bez rozgłosu, i pozwól jej spokojnie leżeć w ciemności.","practice":"• Zapisz jedną intencję na zimę, jednym zdaniem.\n• Włóż kartkę do koperty z kilkoma ziarnami zboża lub nasion.\n• Otwórz kopertę w pełnię 24 grudnia.","extraTitle":"Księżyc","extra":"nów 9 XII 2026, 01:52 · następna pełnia 24 XII, 02:28","whisper":"Nasienie nie pyta, kiedy przyjdzie wiosna. Wie, że przyjdzie.","caution":"","bibliography":"Tablice faz Księżyca 2026","bookKey":""},"sourceRow":40}],["2026-12-10","work","☽ w Strzelcu do 04:08, potem w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Strzelcu do 04:08, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 04:08 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 20:12 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Julii, Danieli","title":"Mak na upiory","subtitle":"ziarenka do policzenia","story":"Upiór nie przejdzie obok rozsypanego maku, dopóki nie policzy wszystkich ziarenek. Tak wierzono, więc mak sypano na progu, wokół domu i do trumny tego, kto mógł nie zaznać spokoju. Zanim upiór skończył liczyć, przychodził świt i musiał wracać do grobu. Mak trafia też do wigilijnych potraw. Zawsze stał na straży snu.","practice":"• Kup mak na święta i zatrzymaj garść na próg.\n• Spróbuj policzyć ziarenka w łyżeczce i zobacz, ile to trwa.\n• Pomyśl, co zajmuje twoje myśli tak długo jak liczenie maku.","extraTitle":"Ciekawostka","extra":"W wierzeniach upiory i strzygi miały dwie dusze. Jedna odchodziła po śmierci, druga zostawała.","whisper":"Nie każdy, kto puka w nocy, ma cierpliwość, by liczyć mak.","caution":"","bibliography":"Śmierć w kulturze i medycynie ludowej, IZPiTN 2026","bookKey":"Mak"},"sourceRow":41}],["2026-12-11","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♄ Saturn rusza naprzód w Baranie (00:31): Struktury się stabilizują. To, co było w zawieszeniu, zaczyna mieć ramy. Rada: zapisz plan na najbliższe miesiące i trzymaj się go.\n☿△♄ Merkury trygon Saturn (14:25): Dobry dzień na skupioną pracę, umowy, planowanie i dokumenty.","sourceText":{"holiday":"","namedays":"Damazego, Waldemara","title":"Ognia się nie pożycza","subtitle":"ogień, którego się nie oddaje","story":"Ogień w piecu był sercem domu. Nie pożyczano go sąsiadom, zwłaszcza przed świętami, bo razem z żarem mogło wyjść szczęście. Do pieca nie pluto, a wieczorem gospodyni starannie zagrzebywała żar w popiele, by przetrwał do rana. Przy przeprowadzce zabierano żar ze starego domu, żeby w nowym nie wygasł ród.","practice":"• Zapal dziś świecę i pozwól jej spokojnie się dopalić przy tobie.\n• Wyczyść kominek, piekarnik albo kuchenkę.\n• Podziękuj w myślach za ciepło w domu.","extraTitle":"Ciekawostka","extra":"Przy przeprowadzce przenoszono do nowego domu żar ze starego pieca, by ciągłość rodu nie wygasła.","whisper":"Niektórych rzeczy się nie pożycza. Ciepła domu też nie.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":42}],["2026-12-12","work","☽ w Koziorożcu, od 17:05 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":10.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 17:05 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 17:05 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu do 17:05: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♂ Wenus sekstyl Mars (10:14): Dobry dzień na namiętność, randki, taniec i twórczą energię.\n♆ Neptun rusza naprzód w Baranie (23:17): Wraca natchnienie, intuicja i tęsknota za czymś większym. Rada: twórz, módl się, odpoczywaj nad wodą.","sourceText":{"holiday":"","namedays":"Dagmary, Aleksandry","title":"Jodła i świerk","subtitle":"drzewo, które wisi czubkiem w dół","story":"Zanim w polskich domach stanęła choinka, pod sufitem wisiała podłaźniczka: wierzchołek jodły, zawieszony czubkiem w dół, przystrojony jabłkami, orzechami i opłatkowymi gwiazdkami. Zielona gałąź w środku zimy obiecywała, że życie nie umarło, tylko śpi. Choinka przyszła z Niemiec dopiero w XIX wieku. Podłaźniczka jest starsza i bardziej nasza.","practice":"• Przynieś do domu kilka gałązek jodły lub świerka.\n• Zawieś jedną nad stołem.\n• Udekoruj ją jabłkiem i orzechem.","extraTitle":"Ciekawostka","extra":"Podłaźniczka przetrwała najdłużej w Małopolsce i na Podhalu. Dziś wraca jako modna, naturalna dekoracja.","whisper":"Zieleń zimą to obietnica, nie ozdoba.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":43}],["2026-12-13","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":17.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♃ Jowisz rusza wstecz we Lwie (01:56): Na cztery miesiące rozwój przenosi się do środka. Mniej łutu szczęścia z zewnątrz, więcej wiary w siebie. Rada: przemyśl, w co naprawdę wierzysz i gdzie chcesz rosnąć.","sourceText":{"holiday":"św. Łucji","namedays":"Lucji, Otylii","title":"Święta Łucja","subtitle":"noc czarownic i dwanaście dni pogody","story":"W starym kalendarzu dzień świętej Łucji był najkrótszy w roku. W noc Łucji czarownice miały mieć szczególną moc, więc zamykano obory i pilnowano progów. Od dziś do Wigilii obserwuje się pogodę. Każdy z dwunastu dni zapowiada jeden miesiąc nowego roku. Zapisuj niebo, a w Wigilię przeczytasz własną przepowiednię.","practice":"• Zacznij dziś dziennik pogody na 12 dni.\n• Każdego wieczoru zapisz jedno zdanie: jaki był dzień.\n• W Wigilię przeczytaj całość jak przepowiednię.","extraTitle":"Przysłowie","extra":"„Święta Łucja dnia przyrzuca.”","whisper":"Rok nie przychodzi nagle. Zapowiada się małymi znakami.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":"Święta Łucja"},"sourceRow":44}],["2026-12-14","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":25.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Skorpionie · ♂ w Pannie. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?","sourceText":{"holiday":"","namedays":"Alfreda, Izydora","title":"Tarnina","subtitle":"owoc, który mięknie po mrozie","story":"Tarnina to krzew kolczasty i nieufny. Jej granatowe owoce są tak cierpkie, że ściągają usta, dopóki nie dotknie ich mróz. Dopiero wtedy łagodnieją i nadają się na nalewkę i powidła. Ciernie tarniny miały chronić obory przed złym. Niektórzy ludzie są jak tarnina: trzeba poczekać na pierwszy chłód, by poznać ich słodycz.","practice":"• Jeśli masz tarninę w okolicy, sprawdź, czy owoce już złagodniały.\n• Ugotuj z nich powidła z jabłkami.\n• Zauważ dziś coś, co staje się lepsze dopiero po trudnym czasie.","extraTitle":"Ciekawostka","extra":"Owoce tarniny można też zamrozić w domu. Mróz w zamrażarce działa tak samo jak przymrozek w sadzie.","whisper":"Nie oceniaj owocu przed pierwszym mrozem.","caution":"Pestek tarniny nie miażdżyć ani nie zjadać, bo zawierają związki uwalniające cyjanowodór.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":45}],["2026-12-15","rest","☽ w Wodniku do 05:35, potem w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":33.0,"moonAndBiodynamic":"☽ w Wodniku do 05:35, potem w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Do 05:35 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Niny, Celiny","title":"Zakwas buraczany","subtitle":"czerwień, która musi się zakwasić","story":"Prawdziwy wigilijny barszcz rodzi się z zakwasu, nie z kartonu. Buraki, czosnek, liść laurowy i ziele angielskie zalane osoloną wodą przez kilka dni pracują w cieple. Woda ciemnieje jak wino, a kwaśny zapach mówi, że niewidzialni pomocnicy wzięli się do roboty. Nastaw go dziś, a na Wigilię będzie rubinowy.","practice":"• Pokrój 1 kg buraków w plastry, dodaj 4 ząbki czosnku, liść laurowy i ziele angielskie.\n• Zalej 2 litrami ostudzonej, przegotowanej wody z 2 łyżkami soli.\n• Przykryj płótnem i odstaw w ciepłe miejsce na 5–7 dni, codziennie zbierając pianę.","extraTitle":"Ciekawostka","extra":"Dodaj kromkę chleba na zakwasie, a fermentacja ruszy szybciej. To stary sposób gospodyń.","whisper":"Kolor, który ma głębię, potrzebuje czasu, nie farby.","caution":"Jeśli na powierzchni pojawi się pleśń, a nie biały kożuszek, zakwas trzeba wylać.","bibliography":"Naturalne sposoby konserwowania żywności – fermentacja, IZPiTN 2026","bookKey":""},"sourceRow":46}],["2026-12-16","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":43.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Albiny, Zdzisławy","title":"Świąteczne porządki","subtitle":"wymiatanie starego roku","story":"Przed świętami bielono izby wapnem, szorowano podłogi, wietrzono pierzyny na mrozie. Dom miał być czysty na przyjście Bożego Narodzenia, ale także dla dusz przodków, które według wierzeń odwiedzały rodzinę w Wigilię. Sprzątanie było więc rytuałem. Z każdym ruchem miotły wymiatało się kurz, troski i cały stary rok.","practice":"• Wybierz jedną szufladę lub półkę i opróżnij ją do końca.\n• Każdą rzecz weź do ręki i zdecyduj: zostaje czy odchodzi.\n• Otwórz okno i wywietrz pokój na koniec.","extraTitle":"Pytanie do dziennika","extra":"Co chcę wymieść ze swojego życia przed nowym rokiem?","whisper":"Pusta półka to zaproszenie dla czegoś nowego.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":47}],["2026-12-17","rest","☽ w Rybach, od 15:34 w Baranie","I kwadra",true,{"phase":"I kwadra o 06:42","nextPhase":"pełnia za 7 dni","illumination":53.0,"moonAndBiodynamic":"☽ w Rybach, od 15:34 w Baranie · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 15:34 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 06:42 do 15:34: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Olimpii, Łazarza","title":"Pierwszy gość","subtitle":"ten, kto wchodzi pierwszy","story":"Kto pierwszy przekroczy próg w święta, ten przynosi domowi los na cały rok. W południowej Polsce czekano na podłaźnika, najlepiej chłopca lub mężczyznę, który wchodził z życzeniami zdrowia i urodzaju. Gospodarze sadzali go przy stole i obdarowywali. Pierwszy gość był jak pierwsze słowo nowej opowieści.","practice":"• Pomyśl, kogo chciałabyś zobaczyć jako pierwszego gościa w nowym roku.\n• Zaproś go albo ją.\n• Przygotuj drobny podarunek dla pierwszej osoby, która cię odwiedzi.","extraTitle":"Ciekawostka","extra":"Słowo „podłaźnik” pochodzi od „podłazić”, czyli zakradać się do domu z życzeniami.","whisper":"Wybieraj ludzi, którzy wchodzą do twojego życia z dobrym słowem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":48}],["2026-12-18","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":64.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉△♃ Słońce trygon Jowisz (22:21): Dobry dzień na optymizm, prośby, oferty, naukę i podróże.","sourceText":{"holiday":"","namedays":"Gracjana, Bogusława","title":"Kolęda jako zaklęcie","subtitle":"życzenia, które mają moc","story":"Kolędnicy nie tylko śpiewali. Ich słowa wypowiedziane w progu miały sprowadzić na dom urodzaj, zdrowie i dostatek. Dlatego przyjmowano ich hojnie. Kolędnik odprawiony z pustymi rękami mógł wypowiedzieć życzenia odwrotne. W święta słowo waży więcej niż zwykle, bo granica między powiedzianym a spełnionym jest wtedy cienka.","practice":"• Napisz komuś życzenia na nowy rok, konkretne i osobiste.\n• Wypowiedz je na głos przy wysyłaniu.\n• Zapisz jedno życzenie dla siebie i przeczytaj je trzy razy.","extraTitle":"Ciekawostka","extra":"Słowo „kolęda” pochodzi od łacińskiego calendae, pierwszego dnia miesiąca, gdy w Rzymie składano sobie noworoczne życzenia.","whisper":"Życz innym tego, czego naprawdę chcesz dla świata. Słowa wracają.","caution":"","bibliography":"Magia słowa, IZPiTN 2026","bookKey":""},"sourceRow":49}],["2026-12-19","start","☽ w Baranie, od 21:29 w Byku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":74.0,"moonAndBiodynamic":"☽ w Baranie, od 21:29 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 21:29 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 17:39 do 21:29: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Gabrieli, Dariusza","title":"Puszczyk","subtitle":"głos najdłuższych nocy","story":"W mroźne noce niesie się po lesie pohukiwanie puszczyka. Dawniej słuchano go z lękiem, bo sowy uchodziły za zwiastunki śmierci, a krzyk pójdźki brzmiał jak wołanie: „pójdź!”. Dziś wiemy, że to głos miłości. Puszczyki łączą się w pary właśnie zimą, w najciemniejszym czasie roku.","practice":"• Wyjdź po zmroku i nasłuchuj sów przez pięć minut.\n• Zapisz, co słyszysz w ciemności.\n• Zastanów się, czego boisz się bardziej, niż powinnaś.","extraTitle":"Ciekawostka","extra":"Pójdźka, mała sowa krajobrazu rolniczego, swoją nazwę zawdzięcza właśnie ludowemu odczytaniu jej głosu.","whisper":"To, czego się boisz, bywa tylko cudzą piosenką miłosną.","caution":"","bibliography":"Demony ludowe a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":50}],["2026-12-20","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":84.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Bogumiły, Dominika","title":"Gody","subtitle":"święty czas między latami","story":"Od Bożego Narodzenia do Trzech Króli trwały Gody. Czas wyjęty z codzienności, kiedy nie wykonywano wielu prac, odwiedzano się, kolędowano i wróżono. Wierzono, że w te dni granica między światami jest cienka jak opłatek, a każdy gest odbija się w całym nadchodzącym roku. Zaplanuj nie tylko, co ugotujesz, ale jak chcesz żyć.","practice":"• Zaplanuj, jak chcesz spędzić te dni, a nie tylko co ugotujesz.\n• Wybierz jedną pracę, której w Gody nie zrobisz.\n• Zostaw w kalendarzu jeden zupełnie pusty dzień.","extraTitle":"Pytanie na niedzielę","extra":"Co chcę zostawić w starym roku, a co zabrać ze sobą?","whisper":"Jak spędzisz Gody, taki rok przed tobą.","caution":"","bibliography":"Kalendarz obrzędów ludowych, IZPiTN 2026","bookKey":""},"sourceRow":51}],["2026-12-21","finances","☽ w Byku, od 23:27 w Bliźniętach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Byku, od 23:27 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 23:27 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 18:26 do 23:27: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Skorpionie · ♂ w Pannie. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☉ Słońce wchodzi w Koziorożca (21:50): Na miesiąc cały świat nabiera barw znaku Koziorożca: czas obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa.","sourceText":{"holiday":"przesilenie zimowe, 21:50 · najkrótszy dzień","namedays":"Tomasza, Tomisława","title":"Słońce rodzi się na nowo","subtitle":"słońce rodzi się na nowo","story":"Dziś o 21:50 przesilenie zimowe. Słońce zatrzymuje się w najniższym punkcie nieba, jakby wahało się, czy wrócić. I wraca. Od jutra dnia zacznie przybywać, najpierw o minutę, potem coraz więcej. Dawne ludy witały ten moment ogniem i nadzieją. Najdłuższa noc roku jest też ostatnią, która ciemność może nazwać swoją.","practice":"• O zachodzie słońca zapal świecę w oknie.\n• Posiedź w ciemności 10 minut, zanim zapalisz inne światło.\n• Zapisz jedną rzecz, którą chcesz wnieść w jaśniejszą część roku.","extraTitle":"Ciekawostka","extra":"Od jutra dzień we Wrocławiu będzie się wydłużał, ale wieczory szybciej niż poranki. Najpóźniejszy wschód słońca wypada dopiero na przełomie roku.","whisper":"Najdłuższa noc zawsze kończy się świtem. Taki jest porządek świata.","caution":"Świeca w oknie tylko pod nadzorem.","bibliography":"Dane astronomiczne 2026","bookKey":"Przesilenie zimowe"},"sourceRow":52}],["2026-12-22","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Zenona, Honoraty","title":"Kutia","subtitle":"pokarm dla żywych i umarłych","story":"Kutia z pszenicy, maku, miodu i orzechów to potrawa wschodnich kresów i dusz. Na Wigilię jej łyżkę zostawiano na noc przodkom, a czasem rzucano kutię pod sufit. Jeśli się przykleiła, wróżyło to urodzaj i roje pszczół. Każde ziarno w niej to obietnica płodności. Jeść ją znaczy dzielić stół z całym rodem.","practice":"• Namocz na noc szklankę pszenicy, potem ugotuj do miękkości.\n• Zmiel szklankę sparzonego maku, wymieszaj z pszenicą.\n• Dodaj 4 łyżki miodu, garść orzechów i rodzynek.","extraTitle":"Ciekawostka","extra":"Jeśli kutia rzucona pod sufit przykleiła się, wróżyło to dobry urodzaj i roje pszczół.","whisper":"Gdy jesz to, co jedli twoi przodkowie, siadają obok ciebie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":53}],["2026-12-23","conversation","☽ w Bliźniętach, od 22:58 w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 22:58 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 22:58 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 18:01 do 22:58: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉□♆ Słońce kwadratura Neptun (12:37): Napięcie między planetami. Można je wykorzystać na intuicję, sztukę, medytację i pomoc innym. Uważaj na złudzenia, zmęczenie i niejasne sytuacje.\n☿△♃ Merkury trygon Jowisz (19:03): Dobry dzień na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości.","sourceText":{"holiday":"","namedays":"Wiktorii, Sławomiry","title":"Siano i puste miejsce","subtitle":"siano, snop i puste krzesło","story":"Pod wigilijny obrus kładzie się siano, na pamiątkę żłóbka i na urodzaj. W kącie izby stawiano snop zboża, na wschodzie zwany diduchem, czyli dziadem, domem duchów przodków. Przy stole zostawiano wolne nakrycie: dla zbłąkanego wędrowca albo dla tych, którzy odeszli. Przygotuj dziś miejsce dla tego, kogo ci brakuje.","practice":"• Kup albo przygotuj trochę siana na jutro.\n• Zdecyduj, dla kogo zostawisz puste nakrycie.\n• Napisz jego imię na karteczce i połóż przy talerzu.","extraTitle":"Ciekawostka","extra":"Snop w kącie izby na wschodzie nazywano diduchem, czyli „dziadem”, duchem przodków.","whisper":"Puste krzesło przy stole też jest gościem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":54}],["2026-12-24","home","☽ w Raku","pełnia",false,{"phase":"pełnia o 02:28","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌕 Pełnia w Raku (02:28): Kulminacja w sprawach: dom, rodzina, korzenie. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"Wigilia Bożego Narodzenia","namedays":"Adama, Ewy","title":"Noc, w której mówią zwierzęta","subtitle":"noc, w której mówią zwierzęta","story":"Kiedy na niebie zapali się pierwsza gwiazda, zaczyna się wieczerza. Łamie się opłatek, kosztuje każdej potrawy, by niczego nie zabrakło w nowym roku. Opłatek zanosi się też zwierzętom. O północy, mówią, przemawiają ludzkim głosem, ale podsłuchiwać ich nie wolno. Dziś także pełnia: Księżyc i gwiazdy czuwają razem z tobą.","practice":"• Wyjdź przed kolacją i poszukaj pierwszej gwiazdy.\n• Podziel się opłatkiem także z kimś, z kim się pokłóciłaś.\n• Daj zwierzętom w domu coś dobrego.","extraTitle":"Przysłowie","extra":"„Jaka Wigilia, taki cały rok.”","whisper":"Niektóre cuda dzieją się tylko wtedy, gdy nikt nie podsłuchuje.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":"Wigilia"},"sourceRow":55}],["2026-12-25","home","☽ w Raku, od 22:12 we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Raku, od 22:12 we Lwie · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 22:12 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 01:09 do 22:12: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury wchodzi w Koziorożca (19:22): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa. Uważaj na surowość wobec siebie i chłód.","sourceText":{"holiday":"Boże Narodzenie","namedays":"Anastazji, Eugenii","title":"Kolędnicy z gwiazdą","subtitle":"turoń, gwiazda i kolędnicy","story":"Od dziś po wsiach chodzą kolędnicy z gwiazdą i szopką. Wśród nich turoń: kudłata, rogata bestia, która kłapie paszczą, straszy dziewczęta, pada martwa i zaraz ożywa. W tej zabawie kryje się bardzo stara opowieść o śmierci starego roku i narodzinach nowego. Śmiech i strach zawsze chodziły razem przez zimę.","practice":"• Zaśpiewaj dziś choć jedną kolędę, choćby półgłosem.\n• Odwiedź kogoś, kto spędza święta sam.\n• Opowiedz dzieciom o turoniu.","extraTitle":"Ciekawostka","extra":"Turoń bywa łączony z turem, dzikim bykiem, który wyginął w Polsce w 1627 roku w Puszczy Jaktorowskiej.","whisper":"Co umiera ze śmiechem, odradza się szybciej.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":56}],["2026-12-26","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":92.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿□♆ Merkury w napięciu z Neptunem (20:46): Nieporozumienia, zgubione wiadomości, niedopowiedzenia. Uwaga: sprawdzaj fakty, pytaj wprost.","sourceText":{"holiday":"drugi dzień Bożego Narodzenia · św. Szczepana","namedays":"Jana, Żanety","title":"Obsypywanie owsem","subtitle":"ziarno rzucone na szczęście","story":"W dzień świętego Szczepana świat obsypywał się owsem: w kościele, w domach, na drodze. Ziarno rzucone na człowieka przynosiło urodzaj i płodność. Tego dnia służba mogła odejść od gospodarza albo zgodzić się na kolejny rok. Szczepan to święto wolnego wyboru. Pomyśl, komu w tym roku przestaniesz służyć.","practice":"• Weź garść ziaren i rozsyp je ptakom.\n• Pomyśl, z jakiej „służby” chcesz się zwolnić w nowym roku.\n• Zrób dziś coś tylko dla siebie.","extraTitle":"Przysłowie","extra":"„Na świętego Szczepana każdy sobie pan.”","whisper":"Wolność zaczyna się od jednego „nie” powiedzianego spokojnie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":57}],["2026-12-27","creative","☽ we Lwie, od 23:12 w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":85.0,"moonAndBiodynamic":"☽ we Lwie, od 23:12 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 23:12 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 17:38 do 23:12: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"św. Jana · święcenie wina","namedays":"Teofili, Godzisława","title":"Wino świętego Jana","subtitle":"kielich, który chroni","story":"W dzień świętego Jana święcono wino. Legenda mówi, że Jan wypił zatrute wino i nic mu się nie stało. Dlatego święcone wino miało chronić przed trucizną, chorobą i urokiem. Dawano je chorym, dolewano do beczek, kropiono nim pola. Wznieś dziś kielich, choćby z wodą, za zdrowie tych, których kochasz.","practice":"• Wznieś dziś toast za zdrowie bliskich, choćby wodą lub sokiem.\n• Powiedz każdemu przy stole jedno dobre słowo.\n• Zapisz, za co jesteś wdzięczna w mijającym roku.","extraTitle":"Pytanie na niedzielę","extra":"Za czyje zdrowie chcę dziś wznieść kielich?","whisper":"Toast to modlitwa, którą wypowiada się z uśmiechem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":58}],["2026-12-28","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":76.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Koziorożcu · ☿ w Koziorożcu · ♀ w Skorpionie · ♂ w Pannie. Pytanie tygodnia: Jaki cel budujesz krok po kroku?","sourceText":{"holiday":"Młodzianków","namedays":"Jana, Maksyma","title":"Wigilijne siano","subtitle":"źdźbło, które zna przyszłość","story":"Siano spod wigilijnego obrusa nie szło do śmieci. Dostawały je zwierzęta, by były zdrowe, a część trafiała do kurzych gniazd. Z wyciągniętego źdźbła czytano los: długie i zielone wróżyło dobry rok, krótkie i pożółkłe trudniejszy. W Młodzianki dzieci smagano rózgą, by przeszła na nie siła rośliny i zdrowie.","practice":"• Jeśli zostało ci siano, wyciągnij jedno źdźbło i przyjrzyj się mu.\n• Resztę oddaj zwierzętom lub na kompost.\n• Daj dzieciom w prezencie jakąś drobną wiosenną roślinkę.","extraTitle":"Ciekawostka","extra":"Smaganie rózgą w Młodzianki miało przekazać dzieciom siłę rośliny i chronić je przed chorobą.","whisper":"Los nie siedzi w źdźble. Ale źdźbło przypomina, że go masz.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":59}],["2026-12-29","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":65.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 11:17 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Dawida, Tomasza","title":"Polewka piwna","subtitle":"śniadanie na mróz","story":"Zanim kawa dotarła do Polski, zimowy dzień zaczynano od polewki piwnej: grzanego piwa z żółtkiem, śmietaną i kminkiem, z kostkami twarogu albo chleba. Jadali ją chłopi i szlachta. Rozgrzewała przed pracą w mroźnym obejściu. Dziś to ciekawostka, ale przypomina, że każde pokolenie miało swój sposób na ciemne poranki.","practice":"• Podgrzej szklankę jasnego piwa z łyżeczką miodu i szczyptą kminku.\n• Rozbełtaj żółtko z 2 łyżkami śmietany i wlej do piwa, mieszając.\n• Podawaj z kostkami twarogu lub grzanką.","extraTitle":"Ciekawostka","extra":"W dawnej Polsce piwo było napojem codziennym, także dla dzieci. Było słabe i bezpieczniejsze niż woda ze studni.","whisper":"Każde pokolenie ma swój napój na ciemne poranki. Znajdź swój.","caution":"Zawiera alkohol. Nie dla dzieci, kobiet w ciąży i kierowców.","bibliography":"Z. Gloger, Encyklopedia staropolska (hasło: polewka)","bookKey":""},"sourceRow":60}],["2026-12-30","relationships","☽ w Pannie do 03:26, potem w Wadze","III kwadra",false,{"phase":"III kwadra o 19:59","nextPhase":"nów za 8 dni","illumination":54.0,"moonAndBiodynamic":"☽ w Pannie do 03:26, potem w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 03:26 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉□♄ Słońce kwadratura Saturn (00:27): Napięcie między planetami. Można je wykorzystać na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach. Uważaj na zniechęcenie, surowość wobec siebie i zmęczenie.","sourceText":{"holiday":"","namedays":"Irminy, Eugeniusza","title":"Rachunek roku","subtitle":"rachunek, który zamyka rok","story":"Dziś wieczorem ostatnia kwadra. Księżyc maleje razem z kończącym się rokiem. To dobra chwila, by usiąść i policzyć, co się wydarzyło, bez wyroków i bez upiększania. Co udało się zebrać, co trzeba było oddać, czego nauczył cię ten rok, choć wcale o to nie prosiłaś. Spisany rok przestaje cię gonić.","practice":"• Zapisz trzy rzeczy, z których jesteś dumna w tym roku.\n• Zapisz jedną, którą chcesz zostawić za sobą.\n• Spal albo podrzyj tę drugą kartkę, a pierwszą zachowaj.","extraTitle":"Pytanie do dziennika","extra":"Czego nauczył mnie ten rok, choć wcale o to nie prosiłam?","whisper":"Rok, który zrozumiesz, nie będzie cię już straszył.","caution":"Palenie kartek tylko w bezpiecznym miejscu, np. w zlewie lub kominku.","bibliography":"Rytuał autorski","bookKey":""},"sourceRow":61}],["2026-12-31","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":44.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿□♄ Merkury kwadratura Saturn (00:54): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.\n☉△♂ Słońce trygon Mars (13:02): Dobry dzień na odważne decyzje, sport i ruszanie spraw z miejsca.","sourceText":{"holiday":"Sylwester","namedays":"Melanii, Sylwestra","title":"Psoty sylwestrowe","subtitle":"hałas na odejście starego roku","story":"W noc sylwestrową młodzi płatali figle: zdejmowali bramy z zawiasów, wynosili wozy na dachy stodół, zatykali kominy. Strzelano z batów i bito w garnki. Wierzono, że zgiełk płoszy złe moce, które czają się na przełomie roku. Dzisiejsze fajerwerki są dalekim echem tego zwyczaju. Pożegnaj stary rok głośno, a przywitaj nowy cicho.","practice":"• O północy zrób trochę hałasu: dzwonek, garnek, śmiech.\n• Otwórz okno, żeby stary rok mógł wyjść.\n• Pierwszą rzeczą w nowym roku niech będzie coś, co lubisz.","extraTitle":"Ciekawostka","extra":"Zwierzęta źle znoszą huk petard. Zostań z nimi w domu albo wybierz ciche świętowanie.","whisper":"Stary rok żegnaj śmiechem, nowy witaj ciszą.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":62}],["2027-01-01","honesty","☽ w Wadze do 11:15, potem w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":34.0,"moonAndBiodynamic":"☽ w Wadze do 11:15, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 11:15 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 04:27 do 11:15: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿△♂ Merkury trygon Mars (00:30): Dobry dzień na szybkie decyzje, debatę i załatwienie zaległości.\n☉☌☿ Słońce koniunkcja Merkury (18:07): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"Nowy Rok","namedays":"Mieszka, Mieczysława","title":"Pierwszy dzień","subtitle":"jak dziś, tak cały rok","story":"Dzisiejszy dzień jest lustrem całego roku. Tak wierzono: kto w Nowy Rok jest wesoły, ten będzie wesoły do grudnia, a kto się kłóci, ten będzie się kłócił. Nie pożyczano nic z domu, by nie oddać szczęścia. Rano myto się w wodzie z monetą, żeby pieniądz się trzymał. Zacznij ten rok tak, jak chcesz go przeżyć.","practice":"• Zrób dziś jedną rzecz, którą chcesz robić przez cały rok.\n• Umyj twarz w wodzie, do której wrzucisz monetę.\n• Nie kłóć się, choćby ktoś bardzo prosił.","extraTitle":"Przysłowie","extra":"„Od Nowego Roku przybywa dnia na kurzy krok.”","whisper":"Pierwszy krok wyznacza kierunek. Postaw go uważnie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":63}],["2027-01-02","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":25.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Izydora, Grzegorza","title":"Kapuśniak na kiszonej kapuście","subtitle":"zupa, która grzeje od środka","story":"W styczniu spiżarnia mówi kapustą. Kiszona jesienią, teraz oddaje to, co najlepsze: kwas, który budzi apetyt, i ciepło, które zostaje w brzuchu na długo. Kapuśniak gotowano na wędzonce, z grzybami, z ziemniakiem. To zupa dla tych, którzy wracają z mrozu i potrzebują, by ktoś na nich czekał.","practice":"• Zagotuj 0,5 kg kiszonej kapusty z wywarem, grzybami suszonymi i liściem laurowym.\n• Dodaj pokrojone ziemniaki i gotuj do miękkości.\n• Dopraw majerankiem, pieprzem i łyżką smalcu lub masła.","extraTitle":"Ciekawostka","extra":"Kapusta kiszona w beczkach przetrwała całą zimę i chroniła przed szkorbutem, bo zachowuje witaminę C.","whisper":"Zupa ugotowana z cierpliwością karmi dłużej niż obiad z pośpiechu.","caution":"","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":64}],["2027-01-03","honesty","☽ w Skorpionie, od 21:57 w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":17.0,"moonAndBiodynamic":"☽ w Skorpionie, od 21:57 w Strzelcu · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 21:57 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 14:33 do 21:57: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀□♃ Wenus kwadratura Jowisz (18:55): Napięcie między planetami. Można je wykorzystać na relacje, randki, zakupy, umowy i świętowanie. Uważaj na rozrzutność i przejadanie się.","sourceText":{"holiday":"","namedays":"Danuty, Zdzisława","title":"Strzyga","subtitle":"ta, która ma dwie dusze","story":"Strzygą stawał się ten, kto urodził się z dwiema duszami. Jedna odchodziła po śmierci, druga zostawała w ciele i nie dawała mu spokoju. Strzyga wychodziła nocą z grobu i szukała krwi. Rozpoznawano ją po podwójnym rzędzie zębów. Chowano ją twarzą do ziemi, z sierpem przy szyi. Opowieści o niej długo straszyły dzieci zimą.","practice":"• Opowiedz dziś komuś starą straszną historię.\n• Zapal światło w ciemnym korytarzu.\n• Pomyśl, jaka twoja „druga dusza” nie daje ci spokoju.","extraTitle":"Pytanie na niedzielę","extra":"Czego we mnie jest dwoje i które z nich chcę karmić?","whisper":"Każdy nosi w sobie dwie dusze. Ważne, której dajesz jeść.","caution":"","bibliography":"Śmierć w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":65}],["2027-01-04","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":11.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Koziorożcu · ☿ w Koziorożcu · ♀ w Skorpionie · ♂ w Pannie. Pytanie tygodnia: Jaki cel budujesz krok po kroku?","sourceText":{"holiday":"","namedays":"Elżbiety, Anieli","title":"Arcydzięgiel","subtitle":"anielskie ziele","story":"Arcydzięgiel to roślina wysoka jak człowiek, z korzeniem pachnącym piżmem i ziołami. Jego łacińska nazwa, Angelica, mówi wszystko: uchodził za dar anioła, chroniący przed zarazą i złymi duchami. Kawałek korzenia noszono przy sobie w czasie morowego powietrza. Zimą jego gorzki korzeń grzeje żołądek i budzi trawienie po świętach.","practice":"• Powąchaj korzeń arcydzięgla albo nalewkę, jeśli ją masz.\n• Zjedz dziś lżej, z czymś gorzkim na początek.\n• Przejdź się po obiedzie, choćby 15 minut.","extraTitle":"Ciekawostka","extra":"Arcydzięgiel jest składnikiem wielu ziołowych likierów klasztornych.","whisper":"Gorycz na początek, słodycz na koniec. Tak trawi się i jedzenie, i życie.","caution":"Uwrażliwia skórę na słońce. Nie w ciąży. Uwaga: w naturze łatwo pomylić go z trującymi baldaszkowatymi.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":66}],["2027-01-05","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Hanny, Edwarda, Szymona","title":"Kisiel owsiany","subtitle":"postna potrawa wigilii Trzech Króli","story":"Kisiel z owsa, kwaśny i gęsty, jadano dawniej w czasie postów, szczególnie na wschodzie. Owies zalewano wodą i zostawiano, by skisł, potem gotowano, aż zgęstniał. Podawany z olejem lnianym i cebulą albo z miodem był pożywny i tani. Wieczór przed Trzema Królami bywał nazywany szczodrym. To dobry czas na prostą, starą potrawę.","practice":"• Zalej szklankę płatków owsianych 2 szklankami wody i odstaw na dobę.\n• Przecedź, płyn zagotuj, mieszając, aż zgęstnieje.\n• Podaj ciepły z miodem albo zimny z olejem lnianym.","extraTitle":"Ciekawostka","extra":"Słowo „kisiel” pochodzi od „kisnąć”. Pierwotnie był potrawą ukwaszoną, nie słodkim deserem z torebki.","whisper":"Proste jedzenie przypomina, że do szczęścia nie trzeba wiele.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":67}],["2027-01-06","work","☽ w Strzelcu do 10:17, potem w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":2.0,"moonAndBiodynamic":"☽ w Strzelcu do 10:17, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 10:17 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 02:23 do 10:17: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"Trzech Króli · Trzech Króli · kreda i kadzidło","namedays":"Kacpra, Melchiora, Baltazara","title":"Kreda i kadzidło","subtitle":"Trzech Króli","story":"Dziś święci się kredę i kadzidło. Kredą pisze się nad drzwiami litery i rok, żeby dom był strzeżony przez cały rok. Kadzidłem okadza się izby, wypędzając wszystko, co nieproszone. Dawniej w ten dzień kończyły się Gody, święty czas przełomu roku, i wracała codzienność. Znak na drzwiach mówi: ten dom ma opiekę.","practice":"• Napisz kredą nad drzwiami rok: 20+C+M+B+27.\n• Zapal kadzidło lub zioła i przejdź z dymem przez każde pomieszczenie.\n• Otwórz na chwilę okno, by wypuścić stare.","extraTitle":"Ciekawostka","extra":"Litery C+M+B to imiona Kacpra, Melchiora i Baltazara, ale też skrót łacińskiego błogosławieństwa: Christus mansionem benedicat, „Niech Chrystus błogosławi ten dom”.","whisper":"Dom, który ma znak na drzwiach, pamięta, komu ufa.","caution":"Kadzidło pal w przewietrzonym pomieszczeniu, z dala od firanek.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":68}],["2027-01-07","work","☽ w Koziorożcu","nów",false,{"phase":"nów o 21:24","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus wchodzi w Strzelca (09:53): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się. Uważaj na przesadę i obietnice bez pokrycia.\n🌑 Nów w Koziorożcu (21:24): Czas zasiewu w sprawach: praca, ambicja, odpowiedzialność. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Lucjana, Juliana","title":"Kalendarz z cebuli","subtitle":"dwanaście łusek pogody","story":"Dawni gospodarze robili sobie kalendarz pogody z cebuli. Dwanaście łupin, na każdą szczypta soli. Te, w których rano sól zwilgotniała, zapowiadały mokre miesiące, te suche suszę. Na tej podstawie planowano siew i zbiory. Dziś w nocy nów: dobry czas, by zajrzeć w nadchodzący rok, choćby przez łupinę cebuli.","practice":"• Ułóż 12 łupin cebuli w rzędzie i podpisz je miesiącami.\n• Na każdą wsyp szczyptę soli i zostaw do rana.\n• Zapisz, które łupiny są mokre, i porównaj z prawdziwą pogodą za rok.","extraTitle":"Fakt czy wiara?","extra":"Pogody na rok z cebuli nie przewidzisz. Ale zabawa w zapisywanie znaków uczy uważności na niebo.","whisper":"Przyszłość nie mieści się w łupinie cebuli. Uważność mieści się wszędzie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":69}],["2027-01-08","work","☽ w Koziorożcu, od 23:10 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 23:10 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 23:10 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 06:11 do 23:10: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Seweryna, Juliusza","title":"Dzwonki u sań","subtitle":"dźwięk, który odpędza","story":"Sanie mknące przez zimowy las brzęczały dzwonkami. Mówiono, że to dla wilków i dla ludzi, by wiedzieli, że ktoś jedzie. Ale w wierzeniach dźwięk dzwonka był też tarczą: złe moce nie znosiły czystego, metalicznego głosu. Dzwoniono w czasie burzy i w czasie zarazy. Czysty dźwięk przecina mrok jak nóż.","practice":"• Zawieś przy drzwiach mały dzwonek.\n• Zadzwoń nim, gdy wracasz do domu po trudnym dniu.\n• Posłuchaj, jak długo wybrzmiewa w ciszy.","extraTitle":"Ciekawostka","extra":"Dzwonieniem w kościołach próbowano odpędzać nadciągające burze i grad. Stąd na dzwonach napisy o piorunach.","whisper":"Czysty dźwięk przecina to, czego nie przetnie żaden nóż.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":70}],["2027-01-09","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀△♆ Wenus trygon Neptun (03:44): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.\n♀☍♅ Wenus opozycja Uran (09:19): Napięcie między planetami. Można je wykorzystać na nowe znajomości, niespodzianki i zmianę wizerunku. Uważaj na nagłe zauroczenia i wydatki pod wpływem chwili.","sourceText":{"holiday":"","namedays":"Adriana, Marceliny","title":"Szron","subtitle":"kwiaty, których nikt nie sadził","story":"Rano na szybach rosną paprocie, pióra i gwiazdy. Szron maluje bez pędzla, w ciszy najzimniejszych godzin. Dawniej mówiono, że to robota Mroza, starego ducha zimy, który chodzi po wsiach i stuka w ściany chat, aż trzeszczą. Spójrz uważnie: w jednym oknie mieści się cały zimowy ogród.","practice":"• Rano obejrzyj szron na szybie lub trawie przez lupę albo z bliska.\n• Zrób mu zdjęcie, zanim zniknie.\n• Przyłóż ciepłą dłoń do szyby i zostaw na niej swój ślad.","extraTitle":"Ciekawostka","extra":"Szron to para wodna, która zamienia się w lód od razu, bez etapu kropli.","whisper":"Najpiękniejsze wzory powstają w najzimniejszych godzinach.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":71}],["2027-01-10","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂ Mars rusza wstecz w Pannie (13:59): Na kilka tygodni energia spada, a złość łatwiej obraca się do środka. Plany zwalniają. Rada: nie zaczynaj wojen ani wielkich projektów, poprawiaj stare. Uwaga: uważaj na urazy i przemęczenie.","sourceText":{"holiday":"","namedays":"Danuty, Wilhelma","title":"Kulig","subtitle":"zimowa zabawa szlachty i wsi","story":"Gdy śnieg leżał na drogach, ruszały kuligi. Sznur sań z pochodniami, muzyką i dzwonkami jeździł od dworu do dworu, a w każdym czekało jedzenie i taniec. Zabawa trwała czasem kilka dni. Kulig był sposobem, by przetrwać ciemne tygodnie razem, głośno i radośnie. Zima smakuje inaczej, gdy dzieli się ją z innymi.","practice":"• Wyjdź na zimowy spacer z kimś bliskim.\n• Weź termos z gorącą herbatą.\n• Zaproś kogoś na kolację bez okazji.","extraTitle":"Pytanie na niedzielę","extra":"Z kim chcę jechać przez tę zimę w jednych saniach?","whisper":"Zima jest krótsza, gdy się ją przejeżdża razem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":72}],["2027-01-11","rest","☽ w Wodniku do 11:35, potem w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Wodniku do 11:35, potem w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Do 11:35 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 02:58 do 11:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Koziorożcu · ☿ w Koziorożcu · ♀ w Strzelcu · ♂ w Pannie. Pytanie tygodnia: Jaki cel budujesz krok po kroku?\n♀✶♇ Wenus sekstyl Pluton (20:26): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach.","sourceText":{"holiday":"","namedays":"Honoraty, Matyldy","title":"Rozmaryn","subtitle":"ziele pamięci i ślubów","story":"Rozmaryn przywędrował do Polski z południa i zamieszkał w doniczkach na parapetach. Stał się ziołem ślubnym: panny młode wplatały go w wianki, a goście dostawali gałązkę przy weselu. Mówiono, że wzmacnia pamięć i wierność. Jego zapach budzi jak poranne słońce. W szarym styczniu przypomina, że gdzieś jest ciepło.","practice":"• Powąchaj gałązkę rozmarynu przed pracą wymagającą skupienia.\n• Dodaj go do pieczonych ziemniaków.\n• Postaw doniczkę na jasnym parapecie.","extraTitle":"Ciekawostka","extra":"W pieśniach ludowych rozmaryn był symbolem panieństwa. „Rozmaryn” w wianku znaczył młodość i niewinność.","whisper":"Pamięć jest jak rozmaryn: trzeba ją podlewać, żeby pachniała.","caution":"W dużych ilościach nie w ciąży i przy padaczce.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":73}],["2027-01-12","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":19.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Ady, Benedykta, Arkadiusza","title":"Grzaniec z miodem","subtitle":"napój długich wieczorów","story":"Gdy mróz szczypie w policzki, w domu paruje grzaniec. Wino albo sok, miód, cynamon, goździki, skórka pomarańczy. Dawniej grzano piwo i miód pitny z korzeniami. Ciepły napój z przyprawami był lekarstwem na przemarznięcie i smutek długich nocy. Pij powoli, trzymając kubek oburącz, jak ogień w dłoniach.","practice":"• Podgrzej sok z czarnej porzeczki lub wino z łyżką miodu.\n• Dodaj laskę cynamonu, 3 goździki i plasterek pomarańczy.\n• Nie gotuj, tylko podgrzej. Pij powoli.","extraTitle":"Ciekawostka","extra":"Wersja na soku jest równie rozgrzewająca, a dzieci mogą ją pić razem z dorosłymi.","whisper":"Trzymaj ciepło w obu dłoniach. Wtedy dociera do serca.","caution":"Wersja z winem zawiera alkohol.","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":74}],["2027-01-13","rest","☽ w Rybach, od 22:13 w Baranie","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":27.0,"moonAndBiodynamic":"☽ w Rybach, od 22:13 w Baranie · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 22:13 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 08:32 do 22:13: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury wchodzi w Wodnika (07:05): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie przyjaźni, wolności, nowości i wspólnoty. Rada: spotkaj się z ludźmi i spróbuj czegoś nowego. Uważaj na bunt dla buntu i dystans.","sourceText":{"holiday":"","namedays":"Bogumiły, Weroniki","title":"Spacer o świcie","subtitle":"pierwsze światło zimy","story":"Zimą słońce wstaje późno i ospale. Właśnie dlatego warto mu wyjść na spotkanie. Dawniej gospodarze wstawali przed świtem, a pierwsze światło witali w obejściu, przy zwierzętach i studni. Kilka minut w szarości poranka, gdy wszystko się budzi, ustawia dzień inaczej niż ekran telefonu. Ciało pamięta słońce, nawet jeśli go nie widzi.","practice":"• Wyjdź na zewnątrz przed ósmą, choćby na 10 minut.\n• Spójrz w stronę wschodu i zrób trzy głębokie oddechy.\n• Wróć i wypij szklankę ciepłej wody.","extraTitle":"Ciekawostka","extra":"Poranne światło, nawet pochmurne, pomaga ustawić rytm snu i czuwania.","whisper":"Słońce wstaje zawsze. Pytanie, czy ty wyjdziesz mu na spotkanie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":75}],["2027-01-14","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":36.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿✶♆ Merkury sekstyl Neptun (10:28): Dobry dzień na pisanie, poezję, muzykę i rozmowy o duchowości.\n☿△♅ Merkury trygon Uran (11:02): Dobry dzień na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania.","sourceText":{"holiday":"","namedays":"Feliksa, Niny","title":"Wilcze noce","subtitle":"gdy głód zbliża się do wsi","story":"Styczeń to czas, gdy wilki podchodziły pod wsie. W wierzeniach wilk był posłańcem innego świata, a jego wycie zapowiadało mróz albo nieszczęście. Nie wymawiano jego imienia na głos, mówiono „on”, „szary”, żeby go nie przywołać. Wilcze kły noszono jako amulety odwagi. Dziś wilki wracają do polskich lasów, ostrożne i rzadko widziane.","practice":"• Poczytaj o wilkach żyjących dziś w Polsce.\n• Zastanów się, czego boisz się tak, że nie wymawiasz tego na głos.\n• Nazwij to dziś po imieniu.","extraTitle":"Ciekawostka","extra":"Unikanie nazwy groźnego zwierzęcia to zjawisko znane w wielu językach. Mówi się o nim „tabu językowe”.","whisper":"To, czego nie nazwiesz, rośnie w ciemności. Nazwane maleje.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":76}],["2027-01-15","start","☽ w Baranie","I kwadra",false,{"phase":"I kwadra o 21:34","nextPhase":"pełnia za 7 dni","illumination":46.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 21:34 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♅✶♆ Uran i Neptun we współpracy (10:30): Rzadki układ wspierający wynalazki, sztukę i nowe formy duchowości. Rada: daj szansę nowym pomysłom w sprawach ducha i twórczości.\n♀△♄ Wenus trygon Saturn (22:39): Dobry dzień na trwałe zobowiązania, inwestycje i porządki w finansach.","sourceText":{"holiday":"","namedays":"Pawła, Arnolda, Izydora","title":"Zamowa na sen","subtitle":"szept przed zaśnięciem","story":"Matki usypiały dzieci szeptem, który był jednocześnie kołysanką i ochroną. Prosiły, by sen przyszedł, a zmora odeszła, by noc była cicha, a rano jasne. Słowa powtarzano po trzykroć, dotykając czoła dziecka. Dziś Księżyc jest w pierwszej kwadrze, rośnie. Dobry czas, by budować w sobie spokój jak ten szept.","practice":"• Przed snem połóż dłoń na czole lub sercu.\n• Wyszeptaj trzy razy: „Niech przyjdzie sen, niech odejdzie trwoga”.\n• Zgaś światło od razu, bez telefonu.","extraTitle":"Ciekawostka","extra":"Kołysanki ludowe często zawierały elementy zaklęć ochronnych przed nocnymi demonami.","whisper":"Sen przychodzi do tych, którzy przestają go gonić.","caution":"","bibliography":"Magia słowa, IZPiTN 2026","bookKey":""},"sourceRow":77}],["2027-01-16","finances","☽ w Baranie do 05:43, potem w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":57.0,"moonAndBiodynamic":"☽ w Baranie do 05:43, potem w Byku · dzień korzenia · ♂ retro","goodFor":"dobry dzień na finanse","energy":"Do 05:43 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿☌♇ Merkury koniunkcja Pluton (03:48): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy. Uważaj tylko na obsesyjne myśli i słowne manipulacje.\n♀□♂ Wenus kwadratura Mars (22:37): Napięcie między planetami. Można je wykorzystać na namiętność, randki, taniec i twórczą energię. Uważaj na napięcie w związku i różnice potrzeb.","sourceText":{"holiday":"","namedays":"Marcelego, Włodzimierza","title":"Orion nad śniegiem","subtitle":"myśliwy zimowego nieba","story":"W styczniowe noce nad południowym horyzontem stoi Orion: trzy jasne gwiazdy pasa w rzędzie, nad nimi czerwonawy Betelgeza, pod nimi błękitny Rigel. Na wsiach mówiono na pas Oriona „kosy” albo „kosiarze”, bo gwiazdy przypominały ludzi idących z kosami. Niebo zimą jest najczystsze. Spójrz w górę, zanim wejdziesz do domu.","practice":"• Wyjdź po zmroku i znajdź trzy gwiazdy w rzędzie.\n• Poszukaj czerwonej gwiazdy nad nimi.\n• Pomyśl, ile nocy przed tobą ludzie patrzyli na ten sam obraz.","extraTitle":"Ciekawostka","extra":"Betelgeza to czerwony nadolbrzym, tak wielki, że w miejscu Słońca sięgnąłby poza orbitę Marsa.","whisper":"Gwiazdy są te same dla ciebie i dla twoich prababek.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":78}],["2027-01-17","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":68.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia · ♂ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Antoniego, Jana","title":"Wilkołak","subtitle":"człowiek pod wilczą skórą","story":"Mówiono, że ktoś może zamienić się w wilka. Czasem z własnej woli, przez czary, czasem rzucony urok zmuszał człowieka, by biegał z wilkami przez kilka lat. Taki wilk miał ludzkie oczy i omijał ludzi. Wracał do siebie, gdy ktoś rzucił mu kawałek chleba lub zdjął z niego czar. Wilkołak budził nie tylko strach, ale i litość.","practice":"• Pomyśl o kimś, kto ostatnio „zdziczał” z bólu.\n• Wyciągnij do niego rękę, choćby jednym zdaniem.\n• Daj dziś komuś kawałek chleba albo ciepłe słowo.","extraTitle":"Pytanie na niedzielę","extra":"Kiedy ostatnio zdziczałam i co pomogło mi wrócić?","whisper":"Pod najdzikszą skórą często kryje się ktoś, kto czeka na chleb.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":79}],["2027-01-18","conversation","☽ w Byku do 09:32, potem w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":79.0,"moonAndBiodynamic":"☽ w Byku do 09:32, potem w Bliźniętach · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Do 09:32 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 05:57 do 09:32: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Koziorożcu · ☿ w Wodniku · ♀ w Strzelcu · ♂ w Pannie. Pytanie tygodnia: Jaki cel budujesz krok po kroku?\n☿✶♄ Merkury sekstyl Saturn (19:05): Dobry dzień na skupioną pracę, umowy, planowanie i dokumenty.","sourceText":{"holiday":"","namedays":"Małgorzaty, Piotra","title":"Jemioła","subtitle":"wiecznie zielona strażniczka","story":"Styczniowe drzewa są nagie, a jemioła wciąż zielona jak w maju. Rośnie wysoko, na brzozach, topolach i jabłoniach, nie dotykając ziemi. Dla dawnych ludów była rośliną pomiędzy światami. Wieszano ją w domach jako ochronę przed piorunem i złymi mocami. Zimą widać, ile jej jest: zielone kule w koronach jak zawieszone gniazda.","practice":"• Wypatrz dziś jemiołę na drzewach podczas spaceru.\n• Policz zielone kule na jednym drzewie.\n• Pomyśl o czymś, co w tobie zostało zielone mimo zimy.","extraTitle":"Ciekawostka","extra":"Nasiona jemioły roznoszą ptaki, głównie jemiołuszki i paszkoty, które zjadają jej lepkie owoce.","whisper":"Zieleń zimą to dowód, że życie ma swoje sekrety.","caution":"Owoce jemioły są trujące. Nie stosuj jej wewnętrznie na własną rękę.","bibliography":"Rośliny niebezpieczne w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":80}],["2027-01-19","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":88.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Henryka, Marty","title":"Pierogi z kaszą i twarogiem","subtitle":"ruskie dawnego stołu","story":"Kasza gryczana z twarogiem i podsmażoną cebulą w cienkim cieście: tak wyglądały pierogi, zanim do farszu trafiły ziemniaki. Kasza była podstawą jedzenia przez wieki, sycąca i tania. Lepienie pierogów to praca, którą najlepiej robić razem: jedna osoba wałkuje, druga nakłada, trzecia zlepia, a wszystkie rozmawiają.","practice":"• Ugotuj szklankę kaszy gryczanej, wymieszaj z 250 g twarogu i cebulą.\n• Zrób ciasto z 500 g mąki, szklanki ciepłej wody i szczypty soli.\n• Lep pierogi z kimś, rozmawiając.","extraTitle":"Ciekawostka","extra":"Ziemniaki upowszechniły się w Polsce dopiero w XVIII wieku. Wcześniej to kasza rządziła w garnkach.","whisper":"Co się lepi razem, smakuje lepiej niż to, co lepione samotnie.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":81}],["2027-01-20","home","☽ w Bliźniętach do 10:21, potem w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":94.0,"moonAndBiodynamic":"☽ w Bliźniętach do 10:21, potem w Raku · dzień liścia · ♂ retro","goodFor":"dobry dzień na dom","energy":"Do 10:21 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 02:01 do 10:21: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉ Słońce wchodzi w Wodnika (08:29): Na miesiąc cały świat nabiera barw znaku Wodnika: czas przyjaźni, wolności, nowości i wspólnoty. Rada: spotkaj się z ludźmi i spróbuj czegoś nowego.","sourceText":{"holiday":"","namedays":"Fabiana, Sebastiana","title":"Okno na zachód","subtitle":"pożegnanie dnia","story":"Zimowe zachody słońca są krótkie i płonące. Niebo na moment robi się różowe, pomarańczowe, fioletowe, a potem nagle gaśnie. Dawniej o zmierzchu kończono pracę w polu i zapalano światło w chacie. Ten moment między dniem a nocą uchodził za szczególny: czas, gdy świat się zmienia. Zatrzymaj się w nim choć na chwilę.","practice":"• O zachodzie słońca podejdź do okna lub wyjdź na zewnątrz.\n• Popatrz, aż kolor zgaśnie.\n• Powiedz w myślach, co dobrego dał ci ten dzień.","extraTitle":"Ciekawostka","extra":"Zimą słońce zachodzi szybciej niż wiosną, bo przy niskim kącie „schodzi” pod horyzont pod innym nachyleniem.","whisper":"Każdy dzień zasługuje na pożegnanie, nawet szary.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":82}],["2027-01-21","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":98.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia · ♂ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 01:45 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Agnieszki, Jarosława","title":"Agnieszka i skowronek","subtitle":"pierwsze znaki wiosny","story":"Na świętą Agnieszkę, mówiło przysłowie, skowronek wylatuje z pierwszym śpiewem. To bardziej życzenie niż obserwacja, bo skowronki wracają zwykle w lutym. Ale ludzie w środku zimy potrzebowali obietnicy, że wiosna istnieje. Szukali jej znaków wszędzie: w dłuższym świetle, w pąkach, w głosach ptaków. Ty też poszukaj.","practice":"• Zapisz godzinę zachodu słońca i porównaj z grudniem.\n• Poszukaj na gałęziach nabrzmiałych pąków.\n• Posłuchaj ptaków rano: czy śpiewają inaczej niż w grudniu?","extraTitle":"Przysłowie","extra":"„Na świętą Agnieszkę wychodzi skowronek na pierwszą ścieżkę.”","whisper":"Wiosna zaczyna się od tego, że w nią uwierzysz.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":83}],["2027-01-22","creative","☽ w Raku do 09:45, potem we Lwie","pełnia",false,{"phase":"pełnia o 13:17","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Raku do 09:45, potem we Lwie · dzień owocu · ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Do 09:45 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu do 09:45: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉△♅ Słońce trygon Uran (03:18): Dobry dzień na nowości, zmianę rutyny i odważne pomysły.\n☉✶♆ Słońce sekstyl Neptun (09:29): Dobry dzień na intuicję, sztukę, medytację i pomoc innym.\n🌕 Pełnia we Lwie (13:17): Kulminacja w sprawach: radość, twórczość, dzieci, miłość. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Anastazego, Wincentego","title":"Pełnia w środku zimy","subtitle":"noc, w której wszystko widać","story":"Dziś pełnia. Śnieg odbija księżycowe światło tak, że w nocy widać ślady zwierząt i kształty drzew. W wierzeniach pełnia była czasem mocy dla zielarek i czarownic, ale też czasem, gdy najlepiej widać, kto się zbliża. Światło Księżyca nie grzeje, ale pokazuje. Zobacz dziś to, czego za dnia nie chcesz widzieć.","practice":"• Wyjdź na kilka minut w świetle pełni.\n• Zgaś w domu światła i popatrz, ile widać bez nich.\n• Zapisz jedną rzecz, którą widzisz dziś wyraźniej niż zwykle.","extraTitle":"Księżyc","extra":"pełnia 22 I, 13:17 · następny nów 6 II","whisper":"Księżyc nie grzeje, ale pokazuje. Czasem to ważniejsze.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":84}],["2027-01-23","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":99.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu · ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿✶♀ Merkury sekstyl Wenus (23:32): Dobry dzień na miłe rozmowy, komplementy, negocjacje i pisanie.","sourceText":{"holiday":"","namedays":"Ildefonsa, Rajmunda","title":"Brzoza zimą","subtitle":"biała panna lasu","story":"Zimą brzoza jest najjaśniejsza w lesie: biała kora na tle szarego nieba. W wierzeniach słowiańskich była drzewem kobiecym, opiekuńczym, związanym z wiosną i oczyszczeniem. Gałązkami brzozy chłostano się w bani, z jej soku robiono napój. Teraz śpi, ale pod korą już krąży życie. Za dwa miesiące popłynie sok.","practice":"• Podejdź do brzozy i dotknij jej kory.\n• Zobacz, jak łatwo łuszczy się jej cienka, papierowa warstwa.\n• Pomyśl, co w tobie śpi i czeka na wiosnę.","extraTitle":"Ciekawostka","extra":"Na korze brzozy pisano w dawnym Nowogrodzie listy i notatki. Zachowało się ponad tysiąc takich „gramot”.","whisper":"Najjaśniejsza w lesie jest ta, która przetrwała zimę bez liści.","caution":"","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":85}],["2027-01-24","organize","☽ we Lwie do 09:44, potem w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":95.0,"moonAndBiodynamic":"☽ we Lwie do 09:44, potem w Pannie · dzień korzenia · ♂ retro","goodFor":"dobry dzień na porządki","energy":"Do 09:44 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 00:33 do 09:44: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Rafała, Felicji, Franciszka","title":"Mróz","subtitle":"stary dziadek zimy","story":"Mróz w ludowych opowieściach był żywym dziadem z siwą brodą, który chodził po wsiach i stukał kijem w ściany, aż pękały belki. Gospodynie zapraszały go czasem do stołu na Wigilię, by nie zmroził zbóż wiosną. Z Mrozem trzeba było się dogadać, bo walczyć się nie dało. Jest w tym stara mądrość o rzeczach, których nie zmienisz.","practice":"• Ubierz się dziś cieplej, niż myślisz, że trzeba.\n• Zastanów się, z czym w życiu warto się dogadać zamiast walczyć.\n• Napisz to jednym zdaniem.","extraTitle":"Pytanie na niedzielę","extra":"Z czym walczę, choć mogłabym się dogadać?","whisper":"Mrozu nie przegonisz. Możesz tylko dobrze napalić w piecu.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":86}],["2027-01-25","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":89.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ♂ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 18:56 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wodniku · ☿ w Wodniku · ♀ w Strzelcu · ♂ w Pannie. Pytanie tygodnia: Z kim chcesz tworzyć przyszłość?\n☉☌♇ Słońce spotyka Plutona (09:01): Intensywny dzień przemiany. Wychodzi na jaw to, co ukryte. Rada: spójrz prawdzie w oczy i odpuść kontrolę.","sourceText":{"holiday":"","namedays":"Pawła, Miłosza","title":"Imbir","subtitle":"korzeń, który przyjechał z daleka","story":"Imbir przypłynął do Europy z Azji przez kupców i trafił do polskich pierników, nalewek i lekarstw już w średniowieczu. Był drogi, więc używano go od święta. Grzeje, pobudza krążenie, łagodzi mdłości. Zimą kawałek imbiru w herbacie z miodem i cytryną to mały ogień, który można wypić.","practice":"• Zetrzyj kawałek świeżego imbiru do kubka.\n• Zalej gorącą wodą, odczekaj 5 minut, dodaj miód i cytrynę.\n• Pij powoli, czując ciepło w gardle.","extraTitle":"Ciekawostka","extra":"Imbir był w średniowieczu jedną z najpopularniejszych przypraw Europy, obok pieprzu.","whisper":"Co przyjeżdża z daleka, czasem najlepiej ogrzewa.","caution":"Przy lekach przeciwkrzepliwych i kamicy żółciowej z umiarem.","bibliography":"Przyprawy w kuchni ludowej, IZPiTN 2026","bookKey":""},"sourceRow":87}],["2027-01-26","organize","☽ w Pannie, od 12:12 w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":81.0,"moonAndBiodynamic":"☽ w Pannie, od 12:12 w Wadze · dzień korzenia · ♂ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 12:12 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu do 12:12: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Tymoteusza, Michała","title":"Żur na zakwasie","subtitle":"zupa, która zaczyna się w słoju","story":"Żur zaczyna się od zakwasu z mąki żytniej i wody, z czosnkiem i skórką chleba, który kilka dni pracuje w cieple. Potem wystarczy wywar, majeranek, ziemniaki, kiełbasa albo grzyby. Kwaśny, gęsty, pachnący, był zupą biednych i bogatych. Zakwas trzymano w glinianym garnku. Nastaw go dziś, za kilka dni będzie gotowy.","practice":"• Wymieszaj 5 łyżek mąki żytniej razowej z 0,5 l ciepłej, przegotowanej wody.\n• Dodaj 2 ząbki czosnku, liść laurowy i skórkę chleba.\n• Przykryj płótnem i odstaw w ciepłe miejsce na 4–5 dni, mieszając codziennie.","extraTitle":"Ciekawostka","extra":"Żur był tak pospolity, że w Wielki Piątek symbolicznie go „pochowano”, kończąc post.","whisper":"Co kwaśne na początku, potrafi być najbardziej sycące.","caution":"Jeśli pojawi się pleśń, zakwas wylej.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":88}],["2027-01-27","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":72.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿☍♃ Merkury opozycja Jowisz (17:37): Napięcie między planetami. Można je wykorzystać na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości. Uważaj na obietnice bez pokrycia i przeoczone szczegóły.","sourceText":{"holiday":"","namedays":"Anieli, Jerzego","title":"Porządek w szafie zimy","subtitle":"co nosisz, a co tylko trzymasz","story":"Zimą ubrań jest najwięcej i najłatwiej zobaczyć, czego się nie używa. Dawniej odzienie szyto na lata, przerabiano, łatano, przekazywano dalej. Nic się nie marnowało. Rzeczy noszone przez kogoś przenosiły też jego cząstkę. Przejrzyj dziś jedną półkę. Oddaj to, co mogłoby komuś posłużyć lepiej niż tobie.","practice":"• Wyjmij z szafy wszystko z jednej półki.\n• Rzeczy nienoszone od roku odłóż do oddania.\n• Jedną rzecz, którą lubisz, załóż jutro.","extraTitle":"Pytanie do dziennika","extra":"Co trzymam z obowiązku, a co z miłości?","whisper":"Rzecz, której nie nosisz, czeka na kogoś innego.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":89}],["2027-01-28","relationships","☽ w Wadze, od 18:21 w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Wadze, od 18:21 w Skorpionie · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 18:21 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 08:46 do 18:21: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Walerego, Karola","title":"Ptaki w zimie","subtitle":"goście za oknem","story":"Ptaki przylatujące zimą pod okno uważano za posłańców. Sikorka stukająca w szybę zapowiadała wiadomość, a gil, czerwony jak żar, mróz. Gospodynie sypały ziarno na parapet, bo głodny ptak przy chacie był znakiem, że i ludziom trzeba się dzielić. Dziś to po prostu dobry uczynek, który wraca śpiewem na wiosnę.","practice":"• Wysyp ziarno słonecznika na karmnik lub parapet.\n• Obserwuj przez 5 minut, kto przylatuje.\n• Zapisz gatunki, które rozpoznałaś.","extraTitle":"Ciekawostka","extra":"Ptaków nie karm chlebem. Najlepsze są ziarna słonecznika, niesolony smalec i owoce.","whisper":"Kto karmi ptaki zimą, ten wiosną budzi się przy śpiewie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":90}],["2027-01-29","honesty","☽ w Skorpionie","III kwadra",false,{"phase":"III kwadra o 11:55","nextPhase":"nów za 8 dni","illumination":50.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀△♃ Wenus trygon Jowisz (03:13): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.","sourceText":{"holiday":"","namedays":"Franciszka, Józefa","title":"Kreda na progu","subtitle":"znaki, które trwają","story":"Znak napisany kredą na Trzech Króli powoli blednie, ale nie powinno się go zmywać. Miał chronić dom przez cały rok, aż do kolejnego święcenia. Gospodynie dodawały czasem kredowy krzyżyk na drzwiach obory i stajni. Dziś ostatnia kwadra: Księżyc maleje. Dobry czas, by sprawdzić, czy twoje znaki ochronne wciąż są na miejscu.","practice":"• Sprawdź znak nad drzwiami. Jeśli go nie ma, narysuj na nowo.\n• Pomyśl o trzech rzeczach, które chronią twój dom.\n• Podziękuj za każdą z nich.","extraTitle":"Ciekawostka","extra":"Kreda to skała z mikroskopijnych skorupek morskich organizmów sprzed milionów lat.","whisper":"Ochrona to nie znak na drzwiach. To uwaga, którą dajesz codziennie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":91}],["2027-01-30","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":40.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉✶♄ Słońce sekstyl Saturn (07:35): Dobry dzień na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach.","sourceText":{"holiday":"","namedays":"Macieja, Martyny","title":"Śnieg i ślady","subtitle":"list, który pisze las","story":"Na świeżym śniegu las pisze listy. Tu przebiegł lis, prosto, łapa za łapą. Tu sarna, tam zając z długimi skokami. Myśliwi i gospodarze umieli czytać te ślady jak książkę. Ktoś chodził nocą koło chaty? Śnieg wszystko zdradzi. Wyjdź i spróbuj przeczytać, kto był tu przed tobą.","practice":"• Po świeżym śniegu poszukaj tropów zwierząt.\n• Zrób zdjęcie i sprawdź, do kogo należą.\n• Zostaw obok swój ślad.","extraTitle":"Ciekawostka","extra":"Lis stawia tylne łapy dokładnie w śladach przednich, więc jego trop wygląda jak jedna linia kropek.","whisper":"Każdy zostawia ślady. Pytanie, czy chce, by ktoś je czytał.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":92}],["2027-01-31","travel","☽ w Skorpionie do 04:13, potem w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Skorpionie do 04:13, potem w Strzelcu · dzień owocu · ♂ retro","goodFor":"dobry dzień na podróże","energy":"Do 04:13 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Jana, Marceli, Ludwiki","title":"Herody","subtitle":"teatr, który chodzi po domach","story":"W styczniu po wsiach chodzili herodzi: przebierańcy z królem Herodem, Śmiercią z kosą, diabłem, żydem, żołnierzem i aniołem. Odgrywali krótkie przedstawienie, w którym Śmierć ścinała okrutnego króla, a diabeł porywał go do piekła. Widzowie się śmiali i bali jednocześnie. Najstarsze prawdy często przychodziły w przebraniu.","practice":"• Opowiedz komuś historię, która była dla ciebie lekcją.\n• Pośmiej się dziś z czegoś, czego się boisz.\n• Zapisz, kto w twoim życiu był „aniołem”, a kto „diabłem”.","extraTitle":"Pytanie na niedzielę","extra":"Jaką prawdę o sobie słyszę najlepiej, gdy podana jest w żartach?","whisper":"Najstraszniejsze prawdy przychodzą w kolorowym przebraniu.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":93}],["2027-02-01","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":23.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wodniku · ☿ w Rybach · ♀ w Strzelcu · ♂ w Pannie. Pytanie tygodnia: Z kim chcesz tworzyć przyszłość?\n☿ Merkury wchodzi w Ryby (02:25): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie intuicji, snów, duchowości i współczucia. Rada: odpocznij, pomedytuj, zapisuj sny. Uważaj na rozmycie, iluzje i ucieczkę od spraw.","sourceText":{"holiday":"","namedays":"Brygidy, Ignacego","title":"Podbiał","subtitle":"pierwszy złoty kwiat","story":"Zanim pojawią się liście, na gołej, gliniastej ziemi wyrastają żółte słoneczka podbiału. Kwitnie jako jeden z pierwszych, czasem jeszcze przy śniegu. Jego liście, od spodu białe i miękkie, przychodzą później. Od wieków był ziołem na kaszel i chrypkę. Nazwa mówi o białym spodzie liścia, jak o podszewce futra.","practice":"• Na spacerze wypatruj żółtych kwiatów na nasypach i skarpach.\n• Zapisz datę pierwszego zobaczonego kwiatu podbiału.\n• Pomyśl, co w tobie kwitnie, zanim pojawią się liście.","extraTitle":"Ciekawostka","extra":"Podbiał kwitnie, zanim wypuści liście. To dlatego dawni zielarze uważali go za roślinę „syna przed ojcem”.","whisper":"Nie czekaj, aż będziesz gotowa w całości. Zakwitnij tym, co masz.","caution":"Zawiera alkaloidy szkodliwe dla wątroby. Nie pij naparu długo ani w ciąży; współcześnie odradza się stosowanie wewnętrzne.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":94}],["2027-02-02","travel","☽ w Strzelcu, od 16:32 w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":15.0,"moonAndBiodynamic":"☽ w Strzelcu, od 16:32 w Koziorożcu · dzień owocu · ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 16:32 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 14:05 do 16:32: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿□♅ Merkury kwadratura Uran (13:17): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.","sourceText":{"holiday":"Matki Boskiej Gromnicznej","namedays":"Marii, Mirosława","title":"Gromnica","subtitle":"świeca przeciw burzy i wilkom","story":"Dziś święci się gromnice: grube, woskowe świece, które strzegą domu przez cały rok. Zapalano je w czasie burzy, stawiając w oknie, by piorun ominął chatę. Wkładano je w dłonie umierającym, by łatwiej przeszli na drugą stronę. Legenda mówi, że Matka Boża Gromniczna odpędza gromnicą wilki od wsi. To święto światła w samym środku zimy.","practice":"• Zapal dziś woskową świecę i pozwól jej świecić przez wieczór.\n• Kopcącym knotem gromnicy dawniej znaczono krzyż na belce sufitu. Narysuj go w myślach nad drzwiami.\n• Schowaj świecę na ciemne dni.","extraTitle":"Przysłowie","extra":"„Gdy na Gromniczną mróz, szykuj chłopie wóz. Gdy na Gromniczną leje, szykuj chłopie sanie.”","whisper":"Światło przechowane na trudny dzień jest więcej warte niż to zapalone bez potrzeby.","caution":"Świeca tylko pod nadzorem.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":95}],["2027-02-03","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 13:52 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus wchodzi w Koziorożca (15:30): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa. Uważaj na surowość wobec siebie i chłód.","sourceText":{"holiday":"św. Błażeja","namedays":"Błażeja, Oskara","title":"Jabłko świętego Błażeja","subtitle":"patron gardeł","story":"Święty Błażej leczy gardła. W jego dzień kapłan przykłada do szyi wiernych dwie skrzyżowane świece, a dawniej święcono też jabłka i chleb, które jedzono na zdrowie gardła. Legenda mówi, że Błażej uratował chłopca, który zadławił się ością. Środek zimy to czas kaszlu i chrypki. Dobry dzień, by zatroszczyć się o głos.","practice":"• Zjedz dziś jabłko powoli, z myślą o zdrowiu.\n• Wypij ciepłe mleko z miodem albo napar z szałwii.\n• Owiń szyję szalem, nawet w domu.","extraTitle":"Ciekawostka","extra":"Szałwia była dawnym ziołem na gardło. Jej łacińska nazwa Salvia pochodzi od „salvare”, czyli ratować.","whisper":"Głos, który się szanuje, mówi mniej, ale mocniej.","caution":"Szałwia nie w ciąży i przy padaczce.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":96}],["2027-02-04","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"tłusty czwartek","namedays":"Andrzeja, Józefa, Tytusa","title":"Pączki na tłusty czwartek","subtitle":"dzień, w którym wolno","story":"Kto w tłusty czwartek nie zje choć jednego pączka, temu, jak mówiono, nie będzie się wiodło. Dawne pączki były z ciasta chlebowego, nadziewane słoniną i smażone na smalcu. Słodkie, z konfiturą różaną, przyszły później. Ten dzień otwiera ostatki: czas obfitości przed postem. Zjedz dziś coś, co sprawi ci radość, bez liczenia.","practice":"• Upiecz albo kup pączka z konfiturą różaną.\n• Zjedz go powoli, przy stole, nie w biegu.\n• Podziel się drugim z kimś, kto go nie dostał.","extraTitle":"Przysłowie","extra":"„Powiedział Bartek, że dziś tłusty czwartek, a Bartkowa, że sprzedała krowę i ma na pączki gotowe.”","whisper":"Kto nie umie świętować, nie umie też pościć.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":97}],["2027-02-05","social","☽ w Koziorożcu do 05:28, potem w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Koziorożcu do 05:28, potem w Wodniku · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 05:28 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀□♆ Wenus kwadratura Neptun (18:34): Napięcie między planetami. Można je wykorzystać na romantyzm, sztukę, muzykę i współczucie. Uważaj na idealizowanie ludzi i rozczarowania.","sourceText":{"holiday":"św. Agaty · chleb i sól od ognia","namedays":"Agaty, Adelajdy","title":"Chleb świętej Agaty","subtitle":"ochrona przed ogniem","story":"W dzień świętej Agaty święcono chleb i sól. Kawałek tego chleba trzymano w domu przez cały rok, a gdy wybuchał pożar, rzucano go w płomienie, wierząc, że ogień przygaśnie. Agata była patronką od pożarów i od chorób piersi. Chleb i sól, najprostsze dary, znów okazywały się najsilniejsze.","practice":"• Odłóż dziś kromkę chleba i szczyptę soli w lnianym woreczku.\n• Schowaj je w kuchni na cały rok.\n• Sprawdź baterię w czujniku dymu.","extraTitle":"Ciekawostka","extra":"Chleb świętej Agaty dawano też w drogę i chorym na gardło.","whisper":"Najlepsza ochrona przed ogniem to chleb w szafce i czujnik dymu pod sufitem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":98}],["2027-02-06","social","☽ w Wodniku","nów",false,{"phase":"nów o 16:56","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🌑 Nów w Wodniku (16:56): Czas zasiewu w sprawach: przyjaciele, marzenia o przyszłości, wolność. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Doroty, Bogdana, Pawła","title":"Nów i pierwsze przebiśniegi","subtitle":"światło pod śniegiem","story":"Dziś nów. Ciemna noc, a pod śniegiem coś się już rusza. Przebiśniegi przebijają się przez zmarzniętą ziemię białymi kropelkami kwiatów. Mają w sobie coś z cudu: kwitną, gdy wszystko inne śpi. Nów to czas zasiewania intencji, przebiśnieg to dowód, że coś może się przebić nawet przez lód.","practice":"• Poszukaj przebiśniegów w parku lub ogrodzie.\n• Zapisz intencję na ten księżycowy miesiąc.\n• Pomyśl, przez jaki „lód” ty się dziś przebijasz.","extraTitle":"Księżyc","extra":"nów 6 II, 16:56 · pełnia 21 II, 00:23","whisper":"Nawet najdelikatniejszy kwiat przebije się przez lód, jeśli ma dość czasu.","caution":"Przebiśniegi są pod ochroną i są trujące. Tylko oglądaj.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":99}],["2027-02-07","social","☽ w Wodniku, od 17:31 w Rybach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Wodniku, od 17:31 w Rybach · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 17:31 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 02:46 do 17:31: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿☍♂ Merkury opozycja Mars (08:14): Napięcie między planetami. Można je wykorzystać na szybkie decyzje, debatę i załatwienie zaległości. Uważaj na kłótnie, ostre słowa i pośpiech w mailach.","sourceText":{"holiday":"","namedays":"Ryszarda, Teodora","title":"Mara","subtitle":"ta, która siada na piersi","story":"Budzisz się w nocy i nie możesz się ruszyć, jakby ktoś siedział ci na piersi. Dawniej mówiono, że to mara, zmora. Może nią być żywa kobieta, której dusza wychodzi nocą, albo duch. Mara plątała włosy i końskie grzywy. Na ochronę kładziono pod poduszkę nóż albo odwracano buty czubkami od łóżka.","practice":"• Przed snem przewietrz sypialnię.\n• Połóż buty czubkami od łóżka.\n• Gdy obudzisz się w nocy, zrób trzy długie wydechy.","extraTitle":"Fakt czy wiara?","extra":"Paraliż przysenny to znane zjawisko: mózg budzi się szybciej niż mięśnie. Dawniej tłumaczono go zmorą.","whisper":"Strach, który nazwiesz, traci połowę swojego ciężaru.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":100}],["2027-02-08","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 04:52 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wodniku · ☿ w Rybach · ♀ w Koziorożcu · ♂ w Pannie. Pytanie tygodnia: Z kim chcesz tworzyć przyszłość?\n♀△♂ Wenus trygon Mars (03:29): Dobry dzień na namiętność, randki, taniec i twórczą energię.\n♅ Uran rusza naprzód w Bliźniętach (13:29): Nagłe zwroty i nowości przyspieszają, zwłaszcza w technologii, informacji i podróżach. Rada: bądź elastyczna i miej plan B.\n☿✶♀ Merkury sekstyl Wenus (18:13): Dobry dzień na miłe rozmowy, komplementy, negocjacje i pisanie.","sourceText":{"holiday":"","namedays":"Hieronima, Sebastiana","title":"Kurdybanek","subtitle":"bluszczyk, który leczył","story":"Kurdybanek, czyli bluszczyk, płoży się po trawnikach i miedzach, a jego liście pachną ostro i ziołowo. Dawniej używano go w kuchni, do piwa i do leczenia ran. Wianki z kurdybanku zakładano w noc świętojańską, by zobaczyć czarownice. Jest wszędzie, a mało kto go zauważa. Ziele skromne, które wie więcej, niż pokazuje.","practice":"• Na spacerze rozpoznaj kurdybanek po okrągłych, karbowanych listkach.\n• Rozetrzyj liść w palcach i powąchaj.\n• Pomyśl o kimś cichym, kto wiele dla ciebie znaczy.","extraTitle":"Ciekawostka","extra":"Z kurdybankiem fermentuje się ocet jabłkowy, który nabiera ziołowego aromatu.","whisper":"Nie przeoczaj tych, którzy rosną cicho pod twoimi stopami.","caution":"Nie w ciąży; świeże ziele w dużych ilościach szkodzi zwierzętom.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":101}],["2027-02-09","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":8.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury rusza wstecz w Rybach (18:36): Przez trzy tygodnie łatwiej o pomyłki w rozmowach, umowach, mailach i podróżach. To dobry czas na powroty: do starych projektów, ludzi i notatek. Rada: sprawdzaj dwa razy, nie podpisuj w pośpiechu, rób kopie.","sourceText":{"holiday":"ostatki · kusaki","namedays":"Apoliny, Eryki, Cyryla","title":"Ostatki","subtitle":"noc przebierańców","story":"W ostatki, zwane kusakami, bawiono się do północy. Po wsiach chodzili przebierańcy: niedźwiedź, koza, bocian, konik. Śpiewali, tańczyli, zaczepiali dziewczęta. O północy muzyka milkła, bo zaczynał się post. Zabawa była pożegnaniem obfitości i ostatnią szansą na szaleństwo. Śmiech na koniec karnawału był jak napełnienie spiżarni na trudny czas.","practice":"• Zrób dziś coś szalonego i radosnego.\n• Potańcz, choćby sama w kuchni.\n• O północy odłóż to, z czego chcesz zrezygnować na post.","extraTitle":"Ciekawostka","extra":"Kusaki od słowa „kusy”, czyli krótki. To krótki czas przed postem.","whisper":"Zanim zaczniesz coś odejmować, pozwól sobie na pełnię.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":102}],["2027-02-10","start","☽ w Rybach do 03:48, potem w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":14.0,"moonAndBiodynamic":"☽ w Rybach do 03:48, potem w Baranie · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Do 03:48 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Popielec · początek Wielkiego Postu","namedays":"Elwiry, Jacka","title":"Popiół","subtitle":"Popielec","story":"Dziś posypuje się głowy popiołem. Prochem jesteś i w proch się obrócisz: najstarsza mądrość o kruchości życia. Popiół to też to, co zostaje po ogniu, czysty i lekki. Zielarki używały go do ługu i nawozu, gospodynie do prania. Post nie musi być karą. Może być ciszą, w której słychać, czego naprawdę potrzebujesz.","practice":"• Wybierz jedną rzecz, z której rezygnujesz na czas postu.\n• Zapisz, po co to robisz.\n• Zostaw w tym miejscu coś dobrego: spacer, książkę, ciszę.","extraTitle":"Ciekawostka","extra":"Popiół na Popielec pochodzi ze spalonych palm z poprzedniej Niedzieli Palmowej. Rok zatacza koło.","whisper":"Post nie odbiera. Robi miejsce.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":103}],["2027-02-11","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":22.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 22:48 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉☍♃ Słońce naprzeciw Jowisza (01:28): Szczodrość i przesada. Łatwo obiecać za dużo. Uwaga: trzymaj się budżetu i realnych planów.","sourceText":{"holiday":"","namedays":"Grzegorza, Lucjana","title":"Zakazy postne","subtitle":"czas pokory","story":"W poście milkły muzyka i śpiewy, odkładano wesela, nie urządzano zabaw. Jedzono żur, śledzie, kaszę, kapustę z olejem, a mięso i nabiał znikały ze stołów. Garnki szorowano, by nie został w nich ślad tłuszczu. Wierzono, że kto łamie post, ściąga na dom biedę. Post był dla ciała i duszy wiosennym oczyszczeniem.","practice":"• Zjedz dziś prosto: kasza, kapusta, olej lniany.\n• Wyszoruj garnek, którego dawno nie myłaś porządnie.\n• Wyłącz muzykę na godzinę i posłuchaj ciszy.","extraTitle":"Ciekawostka","extra":"Olej lniany i konopny był dawniej głównym tłuszczem postnym na polskiej wsi.","whisper":"Prostota oczyszcza bardziej niż najdroższa kuracja.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":104}],["2027-02-12","finances","☽ w Baranie do 11:44, potem w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Baranie do 11:44, potem w Byku · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na finanse","energy":"Do 11:44 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu do 11:44: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Radosława, Damiana","title":"Węgiel i kreda","subtitle":"czarne i białe znaki","story":"Węglem z pieca i święconą kredą rysowano znaki na drzwiach, belkach i powale. Czarny węgiel chronił przed urokiem, biała kreda przypominała o błogosławieństwie. Kawałek węgla wrzucano do wody, w której kąpano dziecko, by nie spojrzało na nie złe oko. Ogień zostawiał po sobie ochronę nawet wtedy, gdy wygasł.","practice":"• Weź kawałek węgla drzewnego lub ołówek.\n• Narysuj na kartce symbol, który dla ciebie znaczy „ochrona”.\n• Powieś go tam, gdzie spędzasz najwięcej czasu.","extraTitle":"Ciekawostka","extra":"Węgiel drzewny wciąż jest używany do pochłaniania zapachów i oczyszczania wody.","whisper":"Nawet po wygasłym ogniu zostaje coś, co cię chroni.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":105}],["2027-02-13","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":41.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀□♄ Wenus w napięciu z Saturnem (12:40): Chłód, poczucie samotności, ograniczony budżet. Uwaga: nie oceniaj związku w zły dzień.","sourceText":{"holiday":"","namedays":"Grzegorza, Katarzyny","title":"Wierzba","subtitle":"drzewo, które zakwita pierwsze","story":"Wierzby nad rzekami pierwsze budzą się z zimy. Ich srebrne bazie, miękkie jak kocie łapki, pojawiają się, gdy wokół jeszcze szaro. W wierzeniach wierzba była drzewem granicy, rosła nad wodą, a w jej dziuplach mieszkały diabły i biesy. Z jej gałązek robi się wielkanocne palmy. Kora wierzby to dawna aspiryna.","practice":"• Poszukaj wierzbowych bazi nad wodą.\n• Dotknij ich miękkiej sierści.\n• Zetnij jedną gałązkę i wstaw do wody.","extraTitle":"Ciekawostka","extra":"Kwas salicylowy, z którego zrobiono aspirynę, odkryto właśnie w korze wierzby.","whisper":"Pierwsze kwitną ci, którzy mają korzenie najbliżej wody.","caution":"Kora wierzby nie dla osób uczulonych na aspirynę.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":106}],["2027-02-14","finances","☽ w Byku, od 16:58 w Bliźniętach","I kwadra",true,{"phase":"I kwadra o 08:58","nextPhase":"pełnia za 7 dni","illumination":51.0,"moonAndBiodynamic":"☽ w Byku, od 16:58 w Bliźniętach · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 16:58 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 08:58 do 16:58: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Walentego","namedays":"Cyryla, Metodego","title":"Święty Walenty","subtitle":"patron zakochanych i chorych","story":"Dziś świętuje się miłość, ale w dawnej Polsce Walenty był przede wszystkim patronem chorych na padaczkę. Nazywano ją nawet „walentą”. Dopiero później, za sprawą zachodnich zwyczajów, został patronem zakochanych. Miłość i opieka nad cierpiącym nie są od siebie dalekie. Dziś także pierwsza kwadra: rośnie to, co karmisz.","practice":"• Napisz do kogoś, kogo kochasz, kilka konkretnych zdań.\n• Zadzwoń do kogoś, kto choruje.\n• Zrób coś czułego dla siebie.","extraTitle":"Pytanie na niedzielę","extra":"Kogo kocham tak, że troszczę się o niego, gdy jest słaby?","whisper":"Miłość widać najlepiej przy łóżku chorego.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":107}],["2027-02-15","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":63.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ☿ ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wodniku · ☿ w Rybach · ♀ w Koziorożcu · ♂ w Pannie. Pytanie tygodnia: Z kim chcesz tworzyć przyszłość?","sourceText":{"holiday":"","namedays":"Jowity, Faustyna","title":"Lukrecja","subtitle":"słodki korzeń","story":"Korzeń lukrecji jest słodszy od cukru, choć cukrem nie jest. Dawniej żuto go jak cukierek i dodawano do mieszanek na kaszel. Łagodzi gardło, a jego słodycz maskowała gorycz innych ziół. Na jarmarkach dzieci dostawały kawałki korzenia do ssania. Jest w nim coś z babcinej przebiegłości: lekarstwo przemycone w słodkim.","practice":"• Zaparz herbatkę z lukrecją, jeśli możesz ją pić.\n• Dodaj ją do mieszanki z gorzkimi ziołami.\n• Pomyśl, jak możesz podać komuś trudną prawdę łagodniej.","extraTitle":"Ciekawostka","extra":"Glicyryzyna z lukrecji jest około 50 razy słodsza od cukru.","whisper":"Gorzką prawdę łatwiej przełknąć, gdy podasz ją z odrobiną słodyczy.","caution":"Lukrecja podnosi ciśnienie i obniża potas. Nie przy nadciśnieniu, chorobach serca i nerek, w ciąży, nie długo.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":108}],["2027-02-16","conversation","☽ w Bliźniętach, od 19:38 w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":74.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 19:38 w Raku · dzień kwiatu · ☿ ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 19:38 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 15:49 do 19:38: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿☍♂ Merkury opozycja Mars (18:42): Napięcie między planetami. Można je wykorzystać na szybkie decyzje, debatę i załatwienie zaległości. Uważaj na kłótnie, ostre słowa i pośpiech w mailach.\n☿□♅ Merkury kwadratura Uran (23:38): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.","sourceText":{"holiday":"","namedays":"Danuty, Juliana","title":"Śledź w oleju z cebulą","subtitle":"postny przysmak","story":"Śledź był królem postu. Beczki śledzi przyjeżdżały z Bałtyku i trafiały na stoły od dworów po chaty. Moczony, pokrojony, z cebulą, olejem lnianym i ziemniakiem w mundurku dawał siłę na długie zimowe tygodnie. W ostatki „chowano śledzia”, a w Wielkanoc wieszano go na drzewie, bo przez post wszystkim już się przejadł.","practice":"• Wymocz 4 płaty śledzia w zimnej wodzie przez godzinę.\n• Pokrój w paski, przełóż cebulą i ziarnami gorczycy.\n• Zalej olejem lnianym, odstaw na noc.","extraTitle":"Ciekawostka","extra":"Wieszanie śledzia na drzewie w Wielki Piątek symbolizowało pożegnanie postu.","whisper":"Co pozwala przetrwać, nie musi być wykwintne.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":109}],["2027-02-17","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":84.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia · ☿ ♂ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 22:49 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♂□♅ Mars w napięciu z Uranem (07:33): Nerwowość, nagłe zrywy, ryzyko wypadków i kłótni. Uwaga: zwolnij przy maszynach i na drodze, nie decyduj w złości.","sourceText":{"holiday":"","namedays":"Aleksego, Łukasza","title":"List do siebie","subtitle":"rozmowa w poście","story":"Post to dobry czas na rozmowę z samą sobą. Dawniej robiono rachunek sumienia, ale można też napisać list. Do siebie sprzed roku albo do tej, którą będziesz jesienią. Papier cierpliwie wysłucha tego, czego nie mówisz nikomu. Kiedy zapiszesz myśli, przestają krążyć w głowie i stają się czymś, co można obejrzeć.","practice":"• Usiądź z kartką i długopisem na 15 minut.\n• Napisz list do siebie z listopada 2027.\n• Zaklej kopertę i podpisz datą, kiedy ją otworzysz.","extraTitle":"Pytanie do dziennika","extra":"Co chcę powiedzieć sobie za dziewięć miesięcy?","whisper":"Papier słucha lepiej niż połowa ludzi.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":110}],["2027-02-18","home","☽ w Raku, od 20:31 we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Raku, od 20:31 we Lwie · dzień liścia · ☿ ♂ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 20:31 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu do 20:31: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury cofa się do Wodnika (13:15): Ruchem wstecznym Merkury wraca do znaku Wodnika i każe dokończyć stare sprawy. Rada: wróć do rozpoczętych rozmów, zanim zaczniesz nowe.\n☉☌☿ Słońce koniunkcja Merkury (17:39): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.\n☉ Słońce wchodzi w Ryby (22:33): Na miesiąc cały świat nabiera barw znaku Ryb: czas intuicji, snów, duchowości i współczucia. Rada: odpocznij, pomedytuj, zapisuj sny.","sourceText":{"holiday":"","namedays":"Szymona, Konstancji","title":"Pierwszy grzmot","subtitle":"budzenie ziemi","story":"Pierwszy wiosenny grzmot budził ziemię. Kto go usłyszał, tarzał się w trawie albo uderzał głową o drzewo, by przez rok nie bolały go plecy ani głowa. Gospodynie dotykały wtedy kamieniem czoła. Wierzono, że od pierwszej burzy ziemia jest otwarta i można zaczynać prace. Luty jeszcze nie grzmi, ale już się przygotowuje.","practice":"• Zapisz w kalendarzu, kiedy usłyszysz pierwszy grzmot.\n• Wtedy dotknij drzewa i powiedz życzenie.\n• Dziś pomyśl, co w tobie czeka na pobudkę.","extraTitle":"Ciekawostka","extra":"Grzmot w lutym zdarza się rzadko. Mówiono, że wtedy wiosna będzie zimna.","whisper":"Ziemia budzi się z hukiem. Ty możesz obudzić się cicho.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":111}],["2027-02-19","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉☍♂ Słońce opozycja Mars (16:50): Napięcie między planetami. Można je wykorzystać na odważne decyzje, sport i ruszanie spraw z miejsca. Uważaj na złość, rywalizację i przeforsowanie się.","sourceText":{"holiday":"","namedays":"Arnolda, Józefa, Konrada","title":"Zamowa na gardło","subtitle":"szept nad chorym","story":"Szeptuchy zamawiały choroby gardła, przesuwając palcami po szyi chorego i szepcząc formuły. Odsyłały chorobę do wody, do lasu, na kamień, który nie czuje bólu. Do szeptu dodawały czasem ciepły okład z kaszy albo smarowały gardło smalcem z ziołami. Słowo i dotyk razem były najstarszym lekarstwem.","practice":"• Zrób ciepły okład z kaszy w lnianym woreczku i połóż na szyi.\n• Szepnij do siebie: „Odejdź na kamień, który nie boli”.\n• Wypij napar z szałwii lub tymianku.","extraTitle":"Ciekawostka","extra":"Okłady z ciepłej kaszy lub soli to stary domowy sposób na rozgrzewanie.","whisper":"Dotyk i słowo leczyły, zanim wymyślono apteki.","caution":"Zamowa to dziedzictwo kulturowe. Przy gorączce i silnym bólu gardła idź do lekarza.","bibliography":"Magia słowa, IZPiTN 2026","bookKey":""},"sourceRow":112}],["2027-02-20","creative","☽ we Lwie, od 20:59 w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ we Lwie, od 20:59 w Pannie · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 20:59 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 17:01 do 20:59: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉□♅ Słońce kwadratura Uran (16:10): Napięcie między planetami. Można je wykorzystać na nowości, zmianę rutyny i odważne pomysły. Uważaj na nagłe zwroty i decyzje pod wpływem impulsu.","sourceText":{"holiday":"półcieniowe zaćmienie Księżyca (noc 20/21 II)","namedays":"Leona, Ludomira","title":"Cień na Księżycu","subtitle":"noc zaćmienia","story":"W nocy z 20 na 21 lutego Księżyc wejdzie w półcień Ziemi. Nie zniknie, tylko lekko przyciemnieje, jakby ktoś zasłonił go mgiełką. Dawniej zaćmienia budziły lęk: mówiono, że smok albo wilk połyka Księżyc, i biło się w garnki, żeby go przepędzić. Dziś możemy po prostu patrzeć i dziwić się, że świat jest taki dokładny.","practice":"• Wyjdź w nocy i spójrz na Księżyc.\n• Porównaj jego jasność z innymi nocami.\n• Pomyśl, jaki cień przechodzi teraz przez twoje życie.","extraTitle":"Ciekawostka","extra":"Zaćmienie półcieniowe jest subtelne. Wielu ludzi w ogóle go nie zauważa.","whisper":"Nie każdy cień jest ciemnością. Niektóre są tylko mgiełką.","caution":"Na Księżyc można patrzeć bez osłony. Na Słońce nigdy.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":113}],["2027-02-21","organize","☽ w Pannie","pełnia",false,{"phase":"pełnia o 00:23","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🌕 Pełnia i półcieniowe zaćmienie Księżyca w Pannie (00:23): Kulminacja w sprawach: zdrowie, nawyki, praca. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.\n♂ Mars cofa się do Lwa (15:13): Wsteczny Mars wraca do poprzedniego znaku. Energia słabnie, za to jest czas na poprawki. Rada: dokończ, nie zaczynaj.","sourceText":{"holiday":"","namedays":"Roberta, Eleonory","title":"Topielica pod lodem","subtitle":"ta, która czeka w przeręblu","story":"Topielice mieszkały w rzekach i jeziorach. Piękne, blade, z mokrymi włosami, wabiły śpiewem i ciągnęły na dno. Zimą miały czekać pod lodem przy przeręblach. Ostrzegano dzieci, by nie wchodziły na zamarzniętą wodę. Dziś pełnia. W jej świetle lód błyszczy pięknie i zdradliwie. Topielica to stara opowieść o tym, że piękno bywa pułapką.","practice":"• Nie wchodź na zamarznięte rzeki i stawy.\n• Opowiedz dzieciom o topielicy, żeby pamiętały.\n• Popatrz na pełnię nad zamarzniętą wodą z bezpiecznego brzegu.","extraTitle":"Pytanie na niedzielę","extra":"Co mnie wabi pięknym głosem, a ciągnie w głąb?","whisper":"Nie każde piękne światło na wodzie jest odbiciem nieba.","caution":"Lód na zbiornikach bywa cienki nawet przy mrozie.","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":114}],["2027-02-22","organize","☽ w Pannie, od 22:44 w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Pannie, od 22:44 w Wadze · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 22:44 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 08:53 do 22:44: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Rybach · ☿ w Wodniku · ♀ w Koziorożcu · ♂ we Lwie. Pytanie tygodnia: Co podpowiada Ci intuicja?","sourceText":{"holiday":"","namedays":"Marty, Małgorzaty","title":"Mniszek","subtitle":"korzeń, który zna ziemię","story":"Mniszek, czyli mlecz, jest wszędzie. Przebija się przez asfalt, wraca, choćby go wyrywać. Jego korzeń, gorzki i mleczny, dawni zielarze cenili za działanie na wątrobę i trawienie. Na wiosnę jedzono młode liście, a z kwiatów robiono miód. Mniszek uczy, jak przetrwać: głęboko w ziemi i z odwagą do kwitnienia.","practice":"• Zaparz napar z suszonego korzenia mniszka.\n• Zapisz, w czym jesteś tak uparta jak mniszek.\n• Nie wyrywaj go w ogrodzie, bo pszczoły go kochają.","extraTitle":"Ciekawostka","extra":"Z prażonego korzenia mniszka robiono zastępczą „kawę”, gdy prawdziwej brakowało.","whisper":"Ten, kogo nie da się wyrwać, ma korzeń głębszy niż ci, którzy go wyrywają.","caution":"Nie przy kamicy żółciowej i niedrożności dróg żółciowych.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":115}],["2027-02-23","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ☿ ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Romany, Damiana","title":"Żur postny z grzybami","subtitle":"zupa Wielkiego Postu","story":"Post miał swój smak: żur na zakwasie, z suszonymi grzybami, czosnkiem i majerankiem, bez mięsa. Jadano go tak często, że pod koniec postu wszyscy mieli go dość i w Wielki Piątek wynoszono garnek, by go „pochować”. Ale w lutym, gdy na dworze szaro, kwaśna zupa z grzybami grzeje i daje siłę.","practice":"• Namocz garść suszonych grzybów na godzinę.\n• Ugotuj z nich wywar, dodaj zakwas żytni, czosnek i majeranek.\n• Podawaj z ziemniakami okraszonymi cebulą.","extraTitle":"Ciekawostka","extra":"Suszone grzyby były dawniej towarem tak cennym, że przyjmowano je jako zapłatę.","whisper":"W poście najlepiej smakuje to, co proste.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":116}],["2027-02-24","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":86.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ☿ ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Macieja, Marka","title":"Wiosenne porządki duszy","subtitle":"Maciej łamie lody","story":"Na świętego Macieja mówiono, że zima się kończy albo dopiero zaczyna. Przysłowie o Macieju, który łamie lody, było nadzieją. To dobry dzień, by rozbić własne lody: wysłać list, który czeka, zadzwonić, porozmawiać o czymś, o czym milczysz od zimy. Lód sam nie pęka. Potrzebuje ciepła albo ciosu.","practice":"• Wybierz jedną zamrożoną sprawę.\n• Zrób w niej jeden mały ruch.\n• Zapisz, jak się po tym czujesz.","extraTitle":"Przysłowie","extra":"„Na świętego Macieja zima się nam rozleje.”","whisper":"Lód nie pęka od czekania. Pęka od ciepła albo od uderzenia.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":117}],["2027-02-25","honesty","☽ w Wadze do 03:24, potem w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":78.0,"moonAndBiodynamic":"☽ w Wadze do 03:24, potem w Skorpionie · dzień liścia · ☿ ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 03:24 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Cezarego, Donata","title":"Bociany na dachu","subtitle":"szczęście, które przylatuje","story":"Bociany wracają na przełomie marca i kwietnia, ale już w lutym wypatruje się ich gniazd. Gniazdo na dachu chroniło przed piorunem i pożarem. Kto zobaczył pierwszego bociana w locie, miał mieć szczęśliwy rok, a kto stojącego, leniwy. Bocianów nie wolno było krzywdzić, bo przynoszą dzieci i urodzaj.","practice":"• Sprawdź, czy w twojej okolicy są bocianie gniazda.\n• Zapisz datę pierwszego bociana, którego zobaczysz.\n• Pomyśl, co chcesz, żeby przyniósł ci ten rok.","extraTitle":"Ciekawostka","extra":"Polska jest domem dla około jednej czwartej światowej populacji bociana białego.","whisper":"Szczęście najczęściej wraca tam, gdzie zostawiłaś mu gniazdo.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":118}],["2027-02-26","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":69.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ☿ ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Mirosława, Aleksandra","title":"Zioła na progu","subtitle":"straż przy drzwiach","story":"Pęczek suszonych ziół nad drzwiami był strażnikiem domu. Bylica, dziurawiec, ruta, czosnek, jałowiec: każda roślina miała swoją moc. Wiązano je czerwoną nicią i wymieniano co roku po święceniu. Wchodzący wnosił ze sobą zapach lata i opiekę. Zioła nie zastąpią zamka, ale przypominają, że dom to coś więcej niż ściany.","practice":"• Zwiąż z suszonych ziół mały pęczek.\n• Przewiąż czerwoną nitką.\n• Zawieś nad drzwiami wejściowymi.","extraTitle":"Ciekawostka","extra":"Ruta była ziołem panieńskim i ochronnym. Jej gałązka w wianku oznaczała czystość.","whisper":"Dom pachnący ziołami jest trudniejszy do przejęcia przez smutek.","caution":"Ruta może podrażniać skórę na słońcu.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":119}],["2027-02-27","travel","☽ w Skorpionie do 11:52, potem w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":58.0,"moonAndBiodynamic":"☽ w Skorpionie do 11:52, potem w Strzelcu · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na podróże","energy":"Do 11:52 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 07:35 do 11:52: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Gabriela, Anastazji","title":"Sikory i koniec zimy","subtitle":"piosenka „ci-ci-be”","story":"W lutym sikory zaczynają śpiewać inaczej: dźwięczne „ci-ci-be, ci-ci-be”. To znak, że wydłuża się dzień i ptaki szykują się do gniazd. Na wsiach mówiono, że sikora woła wiosnę i budzi ziemię. Dni są już dłuższe niż w grudniu o prawie trzy godziny. Wsłuchaj się rano: świat się zmienia.","practice":"• Rano otwórz okno i posłuchaj ptaków.\n• Rozpoznaj piosenkę sikory bogatki.\n• Sprawdź, o ile wydłużył się dzień od przesilenia.","extraTitle":"Ciekawostka","extra":"We Wrocławiu pod koniec lutego dzień trwa już prawie 11 godzin, prawie o 3 więcej niż w grudniu.","whisper":"Wiosnę słychać, zanim się ją zobaczy.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":120}],["2027-02-28","travel","☽ w Strzelcu","III kwadra",false,{"phase":"III kwadra o 06:16","nextPhase":"nów za 8 dni","illumination":48.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Romana, Ludomira","title":"Ostatnia niedziela lutego","subtitle":"rachunek zimy","story":"Luty się kończy, Księżyc jest w ostatniej kwadrze, a zima, choć jeszcze trzyma, nie ma już tej siły co w styczniu. To dobry dzień, by spojrzeć, co ci dała. Odpoczynek, cisza, czas z bliskimi albo trudności, przez które przeszłaś. Dawniej o tej porze liczono w spiżarni, ile zapasów zostało na przednówek.","practice":"• Sprawdź spiżarnię i zrób listę tego, co zostało.\n• Zapisz trzy rzeczy, które dała ci ta zima.\n• Ugotuj coś z tego, co zalega.","extraTitle":"Pytanie na niedzielę","extra":"Z czym wychodzę z tej zimy, czego w nią nie wnosiłam?","whisper":"Zima zawsze coś zabiera i zawsze coś zostawia. Policz jedno i drugie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":121}],["2027-03-01","travel","☽ w Strzelcu, od 23:35 w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":38.0,"moonAndBiodynamic":"☽ w Strzelcu, od 23:35 w Koziorożcu · dzień owocu · ☿ ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 23:35 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 17:19 do 23:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Rybach · ☿ w Wodniku · ♀ w Wodniku · ♂ we Lwie. Pytanie tygodnia: Co podpowiada Ci intuicja?\n♀ Wenus wchodzi w Wodnika (07:32): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie przyjaźni, wolności, nowości i wspólnoty. Rada: spotkaj się z ludźmi i spróbuj czegoś nowego. Uważaj na bunt dla buntu i dystans.","sourceText":{"holiday":"","namedays":"Albina, Antoniego","title":"Pokrzywa","subtitle":"parzy, bo chroni","story":"Pierwsze pokrzywy wychodzą z ziemi w marcu, jeszcze miękkie i jasne. Parzą, bo bronią się włoskami pełnymi kwasu, ale kto zna sposób, ma w nich skarb. Na przednówku ratowały przed głodem: zupa, placki, farsz. Pokrzywą chłostano się na reumatyzm, a jej włókno przędzono jak len. Roślina, która uczy, że ostrość bywa formą troski.","practice":"• Zbieraj tylko czubki młodych pędów, w rękawiczkach.\n• Zbieraj z dala od dróg i pól pryskanych.\n• Sparz liście wrzątkiem, a przestaną parzyć.","extraTitle":"Ciekawostka","extra":"Z włókna pokrzywy tkano dawniej płótno. W baśni Andersena siostra szyje z niej koszule dla braci-łabędzi.","whisper":"Ostrość, która chroni, nie jest złośliwością. Jest granicą.","caution":"Napar odwadnia. Ostrożnie przy niewydolności serca i nerek oraz przy lekach moczopędnych.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":122}],["2027-03-02","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":29.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀△♅ Wenus trygon Uran (22:00): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku.","sourceText":{"holiday":"","namedays":"Heleny, Halszki","title":"Kwas buraczany","subtitle":"czerwona moc przednówka","story":"W post i na przednówek w każdym domu stał gliniany garnek z kiszonymi burakami. Kwas buraczany był bazą barszczu, ale pito go też prosto z kubka, na wzmocnienie. Buraki, woda, sól, czosnek, skórka chleba żytniego i kilka dni cierpliwości. Ciemnoczerwony płyn wyglądał jak eliksir i trochę nim był.","practice":"• Obierz i pokrój w plastry 1 kg buraków.\n• Zalej przegotowaną wodą z łyżką soli na litr, dodaj czosnek i skórkę chleba.\n• Przykryj płótnem, odstaw na 5–7 dni. Zdejmuj kożuszek.","extraTitle":"Ciekawostka","extra":"Kwas buraczany przechowywany w chłodzie wytrzyma kilka tygodni. Na Wigilię zaczyna się go dawno przed świętami.","whisper":"To, co dojrzewa w ciszy, ma najgłębszy kolor.","caution":"Dużo soli. Ostrożnie przy nadciśnieniu.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":123}],["2027-03-03","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":21.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ☿ ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 02:37 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury rusza naprzód w Wodniku (13:32): Komunikacja się odblokowuje, choć przez kilka dni sprawy jeszcze się dopinają. Rada: wyślij to, co czekało, ale daj sobie dwa, trzy dni zapasu.","sourceText":{"holiday":"","namedays":"Maryny, Kunegundy","title":"Siew na parapecie","subtitle":"pierwsze ziarno roku","story":"W marcu na parapetach pojawiały się skrzynki z ziemią. Siano pomidory, papryki, kapustę na rozsadę. Ten gest ma w sobie coś z magii: wkładasz w ziemię niewidoczne ziarno i wierzysz, że wyjdzie życie. Wierzono, że siać trzeba przy przybywającym Księżycu, a nasiona trzymać przedtem w ciepłej dłoni.","practice":"• Kup lub wyjmij z zapasów nasiona jednej rośliny.\n• Wysiej je w doniczce na najjaśniejszym parapecie.\n• Codziennie rano sprawdź ziemię i powiedz coś do niej.","extraTitle":"Ciekawostka","extra":"Bazylia, pomidory i papryka siane w marcu będą gotowe do przesadzenia po zimnych ogrodnikach.","whisper":"Każdy wielki ogród zaczynał się od jednego ziarna w czyjejś ciepłej dłoni.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":124}],["2027-03-04","work","☽ w Koziorożcu, od 12:31 w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":14.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 12:31 w Wodniku · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 12:31 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu do 12:31: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♆ Wenus sekstyl Neptun (02:17): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.","sourceText":{"holiday":"","namedays":"Arkadiusza, Eugeniusza, Kazimierza","title":"Kaziuki","subtitle":"jarmark świętego Kazimierza","story":"Na świętego Kazimierza w Wilnie odbywał się wielki jarmark, Kaziuki. Sprzedawano wileńskie palmy z suszonych traw i kwiatów, pierniki w kształcie serc z lukrowanymi napisami, obwarzanki, gliniane garnki i wiklinę. Zwyczaj wywieziony po wojnie żyje dziś w Polsce, choćby w Białymstoku i na Pomorzu. Kazimierz to jedyny polski królewicz ogłoszony świętym.","practice":"• Upiecz piernikowe serce i napisz na nim lukrem jedno słowo.\n• Podaruj je komuś bez okazji.\n• Kup na targu coś zrobionego ręcznie.","extraTitle":"Przysłowie","extra":"„W marcu jak w garncu.”","whisper":"Słodkie słowo zapisane lukrem trwa dłużej niż wypowiedziane w biegu.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":125}],["2027-03-05","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":8.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Adriana, Fryderyka","title":"Czosnek","subtitle":"biały strażnik","story":"Czosnek odstraszał wszystko, co złe: wampiry, strzygi, choroby i urok. Wieszano warkocze czosnku w sieni, wkładano ząbek do kołyski i do wianka panny młodej. W Wigilię kładziono czosnek pod obrus. Medycyna ludowa ceniła go za siłę przeciw przeziębieniom i robakom. Jego zapach był jak mur, przez który zło nie przejdzie.","practice":"• Powieś w kuchni warkocz albo główkę czosnku.\n• Zjedz dziś ząbek posiekany na kanapce z masłem.\n• Posadź kilka ząbków w doniczce. Szczypior to wiosenna witamina.","extraTitle":"Ciekawostka","extra":"Allicyna, która daje czosnkowi zapach, powstaje dopiero, gdy ząbek się przekroi lub zgniecie.","whisper":"Nie każdy mur musi być z kamienia. Niektóre są z zapachu.","caution":"Czosnek wzmacnia działanie leków przeciwkrzepliwych.","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":126}],["2027-03-06","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 15:00 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀☌♇ Wenus koniunkcja Pluton (14:47): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach. Uważaj tylko na zazdrość i zaborczość.","sourceText":{"holiday":"","namedays":"Róży, Wiktora","title":"Szpaki wracają","subtitle":"pierwsi goście wiosny","story":"Na początku marca wracają szpaki. Siadają na drzewach i dachach, i naśladują wszystko: inne ptaki, skrzypienie bramy, dzwonek telefonu. Dawniej wieszano dla nich budki, bo wierzono, że szpak przy domu przynosi szczęście i wyjada robaki z ogrodu. Ich czarne pióra lśnią w słońcu zielenią i fioletem, jakby były malowane olejem.","practice":"• Posłuchaj ptaków w parku i spróbuj wyłowić szpaka.\n• Zawieś budkę lęgową, jeśli masz ogród lub balkon.\n• Zapisz, czym byś się chwaliła, gdybyś umiała naśladować jak szpak.","extraTitle":"Ciekawostka","extra":"Szpak potrafi wpleść w swój śpiew dźwięki karetki, kosiarki czy alarmu samochodowego.","whisper":"Kto słucha świata uważnie, w końcu śpiewa jego głosami.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":127}],["2027-03-07","rest","☽ w Wodniku do 00:25, potem w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Wodniku do 00:25, potem w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Do 00:25 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Tomasza, Felicyty","title":"Licho","subtitle":"nie wywołuj go z lasu","story":"Licho to drobny, chudy, jednooki demon nieszczęścia. Siedzi cicho za piecem albo w lesie i czeka, aż ktoś je zawoła. Stąd przysłowie: nie wywołuj licha z lasu. Wystarczy chwalić się szczęściem albo mówić o nieszczęściu na głos, by przyszło. I jeszcze jedno: licho nie śpi, więc trzeba uważać nawet wtedy, gdy wszystko idzie dobrze.","practice":"• Zauważ dziś, czy nie „wywołujesz licha” czarnymi myślami na głos.\n• Kiedy mówisz o czymś dobrym, odpukaj w niemalowane drewno.\n• Zapisz jedną rzecz, którą chronisz przez milczenie.","extraTitle":"Pytanie na niedzielę","extra":"O czym mówię głośno, choć lepiej byłoby to chronić ciszą?","whisper":"Szczęście lubi ciszę. Licho lubi przechwałki.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":128}],["2027-03-08","rest","☽ w Rybach","nów",true,{"phase":"nów o 10:29","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ♂ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 10:29 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Rybach · ☿ w Wodniku · ♀ w Wodniku · ♂ we Lwie. Pytanie tygodnia: Co podpowiada Ci intuicja?\n🌑 Nów w Rybach (10:29): Czas zasiewu w sprawach: intuicja, sny, odpoczynek, duchowość. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Beaty, Wincentego","title":"Fiołek wonny","subtitle":"kwiat kobiecy","story":"Fiołek wonny kwitnie w marcu pod krzakami i przy płotach. Jest mały, ale jego zapach słychać z daleka. W ziołolecznictwie używano go na kaszel i do oczyszczania skóry, a w perfumach od starożytności. Fiołkiem obdarowywano kobiety, a jego płatki kandyzowano w cukrze. Dziś Dzień Kobiet i nów: dobry czas, by zasadzić coś tylko dla siebie.","practice":"• Poszukaj fiołków w cieniu krzewów. Rozpoznasz je po zapachu.\n• Podaruj kobiecie, którą podziwiasz, kwiat i jedno zdanie.\n• Zapisz intencję na nowy księżycowy miesiąc.","extraTitle":"Księżyc","extra":"nów 8 III, 10:29 · pełnia 22 III, 11:43","whisper":"Mała rzecz o mocnym zapachu zostaje w pamięci dłużej niż wielki bukiet.","caution":"Korzeń fiołka w dużych dawkach wywołuje wymioty. Do herbatek tylko kwiaty i liście.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":129}],["2027-03-09","start","☽ w Rybach do 10:02, potem w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Rybach do 10:02, potem w Baranie · dzień owocu · ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Do 10:02 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu do 10:02: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Franciszki, Dominiki","title":"Kisiel żurawinowy","subtitle":"czerwony na wzmocnienie","story":"Kisiel z żurawiny gotowano na przednówku, gdy brakowało świeżych owoców. Suszona lub mrożona żurawina z jesieni, woda, miód i mąka ziemniaczana dawały gęsty, kwaśno-słodki napój, który grzał i wzmacniał. Żurawinę zbierano z torfowisk i przechowywano w wodzie przez całą zimę. Kwaśny smak na wiosnę budzi apetyt i ciało.","practice":"• Zagotuj szklankę żurawiny w 3 szklankach wody, przetrzyj.\n• Rozprowadź 2 łyżki mąki ziemniaczanej w zimnej wodzie i wlej, mieszając.\n• Gdy zgęstnieje, zdejmij z ognia i dosłódź miodem.","extraTitle":"Ciekawostka","extra":"Żurawina zawiera kwas benzoesowy, naturalny konserwant. Dlatego tak długo nie psuła się w wodzie.","whisper":"Kwaśne budzi. Słodkie usypia. Wiosną wybierz kwaśne.","caution":"Żurawina wchodzi w interakcję z warfaryną.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":130}],["2027-03-10","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Cypriana, Aleksandra","title":"Wymiatanie kątów","subtitle":"wiosna zaczyna się od miotły","story":"Przed Wielkanocą dom sprzątano od strychu do piwnicy. Bielono ściany, myto okna, wymiatano pajęczyny z kątów. Wierzono, że w kurzu i ciemnych zakamarkach chowa się zima i choroby. Śmieci wynoszono przez próg, nigdy nie zamiatano ich w stronę izby, by nie zmieść szczęścia. Sprzątanie było jak oddech domu po zimie.","practice":"• Wybierz jeden kąt, który omijasz od miesięcy.\n• Wymieć go, umyj i otwórz okno.\n• Śmieci wynieś od razu za próg, nie zostawiaj na noc.","extraTitle":"Ciekawostka","extra":"Zamiatano od drzwi do środka, gdy chciano zatrzymać szczęście, a od środka do drzwi, gdy chciano wymieść biedę.","whisper":"Kurz ma pamięć. Kiedy go wymieciesz, wymiatasz też stare myśli.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":131}],["2027-03-11","start","☽ w Baranie, od 17:16 w Byku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":11.0,"moonAndBiodynamic":"☽ w Baranie, od 17:16 w Byku · dzień owocu · ♂ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 17:16 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 06:06 do 17:16: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿☍♂ Merkury opozycja Mars (09:31): Napięcie między planetami. Można je wykorzystać na szybkie decyzje, debatę i załatwienie zaległości. Uważaj na kłótnie, ostre słowa i pośpiech w mailach.","sourceText":{"holiday":"","namedays":"Benedykta, Konstantego","title":"Czterdziestu Męczenników","subtitle":"czterdzieści dni pogody","story":"Dwa dni temu, 9 marca, wspominano czterdziestu męczenników z Sebasty, rzymskich żołnierzy, którzy zamarzli na jeziorze za wiarę. Na wsi wierzono, że jaka pogoda jest w ich dzień, taka będzie przez następne czterdzieści dni. Mróz zapowiadał długi przednówek, odwilż szybką wiosnę. Marcowa pogoda była wróżbą dla całego zasiewu.","practice":"• Zapisz, jaka była pogoda 9 marca.\n• Za czterdzieści dni sprawdź, czy wróżba się sprawdziła.\n• Pomyśl, co w tobie trwa mimo zimna.","extraTitle":"Ciekawostka","extra":"Męczennicy z Sebasty zginęli około 320 roku w dzisiejszej Turcji. Ich kult jest żywy w całej Europie Wschodniej.","whisper":"Pogoda zmienia się szybko. Wytrwałość zostaje.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":132}],["2027-03-12","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":18.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia · ♂ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Alojzego, Bernarda","title":"Szczypta soli","subtitle":"w kieszeni i w bucie","story":"Szczypta soli w kieszeni chroniła w drodze. Sól wsypywano do butów idących na jarmark, do kołyski, do koszyka z jajkami pod kurę. Rzucano ją przez lewe ramię, gdy się rozsypała, by oślepić diabła, który czai się z tyłu. Sól nie gnije i nie pozwala gnić. Była symbolem trwałości i czystości.","practice":"• Wsyp szczyptę soli do małego woreczka.\n• Noś ją przy sobie w trudny dzień.\n• Gdy rozsypiesz sól, rzuć szczyptę przez lewe ramię i uśmiechnij się.","extraTitle":"Ciekawostka","extra":"Angielskie „salary” pochodzi od łacińskiego salarium, słowa związanego z solą.","whisper":"Ochrona nie musi być wielka. Wystarczy, że jest przy tobie.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":133}],["2027-03-13","finances","☽ w Byku, od 22:30 w Bliźniętach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":27.0,"moonAndBiodynamic":"☽ w Byku, od 22:30 w Bliźniętach · dzień korzenia · ♂ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 22:30 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 14:32 do 22:30: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♄ Wenus sekstyl Saturn (12:01): Dobry dzień na trwałe zobowiązania, inwestycje i porządki w finansach.","sourceText":{"holiday":"","namedays":"Bożeny, Krystyny","title":"Wędrówki żab","subtitle":"noc na drodze","story":"W marcu, gdy w nocy robi się ciepło i wilgotno, żaby i ropuchy ruszają do stawów, w których się urodziły. Wędrują setkami, czasem przez drogi. Dawniej ropucha była zwierzęciem czarownic, ale też domowym strażnikiem, którego nie wolno było zabić. Wierzono, że kto skrzywdzi ropuchę, ściąga na siebie nieszczęście.","practice":"• Jeśli jedziesz wieczorem przy stawach, zwolnij.\n• Posłuchaj w nocy pierwszych żabich głosów.\n• Zapisz, dokąd ty wracasz co wiosnę.","extraTitle":"Ciekawostka","extra":"Ropuchy potrafią wrócić do tego samego stawu przez wiele lat, nawet z odległości ponad kilometra.","whisper":"Każdy ma swój staw, do którego wraca, gdy robi się cieplej.","caution":"Płazy są pod ochroną.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":134}],["2027-03-14","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":37.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Leona, Martyny","title":"Skrzat domowy","subtitle":"ubożę za piecem","story":"Skrzat, zwany też ubożęciem, mieszkał w domu za piecem albo w stodole. Jeśli go karmiono, przynosił zboże i pieniądze, pilnował koni i dobytku. Rozgniewany psuł mleko, plątał przędzę, tłukł garnki. Zostawiano mu na noc miseczkę mleka albo kaszy. Skrzat to strażnik domu, którego się nie widzi, a czuje.","practice":"• Zostaw dziś na noc w kuchni małą miseczkę z kaszą lub mlekiem.\n• Rano sprawdź, czy coś się zmieniło w domu.\n• Podziękuj domowi za to, że cię chroni.","extraTitle":"Pytanie na niedzielę","extra":"Kto w moim domu robi rzeczy, których nikt nie widzi?","whisper":"Dom, w którym ktoś dziękuje, jest pełniejszy niż dom, w którym wszystko jest oczywiste.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":135}],["2027-03-15","conversation","☽ w Bliźniętach","I kwadra",false,{"phase":"I kwadra o 17:25","nextPhase":"pełnia za 7 dni","illumination":48.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 21:52 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Rybach · ☿ w Wodniku · ♀ w Wodniku · ♂ we Lwie. Pytanie tygodnia: Co podpowiada Ci intuicja?","sourceText":{"holiday":"","namedays":"Longina, Klemensa","title":"Pąki topoli","subtitle":"balsam wiosny","story":"Pąki topoli czarnej, kleiste i żywiczne, pachną miodem i balsamem. Zbierano je wczesną wiosną, zanim się rozwiną, i robiono z nich maść na rany, oparzenia i bóle stawów. To z nich pszczoły biorą żywicę do propolisu. Kto rozetrze w palcach taki pąk, długo czuje jego zapach na dłoniach. Dziś pierwsza kwadra: czas budowania.","practice":"• Na spacerze poszukaj topoli i powąchaj jej pąki.\n• Rozetrzyj jeden w palcach.\n• Pomyśl, co w tobie klei się i pachnie, zanim się rozwinie.","extraTitle":"Ciekawostka","extra":"Propolis, czyli kit pszczeli, to w dużej mierze żywica z pąków topoli i brzozy.","whisper":"Najlepszy balsam robi się z tego, co jeszcze się nie rozwinęło.","caution":"Osoby uczulone na propolis mogą reagować na pąki topoli.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":136}],["2027-03-16","home","☽ w Bliźniętach do 02:10, potem w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":59.0,"moonAndBiodynamic":"☽ w Bliźniętach do 02:10, potem w Raku · dzień liścia · ♂ retro","goodFor":"dobry dzień na dom","energy":"Do 02:10 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀☍♃ Wenus opozycja Jowisz (13:04): Napięcie między planetami. Można je wykorzystać na relacje, randki, zakupy, umowy i świętowanie. Uważaj na rozrzutność i przejadanie się.","sourceText":{"holiday":"","namedays":"Izabeli, Oktawii","title":"Zupa z młodej pokrzywy","subtitle":"zielona siła przednówka","story":"Zupa pokrzywowa była pierwszą zieloną potrawą wiosny. Gotowano ją z młodymi pokrzywami, ziemniakami i zasmażką, a na koniec dodawano jajko na twardo. Na przednówku, gdy kończyły się zapasy, ratowała przed osłabieniem. Ma kolor intensywnej zieleni i smak, który trudno pomylić z innym: trochę szpinaku, trochę lasu.","practice":"• Zbierz w rękawiczkach garnek czubków pokrzywy, sparz wrzątkiem.\n• Ugotuj bulion z ziemniakami i cebulą, dodaj posiekane pokrzywy.\n• Gotuj 5 minut, dopraw, podawaj z jajkiem i śmietaną.","extraTitle":"Ciekawostka","extra":"Pokrzywa zawiera więcej żelaza i białka niż szpinak.","whisper":"Kiedy kończą się zapasy, ziemia zawsze daje coś zielonego.","caution":"Patrz uwaga przy pokrzywie (1 III).","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":137}],["2027-03-17","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":70.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia · ♂ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Patryka, Zbigniewa","title":"Kąpiel stóp","subtitle":"wieczór dla tych, które niosą","story":"Stopy niosą cię przez cały dzień, a rzadko dostają uwagę. Dawniej moczono je w ciepłej wodzie z solą, popiołem albo ziołami, na zmęczenie i przeziębienie. Mówiono, że przez stopy uchodzi i wchodzi choroba. Wieczorna kąpiel stóp to najprostszy rytuał uziemienia: ciepła woda, cisza, chwila bez ekranu.","practice":"• Napełnij miskę ciepłą wodą, dodaj garść soli i dwa liście laurowe.\n• Mocz stopy 15 minut z zamkniętymi oczami.\n• Po kąpieli wmasuj olej i włóż wełniane skarpety.","extraTitle":"Ciekawostka","extra":"Kąpiele stóp z gorczycą stosowano dawniej przy przeziębieniu i bólu głowy.","whisper":"Kto dba o swoje stopy, ten pewniej stąpa po świecie.","caution":"Nie przy cukrzycy z neuropatią, ranach stóp i żylakach bez konsultacji.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":138}],["2027-03-18","creative","☽ w Raku do 04:40, potem we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":80.0,"moonAndBiodynamic":"☽ w Raku do 04:40, potem we Lwie · dzień owocu · ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Do 04:40 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿ Merkury wchodzi w Ryby (11:01): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie intuicji, snów, duchowości i współczucia. Rada: odpocznij, pomedytuj, zapisuj sny. Uważaj na rozmycie, iluzje i ucieczkę od spraw.","sourceText":{"holiday":"","namedays":"Cyryla, Edwarda","title":"Chleb do góry spodem","subtitle":"nie odwracaj bochenka","story":"Chleba nie wolno kłaść na stole spodem do góry. Mówiono, że wtedy płacze, że diabeł na nim siada albo że z domu ucieka dostatek. Przed pierwszym kęsem bochenek żegnano nożem, a okruchy zbierano ze stołu do garści i wrzucano do ognia albo dawano ptakom. Chleb był świętością. Upadła kromka była podnoszona i całowana.","practice":"• Kładąc chleb, zwróć uwagę, jak leży.\n• Okruchy po śniadaniu daj ptakom.\n• Pomyśl o kimś, kto upiekł chleb, który dziś jesz.","extraTitle":"Ciekawostka","extra":"Zwyczaj całowania upuszczonego chleba przetrwał w wielu polskich domach do dziś.","whisper":"To, co cię karmi, zasługuje na szacunek nawet w drobnym geście.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":139}],["2027-03-19","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":88.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu · ♂ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 17:16 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀☍♂ Wenus naprzeciw Marsa (17:14): Przyciąganie i spór naraz. Różne potrzeby w związku. Rada: rozmawiaj o potrzebach, nie o winach.","sourceText":{"holiday":"św. Józefa","namedays":"Józefa, Bogdana","title":"Święty Józef","subtitle":"cieśla, który otwiera wiosnę","story":"Święty Józef był patronem cieśli, rodzin i dobrej śmierci. Na wsi jego dzień był znakiem wiosny: wtedy zaczynano myśleć o pierwszych pracach w polu. Według przysłowia Józef kiwnie brodą i zima spływa z wodą. Dobry dzień, by zrobić coś rękami: naprawić, skręcić, przybić. Rzeczy zrobione własnoręcznie mają w sobie ciepło.","practice":"• Napraw dziś jedną drobną rzecz w domu.\n• Pomyśl o kimś, kto troszczy się po cichu.\n• Podziękuj mu.","extraTitle":"Przysłowie","extra":"„Święty Józef kiwnie brodą, idzie zima na dół z wodą.”","whisper":"Opieka nie zawsze mówi. Czasem tylko naprawia.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":140}],["2027-03-20","organize","☽ we Lwie do 06:36, potem w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":95.0,"moonAndBiodynamic":"☽ we Lwie do 06:36, potem w Pannie · dzień korzenia · ♂ retro","goodFor":"dobry dzień na porządki","energy":"Do 06:36 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 10:33 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿□♅ Merkury kwadratura Uran (15:10): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.\n☉ Słońce wchodzi w Barana (21:24): Na miesiąc cały świat nabiera barw znaku Barana: czas odwagi, pośpiechu i nowych startów. Rada: zacznij to, co odkładasz, ale jedną rzecz naraz.","sourceText":{"holiday":"równonoc wiosenna, 21:25","namedays":"Klaudii, Eufemii","title":"Równonoc wiosenna","subtitle":"dzień równy nocy","story":"Dziś o 21:25 Słońce przechodzi przez równik niebieski. Dzień i noc są niemal równe. Od teraz światło będzie mocniejsze od ciemności aż do czerwca. Dawni Słowianie świętowali powrót słońca ogniem i hałasem, budząc ziemię. To moment równowagi, kiedy dobrze zapytać, czego jest w twoim życiu za dużo, a czego za mało.","practice":"• Wyjdź dziś o zachodzie słońca i popatrz, gdzie dokładnie zachodzi.\n• Zapisz dwie listy: czego za dużo, czego za mało.\n• Wybierz jedną rzecz do wyrównania.","extraTitle":"Ciekawostka","extra":"W równonoc Słońce wschodzi niemal dokładnie na wschodzie i zachodzi niemal dokładnie na zachodzie.","whisper":"Równowaga nie trwa długo. Dlatego warto ją zauważyć.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":141}],["2027-03-21","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":99.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ♂ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"pierwszy dzień wiosny · topienie Marzanny · Niedziela Palmowa","namedays":"Ludomira, Benedykta","title":"Marzanna i palmy","subtitle":"śmierć zimy, powitanie zieleni","story":"Dziś spotykają się dwa światy. Dawny: dzieci niosą słomianą Marzannę i topią ją w rzece, a z nią zimę, choroby i biedę. Wracają z gaikiem, zieloną gałązką przystrojoną wstążkami. I chrześcijański: Niedziela Palmowa, kiedy święci się palmy z wierzby, bazi i ziół. Połykano bazie dla zdrowia gardła. Jedna zieleń, dwie opowieści.","practice":"• Zrób małą kukłę ze słomy lub papieru i nazwij ją tym, co chcesz pożegnać.\n• Puść ją na wodę albo spal w bezpiecznym miejscu.\n• Wróć do domu z zieloną gałązką i wstaw ją do wody.","extraTitle":"Pytanie na niedzielę","extra":"Co dziś topię razem z zimą, a co przynoszę w zielonej gałązce?","whisper":"Każde pożegnanie robi miejsce na powitanie.","caution":"Nie wrzucaj do rzeki plastiku ani sztucznych materiałów.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":142}],["2027-03-22","relationships","☽ w Pannie do 09:01, potem w Wadze","pełnia",false,{"phase":"pełnia o 11:43","nextPhase":"nów za 16 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Pannie do 09:01, potem w Wadze · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 09:01 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu do 09:01: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Baranie · ☿ w Rybach · ♀ w Wodniku · ♂ we Lwie. Pytanie tygodnia: Co zaczynasz z odwagą?\n🌕 Pełnia w Wadze (11:43): Kulminacja w sprawach: związki, umowy, równowaga. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Katarzyny, Bogusława","title":"Bukszpan","subtitle":"zieleń święconki","story":"Bukszpan zielony przez cały rok był symbolem życia, które przetrwało zimę. Gałązkami bukszpanu przystrajano wielkanocne koszyki, palmy i pisanki, a dawniej też wianki weselne i trumny. Jest piękny, ale trujący, nie do jedzenia ani do herbat. Dziś pełnia na początku Wielkiego Tygodnia: światło na przygotowania.","practice":"• Ułóż na stole gałązkę bukszpanu lub innej zieleni.\n• Zrób listę tego, co chcesz przygotować na święta. Skróć ją o połowę.\n• Wieczorem spójrz na pełnię.","extraTitle":"Księżyc","extra":"pełnia 22 III, 11:43 · III kwadra 30 III, 02:54","whisper":"Nie wszystko, co pięknie zdobi, nadaje się do jedzenia.","caution":"Bukszpan jest trujący dla ludzi i zwierząt. Tylko do dekoracji.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":143}],["2027-03-23","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 15 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉✶♅ Słońce sekstyl Uran (09:06): Dobry dzień na nowości, zmianę rutyny i odważne pomysły.","sourceText":{"holiday":"","namedays":"Pelagii, Feliksa","title":"Babka drożdżowa","subtitle":"królowa wielkanocnego stołu","story":"Babkę piekło się z wielkim namaszczeniem. W kuchni panowała cisza, drzwi się nie otwierały, mężczyźni nie wchodzili, by ciasto nie opadło. Mówiono, że od udanej babki zależy powodzenie domu przez cały rok. Żółte od żółtek, pachnące wanilią i skórką cytrynową, wyrastało wysoko jak kapelusz.","practice":"• Zrób rozczyn z 50 g drożdży, mleka i łyżki cukru.\n• Utrzyj 8 żółtek z cukrem, dodaj 500 g mąki, rozczyn, 150 g masła, skórkę cytryny.\n• Wyrabiaj długo, wyrośnij w formie, piecz 45 min w 180 °C.","extraTitle":"Ciekawostka","extra":"Kiedy babka opadała, winą obarczano tego, kto trzasnął drzwiami albo zajrzał do pieca.","whisper":"Niektóre rzeczy rosną tylko w ciszy.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":144}],["2027-03-24","relationships","☽ w Wadze, od 13:18 w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Wadze, od 13:18 w Skorpionie · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 13:18 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 08:58 do 13:18: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Marka, Gabriela","title":"Pisanki z łupin cebuli","subtitle":"kolor ziemi i ognia","story":"Najstarsze pisanki barwiono tym, co rosło w zagrodzie. Łupiny cebuli dawały brąz i czerwień, kora dębu czerń, ozimina zieleń, kwiat bzu i jagody fiolet. Wzory rysowano gorącym woskiem, który chronił skorupkę przed barwnikiem. Jajko było symbolem życia i odrodzenia na długo przed chrześcijaństwem. Każdy wzór był modlitwą o urodzaj.","practice":"• Zbierz łupiny z kilku cebul i gotuj je 20 min w wodzie z octem.\n• Na jajka nanieś wzory rozgrzanym woskiem ze świecy, szpilką lub zapałką.\n• Gotuj jajka w wywarze, potem zetrzyj wosk.","extraTitle":"Ciekawostka","extra":"Najstarsza znaleziona w Polsce pisanka pochodzi z X wieku z Opola.","whisper":"Co rysujesz woskiem, zostaje jasne. Tak działa ochrona.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":145}],["2027-03-25","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉☌♆ Słońce spotyka Neptuna (00:12): Mniej energii, więcej wrażliwości i intuicji. Rada: wyśpij się, idź nad wodę. Uwaga: nie decyduj na ważne sprawy.","sourceText":{"holiday":"Zwiastowanie · Matki Boskiej Roztwornej · Wielki Czwartek","namedays":"Marioli, Wieńczysława","title":"Zwiastowanie i Wielki Czwartek","subtitle":"Matka Boża Roztworna","story":"Dziś Zwiastowanie, a na wsi Matka Boża Roztworna, która otwiera ziemię. Od tego dnia można było orać i siać. Bociany przylatywały, a ziemia oddychała. W tym roku to zarazem Wielki Czwartek: dzień Ostatniej Wieczerzy i milknących dzwonów. W niektórych wsiach dzieci wybijały kukłę Judasza, ciągnąc ją przez wieś i topiąc w wodzie.","practice":"• Dotknij dziś ziemi dłonią, gdziekolwiek jesteś.\n• Zjedz kolację w ciszy, przy świecy.\n• Pomyśl, kogo chcesz zaprosić do swojego stołu.","extraTitle":"Ciekawostka","extra":"Nazwa Roztworna mówi o otwieraniu: ziemi do orki, nieba dla ptaków, wody spod lodu.","whisper":"Ziemia otwiera się tylko dla tych, którzy cierpliwie czekali.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":146}],["2027-03-26","honesty","☽ w Skorpionie, od 20:43 w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":84.0,"moonAndBiodynamic":"☽ w Skorpionie, od 20:43 w Strzelcu · dzień liścia · ♂ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 20:43 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 04:04 do 20:43: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀ Wenus wchodzi w Ryby (09:16): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie intuicji, snów, duchowości i współczucia. Rada: odpocznij, pomedytuj, zapisuj sny. Uważaj na rozmycie, iluzje i ucieczkę od spraw.","sourceText":{"holiday":"Wielki Piątek","namedays":"Emanuela, Larysy, Teodora","title":"Woda przed świtem","subtitle":"Wielki Piątek","story":"W Wielki Piątek przed wschodem słońca szło się do strumienia lub rzeki, by obmyć twarz i ręce. Wierzono, że woda tego dnia ma moc oczyszczającą: zmywa choroby, wrzody i grzechy. Kąpano też dzieci i obmywano zwierzęta. Nikt nie pracował w polu, panowała cisza i post. Był to dzień najgłębszej żałoby i najczystszej wody.","practice":"• Rano przed świtem obmyj twarz zimną wodą.\n• Wypowiedz cicho, co chcesz zmyć.\n• Przez cały dzień zachowaj trochę ciszy.","extraTitle":"Ciekawostka","extra":"Woda bieżąca miała większą moc niż stojąca, bo „odnosiła” choroby daleko.","whisper":"Zimna woda o świcie mówi prawdę szybciej niż lustro.","caution":"Nie wchodź do zimnej rzeki. Obmycie twarzy wystarczy.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":147}],["2027-03-27","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":76.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉✶♇ Słońce sekstyl Pluton (17:30): Dobry dzień na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna.","sourceText":{"holiday":"Wielka Sobota · święconka","namedays":"Lidii, Ernesta","title":"Święconka","subtitle":"koszyk całego świata","story":"W koszyku na święconkę każda rzecz miała znaczenie. Jajko to nowe życie, chleb to dostatek, sól oczyszcza, chrzan daje siłę, kiełbasa zdrowie i płodność, ser przyjaźń z przyrodą, baranek zmartwychwstanie. Koszyk wyścielano białą serwetką i przystrajano bukszpanem. Po powrocie do domu nic ze święconki nie mogło się zmarnować.","practice":"• Przygotuj mały koszyk, nawet jeśli nie idziesz do kościoła.\n• Włóż do niego jajko, sól, chleb i coś zielonego.\n• Pomyśl przy każdej rzeczy, co dla ciebie symbolizuje.","extraTitle":"Ciekawostka","extra":"Skorupki ze święconych jajek zakopywano w ogrodzie, by ziemia lepiej rodziła.","whisper":"Koszyk święconki to cały świat w miniaturze. Zobacz, co w nim nosisz.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":148}],["2027-03-28","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":66.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ♂ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 14:39 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀□♅ Wenus kwadratura Uran (15:17): Napięcie między planetami. Można je wykorzystać na nowe znajomości, niespodzianki i zmianę wizerunku. Uważaj na nagłe zauroczenia i wydatki pod wpływem chwili.","sourceText":{"holiday":"Wielkanoc · zmiana czasu na letni","namedays":"Anieli, Jana","title":"Wielkanoc","subtitle":"dzielenie się jajkiem","story":"O świcie dzwony biły na rezurekcję. Śniadanie wielkanocne zaczynało się od podzielenia się jajkiem i życzeń, tak jak opłatkiem w Wigilię. Na stole żur, białe kiełbasy, jaja, chrzan, babka, mazurki. Dziś też zmiana czasu na letni: noc jest o godzinę krótsza. Światło wygrywa nie tylko symbolicznie, ale i na zegarze.","practice":"• Podziel się dziś jajkiem z kimś bliskim i złóż życzenia.\n• Przestaw zegarki o godzinę do przodu.\n• Wyjdź na zewnątrz w najjaśniejszej porze dnia.","extraTitle":"Pytanie na niedzielę","extra":"Co we mnie się dziś odradza?","whisper":"Każda wiosna jest dowodem, że po najciemniejszym dniu przychodzi światło.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":149}],["2027-03-29","work","☽ w Strzelcu do 08:33, potem w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":56.0,"moonAndBiodynamic":"☽ w Strzelcu do 08:33, potem w Koziorożcu · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Do 08:33 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu do 08:33: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Baranie · ☿ w Rybach · ♀ w Rybach · ♂ we Lwie. Pytanie tygodnia: Co zaczynasz z odwagą?","sourceText":{"holiday":"Poniedziałek Wielkanocny · śmigus-dyngus","namedays":"Wiktoryna, Helmuta","title":"Śmigus-dyngus","subtitle":"woda i rózga","story":"Dawniej to były dwa zwyczaje. Śmigus to smaganie rózgą wierzbową lub palmą, dyngus to oblewanie wodą albo wykupywanie się od niego pisankami. Chłopcy oblewali dziewczęta, a im więcej wody, tym większe powodzenie panny. Następnego dnia dziewczęta mogły się odwdzięczyć. Woda niosła zdrowie, rózga budziła siłę.","practice":"• Pokrop kogoś bliskiego kilkoma kroplami wody, z uśmiechem.\n• Wymień się pisanką z kimś, kogo lubisz.\n• Nie oblewaj nikogo, kto tego nie chce.","extraTitle":"Ciekawostka","extra":"Dawniej dziewczęta, których nikt nie oblał, czuły się zawiedzione. Brak wody oznaczał brak zainteresowania.","whisper":"Radość jest najlepsza wtedy, gdy obie strony się śmieją.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":150}],["2027-03-30","work","☽ w Koziorożcu","III kwadra",false,{"phase":"III kwadra o 02:54","nextPhase":"nów za 8 dni","illumination":46.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 18:12 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Anieli, Leonarda","title":"Jajka z rzeżuchą i chrzanem","subtitle":"po świętach","story":"Po świętach zawsze zostają jajka. Dawniej żadne się nie marnowało: robiono pasty, sałatki, jajka w sosie chrzanowym. Rzeżucha, którą siało się przed świętami na talerzyku, dawała ostrą, świeżą zieleń. To dobra pora, by zjeść coś prostego i lekkiego po obfitości stołu. Księżyc maleje: czas na odpuszczanie.","practice":"• Posiekaj 4 jajka na twardo, wymieszaj z łyżką chrzanu i jogurtem.\n• Dopraw solą i pieprzem.\n• Posyp obficie rzeżuchą i podawaj na chlebie żytnim.","extraTitle":"Ciekawostka","extra":"Rzeżucha wyrasta w kilka dni na wilgotnej wacie lub ligninie. To najszybszy ogród świata.","whisper":"Po obfitości przychodzi czas na prostotę. Obie są potrzebne.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":151}],["2027-03-31","work","☽ w Koziorożcu, od 21:19 w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":37.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 21:19 w Wodniku · dzień korzenia · ♂ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 21:19 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu do 21:19: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Beniamina, Balbiny","title":"Skorupki w ogrodzie","subtitle":"resztki, które rodzą","story":"Skorupki ze święconych jajek nie lądowały w śmieciach. Zakopywano je w ogrodzie, w rogach pola, pod drzewami owocowymi, by ziemia rodziła, a kret i zaraza omijały zagony. Wkładano je też do wody dla zwierząt. Popiół z palmy, kości z wielkanocnej szynki, wszystko wracało do ziemi. Nic ze świętego nie mogło się zmarnować.","practice":"• Zbierz skorupki po świętach i wysusz je.\n• Rozkrusz i wsyp do doniczki albo zakop w ogrodzie.\n• Pomyśl, co z twoich resztek może jeszcze coś urodzić.","extraTitle":"Ciekawostka","extra":"Skorupki jaj są źródłem wapnia dla roślin, zwłaszcza dla pomidorów.","whisper":"To, co wydaje się końcem, w ziemi staje się początkiem.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":152}],["2027-04-01","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":27.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ♂ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂ Mars rusza naprzód we Lwie (16:08): Energia wraca. To, co stało od zimy, może ruszyć z miejsca. Rada: wybierz jeden cel i ruszaj, stopniowo przyspieszając.","sourceText":{"holiday":"","namedays":"Grażyny, Ireny","title":"Prima aprilis","subtitle":"dzień, w którym nikomu nie wierz","story":"Prima aprilis przyszedł do Polski z Zachodu w średniowieczu i szybko się przyjął. Mówiono: prima aprilis, uważaj, bo się pomylisz. Wymyślano listy z dziwnymi wieściami, wysyłano kogoś po coś, co nie istnieje. Śmiech był sposobem na przednówek. Dzień kłamstewek przypomina, że warto sprawdzać, zanim się uwierzy.","practice":"• Zrób komuś niewinny żart, który rozśmieszy, nie zrani.\n• Sprawdź dziś jedną wiadomość, zanim ją podasz dalej.\n• Pośmiej się z siebie.","extraTitle":"Ciekawostka","extra":"Już w XVII wieku pisano w Polsce o zwyczaju wprowadzania w błąd pierwszego kwietnia.","whisper":"Kto umie się śmiać z siebie, tego trudniej oszukać.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":153}],["2027-04-02","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":19.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 15:28 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Władysława, Franciszka","title":"Palma za obrazem","subtitle":"przeciw piorunom","story":"Poświęconą palmę przynoszono do domu i zatykano za święty obraz albo pod strzechę. Chroniła przed piorunem, pożarem i chorobą. W czasie burzy kawałek palmy palono w piecu, a dym miał odpędzić nawałnicę. Bazie z palmy dawano zwierzętom, by były zdrowe. Gałązka wierzby zostawała w domu aż do następnej Niedzieli Palmowej.","practice":"• Wstaw zieloną gałązkę z palmy lub wierzby za obraz albo nad drzwi.\n• Zostaw ją tam na cały rok.\n• Przy pierwszej burzy przypomnij sobie, że tam jest.","extraTitle":"Ciekawostka","extra":"Spalone stare palmy dają popiół na następny Popielec. Koło roku się zamyka.","whisper":"Ochrona, którą przynosisz do domu, działa, dopóki o niej pamiętasz.","caution":"Nie pal niczego w domu bez kominka.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":154}],["2027-04-03","rest","☽ w Wodniku do 09:25, potem w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Wodniku do 09:25, potem w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Do 09:25 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu do 09:25: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♃△♄ Jowisz w harmonii z Saturnem (14:59): Rzadki, dobry układ dla mądrych planów: rozwój idzie w parze z rozsądkiem. Rada: buduj coś na lata: firmę, oszczędności, umiejętność.","sourceText":{"holiday":"","namedays":"Ryszarda, Ireny","title":"Zawilce","subtitle":"białe kobierce lasu","story":"W kwietniu lasy liściaste pokrywają się białymi zawilcami. Kwitną, zanim drzewa wypuszczą liście, by złapać światło, które za kilka tygodni zniknie pod koronami. Ich płatki zamykają się na noc i przed deszczem. Zawilec jest piękny i trujący. Pokazuje, że w lesie wszystko ma swój czas, i trzeba się spieszyć, gdy przychodzi.","practice":"• Wybierz się do lasu liściastego i zobacz zawilcowy dywan.\n• Usiądź na chwilę i posłuchaj.\n• Pomyśl, co ty robisz teraz, zanim zamkną się nad tobą liście.","extraTitle":"Ciekawostka","extra":"Zawilec gajowy kwitnie tylko kilka tygodni, a resztę roku przesypia pod ziemią jako kłącze.","whisper":"Twój czas światła nie trwa wiecznie. Kwitnij, póki drzewa są nagie.","caution":"Zawilec jest trujący. Nie zrywaj go i nie dotykaj oczu po kontakcie z sokiem.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":155}],["2027-04-04","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Benedykta, Izydora","title":"Biała Niedziela","subtitle":"koniec Wielkanocy","story":"Pierwszą niedzielę po Wielkanocy nazywano przewodnią albo białą. Biała od szat, w których dawniej chodzili nowo ochrzczeni, przewodnia, bo zamyka okres świąt. Na wsiach odwiedzano się, chodzono na groby, a w niektórych regionach składano wizyty chrzestnym. Po święcie przychodził zwykły czas, ale z nową siłą.","practice":"• Odwiedź albo zadzwoń do kogoś, kto był dla ciebie przewodnikiem.\n• Podziękuj mu za coś konkretnego.\n• Zjedz ostatni kawałek świątecznego ciasta z uwagą.","extraTitle":"Pytanie na niedzielę","extra":"Kto przeprowadził mnie przez coś ważnego?","whisper":"Świętowanie jest pełne dopiero wtedy, gdy umiesz je zakończyć.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":156}],["2027-04-05","rest","☽ w Rybach, od 18:48 w Baranie","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Rybach, od 18:48 w Baranie · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 18:48 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 07:21 do 18:48: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Baranie · ☿ w Rybach · ♀ w Rybach · ♂ we Lwie. Pytanie tygodnia: Co zaczynasz z odwagą?","sourceText":{"holiday":"","namedays":"Katarzyny, Wincentego","title":"Podagrycznik","subtitle":"chwast, który leczy","story":"Podagrycznik to zmora ogrodników. Rozrasta się wszędzie i nie da się go wyplenić. Ale jego młode listki, zbierane w kwietniu, smakują jak marchew z pietruszką i od średniowiecza leczyły podagrę, czyli dnę moczanową. Dlatego tak się nazywa. Mnisi sadzili go przy klasztorach. Czasem to, co nas denerwuje, okazuje się lekarstwem.","practice":"• Rozpoznaj podagrycznik po liściach złożonych z trzech listków.\n• Zbierz garść młodych liści i dodaj do sałatki.\n• Zastanów się, kto w twoim życiu jest „podagrycznikiem”.","extraTitle":"Ciekawostka","extra":"Podagrycznik jest spokrewniony z marchwią, pietruszką i koprem, wszyscy należą do selerowatych.","whisper":"Nie wszystko, czego nie możesz się pozbyć, jest twoim wrogiem.","caution":"Myli się go z trującymi selerowatymi. Zbieraj tylko, gdy jesteś pewna.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":157}],["2027-04-06","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":0.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Izoldy, Ireneusza","title":"Twarożek ze szczypiorkiem","subtitle":"wiosenne śniadanie","story":"Kiedy zielenieje szczypiorek i pojawiają się pierwsze rzodkiewki, na stole wraca twarożek. Biały ser, śmietana, szczypior, sól, pieprz i chleb żytni. Proste śniadanie, które przez wieki jadano na wsi wiosną, gdy krowy zaczynały dawać więcej mleka po wyjściu na pastwisko. Smak zieleni i bieli, jak łąka z kwiatami.","practice":"• Rozgnieć 250 g twarogu z 3 łyżkami śmietany.\n• Dodaj posiekany pęczek szczypiorku i pokrojone rzodkiewki.\n• Dopraw solą, pieprzem, podawaj na chlebie z masłem.","extraTitle":"Ciekawostka","extra":"Szczypiorek był dawniej sadzony przy domu, bo wierzono, że chroni przed złymi duchami.","whisper":"Najprostsze śniadania zostają w pamięci najdłużej.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":158}],["2027-04-07","start","☽ w Baranie","nów",false,{"phase":"nów o 01:51","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 09:21 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🌑 Nów w Baranie (01:51): Czas zasiewu w sprawach: odwaga, pierwszy krok, własna siła. Rada: zapisz intencję na ten księżycowy miesiąc.\n☉△♃ Słońce trygon Jowisz (04:18): Dobry dzień na optymizm, prośby, oferty, naukę i podróże.\n☉☌♄ Słońce spotyka Saturna (19:18): Dzień powagi, obowiązków i rozliczeń. Rada: zrób to, co trudne, ale ważne. Uwaga: nie bądź zbyt surowa dla siebie.","sourceText":{"holiday":"","namedays":"Rufina, Donata","title":"Nów kwietniowy","subtitle":"sadzenie intencji","story":"Dziś w nocy nów. Wiosenny nów jest najlepszym czasem, by coś zasadzić, dosłownie i w przenośni. Dawni ogrodnicy siali przy przybywającym Księżycu rośliny, które rosną nad ziemią, a przy ubywającym te, które rosną w głąb. Wybierz ziarno i intencję i posadź je razem. Ziemia pamięta.","practice":"• Napisz na małej karteczce jedną intencję.\n• Posadź w doniczce nasiono i wsuń karteczkę pod ziemię.\n• Podlewaj codziennie przez ten księżycowy miesiąc.","extraTitle":"Księżyc","extra":"nów 7 IV, 01:51 · pełnia 21 IV, 00:27","whisper":"Intencja zasadzona w ziemi rośnie wolniej, ale mocniej.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":159}],["2027-04-08","finances","☽ w Baranie do 01:09, potem w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Baranie do 01:09, potem w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Do 01:09 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Dionizego, Julii","title":"Pierwsza jaskółka","subtitle":"wiosna na skrzydłach","story":"Jaskółki wracają w kwietniu. Pierwszą jaskółkę witano z radością: kto ją zobaczył, mył twarz w wodzie, by mieć piękną cerę, albo potrząsał pieniędzmi. Jaskółka pod strzechą chroniła dom przed piorunem i pożarem. Kto zniszczył jej gniazdo, ściągał nieszczęście. Mówiono jednak: jedna jaskółka wiosny nie czyni.","practice":"• Wypatruj jaskółek nad wodą i polami.\n• Zapisz datę pierwszej, którą zobaczysz.\n• Pomyśl, na co czekasz, choć pierwsze znaki już są.","extraTitle":"Przysłowie","extra":"„Jedna jaskółka wiosny nie czyni.”","whisper":"Jeden znak to nadzieja. Dopiero wiele znaków to zmiana.","caution":"Gniazda jaskółek są chronione prawem.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":160}],["2027-04-09","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":7.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 14:22 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury wchodzi w Barana (01:20): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie odwagi, pośpiechu i nowych startów. Rada: zacznij to, co odkładasz, ale jedną rzecz naraz. Uważaj na łatwe kłótnie i nieprzemyślane ruchy.","sourceText":{"holiday":"","namedays":"Marii, Dymitra","title":"Kij leszczynowy","subtitle":"przeciw żmijom i złym duchom","story":"Leszczyna była drzewem mądrości i ochrony. Kijem leszczynowym zakreślano wokół siebie koło, przez które nie przejdą węże ani złe duchy. Różdżkarze używali rozwidlonej gałązki leszczyny, by szukać wody. Gałązki zatykano w pola przeciw gradowi. Orzechy laskowe były symbolem płodności i dawano je na weselach.","practice":"• Znajdź na spacerze leszczynę i zobacz jej kotki.\n• Zabierz gałązkę i postaw w domu.\n• Zakreśl wokół siebie koło i powiedz: tu jest moje miejsce.","extraTitle":"Ciekawostka","extra":"Leszczyna kwitnie bardzo wcześnie, czasem już w lutym. Jej żółte kotki to kwiaty męskie.","whisper":"Mądrość czasem wyznacza granicę jednym ruchem kija.","caution":"","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":161}],["2027-04-10","conversation","☽ w Byku do 05:21, potem w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":14.0,"moonAndBiodynamic":"☽ w Byku do 05:21, potem w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Do 05:21 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿✶♅ Merkury sekstyl Uran (22:54): Dobry dzień na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania.","sourceText":{"holiday":"","namedays":"Michała, Makarego","title":"Tarnina","subtitle":"biała chmura na miedzy","story":"Tarnina kwitnie w kwietniu, zanim wypuści liście. Kolczaste krzewy na miedzach i skrajach lasu pokrywają się białymi kwiatami, jakby spadł późny śnieg. Jej owoce, granatowe i cierpkie, zbiera się dopiero po pierwszych przymrozkach. Kolce tarniny chroniły zagrody, a czarownicom przypisywano różdżki z jej drewna.","practice":"• Wypatruj białych krzewów na miedzach.\n• Zapamiętaj, gdzie rosną. Jesienią wróć po owoce.\n• Pomyśl, co w tobie kwitnie, choć wciąż masz kolce.","extraTitle":"Ciekawostka","extra":"Tarninówka, nalewka z owoców tarniny, była dawniej lekarstwem na biegunkę.","whisper":"Nawet najbardziej kolczasty krzew ma swój czas kwitnienia.","caution":"","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":162}],["2027-04-11","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":23.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 18:10 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉△♂ Słońce trygon Mars (17:25): Dobry dzień na odważne decyzje, sport i ruszanie spraw z miejsca.\n☿☌♆ Merkury spotyka Neptuna (19:54): Wyobraźnia kwitnie, ale fakty się rozmywają. Rada: pisz, maluj, śnij. Uwaga: nie podpisuj umów.","sourceText":{"holiday":"","namedays":"Filipa, Leona","title":"Boginki","subtitle":"te, które podmieniają dzieci","story":"Boginki mieszkały nad wodą, w bagnach i jarach. Były blade, z wielkimi piersiami i długimi włosami. Kradły niemowlęta, a w ich miejsce kładły odmieńca, brzydkie i płaczliwe dziecko. Najbardziej narażone były matki przed wywodem. Chroniły je czerwone wstążki, czosnek, żelazo pod poduszką. Boginki to dawny lęk przed tym, co zagraża najbezbronniejszym.","practice":"• Zawiąż czerwoną nić na nadgarstku albo przy wózku.\n• Pomyśl o jakiejś młodej matce i zaproponuj jej pomoc.\n• Zapytaj, czego potrzebuje, zamiast dawać rady.","extraTitle":"Pytanie na niedzielę","extra":"Komu w moim otoczeniu przydałaby się ochrona, choćby zwykła pomoc?","whisper":"Matkę chroni nie tylko czerwona nić, ale też ludzie, którzy przy niej są.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":163}],["2027-04-12","home","☽ w Bliźniętach do 08:31, potem w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":33.0,"moonAndBiodynamic":"☽ w Bliźniętach do 08:31, potem w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Do 08:31 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu do 08:31: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Baranie · ☿ w Baranie · ♀ w Rybach · ♂ we Lwie. Pytanie tygodnia: Co zaczynasz z odwagą?","sourceText":{"holiday":"","namedays":"Damiana, Juliusza","title":"Pierwiosnek","subtitle":"kluczyki świętego Piotra","story":"Pierwiosnek, z żółtymi kwiatami w kształcie pęku kluczy, nazywano kluczykami świętego Piotra. Legenda mówi, że Piotr upuścił klucze do nieba, a w miejscu, gdzie spadły, wyrosły kwiaty. Korzeń pierwiosnka był ziołem na kaszel, a kwiaty na nerwy i sen. Kwitnie na łąkach i w zaroślach jako jeden z pierwszych.","practice":"• Na łące wypatruj żółtych pęczków kwiatów.\n• Powąchaj, mają delikatny miodowy zapach.\n• Pomyśl, jaki klucz otworzyłby teraz twoje drzwi.","extraTitle":"Ciekawostka","extra":"Nazwa pierwiosnek mówi sama za siebie: to jeden z pierwszych kwiatów wiosny.","whisper":"Klucze często leżą tam, gdzie upadły. Wystarczy spojrzeć w trawę.","caution":"Pierwiosnki są pod ochroną częściową. Kupuj z upraw. Nie przy uczuleniu.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":164}],["2027-04-13","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":44.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿✶♇ Merkury sekstyl Pluton (02:53): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy.\n♃ Jowisz rusza naprzód we Lwie (04:11): Szanse z zewnątrz wracają, a plany z ostatnich miesięcy mogą się zacząć realizować. Rada: przypomnij sobie, co planowałaś, i zrób pierwszy krok.","sourceText":{"holiday":"","namedays":"Przemysława, Idy","title":"Pesto z czosnku niedźwiedziego","subtitle":"zielony zapach lasu","story":"Czosnek niedźwiedzi pojawia się w kwietniu w wilgotnych lasach. Wierzono, że jedzą go niedźwiedzie po zimowym śnie, by nabrać sił. Jego liście pachną czosnkiem, ale są delikatniejsze. Robi się z nich pesto, masło, zupę. W Polsce rośnie dziko pod ochroną, ale łatwo go kupić lub posadzić w ogrodzie.","practice":"• Zmiksuj pęczek liści czosnku niedźwiedziego z garścią orzechów.\n• Dodaj oliwę, sól i trochę startego sera.\n• Podawaj z makaronem albo na chlebie.","extraTitle":"Ciekawostka","extra":"Czosnek niedźwiedzi łatwo pomylić z trującą konwalią i zimowitem. Liść czosnku pachnie czosnkiem po roztarciu.","whisper":"Siła po długim śnie przychodzi z prostych, zielonych rzeczy.","caution":"Nie zbieraj z natury. Pomyłka z konwalią lub zimowitem może zabić.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":165}],["2027-04-14","creative","☽ w Raku do 11:29, potem we Lwie","I kwadra",false,{"phase":"I kwadra o 00:56","nextPhase":"pełnia za 7 dni","illumination":55.0,"moonAndBiodynamic":"☽ w Raku do 11:29, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 11:29 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 00:56 do 11:29: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Bereniki, Waleriana","title":"Pościel na słońcu","subtitle":"wietrzenie po zimie","story":"Wiosną wynoszono pierzyny i poduszki na płot, by przewietrzyć je na słońcu. Wierzono, że słońce i wiatr wypędzają choroby, złe sny i zimowe duchy. Trzepano je kijem, aż kurz leciał chmurą. Pościel po takim dniu pachniała wiatrem. Dziś pierwsza kwadra: dobry czas, by dać domowi więcej powietrza.","practice":"• Wywieś pościel na balkonie lub przy otwartym oknie.\n• Zostaw ją na słońcu przynajmniej na dwie godziny.\n• Śpij dziś w świeżej pościeli i zapamiętaj sen.","extraTitle":"Ciekawostka","extra":"Promienie słońca naprawdę pomagają ograniczyć roztocza i wilgoć w pościeli.","whisper":"Sen jest lepszy w pościeli, która pamięta wiatr.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":166}],["2027-04-15","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":66.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Ludwiny, Wacławy","title":"Kukułka i pieniądze","subtitle":"ile lat mi zostało","story":"Kukułka wraca w drugiej połowie kwietnia. Kto pierwszy raz w roku ją usłyszał, potrząsał pieniędzmi w kieszeni, by przez cały rok ich nie brakowało. Pytano ją: kukułeczko, ile lat będę żyć, i liczono, ile razy zakuka. Kukułka podrzuca jaja do cudzych gniazd, więc była też symbolem zdrady i samotności.","practice":"• Gdy usłyszysz kukułkę, potrząśnij monetami w kieszeni.\n• Policz jej kukanie, z uśmiechem.\n• Zastanów się, gdzie ty podrzucasz swoje sprawy innym.","extraTitle":"Ciekawostka","extra":"Pisklę kukułki wyrzuca z gniazda jaja i pisklęta przybranych rodziców.","whisper":"Nie każdy, kto głośno woła, zostaje, by wychować to, co zaczął.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":167}],["2027-04-16","creative","☽ we Lwie, od 14:39 w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":76.0,"moonAndBiodynamic":"☽ we Lwie, od 14:39 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 14:39 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 07:52 do 14:39: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Cecyliana, Bernadety","title":"Dzwonienie na burzę","subtitle":"głos przeciw piorunom","story":"Gdy nadchodziła burza, w kościołach bito w dzwony. Wierzono, że ich głos rozbija chmury gradowe i odpędza płanetników, którzy kierują burzą. W domach dzwoniono małymi dzwonkami, zapalano gromnicę i palmę. Dźwięk był ochroną. Dziś wiemy, że dzwonienie podczas burzy było dla dzwonników niebezpieczne, ale wiara w moc głosu została.","practice":"• Powieś przy drzwiach mały dzwonek.\n• Zadzwoń nim, gdy wchodzisz do domu po ciężkim dniu.\n• Sprawdź, czy w domu masz latarkę na burzę.","extraTitle":"Ciekawostka","extra":"Wiele średniowiecznych dzwonów ma inskrypcje o odpędzaniu piorunów.","whisper":"Głos, który się podnosi w porę, czasem rozprasza chmury.","caution":"Podczas burzy nie stój pod drzewem ani na otwartym terenie.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":168}],["2027-04-17","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":85.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Roberta, Rudolfa","title":"Kwitnące sady","subtitle":"biały tydzień","story":"Druga połowa kwietnia to czas, gdy kwitną wiśnie, czereśnie i śliwy. Sady stają się białe i różowe, brzęczą pszczoły. Dawniej obawiano się przymrozków, które mogą zniszczyć kwiat w jedną noc. Rozpalano wtedy dymiące ogniska między drzewami. Kwitnący sad był obietnicą lata i najdelikatniejszym momentem roku.","practice":"• Wybierz się na spacer do sadu lub parku z drzewami owocowymi.\n• Postój pod kwitnącym drzewem i posłuchaj pszczół.\n• Zapisz, co w twoim życiu jest teraz delikatne jak kwiat.","extraTitle":"Ciekawostka","extra":"Bez pszczół i innych owadów zapylających większość drzew owocowych nie dałaby owoców.","whisper":"Najpiękniejsze chwile bywają najbardziej kruche. Dlatego się je zauważa.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":169}],["2027-04-18","organize","☽ w Pannie, od 18:21 w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":92.0,"moonAndBiodynamic":"☽ w Pannie, od 18:21 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 18:21 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 14:56 do 18:21: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿△♃ Merkury trygon Jowisz (12:48): Dobry dzień na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości.","sourceText":{"holiday":"","namedays":"Alicji, Bogusławy","title":"Płanetnik","subtitle":"ten, który prowadzi chmury","story":"Płanetnicy to duchy ludzi, którzy zginęli nagłą śmiercią: utopionych, powieszonych, zabitych przez piorun. Chodzą po chmurach i prowadzą je na powrozach, decydując, gdzie spadnie deszcz, a gdzie grad. Mówiono, że niektórzy żywi ludzie mieli moc płanetników i umieli odwrócić burzę. Chłopi częstowali ich w myślach, by grad ominął pola.","practice":"• Popatrz dziś na chmury i spróbuj zobaczyć w nich kształty.\n• Zapisz, co zobaczyłaś.\n• Pomyśl, czy ty też czasem chcesz „prowadzić chmury”.","extraTitle":"Pytanie na niedzielę","extra":"Na co próbuję mieć wpływ, choć to nie w moich rękach?","whisper":"Chmurami nie da się kierować. Można tylko wiedzieć, kiedy schować się pod dach.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":170}],["2027-04-19","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Baranie · ☿ w Baranie · ♀ w Rybach · ♂ we Lwie. Pytanie tygodnia: Co zaczynasz z odwagą?\n☿☌♄ Merkury koniunkcja Saturn (15:03): Mocny, wymagający dzień. Dobry moment na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.","sourceText":{"holiday":"","namedays":"Adolfa, Tymona","title":"Bratek","subtitle":"fiołek trójbarwny","story":"Bratek polny, czyli fiołek trójbarwny, ma kwiaty jak małe twarze: żółte, fioletowe, białe. Nazywano go sercowym zielem, bo wierzono, że leczy złamane serca i daje miłość. W ziołolecznictwie był ziołem na skórę, trądzik i wysypki u dzieci. Szekspir w Śnie nocy letniej robi z niego eliksir miłosny.","practice":"• Przyjrzyj się bratkowi i zobacz w nim twarz.\n• Zaparz napar z suszonego ziela, jeśli masz.\n• Pomyśl, czyje serce chcesz dziś ukoić.","extraTitle":"Ciekawostka","extra":"Angielska nazwa pansy pochodzi od francuskiego pensée, czyli myśl. Bratek był kwiatem pamięci.","whisper":"Serce goi się wolniej niż skóra, ale też się goi.","caution":"Nie stosuj długo. Ostrożnie w ciąży.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":171}],["2027-04-20","relationships","☽ w Wadze, od 23:20 w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ w Wadze, od 23:20 w Skorpionie · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 23:20 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 10:39 do 23:20: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀ Wenus wchodzi w Barana (05:57): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie odwagi, pośpiechu i nowych startów. Rada: zacznij to, co odkładasz, ale jedną rzecz naraz. Uważaj na łatwe kłótnie i nieprzemyślane ruchy.\n☉ Słońce wchodzi w Byka (09:17): Na miesiąc cały świat nabiera barw znaku Byka: czas spokoju, ciała, pieniędzy i przyjemności. Rada: zadbaj o budżet i o ciało, zjedz coś dobrego powoli.","sourceText":{"holiday":"","namedays":"Czesława, Agnieszki","title":"Zupa szczawiowa","subtitle":"kwaśne zielone","story":"Szczaw pojawia się na łąkach w kwietniu, jego kwaśne liście są pierwszą wiosenną kwasotą. Zupa szczawiowa z jajkiem na twardo była przysmakiem przednówka i całego lata. Dzieci żuły szczaw prosto z łąki. Kwaśny smak budził apetyt i dawał siłę po zimie. Gotowana krótko zachowuje zielony kolor.","practice":"• Ugotuj bulion z ziemniakami.\n• Dodaj dwie garście posiekanego szczawiu, gotuj 5 minut.\n• Zabiel śmietaną, podawaj z jajkiem na twardo.","extraTitle":"Ciekawostka","extra":"Szczaw zawiera kwas szczawiowy. To od niego wzięła się nazwa tego związku.","whisper":"Kwaśne budzi tych, którzy przespali zimę.","caution":"Szczaw nie przy kamicy nerkowej, dnie moczanowej i chorobach nerek.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":172}],["2027-04-21","honesty","☽ w Skorpionie","pełnia",false,{"phase":"pełnia o 00:27","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌕 Pełnia w Skorpionie (00:27): Kulminacja w sprawach: przemiana, wspólne pieniądze, bliskość. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.\n☿△♂ Merkury trygon Mars (15:46): Dobry dzień na szybkie decyzje, debatę i załatwienie zaległości.","sourceText":{"holiday":"","namedays":"Bartosza, Feliksa","title":"Woda pełni","subtitle":"światło w szklanym naczyniu","story":"Dziś w nocy pełnia. Zielarki zostawiały na noc wodę w szklanym naczyniu na parapecie, by nasiąknęła światłem Księżyca. Rano przemywały nią twarz albo podlewały rośliny. To rytuał, który niczego nie obiecuje, ale daje chwilę skupienia. Pełnia kwietniowa świeci nad kwitnącymi drzewami, jaśniej niż zimą.","practice":"• Napełnij szklankę wodą i postaw na parapecie na noc.\n• Rano przemyj nią twarz albo podlej kwiaty.\n• Zapisz, co czujesz, gdy patrzysz na pełnię.","extraTitle":"Księżyc","extra":"pełnia 21 IV, 00:27 · III kwadra 28 IV, 22:18","whisper":"Światło można zbierać, nawet jeśli nie da się go zatrzymać.","caution":"Wody z parapetu nie pij.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":173}],["2027-04-22","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":98.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 18:12 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Kai, Łukasza","title":"Ziemia święta","subtitle":"nie pluj, nie bij","story":"Ziemię traktowano jak matkę. Nie wolno było w nią pluć, bić kijem ani wbijać noża bez potrzeby, zwłaszcza na wiosnę, gdy była „brzemienna”. Wierzono, że do Zwiastowania śpi, potem zaczyna rodzić. Przysięgano na ziemię, całowano ją, wkładano do ust grudkę na znak prawdy. Dziś Dzień Ziemi: stare zakazy mają nowe znaczenie.","practice":"• Posadź dziś coś: kwiat, drzewo, zioło.\n• Podnieś jeden śmieć z ziemi na spacerze.\n• Dotknij gołą dłonią ziemi i podziękuj jej.","extraTitle":"Ciekawostka","extra":"Słowianie mieli boginię Mokosz, związaną z ziemią, wilgocią i płodnością.","whisper":"Ziemia nie mówi, ale wszystko pamięta.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":174}],["2027-04-23","travel","☽ w Skorpionie do 06:37, potem w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":94.0,"moonAndBiodynamic":"☽ w Skorpionie do 06:37, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 06:37 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀✶♅ Wenus sekstyl Uran (10:08): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku.","sourceText":{"holiday":"św. Wojciecha i św. Jerzego","namedays":"Jerzego, Wojciecha, Idziego","title":"Wojciech i Jerzy","subtitle":"otwieracz pastwisk","story":"Na świętego Jerzego pierwszy raz wypędzano bydło na pastwiska. Przed bramą kładziono jajko, siekierę albo kłódkę, by krowy przeszły nad nimi i były zdrowe. Jerzy zabijał smoka, więc chronił też przed wilkami i żmijami. Rosa jerzowa miała moc: kto się w niej wytarzał, był zdrowy. Dziś też święty Wojciech, patron Polski.","practice":"• Rano wyjdź boso na trawę, choćby na chwilę.\n• Przemyj twarz rosą.\n• Pomyśl, jakiego „smoka” chcesz dziś pokonać.","extraTitle":"Ciekawostka","extra":"Jerzy to imię greckie, oznacza rolnika, kogoś, kto uprawia ziemię.","whisper":"Smoki są mniejsze, gdy wyjdziesz im naprzeciw o świcie.","caution":"Po trawie boso tylko tam, gdzie nie ma szkła i kleszczy.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":175}],["2027-04-24","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":89.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀☌♆ Wenus koniunkcja Neptun (12:55): Dobry dzień na romantyzm, sztukę, muzykę i współczucie. Uważaj tylko na idealizowanie ludzi i rozczarowania.","sourceText":{"holiday":"","namedays":"Aleksego, Horacego","title":"Kaczeńce","subtitle":"złoto na mokrych łąkach","story":"Kaczeńce, czyli knieć błotna, zakwitają w kwietniu nad strumieniami i na podmokłych łąkach. Ich żółte kwiaty błyszczą jak lakierowane. Na wsi były znakiem, że przyszła prawdziwa wiosna. W niektórych regionach z kaczeńców robiono wianki na Zielone Świątki. Pięknie wyglądają w wazonie, ale są trujące i mogą podrażniać skórę.","practice":"• Wybierz się nad strumień i poszukaj kaczeńców.\n• Zrób zdjęcie, nie zrywaj.\n• Pomyśl, co dla ciebie znaczy „prawdziwa wiosna”.","extraTitle":"Ciekawostka","extra":"Kaczeniec należy do rodziny jaskrowatych, tak jak zawilec i jaskier. Wszystkie są trujące.","whisper":"Złoto, które rośnie w błocie, jest prawdziwsze niż to w skarbcu.","caution":"Kaczeniec jest trujący, nie zrywaj go gołymi rękami.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":176}],["2027-04-25","travel","☽ w Strzelcu, od 16:51 w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":81.0,"moonAndBiodynamic":"☽ w Strzelcu, od 16:51 w Koziorożcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 16:51 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 04:54 do 16:51: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿ Merkury wchodzi w Byka (00:18): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie spokoju, ciała, pieniędzy i przyjemności. Rada: zadbaj o budżet i o ciało, zjedz coś dobrego powoli. Uważaj na upór i trzymanie się starego.","sourceText":{"holiday":"św. Marka","namedays":"Marka, Jarosława","title":"Święty Marek","subtitle":"procesja w pole","story":"Na świętego Marka wychodziły procesje w pola. Kapłan święcił zasiewy, a gospodarze zatykali w ziemię poświęcone gałązki, by chronić zboże przed gradem i szkodnikami. W niektórych wsiach chodzono wokół pól z krzyżem i śpiewem. Wiosenne obejście pola było jak zakreślenie granicy, w której dobro ma rosnąć.","practice":"• Obejdź dziś swój dom, ogród albo osiedle z uwagą.\n• Zatknij gałązkę albo kwiat w ziemię.\n• Wypowiedz życzenie dla tego, co rośnie wokół ciebie.","extraTitle":"Pytanie na niedzielę","extra":"Co w moim życiu potrzebuje dziś obejścia i błogosławieństwa?","whisper":"Granica zakreślona z miłością chroni lepiej niż płot.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":177}],["2027-04-26","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":73.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Byku · ☿ w Byku · ♀ w Baranie · ♂ we Lwie. Pytanie tygodnia: Co daje Ci poczucie bezpieczeństwa?\n♀✶♇ Wenus sekstyl Pluton (03:20): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach.","sourceText":{"holiday":"","namedays":"Marzeny, Marii, Klaudiusza","title":"Glistnik","subtitle":"jaskółcze ziele","story":"Glistnik kwitnie przy płotach i murach, od kwietnia do jesieni. Jego pomarańczowy sok spływa z przełamanej łodygi. Legenda mówi, że jaskółki przemywały nim oczy pisklętom, dlatego nazywa się jaskółczym zielem. Sokiem smarowano brodawki i kurzajki. To jedno z najsilniejszych dzikich ziół i jedno z najniebezpieczniejszych.","practice":"• Rozpoznaj glistnik po żółtych kwiatach i pomarańczowym soku.\n• Nie pij naparu z glistnika.\n• Pomyśl, co w twoim życiu jest silne, ale wymaga ostrożności.","extraTitle":"Ciekawostka","extra":"Łacińska nazwa Chelidonium pochodzi od greckiego chelidon, czyli jaskółka.","whisper":"Im silniejsze lekarstwo, tym mniejsza dawka.","caution":"Glistnik uszkadza wątrobę. Nie stosuj wewnętrznie. Sok tylko punktowo na kurzajki.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":178}],["2027-04-27","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":64.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 09:19 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉□♇ Słońce kwadratura Pluton (17:24): Napięcie między planetami. Można je wykorzystać na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna. Uważaj na walkę o władzę i kontrolowanie innych.","sourceText":{"holiday":"","namedays":"Ludwika, Piotra","title":"Szparagi z masłem i bułką","subtitle":"sezon zaczyna się","story":"Szparagi pojawiają się pod koniec kwietnia. W dawnej Polsce były warzywem dworów i klasztorów. Tradycja łączy ich popularność z królową Boną. Białe, zielone, fioletowe. Podawano je po polsku: gotowane i polane masłem ze zrumienioną bułką tartą. Sezon trwa tylko do świętego Jana, więc trzeba się nimi nacieszyć.","practice":"• Obierz białe szparagi od główki w dół i odetnij końcówki.\n• Gotuj na stojąco w osolonej wodzie 10–12 minut.\n• Polej masłem ze zrumienioną bułką tartą.","extraTitle":"Ciekawostka","extra":"Tradycyjnie sezon szparagowy kończy się 24 czerwca, na świętego Jana.","whisper":"Najlepsze smaki mają krótki sezon. Nie odkładaj ich na potem.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":179}],["2027-04-28","social","☽ w Koziorożcu do 05:23, potem w Wodniku","III kwadra",false,{"phase":"III kwadra o 22:18","nextPhase":"nów za 8 dni","illumination":54.0,"moonAndBiodynamic":"☽ w Koziorożcu do 05:23, potem w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 05:23 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿□♇ Merkury kwadratura Pluton (09:46): Napięcie między planetami. Można je wykorzystać na dociekliwość, badania, terapię i szczere rozmowy. Uważaj na obsesyjne myśli i słowne manipulacje.\n☉☌☿ Słońce koniunkcja Merkury (23:21): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"","namedays":"Pawła, Walerii","title":"List, który spalasz","subtitle":"ostatnia kwadra","story":"Dziś wieczorem ostatnia kwadra. Księżyc maleje, a z nim to, co chcesz odpuścić. Napisz list do tego, co cię ciągnie w dół: do lęku, do żalu, do kogoś, kto nie przeprosił. Nie wysyłaj go. Spal w bezpiecznym miejscu albo podrzyj i wyrzuć. Słowa wypowiedziane na papierze tracą władzę nad tobą.","practice":"• Usiądź z kartką i pisz szczerze przez 10 minut.\n• Nie czytaj tego, co napisałaś.\n• Spal kartkę w metalowej misce albo podrzyj na drobne kawałki.","extraTitle":"Ciekawostka","extra":"Pisanie o trudnych przeżyciach, nawet bez wysyłania, pomaga wielu ludziom uporządkować emocje.","whisper":"Ogień nie odbiera wspomnienia. Odbiera mu ciężar.","caution":"Ogień tylko w bezpiecznym miejscu.","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":180}],["2027-04-29","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":44.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Rity, Donaty","title":"Czarownice odbierają mleko","subtitle":"noc przed Walpurgią","story":"Wierzono, że w noce przed świętem czarownice chodzą po łąkach i zbierają rosę płachtą. Kto zebrał rosę z cudzej łąki, ten odbierał krowom sąsiada mleko. Dlatego gospodynie wstawały przed świtem i pilnowały swoich pastwisk. Na bramę obory zatykano gałązki osiki i kreślono krzyże. Mleko było bogactwem, a jego utrata nieszczęściem.","practice":"• Zastanów się, kto „odbiera mleko” z twojego życia.\n• Zapisz to i postaw dziś jedną granicę.\n• Wieczorem zapal świeczkę przy oknie.","extraTitle":"Ciekawostka","extra":"Podobne wierzenia o czarownicach zbierających rosę są znane w całej Europie Środkowej.","whisper":"To, co twoje, warto pilnować o świcie, zanim ktoś przyjdzie z płachtą.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":181}],["2027-04-30","social","☽ w Wodniku, od 17:52 w Rybach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":34.0,"moonAndBiodynamic":"☽ w Wodniku, od 17:52 w Rybach · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 17:52 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 08:31 do 17:52: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"noc Walpurgii","namedays":"Mariana, Katarzyny","title":"Noc Walpurgii","subtitle":"zielone gałązki w oknach","story":"Noc z 30 kwietnia na 1 maja to czas, gdy czarownice ciągną na sabat na Łysą Górę. Na Śląsku i w Niemczech palono ognie, strzelano z bata, dzwoniono, by je przepędzić. W oknach i na bramach zatykano zielone gałązki brzozy. Rano dziewczęta myły twarz majową rosą dla urody. To noc granicy między wiosną a latem.","practice":"• Zatknij w oknie zieloną gałązkę.\n• Wieczorem zapal świecę i powiedz: tu nie ma wstępu dla zła.\n• Rano przemyj twarz rosą, jeśli możesz.","extraTitle":"Ciekawostka","extra":"Walpurgia była angielską mniszką, której święto przypadło na noc dawnych pogańskich obrzędów wiosennych.","whisper":"Każda granica ma swoją noc. Tej nocy zapal światło.","caution":"Ognisko tylko w bezpiecznym, dozwolonym miejscu.","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":182}],["2027-05-01","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":25.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 22:47 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"Święto Pracy","namedays":"Józefa, Jeremiasza","title":"Stawianie maja","subtitle":"drzewko pod oknem dziewczyny","story":"W nocy na pierwszego maja chłopcy stawiali maj: wysoką, okorowaną brzozę albo świerk przystrojony wstążkami. Ustawiali go przed domem dziewczyny, która im się podobała, albo na środku wsi. Maj miał zapewnić urodzaj i szczęście. Rano dziewczęta szukały go pod swoim oknem. Zwyczaj przetrwał na Śląsku, Opolszczyźnie i w Wielkopolsce.","practice":"• Postaw w wazonie gałązkę brzozy przewiązaną wstążką.\n• Podaruj komuś kwiat bez okazji.\n• Zapisz, co chcesz, żeby rosło w tobie w maju.","extraTitle":"Ciekawostka","extra":"W Niemczech i Austrii majowe drzewa, Maibaum, osiągają nawet 30 metrów wysokości.","whisper":"Kto wita maj zielenią, ten przez cały rok pamięta, że życie wraca.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":183}],["2027-05-02","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":16.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Zygmunta, Atanazego","title":"Kapliczka i majówka","subtitle":"śpiew przy drodze","story":"W maju przy przydrożnych kapliczkach i krzyżach zbierali się wieczorem sąsiedzi. Śpiewali litanię i pieśni maryjne, przystrajali kapliczkę kwiatami i wstążkami. Majówka była też okazją do spotkań, plotek i zalotów. Kapliczki stawiano na rozstajach dróg, bo tam według wierzeń czaiły się złe moce. Śpiew je przepędzał.","practice":"• Na spacerze zatrzymaj się przy kapliczce lub krzyżu przydrożnym.\n• Zostaw przy niej polny kwiat.\n• Pomyśl, z kim chcesz dziś pobyć wieczorem.","extraTitle":"Pytanie na niedzielę","extra":"Z kim mogłabym dziś po prostu pośpiewać albo pogadać?","whisper":"Wspólny śpiew przegania więcej strachów niż samotna modlitwa.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":184}],["2027-05-03","start","☽ w Rybach do 03:42, potem w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":10.0,"moonAndBiodynamic":"☽ w Rybach do 03:42, potem w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Do 03:42 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Byku · ☿ w Byku · ♀ w Baranie · ♂ we Lwie. Pytanie tygodnia: Co daje Ci poczucie bezpieczeństwa?\n☿□♃ Merkury kwadratura Jowisz (06:27): Napięcie między planetami. Można je wykorzystać na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości. Uważaj na obietnice bez pokrycia i przeoczone szczegóły.","sourceText":{"holiday":"Święto Konstytucji 3 Maja","namedays":"Marii, Marioli","title":"Konwalia","subtitle":"majowy dzwonek","story":"Konwalia kwitnie na początku maja w cienistych lasach. Jej białe dzwoneczki pachną intensywnie i słodko. Legenda mówi, że wyrosła z łez Matki Bożej pod krzyżem. W medycynie była ważnym ziołem na serce, ale tylko w rękach znawców, bo jest silnie trująca. Dziś święto Konstytucji 3 Maja: dzień pamięci o tym, co delikatne i ważne.","practice":"• Powąchaj konwalię, ale nie zrywaj jej w lesie.\n• Umyj ręce po dotknięciu.\n• Pomyśl o czymś, co jest piękne i wymaga ostrożności.","extraTitle":"Ciekawostka","extra":"Glikozydy z konwalii działają na serce podobnie jak naparstnica. Dawniej leczono nimi niewydolność serca.","whisper":"Najsłodszy zapach bywa ostrzeżeniem.","caution":"Konwalia jest śmiertelnie trująca. Nawet woda z wazonu jest niebezpieczna. Chroń dzieci i zwierzęta.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":185}],["2027-05-04","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀△♃ Wenus trygon Jowisz (20:15): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.","sourceText":{"holiday":"","namedays":"Moniki, Floriana","title":"Miód z mniszka","subtitle":"złoto w słoiku","story":"Na początku maja łąki są żółte od mniszka. Z jego kwiatów robi się syrop, zwany miodem mniszkowym. Kwiaty zalewa się wodą, gotuje, odcedza i gotuje z cukrem i cytryną, aż zgęstnieje. Pachnie wiosną i łąką. Dawniej podawano go na kaszel i przeziębienie, dziś na chleb, do herbaty i naleśników.","practice":"• Zbierz 300 główek mniszka w słoneczny dzień, z dala od dróg.\n• Zalej 1 l wody, gotuj 15 min, odstaw na noc i odcedź.\n• Gotuj z 1 kg cukru i sokiem z cytryny do zgęstnienia, przelej do słoików.","extraTitle":"Ciekawostka","extra":"Kwiaty mniszka zamykają się wieczorem i przy pochmurnej pogodzie. Zbieraj w południe.","whisper":"Złoto, którego nikt nie liczy, rośnie na każdej łące.","caution":"Nie przy uczuleniu na astrowate.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":186}],["2027-05-05","finances","☽ w Baranie do 09:52, potem w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Baranie do 09:52, potem w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Do 09:52 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 04:08 do 09:52: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Ireny, Waldemara","title":"Pierwszy majowy deszcz","subtitle":"rośnij jak grzyb","story":"Wierzono, że pierwszy majowy deszcz ma moc wzrostu. Dzieci wybiegały na dwór, by na nie popadało, bo wtedy szybciej rosną. Dziewczęta myły w deszczówce włosy, by były gęste i błyszczące. Mówiono: majowy deszcz, a dzieci rosną. Deszczówkę zbierano do beczek i podlewano nią rozsadę.","practice":"• Gdy spadnie majowy deszcz, wyjdź na chwilę bez parasola.\n• Zbierz trochę deszczówki do podlewania roślin.\n• Zapisz, w czym chcesz urosnąć.","extraTitle":"Przysłowie","extra":"„Majowy deszcz, a dzieci rosną.”","whisper":"Nie bój się zmoknąć. Niektóre rzeczy rosną tylko pod deszczem.","caution":"Nie wychodź w burzę.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":187}],["2027-05-06","finances","☽ w Byku","nów",true,{"phase":"nów o 12:58","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🌑 Nów w Byku (12:58): Czas zasiewu w sprawach: pieniądze, ciało, poczucie bezpieczeństwa. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"Wniebowstąpienie","namedays":"Filipa, Judyty","title":"Wniebowstąpienie","subtitle":"dzień bez pracy w polu","story":"W Wniebowstąpienie nie pracowano w polu ani w ogrodzie. Mówiono, że kto będzie orał lub siał, temu grad zbije zboże, a piorun uderzy w dom. Kobiety nie szyły i nie prały. Był to dzień spokoju, kiedy niebo i ziemia się spotykają. Wierzono też, że deszcz w ten dzień zapowiada mokre lato.","practice":"• Daj sobie dziś godzinę bez pracy.\n• Spójrz w niebo i zobacz, jaka jest pogoda.\n• Zapisz, co chciałabyś podnieść wyżej w swoim życiu.","extraTitle":"Ciekawostka","extra":"Wniebowstąpienie przypada zawsze 40 dni po Wielkanocy, w czwartek.","whisper":"Odpoczynek to też praca. Tylko innego rodzaju.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":188}],["2027-05-07","finances","☽ w Byku, od 13:06 w Bliźniętach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Byku, od 13:06 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 13:06 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 08:48 do 13:06: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀☌♄ Wenus spotyka Saturna (20:48): Uczucia i pieniądze przechodzą test trwałości. Rada: zainwestuj w to, co trwałe. Uwaga: chłód nie oznacza braku miłości.","sourceText":{"holiday":"","namedays":"Benedykta, Gizeli","title":"Czarny bez","subtitle":"drzewo, którego się nie ścina","story":"Czarny bez rósł przy każdej zagrodzie. Wierzono, że mieszkają w nim duchy przodków i dobre demony. Nie wolno go było ścinać, palić ani wycinać bez przeprosin. Kto to zrobił, ściągał chorobę albo śmierć. Chronił dom przed piorunem i złymi czarami. Jego kwiaty, owoce, kora i liście były apteką całej wsi.","practice":"• Jeśli masz bez w okolicy, odwiedź go i przyjrzyj się pąkom.\n• Pomyśl, kto w twoim życiu jest jak drzewo przy domu.\n• Nie łam gałęzi bez potrzeby.","extraTitle":"Ciekawostka","extra":"Czarny bez kwitnie pod koniec maja i w czerwcu. Jego owoce dojrzewają we wrześniu.","whisper":"Niektóre drzewa chronią dom tylko dlatego, że nikt ich nie ściął.","caution":"Surowe owoce, liście i kora są trujące.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":189}],["2027-05-08","conversation","☽ w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿□♂ Merkury kwadratura Mars (00:21): Napięcie między planetami. Można je wykorzystać na szybkie decyzje, debatę i załatwienie zaległości. Uważaj na kłótnie, ostre słowa i pośpiech w mailach.\n♇ Pluton rusza wstecz w Wodniku (14:54): Na pięć miesięcy przemiana idzie w głąb. Wychodzą na wierzch sprawy władzy i kontroli. Rada: przyjrzyj się, kto ma władzę nad Tobą, a nad kim Ty.\n☉□♃ Słońce kwadratura Jowisz (21:37): Napięcie między planetami. Można je wykorzystać na optymizm, prośby, oferty, naukę i podróże. Uważaj na przesadę i obietnice ponad siły.","sourceText":{"holiday":"","namedays":"Ilzy, Stanisława, Wiktora","title":"Słowiki","subtitle":"pieśń nocy majowej","story":"W maju nocami śpiewają słowiki. Słowik szary w zaroślach nad wodą i w parkach śpiewa godzinami, tak głośno i pięknie, że trudno uwierzyć, że to mały, szary ptak. Poeci uczynili go symbolem miłości i tęsknoty. Śpiewa najgłośniej w nocy, bo wtedy samce wabią samice przylatujące z południa.","practice":"• Wieczorem wyjdź do parku lub nad wodę i posłuchaj słowika.\n• Zamknij oczy i licz, ile różnych fraz usłyszysz.\n• Zapisz, co cię dziś wzruszyło.","extraTitle":"Ciekawostka","extra":"Słowik może mieć w repertuarze ponad 200 różnych motywów.","whisper":"Najpiękniejsze głosy często należą do tych, których nie widać.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":190}],["2027-05-09","conversation","☽ w Bliźniętach, od 14:59 w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":11.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 14:59 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 14:59 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 11:54 do 14:59: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿ Merkury wchodzi w Bliźnięta (03:57): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie rozmów, ciekawości, krótkich podróży i wiadomości. Rada: zadzwoń, napisz, zapytaj. Uważaj na rozproszenie i plotki.","sourceText":{"holiday":"","namedays":"Bożydara, Grzegorza","title":"Latawiec","subtitle":"ten, który przylatuje z wiatrem","story":"Latawiec był demonem wiatru i powietrza. Przylatywał w postaci ognistego węża lub gwiazdy i odwiedzał nocą samotne kobiety, wdowy i panny. Te, które odwiedzał, chudły i bladły. Mówiono, że kto widział spadającą gwiazdę, ten widział latawca. Chroniły przed nim czosnek, krzyż i zamknięte okno.","practice":"• Wieczorem popatrz w niebo i poszukaj spadającej gwiazdy.\n• Pomyśl życzenie, jeśli ją zobaczysz.\n• Zamknij okno przed snem.","extraTitle":"Pytanie na niedzielę","extra":"Co mnie odwiedza w samotności i zabiera siły?","whisper":"Nie każdy, kto przylatuje nocą jak gwiazda, przynosi światło.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":191}],["2027-05-10","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Byku · ☿ w Bliźniętach · ♀ w Baranie · ♂ we Lwie. Pytanie tygodnia: Co daje Ci poczucie bezpieczeństwa?","sourceText":{"holiday":"","namedays":"Izydora, Antoniny","title":"Kasztanowiec","subtitle":"świece maja","story":"Kasztanowiec kwitnie w maju białymi świecami. To drzewo matur i parków, ale też zioło: z jego nasion i kory robi się preparaty na żylaki, obrzęki i ciężkie nogi. Kasztany nosi się w kieszeni na reumatyzm, choć to bardziej wiara niż działanie. Kwitnące kasztany to znak, że lato jest blisko.","practice":"• Usiądź pod kwitnącym kasztanowcem.\n• Przyjrzyj się jego kwiatom z czerwonymi plamkami.\n• Jesienią zbierz kasztany na pamiątkę.","extraTitle":"Ciekawostka","extra":"Plamki na kwiatach kasztanowca zmieniają kolor z żółtego na czerwony, gdy kwiat zostaje zapylony.","whisper":"Każda świeca na drzewie to obietnica owocu.","caution":"Nasiona są trujące. Preparaty tylko z apteki.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":192}],["2027-05-11","home","☽ w Raku, od 17:00 we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":30.0,"moonAndBiodynamic":"☽ w Raku, od 17:00 we Lwie · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 17:00 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 09:45 do 17:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿☌♅ Merkury spotyka Urana (14:49): Błyskawiczne pomysły i nagłe wiadomości. Rada: zapisuj olśnienia. Uwaga: nie wysyłaj maila w emocjach.","sourceText":{"holiday":"","namedays":"Igi, Ignacego","title":"Sałata ze śmietaną","subtitle":"smak nowalijek","story":"Pierwsza sałata z ogrodu była świętem. Podawano ją ze śmietaną, odrobiną cukru, soli i octu albo soku z cytryny, czasem z jajkiem na twardo i koperkiem. Na wsi mówiono, że sałata ze śmietaną oczyszcza krew po zimie. Prosta potrawa, której smak pamięta się z dzieciństwa.","practice":"• Umyj i osusz główkę młodej sałaty, porwij liście.\n• Wymieszaj 4 łyżki śmietany z sokiem z cytryny, solą i szczyptą cukru.\n• Polej sałatę, posyp koperkiem i jajkiem.","extraTitle":"Ciekawostka","extra":"Słowo „nowalijki” pochodzi od łacińskiego novalis, czyli nowo zaorana ziemia.","whisper":"Najbardziej zielone są te rzeczy, które dopiero co wyszły z ziemi.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":193}],["2027-05-12","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":41.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿✶♆ Merkury sekstyl Neptun (02:12): Dobry dzień na pisanie, poezję, muzykę i rozmowy o duchowości.\n☿△♇ Merkury trygon Pluton (20:13): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy.","sourceText":{"holiday":"zimni ogrodnicy: Pankracy","namedays":"Joanny, Achillesa","title":"Okrywanie rozsady","subtitle":"Pankracy","story":"Od dziś zaczynają się zimni ogrodnicy: Pankracy, Serwacy, Bonifacy i zimna Zośka. W połowie maja często wracają przymrozki. Ogrodnicy okrywali młode rośliny płótnem, słomą, odwróconymi garnkami. Wiedzieli, że jedna mroźna noc może zniszczyć całą pracę. Ochrona tego, co delikatne, to też rytuał.","practice":"• Sprawdź prognozę na najbliższe noce.\n• Okryj rośliny na balkonie lub w ogrodzie, jeśli zapowiadają przymrozek.\n• Pomyśl, co delikatnego w twoim życiu potrzebuje teraz okrycia.","extraTitle":"Ciekawostka","extra":"Zimni ogrodnicy to zjawisko meteorologiczne: napływ chłodnego powietrza z północy w połowie maja.","whisper":"Delikatne rzeczy potrzebują ochrony najbardziej wtedy, gdy wydaje się, że zima już minęła.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":194}],["2027-05-13","creative","☽ we Lwie, od 20:05 w Pannie","I kwadra",false,{"phase":"I kwadra o 06:43","nextPhase":"pełnia za 7 dni","illumination":52.0,"moonAndBiodynamic":"☽ we Lwie, od 20:05 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 20:05 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 19:31 do 20:05: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"zimni ogrodnicy: Serwacy","namedays":"Glorii, Gerwazego","title":"Zimni ogrodnicy","subtitle":"Serwacy i pierwsza kwadra","story":"Mówiono, że zimni ogrodnicy to trzech świętych, którzy pilnują, by wiosna nie przyszła za szybko. Przysłowia ostrzegają: Pankracy, Serwacy, Bonifacy, źli na ogrody chłopacy. Dopiero po zimnej Zośce można było bezpiecznie sadzić ogórki i fasolę. Dziś pierwsza kwadra: czas, gdy rośnie, ale jeszcze trzeba poczekać.","practice":"• Nie spiesz się dziś z niczym, co może jeszcze poczekać.\n• Zapisz jedną rzecz, którą chcesz zasiać po Zośce.\n• Okryj delikatne rośliny na noc.","extraTitle":"Przysłowie","extra":"„Pankracy, Serwacy, Bonifacy, źli na ogrody chłopacy.”","whisper":"Cierpliwość ogrodnika to nie lenistwo. To mądrość o przymrozkach.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":195}],["2027-05-14","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":63.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♂ Mars wchodzi w Pannę (16:47): Na kilka tygodni energia i działanie płyną w rytmie porządku, zdrowia, codziennej pracy i szczegółu. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów. Uważaj na krytykanctwo i przemęczenie.\n♀ Wenus wchodzi w Byka (23:01): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie spokoju, ciała, pieniędzy i przyjemności. Rada: zadbaj o budżet i o ciało, zjedz coś dobrego powoli. Uważaj na upór i trzymanie się starego.","sourceText":{"holiday":"zimni ogrodnicy: Bonifacy","namedays":"Bonifacego, Dobiesława","title":"Piołun nad drzwiami","subtitle":"gorzki strażnik","story":"Piołun, gorzki jak żadne inne zioło, wieszano nad drzwiami i w oborze, by odpędzał złe duchy, robactwo i choroby. Był ziołem żałoby i ochrony, a jego gorycz miała odstraszać to, co złe. Kładziono go do szaf przeciw molom. W medycynie ludowej pobudzał trawienie i apetyt.","practice":"• Powieś nad drzwiami pęczek suszonego piołunu albo bylicy.\n• Włóż gałązkę do szafy z wełną.\n• Pomyśl, jaka gorycz w twoim życiu cię chroni.","extraTitle":"Ciekawostka","extra":"Z piołunu robiono absynt, napój tak mocny, że w wielu krajach go zakazano.","whisper":"Gorycz nie zawsze jest wrogiem. Czasem to straż przy drzwiach.","caution":"Piołun zawiera tujon, toksyczny w większych dawkach. Nie w ciąży, nie dla dzieci, nie długo.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":196}],["2027-05-15","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":73.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 14:48 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀△♂ Wenus trygon Mars (01:46): Dobry dzień na namiętność, randki, taniec i twórczą energię.","sourceText":{"holiday":"zimna Zośka","namedays":"Zofii, Nadziei","title":"Zimna Zośka","subtitle":"koniec przymrozków","story":"Dziś zimna Zośka, ostatnia z zimnych ogrodników. Po niej przymrozki zdarzają się rzadko i ogrodnicy mogą sadzić wszystko: pomidory, ogórki, fasolę, dynie. Dzień jest już długi, ziemia ciepła. W lasach kwitną bzy i jarzębiny, a na łąkach mnóstwo kwiatów. Teraz lato naprawdę się zaczyna, choć kalendarzowo jeszcze nie.","practice":"• Posadź dziś rozsadę, która czekała na parapecie.\n• Podlej ją deszczówką.\n• Zapisz, co zasiałaś w tym roku.","extraTitle":"Ciekawostka","extra":"Zośka to Zofia, imię greckie, które znaczy mądrość. Mądrość ogrodnika to czekać.","whisper":"Najlepszy czas na sadzenie przychodzi zawsze po ostatnim przymrozku.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":197}],["2027-05-16","relationships","☽ w Pannie do 00:33, potem w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":82.0,"moonAndBiodynamic":"☽ w Pannie do 00:33, potem w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 00:33 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"Zielone Świątki (Zesłanie Ducha Świętego)","namedays":"Andrzeja, Jędrzeja","title":"Zielone Świątki","subtitle":"majenie domów","story":"Na Zielone Świątki domy majono zielenią. Zatykano gałązki brzozy w ściany, okna i bramy, a podłogi wysypywano tatarakiem. Zapach tataraku chronił przed złym i oczyszczał dom. Pasterze palili ognie i wyprowadzali bydło przystrojone wiankami. Dawniej był to też czas Rusaliów, święta zmarłych i duchów wody.","practice":"• Przynieś do domu gałązkę brzozy lub garść świeżej zieleni.\n• Rozłóż ją w miejscu, gdzie często bywasz.\n• Pomyśl o zmarłych, którzy byli dla ciebie ważni.","extraTitle":"Pytanie na niedzielę","extra":"Czym chcę dziś przyozdobić swój dom i swoje życie?","whisper":"Zieleń w domu przypomina, że nawet ściany mogą oddychać.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":198}],["2027-05-17","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":90.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 16:55 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Byku · ☿ w Bliźniętach · ♀ w Byku · ♂ w Pannie. Pytanie tygodnia: Co daje Ci poczucie bezpieczeństwa?","sourceText":{"holiday":"","namedays":"Brunona, Paschalisa","title":"Tatarak","subtitle":"zapach Zielonych Świątek","story":"Tatarak rośnie nad stawami i rzekami. Jego długie liście pachną cytrusami i kadzidłem. Na Zielone Świątki wysypywano nim podłogi, a wierzono, że jego zapach przepędza czarownice i choroby. Korzeń tataraku żuto na trawienie i przeciw paleniu tytoniu. Przywieziono go do Polski podobno przez Tatarów, stąd nazwa.","practice":"• Na spacerze nad wodą poszukaj tataraku i rozetrzyj liść w palcach.\n• Weź kilka liści do domu i rozłóż w sieni.\n• Pomyśl, jaki zapach kojarzy ci się z ochroną.","extraTitle":"Ciekawostka","extra":"Według legendy Tatarzy sadzili tatarak tam, gdzie woda była czysta i nadawała się do picia.","whisper":"Zapach czystej wody chroni dom lepiej niż zamek.","caution":"Korzeń tataraku zawiera beta-azaron, toksyczny w dużych dawkach. Nie stosuj wewnętrznie długo, nie w ciąży.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":199}],["2027-05-18","honesty","☽ w Wadze do 06:33, potem w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":95.0,"moonAndBiodynamic":"☽ w Wadze do 06:33, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 06:33 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Eryka, Feliksa","title":"Kompot z rabarbaru","subtitle":"kwaśny róż maja","story":"Rabarbar rośnie w ogrodach jak wielkie liście parasole. Jego łodygi, różowe i kwaśne, są pierwszym owocem wiosny, choć to warzywo. Kompot z rabarbaru, z truskawkami albo bez, pito w maju chłodny jak lemoniada. Pieczono też ciasta z kruszonką. Kwaśny smak budzi i orzeźwia po zimie.","practice":"• Pokrój 4 łodygi rabarbaru w kawałki.\n• Gotuj w 2 l wody z cukrem do smaku przez 10 minut.\n• Ostudź i podawaj z miętą.","extraTitle":"Ciekawostka","extra":"Liście rabarbaru są trujące, bo zawierają dużo kwasu szczawiowego. Jemy tylko łodygi.","whisper":"Kwaśne rzeczy bywają najbardziej orzeźwiające.","caution":"Rabarbar nie przy kamicy nerkowej i dnie moczanowej.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":200}],["2027-05-19","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":99.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿✶♃ Merkury sekstyl Jowisz (19:54): Dobry dzień na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości.","sourceText":{"holiday":"","namedays":"Piotra, Iwa","title":"Boso po trawie","subtitle":"uziemienie","story":"W maju trawa jest miękka i pełna rosy. Chodzenie boso po trawie zalecał ksiądz Sebastian Kneipp jako sposób na zdrowie, ale znano je dużo wcześniej. Na wsi dzieci od maja do jesieni chodziły boso. Stopy czują ziemię, a ziemia mówi rzeczy, których nie słychać w butach. To najprostszy rytuał wiosenny.","practice":"• Wyjdź boso na trawę na 10 minut, rano lub wieczorem.\n• Skup się na tym, co czujesz w stopach.\n• Po powrocie umyj i natłuść stopy.","extraTitle":"Ciekawostka","extra":"Kneipp, bawarski ksiądz z XIX wieku, leczył ludzi wodą, ziołami i chodzeniem boso po rosie.","whisper":"Ziemia nie mówi głośno. Trzeba ją usłyszeć stopami.","caution":"Uważaj na szkło, kleszcze i trawniki pryskane chemią.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":201}],["2027-05-20","honesty","☽ w Skorpionie, od 14:27 w Strzelcu","pełnia",false,{"phase":"pełnia o 12:59","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Skorpionie, od 14:27 w Strzelcu · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 14:27 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 12:59 do 14:27: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌕 Pełnia w Skorpionie (12:59): Kulminacja w sprawach: przemiana, wspólne pieniądze, bliskość. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.\n♀□♇ Wenus kwadratura Pluton (20:02): Napięcie między planetami. Można je wykorzystać na głębokie uczucia, intymność i odnowę w relacjach. Uważaj na zazdrość i zaborczość.","sourceText":{"holiday":"","namedays":"Aleksandra, Bazylego","title":"Pełnia i lunatycy","subtitle":"nie śpij w świetle księżyca","story":"Dziś w południe pełnia. Wierzono, że kto śpi w świetle księżyca, zostanie lunatykiem albo straci zmysły. Okna zasłaniano, a dzieciom nie pozwalano spać przy oknie. Słowo lunatyk pochodzi od łacińskiego luna. Majowa pełnia jest jasna i ciepła, dobra na nocny spacer, ale nie do spania z odsłoniętym oknem.","practice":"• Wyjdź wieczorem i popatrz na pełnię.\n• Zasłoń okno, zanim zaśniesz.\n• Zapisz sen, jeśli go zapamiętasz.","extraTitle":"Księżyc","extra":"pełnia 20 V, 12:59 · III kwadra 28 V, 15:58","whisper":"Księżyc jest piękny, ale nie musi ci świecić w oczy, kiedy śpisz.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":202}],["2027-05-21","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉ Słońce wchodzi w Bliźnięta (08:18): Na miesiąc cały świat nabiera barw znaku Bliźniąt: czas rozmów, ciekawości, krótkich podróży i wiadomości. Rada: zadzwoń, napisz, zapytaj.","sourceText":{"holiday":"","namedays":"Jana, Wiktora","title":"Podkowa nad drzwiami","subtitle":"żelazo i szczęście","story":"Podkowę wieszano nad drzwiami, by przynosiła szczęście i chroniła przed złym. Żelazo od zawsze odstraszało demony, czarownice i złe duchy. Spór trwa, jak ją wieszać: ramionami do góry, by szczęście się nie wysypało, czy w dół, by spływało na wchodzących. Kowal, który ją wykuł, był człowiekiem ognia i miał w sobie trochę magii.","practice":"• Jeśli masz podkowę albo żelazny przedmiot, powieś go przy drzwiach.\n• Zdecyduj sama: do góry czy w dół.\n• Dotknij go, gdy wychodzisz w ważnej sprawie.","extraTitle":"Ciekawostka","extra":"Znaleziona podkowa przynosi więcej szczęścia niż kupiona.","whisper":"Szczęście najlepiej trzyma się w żelazie, które ktoś kiedyś wykuł ogniem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":203}],["2027-05-22","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 10:58 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿✶♄ Merkury sekstyl Saturn (17:21): Dobry dzień na skupioną pracę, umowy, planowanie i dokumenty.","sourceText":{"holiday":"","namedays":"Heleny, Wiesławy","title":"Kwitnący bez","subtitle":"lilak pod oknem","story":"Pod koniec maja kwitnie lilak, zwany bzem. Fioletowe, białe i różowe kiście pachną tak, że czuć je w całym ogrodzie. Bez był kwiatem matur, zalotów i majowych spacerów. W niektórych domach nie wnoszono go do środka, bo wierzono, że przynosi smutek. Inni stawiali go na stole jako symbol pierwszej miłości.","practice":"• Powąchaj bez na spacerze.\n• Postaw gałązkę w wazonie albo zostaw na krzaku.\n• Pomyśl o pierwszej miłości, z uśmiechem.","extraTitle":"Ciekawostka","extra":"Lilak pochodzi z Bałkanów. Do Polski przywędrował w XVI wieku jako krzew ozdobny.","whisper":"Niektóre zapachy wracają co roku i przypominają, kim byłaś.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":204}],["2027-05-23","work","☽ w Strzelcu do 00:42, potem w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":92.0,"moonAndBiodynamic":"☽ w Strzelcu do 00:42, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 00:42 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Emilii, Iwony","title":"Rusałki","subtitle":"tańczą w zbożu","story":"Po Zielonych Świątkach przychodził rusałczany tydzień. Wtedy rusałki, dusze dziewcząt zmarłych przed ślubem, wychodziły z wody i tańczyły na łąkach i w zbożu. Kogo spotkały, mogły zatańczyć na śmierć albo załaskotać. Na ochronę noszono przy sobie piołun albo bylicę. Zapytana o nazwę rośliny, odpowiadałaś, a rusałka uciekała.","practice":"• Wieczorem przejdź się przez łąkę, jeśli możesz.\n• Weź ze sobą gałązkę piołunu albo bylicy.\n• Zapisz, która dziewczyna z twojej rodziny umarła za młodo.","extraTitle":"Pytanie na niedzielę","extra":"Czyja historia w mojej rodzinie urwała się za wcześnie?","whisper":"Duchy, o których się pamięta, tańczą łagodniej.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":205}],["2027-05-24","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":86.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Bliźniętach · ☿ w Bliźniętach · ♀ w Byku · ♂ w Pannie. Pytanie tygodnia: Czego chcesz się dowiedzieć?","sourceText":{"holiday":"","namedays":"Joanny, Zuzanny","title":"Babka","subtitle":"plaster z drogi","story":"Babka rośnie przy każdej drodze i ścieżce. Jej liście, przyłożone do skaleczenia, ukąszenia albo otarcia, łagodzą ból i pomagają się goić. Dzieci znały ją jako pierwszy plaster. Syrop z babki był lekiem na kaszel. Rośnie tam, gdzie ludzie chodzą, bo lubi ubitą ziemię.","practice":"• Znajdź babkę przy drodze.\n• Rozgnieć liść w palcach i przyłóż do ukąszenia komara.\n• Zastanów się, co w twoim życiu jest pod nogami, a leczy.","extraTitle":"Ciekawostka","extra":"Nasiona babki płesznik są dziś stosowane jako błonnik na trawienie.","whisper":"Lekarstwo często rośnie tam, gdzie chodzisz codziennie.","caution":"Na rany przykładaj czysty liść. Przy głębokich ranach idź do lekarza.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":206}],["2027-05-25","work","☽ w Koziorożcu, od 13:04 w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":79.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 13:04 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 13:04 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu do 13:04: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Borysława, Grzegorza","title":"Racuchy z kwiatów bzu","subtitle":"białe parasolki w cieście","story":"Gdy kwitnie czarny bez, jego białe baldachy można zanurzać w cieście naleśnikowym i smażyć. Wychodzą chrupiące, koronkowe placki, posypane cukrem pudrem. To dawny przysmak wsi i dworów. Kwiaty zbiera się w słoneczny dzień, gdy pachną najmocniej, i nie myje, tylko otrząsa z owadów.","practice":"• Zbierz 10 baldachów czarnego bzu, otrząśnij z owadów.\n• Zanurz w gęstym cieście naleśnikowym, trzymając za łodyżkę.\n• Smaż w głębokim tłuszczu, posyp cukrem pudrem.","extraTitle":"Ciekawostka","extra":"Z kwiatów czarnego bzu robi się też syrop i szampan bzowy.","whisper":"Kwiat to nie tylko ozdoba. Czasem to obiad.","caution":"Jedz tylko kwiaty, nie zielone łodygi. Uważaj na pomyłkę z innymi baldachami.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":207}],["2027-05-26","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":70.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉□♂ Słońce kwadratura Mars (01:13): Napięcie między planetami. Można je wykorzystać na odważne decyzje, sport i ruszanie spraw z miejsca. Uważaj na złość, rywalizację i przeforsowanie się.","sourceText":{"holiday":"","namedays":"Filipa, Pauliny","title":"List do matki","subtitle":"Dzień Matki","story":"Dziś Dzień Matki. Niezależnie od tego, jaka była twoja relacja, matka jest korzeniem. Dawniej dziękowano rodzicom w ważnych chwilach życia: przed ślubem, przed wyjazdem, na łożu śmierci. Napisz list do swojej matki, babki albo kobiety, która była dla ciebie jak matka. Możesz go wysłać albo zostawić dla siebie.","practice":"• Napisz list do matki, babki albo kobiety, która cię wychowała.\n• Wspomnij jedną konkretną chwilę.\n• Zdecyduj, czy go wysyłasz, czy zostawiasz.","extraTitle":"Ciekawostka","extra":"W Polsce Dzień Matki obchodzi się 26 maja od 1923 roku.","whisper":"Korzeń nie musi być idealny, żeby był twój.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":208}],["2027-05-27","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉☌♅ Słońce spotyka Urana (08:11): Niespodzianki, nagłe zmiany planów i przypływ odwagi. Rada: spróbuj czegoś nowego, ale miej plan B.\n☉✶♆ Słońce sekstyl Neptun (18:08): Dobry dzień na intuicję, sztukę, medytację i pomoc innym.","sourceText":{"holiday":"Boże Ciało","namedays":"Augustyna, Juliana","title":"Boże Ciało","subtitle":"wianki i ołtarze","story":"W Boże Ciało procesja idzie od ołtarza do ołtarza, przystrojonych brzozami i kwiatami. Dziewczynki sypią płatki. Po procesji ludzie zabierali gałązki z ołtarzy do domu i ogrodu, by chroniły przed piorunem i szkodnikami. W oktawie święcono wianki z ziół: macierzanki, mięty, rumianku. Wianki wieszano w domu przez cały rok.","practice":"• Uwij mały wianek z ziół, które masz pod ręką.\n• Powieś go w kuchni albo nad drzwiami.\n• Zapisz, co chcesz, żeby chronił.","extraTitle":"Ciekawostka","extra":"Wianki z oktawy Bożego Ciała kładziono pod poduszkę chorym albo dodawano do kąpieli.","whisper":"Wianek to krąg. Co jest w środku, jest chronione.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":209}],["2027-05-28","rest","☽ w Wodniku do 01:55, potem w Rybach","III kwadra",true,{"phase":"III kwadra o 15:58","nextPhase":"nów za 7 dni","illumination":52.0,"moonAndBiodynamic":"☽ w Wodniku do 01:55, potem w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Do 01:55 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉△♇ Słońce trygon Pluton (17:19): Dobry dzień na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna.\n☿ Merkury wchodzi w Raka (19:06): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie domu, rodziny, wspomnień i emocji. Rada: ugotuj coś dla bliskich, zadbaj o gniazdo. Uważaj na nadwrażliwość i obrażanie się.","sourceText":{"holiday":"","namedays":"Jaromira, Justa","title":"Gałązka z ołtarza","subtitle":"w ogrodzie, w polu","story":"Gałązki brzozy z ołtarzy Bożego Ciała zatykano w grządki z kapustą, w pola z lnem, w kąty stodoły. Miały chronić przed gradem, piorunem i gąsienicami. Dziś ostatnia kwadra. Księżyc maleje, a z nim zmartwienia. Dobry czas, by zatknąć w ziemi coś, co mówi: tu jest dobrze.","practice":"• Zatknij gałązkę albo ziele w doniczce lub w ogrodzie.\n• Wypowiedz życzenie dla tego, co rośnie.\n• Odpuść jedno zmartwienie, które nosisz od tygodnia.","extraTitle":"Ciekawostka","extra":"Brzoza była drzewem świętym jeszcze w czasach przedchrześcijańskich. Kościół przejął jej symbolikę.","whisper":"Ochrona zatknięta w ziemi rośnie razem z tym, co chroni.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":210}],["2027-05-29","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":41.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 13:03 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♂□♅ Mars w napięciu z Uranem (04:14): Nerwowość, nagłe zrywy, ryzyko wypadków i kłótni. Uwaga: zwolnij przy maszynach i na drodze, nie decyduj w złości.","sourceText":{"holiday":"","namedays":"Magdaleny, Bogumiły","title":"Jaskry","subtitle":"złote łąki","story":"Pod koniec maja łąki stają się żółte od jaskrów. Ich płatki błyszczą jakby lakierowane, i to dosłownie: mają specjalną warstwę, która odbija światło. Dzieci przykładały jaskry pod brodę: jeśli broda zażółciła się, znaczyło to, że lubisz masło. Jaskry są piękne, ale trujące, a krowy omijają je na pastwisku.","practice":"• Przyłóż jaskier pod brodę komuś bliskiemu i sprawdź, czy lubi masło.\n• Popatrz, jak płatki odbijają światło.\n• Umyj ręce po kontakcie.","extraTitle":"Ciekawostka","extra":"Połysk jaskrów pochodzi z cienkiej warstwy komórek pod powierzchnią płatka, działającej jak lusterko.","whisper":"Nie wszystko, co błyszczy, jest do jedzenia.","caution":"Jaskry są trujące i podrażniają skórę.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":211}],["2027-05-30","rest","☽ w Rybach, od 12:39 w Baranie","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Rybach, od 12:39 w Baranie · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 12:39 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu do 12:39: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Karola, Ferdynanda","title":"Bazyliszek","subtitle":"spojrzenie, które zabija","story":"Bazyliszek był potworem z koguciego jaja wysiedzianego przez ropuchę. Miał głowę koguta, ciało węża i wzrok, który zamieniał w kamień albo zabijał. Według warszawskiej legendy mieszkał w piwnicy na Krzywym Kole. Pokonał go śmiałek, który założył zbroję z lusterek. Bazyliszek zginął od własnego spojrzenia.","practice":"• Popatrz dziś w lustro dłużej niż zwykle.\n• Zapytaj, czy ktoś patrzy na ciebie z jadem.\n• Pomyśl, jak możesz odbić to spojrzenie.","extraTitle":"Pytanie na niedzielę","extra":"Czyje spojrzenie mnie zamraża i jak mogę je od siebie odbić?","whisper":"Najlepszą tarczą przed złym spojrzeniem jest lustro.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":212}],["2027-05-31","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":21.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Bliźniętach · ☿ w Raku · ♀ w Byku · ♂ w Pannie. Pytanie tygodnia: Czego chcesz się dowiedzieć?\n♀□♃ Wenus kwadratura Jowisz (16:46): Napięcie między planetami. Można je wykorzystać na relacje, randki, zakupy, umowy i świętowanie. Uważaj na rozrzutność i przejadanie się.","sourceText":{"holiday":"","namedays":"Anieli, Petroneli","title":"Melisa","subtitle":"zioło spokoju","story":"Melisa pachnie cytryną i miodem. Pszczoły ją uwielbiają, stąd grecka nazwa melissa, czyli pszczoła. Od średniowiecza była ziołem na nerwy, sen i smutek. Mnisi robili z niej wodę karmelitańską. Wystarczy rozetrzeć liść, by poczuć, jak się uspokajasz. Koniec maja to dobry czas, by ją posadzić.","practice":"• Zaparz napar z melisy przed snem.\n• Posadź melisę w doniczce albo w ogrodzie.\n• Rozetrzyj liść, gdy poczujesz napięcie.","extraTitle":"Ciekawostka","extra":"Woda karmelitańska była XVII-wiecznym lekiem na wszystko, od bólu głowy po melancholię.","whisper":"Spokój ma zapach. Często pachnie cytryną.","caution":"Melisa może nasilać senność i działanie leków uspokajających. Ostrożnie przy niedoczynności tarczycy.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":213}],["2027-06-01","start","☽ w Baranie, od 19:33 w Byku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":13.0,"moonAndBiodynamic":"☽ w Baranie, od 19:33 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 19:33 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 09:01 do 19:33: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Jakuba, Justyna","title":"Truskawki ze śmietaną","subtitle":"smak dzieciństwa","story":"Pierwsze truskawki pojawiają się na przełomie maja i czerwca. Na wsi i w mieście podawano je najprościej: w misce ze śmietaną i cukrem albo z twarogiem. Dla dzieci to był smak lata. Truskawki przywędrowały do Polski z Francji w XVIII wieku, a wcześniej jadano tylko leśne poziomki. Dziś Dzień Dziecka: zjedz coś, co cię kiedyś cieszyło.","practice":"• Umyj miskę truskawek, odszypułkuj.\n• Polej śmietaną, posyp cukrem albo polej miodem.\n• Zjedz powoli, najlepiej na dworze.","extraTitle":"Ciekawostka","extra":"Truskawka ogrodowa powstała we Francji w XVIII wieku jako krzyżówka dwóch amerykańskich gatunków poziomki.","whisper":"Dziecko w tobie nie potrzebuje wiele. Wystarczy miska truskawek.","caution":"Nie przy uczuleniu na truskawki.","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":214}],["2027-06-02","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":7.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Erazma, Marianny","title":"Zbieranie ziół o świcie","subtitle":"zasady zielarki","story":"Zielarki znały zasady: zioła zbiera się w suchy, słoneczny dzień, rano po obeschnięciu rosy, a przed południowym upałem. Nie zrywa się wszystkiego, zostawia się część, by roślina odrosła. Nie zbiera się przy drogach i polach pryskanych. Dziękuje się roślinie. Wierzono, że ziele zebrane bez szacunku traci moc.","practice":"• Wyjdź rano na łąkę i rozpoznaj trzy rośliny.\n• Zbierz garść jednej z nich, zostawiając resztę.\n• Podziękuj w myślach i zapisz, gdzie rośnie.","extraTitle":"Ciekawostka","extra":"Zawartość olejków eterycznych w wielu ziołach jest najwyższa w porze kwitnienia, w słoneczne przedpołudnie.","whisper":"Kto bierze wszystko, następnym razem nie znajdzie nic.","caution":"Zbieraj tylko rośliny, które znasz na pewno. Sprawdź, czy nie są chronione.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":215}],["2027-06-03","finances","☽ w Byku, od 22:43 w Bliźniętach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":2.0,"moonAndBiodynamic":"☽ w Byku, od 22:43 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 22:43 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 12:23 do 22:43: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Leszka, Tamary","title":"Nie zabijaj pająka","subtitle":"tkacz szczęścia","story":"Pająka w domu nie wolno było zabijać. Wierzono, że przynosi szczęście, pieniądze i wiadomości. Pająk spuszczający się z sufitu zapowiadał gościa albo list. Pajęczyny w oborze zostawiano, bo łapały muchy, a w ranach dawniej używano ich do tamowania krwi. Pająk tkacz był symbolem cierpliwości i losu.","practice":"• Gdy zobaczysz pająka w domu, wynieś go delikatnie na zewnątrz.\n• Przyjrzyj się pajęczynie z rosą rano.\n• Pomyśl, jaką sieć tkasz w swoim życiu.","extraTitle":"Ciekawostka","extra":"Nić pajęcza jest wytrzymalsza od stali o tej samej grubości.","whisper":"Kto cierpliwie tka, w końcu złapie to, czego szuka.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":216}],["2027-06-04","conversation","☽ w Bliźniętach","nów",false,{"phase":"nów o 21:40","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🌑 Nów w Bliźniętach (21:40): Czas zasiewu w sprawach: rozmowy, nauka, rodzeństwo i sąsiedzi. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Franciszka, Karola","title":"Dziurawiec","subtitle":"czarcie ziele","story":"Dziurawiec zaczyna kwitnąć w czerwcu, a pełnię osiąga na świętego Jana. Spójrz na liść pod światło: zobaczysz drobne dziurki, które legenda przypisuje diabłu, który przebijał go ze złości. Rozetrzyj kwiat, a palce zabarwią się na czerwono. Wierzono, że odpędza złe duchy i melancholię. Dziś nów: dobry czas, by zacząć od ochrony.","practice":"• Poszukaj dziurawca na suchej łące i obejrzyj liść pod światło.\n• Zbierz kilka kwitnących wierzchołków do suszenia.\n• Zapisz intencję na nowy księżycowy miesiąc.","extraTitle":"Księżyc","extra":"nów 4 VI, 21:40 · pełnia 19 VI, 02:44","whisper":"To, co diabeł przebił, przepuszcza światło.","caution":"Dziurawiec uczula na słońce i osłabia działanie wielu leków, w tym antykoncepcji i antydepresantów.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":217}],["2027-06-05","conversation","☽ w Bliźniętach, od 23:38 w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 23:38 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 23:38 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 14:44 do 23:38: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Bonifacego, Waltera","title":"Świetliki","subtitle":"świętojańskie robaczki","story":"W ciepłe czerwcowe noce na skraju lasu i w wilgotnych ogrodach zapalają się świetliki. To chrząszcze, które świecą, by znaleźć partnera. Na wsi nazywano je świętojańskimi robaczkami, bo najwięcej ich koło Jana. Wierzono, że to dusze zmarłych albo iskierki z kwiatu paproci. Coraz ich mniej, bo boją się sztucznego światła.","practice":"• Wyjdź po zmroku na skraj lasu lub do ciemnego ogrodu.\n• Zgaś latarkę i poczekaj, aż oczy przywykną.\n• Zapisz, ile świetlików zobaczyłaś.","extraTitle":"Ciekawostka","extra":"Świecenie świetlika to reakcja chemiczna, w której prawie cała energia zamienia się w światło, prawie bez ciepła.","whisper":"Światło, które nie parzy, jest najrzadsze na świecie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":218}],["2027-06-06","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♅✶♆ Uran i Neptun we współpracy (12:07): Rzadki układ wspierający wynalazki, sztukę i nowe formy duchowości. Rada: daj szansę nowym pomysłom w sprawach ducha i twórczości.","sourceText":{"holiday":"","namedays":"Norberta, Laurentego","title":"Południca","subtitle":"pani południa w zbożu","story":"W upalne południe po polach chodzi południca. Wysoka kobieta w bieli, z sierpem w ręku. Kto pracował w polu w samo południe, mógł ją spotkać. Zadawała zagadki, a kto nie odpowiedział, temu skręcała kark albo zsyłała chorobę. Dziś wiemy, że to opowieść o udarze słonecznym. Południca uczy, że w najgorętszej porze trzeba odpocząć w cieniu.","practice":"• Dziś w południe zrób przerwę w cieniu.\n• Wypij szklankę wody.\n• Zapisz zagadkę, którą chciałabyś zadać światu.","extraTitle":"Pytanie na niedzielę","extra":"Gdzie pracuję w największym upale, choć mogłabym odpocząć?","whisper":"Kto nie umie odpocząć w południe, spotyka południcę.","caution":"Unikaj słońca między 11 a 15. Pij wodę.","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":219}],["2027-06-07","home","☽ w Raku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 22:55 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Bliźniętach · ☿ w Raku · ♀ w Byku · ♂ w Pannie. Pytanie tygodnia: Czego chcesz się dowiedzieć?","sourceText":{"holiday":"","namedays":"Roberta, Wiesława","title":"Rumianek","subtitle":"złote oczko","story":"Rumianek kwitnie w czerwcu na miedzach i polach. Jego zapach przypomina jabłka. To najbardziej znane zioło w polskich domach: na brzuch, oczy, skórę, sen, dziąsła. Przemywano nim oczy, płukano gardło, kąpano niemowlęta. Mówiono, że im bardziej deptany, tym lepiej rośnie. Prawdziwy rumianek ma pusty, wypukły środek kwiatu.","practice":"• Zbierz kwiaty rumianku w słoneczny dzień.\n• Przekrój jeden: prawdziwy rumianek ma pusty środek.\n• Zaparz napar wieczorem.","extraTitle":"Ciekawostka","extra":"Rumianek bezpromieniowy, rosnący przy drogach, pachnie podobnie, ale nie ma białych płatków.","whisper":"Łagodność bywa najsilniejszym lekarstwem.","caution":"Nie przy uczuleniu na astrowate. Do oczu tylko świeżo przecedzony napar.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":220}],["2027-06-08","creative","☽ w Raku do 00:12, potem we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":17.0,"moonAndBiodynamic":"☽ w Raku do 00:12, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 00:12 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀ Wenus wchodzi w Bliźnięta (14:32): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie rozmów, ciekawości, krótkich podróży i wiadomości. Rada: zadzwoń, napisz, zapytaj. Uważaj na rozproszenie i plotki.","sourceText":{"holiday":"św. Medarda","namedays":"Maksyma, Medarda","title":"Chłodnik na Medarda","subtitle":"różowa zupa upału","story":"Na świętego Medarda patrzono w niebo. Jeśli padał deszcz, miało padać przez czterdzieści dni. W upał podawano chłodnik: zimną zupę z botwiny, ogórka, rzodkiewki, koperku i kwaśnego mleka. Różowy kolor dają młode buraczki. Na Litwie i w Polsce to klasyk czerwca, który chłodzi lepiej niż lody.","practice":"• Ugotuj botwinę z buraczkami, ostudź.\n• Wymieszaj z litrem kefiru, ogórkiem, rzodkiewką i koperkiem.\n• Schłodź i podawaj z jajkiem na twardo.","extraTitle":"Ciekawostka","extra":"Medard był biskupem z VI wieku. Ludowe przysłowia o czterdziestu dniach deszczu łączono z nim w całej Europie.","whisper":"W upał najlepiej działają rzeczy proste i zimne.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":221}],["2027-06-09","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":27.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 17:21 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Anny, Felicjana","title":"Suszenie ziół","subtitle":"w cieniu i przewiewie","story":"Zioła suszy się w cieniu, w przewiewnym miejscu, nigdy na słońcu, bo tracą kolor i moc. Wiąże się je w pęczki i wiesza główkami w dół albo rozkłada cienką warstwą na papierze. Na strychu chaty zawsze wisiały pęki ziół i pachniało jak w aptece. Dobrze wysuszone zioło szeleści, ale nie kruszy się w pył.","practice":"• Zwiąż pęczek ziół, które masz.\n• Zawieś w cienistym, przewiewnym miejscu główkami w dół.\n• Po kilku dniach przełóż do papierowej torby lub słoika.","extraTitle":"Ciekawostka","extra":"Suszone zioła najlepiej zużyć w ciągu roku. Później tracą olejki i działanie.","whisper":"Moc zachowuje się w cieniu, nie na słońcu.","caution":"Pilnuj, by zioła nie spleśniały. Spleśniałe wyrzuć.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":222}],["2027-06-10","organize","☽ we Lwie do 02:00, potem w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":38.0,"moonAndBiodynamic":"☽ we Lwie do 02:00, potem w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Do 02:00 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury rusza wstecz w Raku (20:15): Przez trzy tygodnie łatwiej o pomyłki w rozmowach, umowach, mailach i podróżach. To dobry czas na powroty: do starych projektów, ludzi i notatek. Rada: sprawdzaj dwa razy, nie podpisuj w pośpiechu, rób kopie.","sourceText":{"holiday":"","namedays":"Bogumiła, Małgorzaty","title":"Kąpiel przed Janem","subtitle":"woda jeszcze nie oczyszczona","story":"Do świętego Jana nie wolno było kąpać się w rzekach i jeziorach. Mówiono, że woda jest jeszcze nieochrzczona, a topielce i rusałki czekają na ofiarę. Dopiero po Janie, gdy święty pobłogosławi wody, można było wejść bez lęku. W tej opowieści jest też zdrowy rozsądek: w czerwcu woda bywa zimna, a nurt rzeki zdradliwy.","practice":"• Jeśli idziesz nad wodę, sprawdź, czy jest kąpielisko strzeżone.\n• Nie wchodź do wody po alkoholu.\n• Pomyśl, w co ty wchodzisz za szybko.","extraTitle":"Ciekawostka","extra":"Według statystyk najwięcej utonięć zdarza się w niestrzeżonych miejscach w ciepłe dni.","whisper":"Woda nie zna pośpiechu. Kto się spieszy, ten tonie.","caution":"Kąp się tylko w miejscach strzeżonych.","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":223}],["2027-06-11","organize","☽ w Pannie","I kwadra",false,{"phase":"I kwadra o 12:56","nextPhase":"pełnia za 8 dni","illumination":50.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ☿ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 12:56 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Barnaby, Radomiła","title":"Osika","subtitle":"drzewo, które drży","story":"Liście osiki drżą przy najmniejszym wietrze. Legenda mówi, że na osice powiesił się Judasz albo że z jej drewna zrobiono krzyż, i dlatego drży ze wstydu. Osikowy kołek wbijano w grób wampira, by nie wstawał. Gałązki osiki zatykano na bramach przeciw czarownicom. Drzewo przeklęte i ochronne zarazem.","practice":"• Znajdź osikę i posłuchaj szumu jej liści.\n• Zabierz jeden liść i włóż do książki.\n• Pomyśl, co w tobie drży, choć jest silne.","extraTitle":"Ciekawostka","extra":"Liście osiki drżą, bo mają spłaszczone ogonki, które łatwo skręcają się na wietrze.","whisper":"To, co drży, nie zawsze jest słabe. Czasem po prostu czuje wiatr.","caution":"","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":224}],["2027-06-12","relationships","☽ w Pannie do 05:57, potem w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":60.0,"moonAndBiodynamic":"☽ w Pannie do 05:57, potem w Wadze · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 05:57 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Janiny, Jana","title":"Maki i chabry","subtitle":"czerwień i błękit w zbożu","story":"W czerwcu zboża kwitną czerwienią maków i błękitem chabrów. Kiedyś były wszędzie, dziś coraz rzadsze przez opryski. Chabrem barwiono płótno i przemywano oczy. Mak był kwiatem snu i zapomnienia, a jego ziarna sypano w Wigilię. Pole z makami i chabrami to obraz, który znają wszyscy, choć rzadko widzą.","practice":"• Poszukaj maków i chabrów na skraju pola.\n• Zrób zdjęcie, nie wchodź w zboże.\n• Pomyśl o kolorach, które cię uspokajają.","extraTitle":"Ciekawostka","extra":"Chaber był ulubionym kwiatem cesarza Wilhelma I i stał się symbolem Prus.","whisper":"Najpiękniejsze kolory rosną na skraju, nie w środku pola.","caution":"Nie depcz zboża.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":225}],["2027-06-13","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":70.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉✶♃ Słońce sekstyl Jowisz (11:38): Dobry dzień na optymizm, prośby, oferty, naukę i podróże.\n♀✶♆ Wenus sekstyl Neptun (21:56): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.","sourceText":{"holiday":"","namedays":"Lucjana, Antoniego","title":"Wodnik","subtitle":"pan topielców","story":"W głębokich rzekach i stawach mieszkał wodnik, zwany też topielcem. Był zielonkawy, z długimi włosami, mokry od stóp do głów. Wciągał ludzi pod wodę i trzymał ich dusze w odwróconych garnkach na dnie. Młynarze składali mu ofiary, bo mógł zniszczyć młyn. Wodnik uczy szacunku do wody, która daje życie i może je zabrać.","practice":"• Usiądź nad wodą i posłuchaj jej szumu.\n• Wrzuć do niej kwiat zamiast śmieci.\n• Pomyśl, czego się boisz w głębi.","extraTitle":"Pytanie na niedzielę","extra":"Jaką głębię w sobie omijam, bo boję się, że mnie wciągnie?","whisper":"Woda jest dobra dla tych, którzy znają jej miarę.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":226}],["2027-06-14","relationships","☽ w Wadze, od 12:17 w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":79.0,"moonAndBiodynamic":"☽ w Wadze, od 12:17 w Skorpionie · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 12:17 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 03:33 do 12:17: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Bliźniętach · ☿ w Raku · ♀ w Bliźniętach · ♂ w Pannie. Pytanie tygodnia: Czego chcesz się dowiedzieć?\n♀☌♅ Wenus koniunkcja Uran (04:18): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku. Uważaj tylko na nagłe zauroczenia i wydatki pod wpływem chwili.\n♀△♇ Wenus trygon Pluton (06:03): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach.","sourceText":{"holiday":"","namedays":"Bazylego, Elizy","title":"Krwawnik","subtitle":"ziele wojowników","story":"Krwawnik rośnie przy drogach i na łąkach, z białymi baldachami i pierzastymi liśćmi. Nazwa mówi wszystko: tamował krew z ran. Legenda wiąże go z Achillesem, który leczył nim rany żołnierzy, stąd łacińska nazwa Achillea. W medycynie ludowej był ziołem kobiecym, na bóle miesiączkowe i trawienie.","practice":"• Rozpoznaj krwawnik po pierzastych liściach.\n• Rozetrzyj liść i powąchaj, pachnie ostro i ziołowo.\n• Zbierz kwitnące wierzchołki do suszenia.","extraTitle":"Ciekawostka","extra":"Łodygi krwawnika służyły w Chinach do wróżenia z Księgi Przemian.","whisper":"Kto zna rany, zna też zioła, które je goją.","caution":"Nie w ciąży. Nie przy uczuleniu na astrowate.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":227}],["2027-06-15","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":87.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia · ☿ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♅△♇ Uran w harmonii z Plutonem (10:08): Pokoleniowy układ sprzyjający przełomom i odnowie, zwłaszcza w technologii i społeczeństwie. Rada: nie bój się zmiany, która od dawna dojrzewa.","sourceText":{"holiday":"","namedays":"Wita, Jolanty","title":"Młode ziemniaki z koperkiem","subtitle":"z zsiadłym mlekiem","story":"W czerwcu wychodzą pierwsze młode ziemniaki. Na wsi jadano je najprościej: ugotowane w mundurkach albo obrane, polane masłem i posypane koperkiem, z kubkiem zsiadłego mleka. To była potrawa żniw i upałów, tania i sycąca. Zsiadłe mleko chłodzi, koperek pachnie latem.","practice":"• Wyszoruj młode ziemniaki, ugotuj w osolonej wodzie z gałązką kopru.\n• Polej masłem i posyp posiekanym koperkiem.\n• Podawaj z kubkiem zimnego kefiru albo zsiadłego mleka.","extraTitle":"Ciekawostka","extra":"Zsiadłe mleko robiono, zostawiając świeże mleko w cieple na noc. Dziś najbliższy jest kefir lub maślanka.","whisper":"Najlepsze jedzenie lata nie potrzebuje przepisu.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":228}],["2027-06-16","honesty","☽ w Skorpionie, od 20:53 w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Skorpionie, od 20:53 w Strzelcu · dzień liścia · ☿ retro","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 20:53 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 06:45 do 20:53: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉✶♄ Słońce sekstyl Saturn (23:08): Dobry dzień na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach.","sourceText":{"holiday":"","namedays":"Aliny, Benona","title":"Wicie wianka","subtitle":"przed Nocą Kupały","story":"Przed Nocą Kupały dziewczęta wiły wianki z polnych kwiatów i ziół: rumianku, bylicy, macierzanki, dziurawca, maków, chabrów. Każde zioło miało znaczenie. Wianek był symbolem dziewictwa, cyklu i ochrony. Wito go w skupieniu, myśląc o tym, czego się pragnie. Później puszczano go na wodę.","practice":"• Zbierz polne kwiaty i zioła.\n• Uwij wianek, myśląc o jednym pragnieniu.\n• Zostaw go do Nocy Kupały w chłodnym miejscu.","extraTitle":"Ciekawostka","extra":"Do wianka wplatano często dziewięć ziół. Dziewiątka była liczbą magiczną.","whisper":"Wianek to modlitwa, którą się trzyma w rękach.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":229}],["2027-06-17","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ☿ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Alberta, Ignacego","title":"Nie gwiżdż w domu","subtitle":"wywołasz biedę","story":"W domu nie wolno było gwizdać. Mówiono, że gwizdanie wywołuje złe duchy, diabła albo biedę, a pieniądze uciekają z domu. Na morzu gwizdanie miało wywołać sztorm. Gwizd to dźwięk, który przenika i woła. Dlatego używano go na zewnątrz, by przywołać psa albo dać znak, nie w domu, gdzie miał panować spokój.","practice":"• Zauważ, kiedy gwiżdżesz.\n• Gwiżdż na zewnątrz, nie w domu, i obserwuj, jak się czujesz.\n• Pomyśl, co w twoim domu wymaga ciszy.","extraTitle":"Ciekawostka","extra":"Przesąd o gwizdaniu jest znany w Rosji, na Ukrainie i w krajach bałtyckich.","whisper":"Niektóre dźwięki wołają. Uważaj, co wołasz.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":230}],["2027-06-18","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu · ☿ retro","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Marka, Elżbiety","title":"Pas z bylicy","subtitle":"na Noc Kupały","story":"W Noc Kupały przepasywano się bylicą. Pas z bylicy chronił przed czarami, chorobami i bólem krzyża przy żniwach. Po zabawie wrzucano go w ogień, a z nim wszystkie nieszczęścia. Bylica była zielem świętojańskim, zwanym też czarnobylem. Wierzono, że jej zapach odpędza diabła i złe sny.","practice":"• Zbierz kilka łodyg bylicy.\n• Uwij z nich pas albo bransoletkę.\n• Noś przez chwilę, a potem spal lub zakop.","extraTitle":"Ciekawostka","extra":"Bylica była zielem poświęconym Artemidzie, bogini kobiet, stąd łacińska nazwa Artemisia.","whisper":"To, co cię opasuje, chroni twój środek.","caution":"Bylica może uczulać. Nie w ciąży.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":231}],["2027-06-19","work","☽ w Strzelcu do 07:35, potem w Koziorożcu","pełnia",false,{"phase":"pełnia o 02:44","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Strzelcu do 07:35, potem w Koziorożcu · dzień korzenia · ☿ retro","goodFor":"dobry dzień na pracę","energy":"Do 07:35 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 02:44 do 07:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🌕 Pełnia w Strzelcu (02:44): Kulminacja w sprawach: sens, podróże, nauka. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Gerwazego, Protazego","title":"Niska pełnia","subtitle":"Księżyc przy ziemi","story":"Dziś nad ranem pełnia. Czerwcowa pełnia jest najniżej na niebie z całego roku, bo Księżyc w pełni jest zawsze po przeciwnej stronie niż Słońce, a Słońce teraz jest najwyżej. Dlatego czerwcowy Księżyc wisi nisko nad horyzontem, duży i często złoty albo pomarańczowy. Noce są krótkie, a Księżyc bliski jak latarnia.","practice":"• Wyjdź wieczorem i popatrz na Księżyc nisko nad horyzontem.\n• Porównaj jego kolor z zimowym.\n• Zapisz, co cię dziś przyciąga.","extraTitle":"Księżyc","extra":"pełnia 19 VI, 02:44 · III kwadra 27 VI, 06:54","whisper":"Światło, które jest blisko ziemi, wydaje się większe.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":232}],["2027-06-20","work","☽ w Koziorożcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":98.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia · ☿ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Diny, Bogny","title":"Czarownica","subtitle":"ta, która wie","story":"Słowo czarownica pochodzi od czarów, a wiedźma od wiedzy. Wiedźma to ta, która wie: zna zioła, poród, sny, choroby i pogodę. Na wsi bano się jej i szukano jej pomocy jednocześnie. W XVII i XVIII wieku w Polsce, jak w całej Europie, oskarżano kobiety o czary i palono je na stosach. Wiedza bywała niebezpieczna dla tych, które ją miały.","practice":"• Pomyśl o kobiecie w twojej rodzinie, która „wiedziała”.\n• Zapisz jedną rzecz, której cię nauczyła.\n• Przekaż tę wiedzę komuś dalej.","extraTitle":"Pytanie na niedzielę","extra":"Czego wiem, a boję się tego pokazać?","whisper":"Wiedza, która się ukrywa, zostaje zapomniana. Ta, która się dzieli, żyje.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":233}],["2027-06-21","work","☽ w Koziorożcu, od 20:00 w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":95.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 20:00 w Wodniku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 20:00 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 11:36 do 20:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Bliźniętach · ☿ w Raku · ♀ w Bliźniętach · ♂ w Pannie. Pytanie tygodnia: Czego chcesz się dowiedzieć?\n☉ Słońce wchodzi w Raka (16:10): Na miesiąc cały świat nabiera barw znaku Raka: czas domu, rodziny, wspomnień i emocji. Rada: ugotuj coś dla bliskich, zadbaj o gniazdo.","sourceText":{"holiday":"przesilenie letnie, 16:11 · najdłuższy dzień","namedays":"Alicji, Alojzego","title":"Dziewanna","subtitle":"królewska świeca","story":"Dziś o 16:11 przesilenie letnie i najdłuższy dzień roku. Na suchych skarpach kwitną dziewanny: wysokie, żółte świece z puszystymi liśćmi. Łodygi maczano w smole i używano jako pochodni. Kwiaty dziewanny leczyły kaszel, a liście służyły jako miękkie wkładki do butów. Dziewanna stoi wysoko jak słońce w najdłuższym dniu.","practice":"• Wyjdź dziś o zachodzie słońca i zapamiętaj, gdzie zachodzi.\n• Poszukaj dziewanny na skarpie.\n• Zapisz, co osiągnęło w tobie pełnię.","extraTitle":"Ciekawostka","extra":"Od jutra dni zaczną się skracać. Najdłuższy dzień to zarazem początek drogi ku zimie.","whisper":"Pełnia światła to też moment, w którym zaczyna się powrót do ciemności.","caution":"Napar z kwiatów przecedź przez gęste płótno, by usunąć włoski.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":234}],["2027-06-22","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":90.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Pauliny, Tomasza","title":"Syrop z kwiatów czarnego bzu","subtitle":"lato w butelce","story":"Z kwiatów czarnego bzu robi się syrop, który pachnie miodem i latem. Kwiaty zalewa się wodą z cytryną, odstawia na dobę, odcedza i gotuje z cukrem. Syrop rozcieńczony wodą to najlepsza lemoniada świata. Dawniej pito go na przeziębienie, bo kwiat bzu działa napotnie. Zrobiony w czerwcu przypomni lato w styczniu.","practice":"• Zalej 20 baldachów bzu 2 l wody, dodaj pokrojoną cytrynę.\n• Odstaw pod przykryciem na 24 godziny, odcedź.\n• Zagotuj z 1,5 kg cukru, przelej gorący do butelek.","extraTitle":"Ciekawostka","extra":"W Wielkiej Brytanii syrop z kwiatów bzu nazywa się elderflower cordial i jest bardzo popularny.","whisper":"Lato można zamknąć w butelce. Trzeba tylko wiedzieć kiedy.","caution":"Tylko kwiaty, bez zielonych łodyżek.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":235}],["2027-06-23","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":83.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀□♂ Wenus kwadratura Mars (08:28): Napięcie między planetami. Można je wykorzystać na namiętność, randki, taniec i twórczą energię. Uważaj na napięcie w związku i różnice potrzeb.\n☉☌☿ Słońce koniunkcja Merkury (09:59): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"Noc Kupały · sobótka","namedays":"Wandy, Zenona","title":"Noc Kupały","subtitle":"ogień, woda, kwiat paproci","story":"Najkrótsza noc roku należy do ognia i wody. Palono sobótki, wielkie ogniska na wzgórzach, a młodzi skakali przez nie parami. Kto przeskoczył razem, miał być razem. Dziewczęta puszczały wianki na wodę: jeśli chłopak wyłowił, był znak. O północy w lesie zakwitał kwiat paproci, dający szczęście i bogactwo temu, kto go znalazł.","practice":"• Zapal świecę albo ognisko, jeśli możesz bezpiecznie.\n• Puść wianek na wodę albo zostaw go w ogrodzie.\n• Przez chwilę posłuchaj nocy bez telefonu.","extraTitle":"Ciekawostka","extra":"Nazwa sobótka pochodzi od soboty, a Kupała prawdopodobnie od kąpieli, czyli oczyszczenia w wodzie.","whisper":"W najkrótszą noc liczy się każda chwila. Spędź ją przy ogniu.","caution":"Ognisko tylko w dozwolonym miejscu. Wianek bez plastiku.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":236}],["2027-06-24","rest","☽ w Wodniku do 09:00, potem w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":76.0,"moonAndBiodynamic":"☽ w Wodniku do 09:00, potem w Rybach · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Do 09:00 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 01:02 do 09:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"św. Jana Chrzciciela","namedays":"Jana, Danuty","title":"Rosa świętojańska","subtitle":"Jan otwiera wody","story":"W dzień świętego Jana rosa miała moc leczenia. Dziewczęta myły nią twarz dla urody, a chorzy tarzali się w niej. Od Jana można było kąpać się w rzekach. Zbierano zioła świętojańskie: dziurawiec, bylicę, rumianek, macierzankę. Wierzono, że zebrane w tę noc mają podwójną moc. Kukułka przestaje kukać, lato się zaczyna.","practice":"• Rano przemyj twarz rosą.\n• Zbierz garść ziół i zwiąż je w pęczek świętojański.\n• Powieś go w domu do następnego roku.","extraTitle":"Ciekawostka","extra":"Wierzono, że po świętym Janie kukułka milknie, bo zadławiła się kłosem zboża.","whisper":"Rosa jest najświeższa przed pierwszym promieniem. Tak samo nadzieja.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":237}],["2027-06-25","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":67.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Lucji, Wilhelma","title":"Supeł","subtitle":"zło zamknięte w węźle","story":"Węzeł był magiczny. Szeptuchy zawiązywały choroby w supłach i zakopywały je albo palono. Na czerwonych nitkach wiązano supełki ochronne. Podczas porodu rozwiązywano wszystkie węzły w domu, by dziecko łatwiej przyszło na świat. Zawiązać to zamknąć, rozwiązać to uwolnić.","practice":"• Weź nitkę i zawiąż na niej trzy supły, każdy z jedną intencją.\n• Noś ją przy sobie przez tydzień.\n• Potem zdecyduj: rozwiązujesz czy palisz.","extraTitle":"Ciekawostka","extra":"Słowa „zawiązać” i „rozwiązać” w wielu językach znaczą też zaczarować i odczarować.","whisper":"Niektóre sprawy trzeba zawiązać, żeby nie rozlały się na całe życie.","caution":"","bibliography":"Magia słowa, IZPiTN 2026","bookKey":""},"sourceRow":238}],["2027-06-26","rest","☽ w Rybach, od 20:35 w Baranie","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":58.0,"moonAndBiodynamic":"☽ w Rybach, od 20:35 w Baranie · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 20:35 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 20:08 do 20:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿ Merkury cofa się do Bliźniąt (09:19): Ruchem wstecznym Merkury wraca do znaku Bliźniąt i każe dokończyć stare sprawy. Rada: wróć do rozpoczętych rozmów, zanim zaczniesz nowe.","sourceText":{"holiday":"","namedays":"Jana, Pawła","title":"Lipa kwitnie","subtitle":"miodowy zapach","story":"Pod koniec czerwca kwitną lipy. Cała ulica pachnie miodem, a pszczoły brzęczą tak, że drzewo zdaje się śpiewać. Lipa była świętym drzewem Słowian, drzewem kobiet i spokoju. Pod lipą sądzono, rozmawiano, odpoczywano. Kochanowski napisał o niej fraszkę. Kwiat lipy na przeziębienie zna każda babcia.","practice":"• Usiądź pod kwitnącą lipą i posłuchaj pszczół.\n• Zbierz kilka kwiatostanów z przysadkami do suszenia.\n• Przeczytaj fraszkę Kochanowskiego „Na lipę”.","extraTitle":"Ciekawostka","extra":"Lipa jest najczęstszym drzewem w nazwach polskich miejscowości: Lipno, Lipsko, Lipiny.","whisper":"Drzewo, pod którym się odpoczywa, jest ważniejsze niż drzewo, które się ścina.","caution":"Kwiat lipy działa napotnie. Ostrożnie przy chorobach serca.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":239}],["2027-06-27","start","☽ w Baranie","III kwadra",false,{"phase":"III kwadra o 06:54","nextPhase":"nów za 7 dni","illumination":48.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ☿ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Maryli, Władysława","title":"Kwiat paproci","subtitle":"szczęście, którym się nie dzieli","story":"W baśniach kwiat paproci daje bogactwo i szczęście. Ale jest warunek: tym szczęściem nie można się dzielić. W opowieści Kraszewskiego Jacek znalazł kwiat i stał się bogaty, ale gdy wrócił do domu, jego bliscy już nie żyli, a on był sam. Dziś ostatnia kwadra. Księżyc maleje i pyta: po co ci szczęście bez ludzi?","practice":"• Pomyśl o momencie, w którym szczęście było większe, bo dzieliłaś je z kimś.\n• Podziel się dziś czymś dobrym.\n• Zadzwoń do kogoś, z kim dawno nie rozmawiałaś.","extraTitle":"Pytanie na niedzielę","extra":"Jakie szczęście zatrzymuję dla siebie, choć mogłabym je dzielić?","whisper":"Szczęście, którym się nie dzielisz, zamienia się w samotność.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":240}],["2027-06-28","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":36.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ☿ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Raku · ☿ w Bliźniętach · ♀ w Bliźniętach · ♂ w Pannie. Pytanie tygodnia: Czego potrzebuje Twój dom?\n☉□♆ Słońce kwadratura Neptun (14:50): Napięcie między planetami. Można je wykorzystać na intuicję, sztukę, medytację i pomoc innym. Uważaj na złudzenia, zmęczenie i niejasne sytuacje.\n♀✶♃ Wenus sekstyl Jowisz (20:44): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.","sourceText":{"holiday":"","namedays":"Leona, Ireneusza","title":"Macierzanka","subtitle":"tymianek łąk","story":"Macierzanka płoży się po suchych łąkach i skarpach, tworząc fioletowe poduszki pachnące tymiankiem. Nazwa pochodzi od matki: była ziołem kobiet, matek i dzieci. Kąpano w niej niemowlęta, robiono syrop na kaszel i dodawano do wianków. Pszczoły ją kochają. Usiądź na niej, a zapach otuli cię jak koc.","practice":"• Poszukaj macierzanki na suchej, słonecznej łące.\n• Usiądź obok niej i powąchaj.\n• Zbierz kilka gałązek do herbaty.","extraTitle":"Ciekawostka","extra":"Macierzanka to dziki krewny tymianku ogrodowego. Oba zawierają tymol, olejek o działaniu antyseptycznym.","whisper":"Matczyna troska często pachnie skromnie, ale zostaje w pamięci na zawsze.","caution":"Nie w ciąży w dużych ilościach.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":241}],["2027-06-29","finances","☽ w Baranie do 04:46, potem w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":26.0,"moonAndBiodynamic":"☽ w Baranie do 04:46, potem w Byku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na finanse","energy":"Do 04:46 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♆✶♇ Neptun i Pluton we współpracy (01:56): Długi, pokoleniowy układ, który teraz jest dokładny. Duchowość i głęboka przemiana idą w parze. Rada: pomyśl, w co wierzysz naprawdę i co chcesz zmienić na lata.","sourceText":{"holiday":"św. Piotra i Pawła","namedays":"Piotra, Pawła","title":"Ryba z masłem i koperkiem","subtitle":"na Piotra rybaka","story":"Święty Piotr był rybakiem, więc w jego dzień rybacy święcili sieci i łodzie. W niektórych nadmorskich wsiach odbywały się procesje na wodzie. Na stół trafiała ryba: pstrąg, lin albo okoń, smażona na maśle z koperkiem. Proste, letnie danie, które smakuje najlepiej nad wodą.","practice":"• Opłucz rybę, osusz, posól i obtocz w mące.\n• Smaż na maśle po 4 minuty z każdej strony.\n• Podawaj z koperkiem, cytryną i młodymi ziemniakami.","extraTitle":"Ciekawostka","extra":"Kaszubskie procesje na wodzie w dniu Piotra i Pawła odbywają się do dziś w Pucku.","whisper":"Kto łowi cierpliwie, ten zawsze coś przyniesie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":242}],["2027-06-30","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":17.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♄ Wenus sekstyl Saturn (07:25): Dobry dzień na trwałe zobowiązania, inwestycje i porządki w finansach.","sourceText":{"holiday":"","namedays":"Emilii, Lucyny","title":"Połowa roku","subtitle":"rachunek półrocza","story":"Dziś koniec czerwca i połowa roku. Dobry czas, by się zatrzymać i spojrzeć, co się wydarzyło od stycznia. Jakie postanowienia się spełniły, które przestały mieć sens, a które czekają. Na wsi w tym czasie zaczynały się żniwa i liczyło się, ile przyniesie pole. Twoje pole też już coś przyniosło.","practice":"• Przeczytaj, co zapisałaś w styczniu, jeśli zapisałaś.\n• Zrób listę: co się udało, co odpuszczam, co zostaje.\n• Wybierz jedną rzecz na drugą połowę roku.","extraTitle":"Pytanie do dziennika","extra":"Co ta połowa roku powiedziała mi o mnie?","whisper":"Pół roku to dość, by zobaczyć, co rośnie, i dość, by jeszcze zmienić kierunek.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":243}],["2027-07-01","conversation","☽ w Byku do 08:55, potem w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Byku do 08:55, potem w Bliźniętach · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy","energy":"Do 08:55 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 00:41 do 08:55: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿☌♀ Merkury koniunkcja Wenus (11:22): Dobry dzień na miłe rozmowy, komplementy, negocjacje i pisanie. Uważaj tylko na pustą uprzejmość i niezałatwione sprawy.","sourceText":{"holiday":"","namedays":"Haliny, Mariana","title":"Nie pokazuj tęczy palcem","subtitle":"tęcza pije wodę","story":"Tęcza po burzy była cudem i zagadką. Mówiono, że tęcza pije wodę z rzek i jezior, a potem oddaje ją jako deszcz. Nie wolno było jej pokazywać palcem, bo palec usycha albo przychodzi nieszczęście. Kto przeszedł pod tęczą, miał zmienić płeć. Na końcu tęczy miał leżeć skarb, ale nikt nigdy do niego nie doszedł.","practice":"• Gdy po burzy pojawi się tęcza, popatrz na nią bez telefonu.\n• Policz jej kolory.\n• Zapisz życzenie, które pojawia się w głowie.","extraTitle":"Ciekawostka","extra":"Tęcza zawsze pojawia się po przeciwnej stronie nieba niż Słońce. Trzeba stać plecami do słońca.","whisper":"Niektórych rzeczy nie trzeba wskazywać. Wystarczy na nie patrzeć.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":244}],["2027-07-02","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"Matki Boskiej Jagodnej","namedays":"Jagody, Urbana","title":"Matka Boża Jagodna","subtitle":"jagody dla zmarłych dzieci","story":"Do tego dnia matki, które straciły dziecko, nie jadły jagód ani poziomek. Wierzono, że w niebie Matka Boża rozdaje jagody zmarłym dzieciom, ale nie da ich dziecku, którego matka zjadła już swoje. To jeden z najczulszych zwyczajów polskiej wsi. Od Jagodnej można było iść do lasu na jagody bez lęku.","practice":"• Pomyśl o dzieciach, które odeszły za wcześnie w twojej rodzinie lub wśród bliskich.\n• Zostaw w ogrodzie albo na parapecie garść jagód.\n• Zadzwoń do kogoś, kto stracił dziecko, i po prostu zapytaj, jak się ma.","extraTitle":"Ciekawostka","extra":"Święto Nawiedzenia Najświętszej Maryi Panny ma wiele ludowych nazw: Jagodna, Matki Boskiej Jagodnej, Matki Boskiej Wędrownej.","whisper":"Żałoba ma swój czas. Nawet jagody na nią czekają.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":245}],["2027-07-03","home","☽ w Bliźniętach do 09:58, potem w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Bliźniętach do 09:58, potem w Raku · dzień liścia · ☿ retro","goodFor":"dobry dzień na dom","energy":"Do 09:58 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 06:05 do 09:58: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀ Wenus wchodzi w Raka (04:01): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie domu, rodziny, wspomnień i emocji. Rada: ugotuj coś dla bliskich, zadbaj o gniazdo. Uważaj na nadwrażliwość i obrażanie się.","sourceText":{"holiday":"","namedays":"Jacka, Anatola","title":"Jagody w lesie","subtitle":"granatowe dłonie","story":"W lipcu w borach sosnowych dojrzewają jagody, czyli borówki czarne. Całe wsie chodziły na jagody z koszami, a dzieci wracały z granatowymi ustami i rękami. Jagody sprzedawano na targu i suszono na zimę, bo suszone leczyły biegunkę. Jagodziny chronią przed słońcem kleszcze i grzyby. Las jest pełen życia, które trzeba umieć zobaczyć.","practice":"• Wybierz się do lasu na jagody, jeśli możesz.\n• Zbieraj ręcznie, nie grzebieniem.\n• Zjedz garść prosto z krzaczka.","extraTitle":"Ciekawostka","extra":"Leśna jagoda ma fioletowy miąższ, a borówka amerykańska biały. Stąd granatowe ręce.","whisper":"Najlepsze owoce rosną nisko. Trzeba się do nich schylić.","caution":"Myj jagody przed jedzeniem. Po lesie sprawdź ciało pod kątem kleszczy.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":246}],["2027-07-04","home","☽ w Raku","nów",false,{"phase":"nów o 05:02","nextPhase":"pełnia za 14 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia · ☿ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: nów, czas na zasiew, ciszę i intencje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌑 Nów w Raku (05:02): Czas zasiewu w sprawach: dom, rodzina, korzenie. Rada: zapisz intencję na ten księżycowy miesiąc.\n☿ Merkury rusza naprzód w Bliźniętach (21:39): Komunikacja się odblokowuje, choć przez kilka dni sprawy jeszcze się dopinają. Rada: wyślij to, co czekało, ale daj sobie dwa, trzy dni zapasu.","sourceText":{"holiday":"","namedays":"Malwiny, Odona","title":"Leszy","subtitle":"pan lasu","story":"Leszy, zwany też borowym, był panem lasu. Mógł być wysoki jak sosna albo mały jak trawa. Zwodził ludzi, prowadził w kółko, aż się zgubili. Na ochronę przewracano ubranie na lewą stronę albo zakładano buty na odwrót. Leszy nie lubił gwałtowników i krzykaczy. Dziś nów: dobry dzień, by wejść do lasu z szacunkiem.","practice":"• Wchodząc do lasu, przywitaj się w myślach.\n• Nie krzycz, nie łam gałęzi.\n• Jeśli się zgubisz, zatrzymaj się i pomyśl.","extraTitle":"Pytanie na niedzielę","extra":"Gdzie kręcę się w kółko, bo nie zatrzymałam się, by pomyśleć?","whisper":"Las nie zwodzi tych, którzy wchodzą do niego cicho.","caution":"Zabierz do lasu telefon, wodę i powiedz komuś, dokąd idziesz.","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":247}],["2027-07-05","creative","☽ w Raku do 09:40, potem we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Raku do 09:40, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 09:40 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 04:35 do 09:40: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Raku · ☿ w Bliźniętach · ♀ w Raku · ♂ w Pannie. Pytanie tygodnia: Czego potrzebuje Twój dom?","sourceText":{"holiday":"","namedays":"Marii, Antoniego","title":"Nagietek","subtitle":"pomarańczowe słońce ogrodu","story":"Nagietek kwitnie od czerwca do przymrozków, pomarańczowy jak słońce. Jego kwiaty otwierają się rano i zamykają wieczorem. Maść nagietkowa goiła rany, otarcia i odparzenia u dzieci. Płatki dodawano do sera i masła, by miały złoty kolor. Nagietek sadzono przy warzywach, bo odstrasza szkodniki.","practice":"• Zbierz kwiaty nagietka do suszenia.\n• Zrób olej nagietkowy: zalej suszone płatki oliwą, odstaw na 3 tygodnie w ciemne miejsce.\n• Posadź nagietek przy pomidorach.","extraTitle":"Ciekawostka","extra":"Łacińska nazwa Calendula pochodzi od calendae, pierwszego dnia miesiąca. Nagietek kwitnie niemal co miesiąc.","whisper":"Kwiat, który otwiera się codziennie, uczy, że każdy dzień to nowy początek.","caution":"Nie przy uczuleniu na astrowate.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":248}],["2027-07-06","creative","☽ we Lwie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":7.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Dominiki, Gotarda","title":"Pierogi z jagodami","subtitle":"lipcowy obiad","story":"Pierogi z jagodami to kwintesencja lipca. Ciasto z mąki i wody, nadzienie z jagód z odrobiną cukru, polane śmietaną i posypane cukrem. Jadano je po powrocie z lasu, całą rodziną. Granatowy sok wypływa z pieroga i barwi talerz. To jedno z tych dań, których smak przenosi do dzieciństwa.","practice":"• Zagnieć ciasto z 500 g mąki, szklanki ciepłej wody i szczypty soli.\n• Rozwałkuj, wykrój krążki, nałóż łyżkę jagód z cukrem, sklej.\n• Gotuj 3 minuty, podawaj ze śmietaną i cukrem.","extraTitle":"Ciekawostka","extra":"Do jagód w pierogach dodaje się czasem łyżeczkę mąki ziemniaczanej, by sok nie wypływał.","whisper":"Niektóre smaki są jak wehikuł czasu.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":249}],["2027-07-07","organize","☽ we Lwie do 09:56, potem w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":14.0,"moonAndBiodynamic":"☽ we Lwie do 09:56, potem w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Do 09:56 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 06:11 do 09:56: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Benedykta, Cyryla","title":"Płukanka z ziół","subtitle":"włosy jak u rusałki","story":"Kobiety płukały włosy w naparach z ziół. Pokrzywa wzmacniała i dodawała blasku, rumianek rozjaśniał, szałwia przyciemniała, łopian przeciwdziałał wypadaniu. Mycie włosów w deszczówce i ziołach było rytuałem urody i siły. Włosy długie i gęste były dumą każdej dziewczyny i miały w sobie magię.","practice":"• Zaparz garść pokrzywy lub rumianku w litrze wody.\n• Ostudź i po umyciu włosów przelej je naparem.\n• Nie spłukuj, osusz ręcznikiem.","extraTitle":"Ciekawostka","extra":"W wierzeniach we włosach kobiety mieszkała siła. Dlatego zamężne zakrywały je czepcem.","whisper":"Kto dba o swoje korzenie, ten ma piękną koronę.","caution":"Nie przy uczuleniu na dane zioła.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":250}],["2027-07-08","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":24.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀□♆ Wenus kwadratura Neptun (14:27): Napięcie między planetami. Można je wykorzystać na romantyzm, sztukę, muzykę i współczucie. Uważaj na idealizowanie ludzi i rozczarowania.","sourceText":{"holiday":"","namedays":"Adriany, Eugeniusza","title":"Piorun w dąb","subtitle":"drzewo Peruna","story":"Dąb był drzewem Peruna, słowiańskiego boga piorunów. Mówiono, że piorun najczęściej uderza w dąb, i to prawda: dęby są wysokie i mają głębokie korzenie, które łączą je z wodą. Dlatego podczas burzy nie wolno chować się pod dębem. Drewno z dębu porażonego piorunem uważano za magiczne i noszono jako amulet.","practice":"• Podczas burzy nie stój pod drzewem, a już zwłaszcza pod dębem.\n• Na spacerze poszukaj dębu i przyjrzyj się jego korze.\n• Pomyśl, co w tobie jest mocne jak dąb.","extraTitle":"Ciekawostka","extra":"Stare powiedzenie każe przed dębem uciekać, a buka szukać. To mit: piorun trafia w każde wysokie drzewo.","whisper":"Najsilniejsze drzewo przyciąga najsilniejsze błyskawice.","caution":"W czasie burzy unikaj wysokich drzew i otwartej przestrzeni.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":251}],["2027-07-09","organize","☽ w Pannie, od 12:23 w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":34.0,"moonAndBiodynamic":"☽ w Pannie, od 12:23 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 12:23 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 09:28 do 12:23: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Lukrecji, Weroniki","title":"Chmiel w poduszce","subtitle":"dla spokojnego snu","story":"Szyszki chmielu, zbierane w sierpniu, wkładano do poduszek, by sen był spokojny i głęboki. Chmiel pachnie gorzko i ziołowo, a jego olejki działają uspokajająco. Do poduszek dodawano też lawendę, melisę, siano. Poduszka ziołowa to jedna z najstarszych metod na bezsenność. Chroniła też przed złymi snami i zmorami.","practice":"• Uszyj małą poduszkę z lnianego płótna.\n• Wypełnij ją suszonym chmielem, lawendą albo melisą.\n• Połóż obok poduszki na noc.","extraTitle":"Ciekawostka","extra":"Chmiel jest krewnym konopi. Oba należą do rodziny konopiowatych.","whisper":"Sen chroniony zapachem jest głębszy niż ten w ciszy.","caution":"Chmiel może nasilać działanie leków nasennych. Nie przy depresji bez konsultacji.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":252}],["2027-07-10","relationships","☽ w Wadze","I kwadra",false,{"phase":"I kwadra o 20:39","nextPhase":"pełnia za 8 dni","illumination":46.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♆ Neptun rusza wstecz w Baranie (00:41): Mgła powoli opada. Łatwiej zobaczyć, co było złudzeniem. Rada: zapytaj, czemu wierzysz bez sprawdzenia.","sourceText":{"holiday":"","namedays":"Olafa, Witalisa","title":"Zboże dojrzewa","subtitle":"złoty lipiec","story":"W lipcu żyto i pszenica złocą się na polach. Zaczynają się żniwa. Dawniej cała wieś wychodziła z sierpami i kosami. Pierwszy snop wiązano z modlitwą i przynoszono do domu. Mówiono, że w zbożu mieszka żytnia matka, duch urodzaju. Dziś pierwsza kwadra: rośnie, dojrzewa, jest prawie gotowe.","practice":"• Wybierz się na spacer wśród pól.\n• Dotknij kłosa i zobacz, czy ziarno jest twarde.\n• Pomyśl, co w twoim życiu jest już prawie gotowe do zbioru.","extraTitle":"Ciekawostka","extra":"Żniwa zaczynały się zwykle od żyta, bo ono dojrzewa najwcześniej.","whisper":"Złoto pola przychodzi powoli. Trzeba umieć poczekać.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":253}],["2027-07-11","relationships","☽ w Wadze, od 17:54 w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":56.0,"moonAndBiodynamic":"☽ w Wadze, od 17:54 w Skorpionie · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 17:54 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 16:49 do 17:54: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Olgi, Kaliny","title":"Boruta","subtitle":"diabeł z Łęczycy","story":"Boruta to najbardziej znany polski diabeł. Według legendy mieszkał w lochach zamku w Łęczycy i strzegł ukrytego skarbu. Przybierał postać szlachcica w kontuszu i ze szpadą. Bywał złośliwy, ale też dowcipny i można go było przechytrzyć. Polskie diabły w ogóle są raczej figlarne niż straszne.","practice":"• Pomyśl o pokusie, którą ostatnio przechytrzyłaś.\n• Zapisz ją z humorem.\n• Pośmiej się z niej.","extraTitle":"Pytanie na niedzielę","extra":"Jaką pokusę mogę przechytrzyć sprytem zamiast siłą?","whisper":"Diabła rzadko pokonuje się siłą. Częściej sprytem i śmiechem.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":254}],["2027-07-12","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":66.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Raku · ☿ w Bliźniętach · ♀ w Raku · ♂ w Pannie. Pytanie tygodnia: Czego potrzebuje Twój dom?\n♃△♄ Jowisz w harmonii z Saturnem (01:15): Rzadki, dobry układ dla mądrych planów: rozwój idzie w parze z rozsądkiem. Rada: buduj coś na lata: firmę, oszczędności, umiejętność.\n☿ Merkury wchodzi w Raka (15:48): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie domu, rodziny, wspomnień i emocji. Rada: ugotuj coś dla bliskich, zadbaj o gniazdo. Uważaj na nadwrażliwość i obrażanie się.","sourceText":{"holiday":"","namedays":"Jana, Brunona","title":"Mięta","subtitle":"chłód w upał","story":"Mięta rośnie w każdym ogrodzie i rozrasta się bez opanowania. Jej liście chłodzą usta i żołądek. Napar z mięty pito na mdłości, bóle brzucha i w upał. Mówiono, że mięta przywraca jasność umysłu. Grecka legenda mówi, że Minta była nimfą zamienioną w roślinę przez zazdrosną Persefonę.","practice":"• Wrzuć kilka liści mięty do dzbanka z wodą.\n• Zaparz napar i schłódź na lemoniadę.\n• Rozetrzyj liść między palcami, gdy jesteś zmęczona.","extraTitle":"Ciekawostka","extra":"Mięta pieprzowa to krzyżówka mięty zielonej i mięty nadwodnej.","whisper":"Chłód w środku lata to dar, nie kara.","caution":"Mięta pieprzowa może nasilać zgagę i refluks.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":255}],["2027-07-13","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":75.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Ernesta, Małgorzaty","title":"Ogórki małosolne","subtitle":"lato w słoiku","story":"W lipcu robi się ogórki małosolne. Kiszone tylko kilka dni, są chrupiące, świeże i lekko kwaśne. Ogórki układa się w słoju z koprem, czosnkiem, chrzanem i liśćmi wiśni lub dębu, zalewa solanką i zostawia w cieple. Zapach kopru i czosnku w kuchni to zapach lata.","practice":"• Ułóż w słoju 1 kg małych ogórków z koprem, czosnkiem, chrzanem i liściem dębu.\n• Zalej solanką: litr wody, łyżka soli.\n• Odstaw w ciepłe miejsce na 3 dni.","extraTitle":"Ciekawostka","extra":"Liście dębu, wiśni lub winogron dodaje się, bo zawierają garbniki, które utrzymują chrupkość ogórków.","whisper":"Najlepsze rzeczy dzieją się w kilka dni, gdy się ich nie pogania.","caution":"Dużo soli. Ostrożnie przy nadciśnieniu.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":256}],["2027-07-14","travel","☽ w Skorpionie do 02:32, potem w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":83.0,"moonAndBiodynamic":"☽ w Skorpionie do 02:32, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 02:32 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Bonawentury, Stelli","title":"Okadzanie domu","subtitle":"dym z ziół","story":"Dym z suszonych ziół oczyszczał dom. Palono jałowiec, bylicę, szałwię, ziele z wianków świętojańskich. Chodzono z dymiącym naczyniem po wszystkich kątach, zwłaszcza po chorobie, kłótni albo śmierci. Wierzono, że dym wypędza złe duchy i zarazę. Dziś wiemy, że dym niektórych ziół ma działanie antybakteryjne.","practice":"• Zapal pęczek suszonych ziół w metalowej misce.\n• Przejdź przez dom, od drzwi do najdalszego kąta.\n• Otwórz okna, by dym wyszedł razem ze starym.","extraTitle":"Ciekawostka","extra":"Okadzanie jałowcem było w średniowieczu sposobem na zarazę w domach i szpitalach.","whisper":"Dym niesie to, co chcesz wypuścić, za okno.","caution":"Okadzaj tylko z otwartym oknem. Nie przy astmie, dzieciach i zwierzętach w pomieszczeniu.","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":257}],["2027-07-15","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":90.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♂ Mars wchodzi w Wagę (07:40): Na kilka tygodni energia i działanie płyną w rytmie relacji, piękna, kompromisu i umów. Rada: szukaj porozumienia i piękna. Uważaj na niezdecydowanie i zadowalanie wszystkich.","sourceText":{"holiday":"","namedays":"Dawida, Henryka","title":"Nie licz gwiazd","subtitle":"bo wyrosną kurzajki","story":"W letnie noce niebo jest pełne gwiazd. Ale dzieciom mówiono: nie licz gwiazd, bo wyrosną ci kurzajki. Nie wolno też było wskazywać gwiazd palcem. Wierzono, że każdy człowiek ma swoją gwiazdę, która spada, gdy umiera. Wskazując gwiazdę, można było przypadkiem wskazać czyjąś śmierć.","practice":"• Wieczorem połóż się na trawie i popatrz w gwiazdy.\n• Nie licz ich, po prostu patrz.\n• Poszukaj tej, którą mogłabyś nazwać swoją.","extraTitle":"Ciekawostka","extra":"W bezksiężycową noc z dala od miast gołym okiem widać około 2–3 tysiące gwiazd.","whisper":"Nie wszystko musi być policzone, żeby było ważne.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":258}],["2027-07-16","travel","☽ w Strzelcu, od 13:39 w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":95.0,"moonAndBiodynamic":"☽ w Strzelcu, od 13:39 w Koziorożcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 13:39 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 09:41 do 13:39: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Eustachego, Marii","title":"Jałowiec","subtitle":"kolczasty strażnik","story":"Jałowiec rośnie na wrzosowiskach i w suchych borach. Jego kłujące igły i niebieskie szyszkojagody chroniły przed złymi duchami. Gałązki jałowca wieszano w oborach i przy drzwiach, okadzano nim dom w czasie zarazy. Szyszkojagody dodawano do bigosu i dziczyzny, a z nich robi się gin.","practice":"• Dodaj kilka szyszkojagód jałowca do mięsa lub kapusty.\n• Zawieś gałązkę jałowca przy wejściu.\n• Pomyśl, jakie kolce chronią ciebie.","extraTitle":"Ciekawostka","extra":"Szyszkojagody jałowca dojrzewają aż dwa lub trzy lata. Na jednym krzewie są zielone i granatowe naraz.","whisper":"Kolce nie są złe. Pozwalają owocom spokojnie dojrzeć.","caution":"Jałowiec nie w ciąży i przy chorobach nerek.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":259}],["2027-07-17","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":98.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Anety, Bogdana","title":"Burza letnia","subtitle":"oddech nieba","story":"W lipcu przychodzą burze. Powietrze gęstnieje, ptaki milkną, liście odwracają się srebrną stroną. Potem grzmot, błyskawica, ulewa. Dawniej w czasie burzy zapalano gromnicę, wkładano palmę do pieca i modlono się. Po burzy powietrze pachnie ozonem i ziemią. To zapach, który ma nawet swoją nazwę: petrichor.","practice":"• Gdy nadchodzi burza, zauważ znaki: cisza, wiatr, zapach.\n• Licz sekundy między błyskiem a grzmotem, by wiedzieć, jak daleko jest.\n• Po burzy wyjdź i powąchaj powietrze.","extraTitle":"Ciekawostka","extra":"Liczbę sekund między błyskawicą a grzmotem podziel przez trzy. Wynik to odległość od burzy w kilometrach.","whisper":"Po każdej burzy powietrze pachnie lepiej niż przed nią.","caution":"Podczas burzy unikaj otwartych przestrzeni, wody i wysokich drzew.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":260}],["2027-07-18","work","☽ w Koziorożcu","pełnia",false,{"phase":"pełnia o 17:45","nextPhase":"nów za 15 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 21:06 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🌕 Pełnia w Koziorożcu (17:44): Kulminacja w sprawach: praca, ambicja, odpowiedzialność. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Emila, Erwina","title":"Upiór","subtitle":"ten, który ma dwa serca","story":"Słowo upiór dało światu słowo wampir. Upiorem stawał się ktoś, kto urodził się z zębami, miał dwa serca albo dwie dusze. Po śmierci wstawał z grobu i wysysał krew bliskich. Dlatego chowano go twarzą w dół, z sierpem na szyi albo z kamieniem w ustach. Dziś pełnia: noc, kiedy upiory były najsilniejsze.","practice":"• Wieczorem spójrz na pełnię.\n• Pomyśl, co w twoim życiu wysysa z ciebie siłę.\n• Zapisz jedną rzecz, którą możesz od siebie odciąć.","extraTitle":"Pytanie na niedzielę","extra":"Co w moim życiu jest jak upiór: martwe, a wciąż wysysa ze mnie siłę?","whisper":"Upiory żywią się tym, czego nie umiesz pożegnać.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":261}],["2027-07-19","social","☽ w Koziorożcu do 02:15, potem w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 14 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Koziorożcu do 02:15, potem w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 02:15 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Raku · ☿ w Raku · ♀ w Raku · ♂ w Wadze. Pytanie tygodnia: Czego potrzebuje Twój dom?\n☿□♆ Merkury w napięciu z Neptunem (16:05): Nieporozumienia, zgubione wiadomości, niedopowiedzenia. Uwaga: sprawdzaj fakty, pytaj wprost.","sourceText":{"holiday":"","namedays":"Wincentego, Wodzisława","title":"Lebiodka","subtitle":"dzikie oregano","story":"Lebiodka pospolita rośnie na suchych łąkach i skrajach lasów, z różowymi kwiatami i ziołowym zapachem. To dziki krewny oregano. Pito ją na kaszel, trawienie i bóle brzucha. Dodawano do kąpieli i do piwa. Ma w sobie siłę ciepłych, suchych miejsc. Lipiec to najlepszy czas na jej zbiór.","practice":"• Rozpoznaj lebiodkę po różowych kwiatach i zapachu oregano.\n• Zbierz kilka gałązek do suszenia.\n• Dodaj suszone liście do pizzy albo zupy pomidorowej.","extraTitle":"Ciekawostka","extra":"Olejek z lebiodki ma silne działanie przeciwbakteryjne, badane we współczesnej medycynie.","whisper":"Siła często rośnie tam, gdzie jest sucho i słonecznie.","caution":"Nie w ciąży w dużych dawkach.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":262}],["2027-07-20","social","☽ w Wodniku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉□♄ Słońce kwadratura Saturn (12:48): Napięcie między planetami. Można je wykorzystać na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach. Uważaj na zniechęcenie, surowość wobec siebie i zmęczenie.","sourceText":{"holiday":"","namedays":"Czesława, Fryderyka","title":"Konfitura wiśniowa","subtitle":"rubinowe słoiki","story":"W lipcu dojrzewają wiśnie. Gospodynie drylowały je wieczorami, a dzieci miały czerwone ręce i usta. Z wiśni robiono konfitury, nalewki, kompoty i soki. Konfitura wiśniowa z pestkami była podawana do herbaty, a wiśniówka na przeziębienie. Rubinowe słoiki na półce były skarbem na zimę.","practice":"• Wydryluj 1 kg wiśni.\n• Zasyp 500 g cukru i odstaw na noc.\n• Gotuj na małym ogniu, aż zgęstnieje, przełóż do wyparzonych słoików.","extraTitle":"Ciekawostka","extra":"Pestki wiśni zawierają amigdalinę. Dawniej wkładano je do woreczków, które po podgrzaniu służyły jako termofor.","whisper":"Słodycz zamknięta w słoiku w lipcu ogrzeje cię w styczniu.","caution":"Nie rozgryzaj pestek.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":263}],["2027-07-21","social","☽ w Wodniku, od 15:14 w Rybach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Wodniku, od 15:14 w Rybach · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 15:14 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 13:17 do 15:14: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Daniela, Dalidy","title":"Zielnik w książce","subtitle":"suszona pamięć","story":"Dawniej dziewczęta i kobiety prowadziły zielniki. Zasuszone rośliny wkładano między kartki ciężkich książek, a potem przyklejano do papieru z podpisem i datą. Zielnik to pamiętnik lata. Każda roślina przypomina, gdzie się było i co się czuło. Dzieci szkolne prowadzą zielniki do dziś.","practice":"• Zerwij jeden kwiat albo liść na spacerze.\n• Włóż go między kartki ciężkiej książki na dwa tygodnie.\n• Potem przyklej na kartkę i podpisz datą i miejscem.","extraTitle":"Ciekawostka","extra":"Najstarsze zielniki w Europie pochodzą z XVI wieku i są przechowywane w muzeach.","whisper":"Kwiat zasuszony w książce pamięta lato dłużej niż ty.","caution":"Nie zrywaj roślin chronionych.","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":264}],["2027-07-22","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":87.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Marii, Magdaleny","title":"Nie witaj się przez próg","subtitle":"granica domu","story":"Próg był granicą między domem a światem zewnętrznym. Pod nim chowano przedmioty ochronne, a według wierzeń mieszkały tam duchy przodków. Nie wolno było witać się przez próg ani podawać nic przez niego, bo to wróżyło kłótnię. Pannę młodą przenoszono przez próg, by nie potknęła się o duchy domu.","practice":"• Witając gościa, wpuść go najpierw do środka albo wyjdź do niego.\n• Pomyśl, co dla ciebie jest granicą domu.\n• Przetrzyj dziś swój próg wilgotną szmatką.","extraTitle":"Ciekawostka","extra":"Pod progiem nowego domu zakopywano monety, chleb albo zioła, by szczęście nie odeszło.","whisper":"Każda granica zasługuje na szacunek, nawet ta pod twoimi stopami.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":265}],["2027-07-23","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":80.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 17:47 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉ Słońce wchodzi w Lwa (03:04): Na miesiąc cały świat nabiera barw znaku Lwa: czas serca, twórczości, radości i widoczności. Rada: pokaż, co umiesz, i baw się.","sourceText":{"holiday":"","namedays":"Bogny, Apolinarego","title":"Bazylia w oknie","subtitle":"przeciw muchom i złym myślom","story":"Bazylia w doniczce na parapecie odstraszała muchy i komary. W wierzeniach śródziemnomorskich chroniła dom przed złym i przynosiła miłość. Do Polski trafiła z kuchnią włoską za królowej Bony, choć wcześniej znano ją w klasztorach. Jej zapach poprawia nastrój, a liście dodane do pomidorów to smak lata.","practice":"• Postaw doniczkę bazylii na parapecie w kuchni.\n• Uszczknij kilka listków do pomidorów.\n• Rozetrzyj liść i poczuj, jak zmienia nastrój.","extraTitle":"Ciekawostka","extra":"Nazwa bazylii pochodzi od greckiego basileus, czyli król. To królewskie zioło.","whisper":"Dom pachnący bazylią nie ma miejsca na złe myśli.","caution":"","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":266}],["2027-07-24","start","☽ w Rybach do 03:09, potem w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":72.0,"moonAndBiodynamic":"☽ w Rybach do 03:09, potem w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Do 03:09 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Kingi, Krystyny","title":"Perseidy","subtitle":"spadające gwiazdy lata","story":"Pod koniec lipca zaczynają się Perseidy, najsłynniejszy rój meteorów. Maksimum będzie w nocy z 12 na 13 sierpnia, ale już teraz można zobaczyć pierwsze spadające gwiazdy. To okruchy komety Swift-Tuttle, które spalają się w atmosferze. Dawniej nazywano je łzami świętego Wawrzyńca, bo spadają w okolicach jego święta.","practice":"• Po północy połóż się na kocu z dala od świateł.\n• Patrz w kierunku północno-wschodniego nieba.\n• Każdą spadającą gwiazdę przywitaj życzeniem.","extraTitle":"Ciekawostka","extra":"Perseidy wpadają w atmosferę z prędkością około 59 kilometrów na sekundę.","whisper":"Spadające gwiazdy to okruchy czegoś, co kiedyś było wielkie. Wciąż świecą.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":267}],["2027-07-25","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":62.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀□♄ Wenus w napięciu z Saturnem (17:19): Chłód, poczucie samotności, ograniczony budżet. Uwaga: nie oceniaj związku w zły dzień.\n♂△♇ Mars w harmonii z Plutonem (17:24): Ogromna siła przebicia i wytrwałość. Rada: zmierz się z czymś trudnym, co od dawna czeka.","sourceText":{"holiday":"św. Jakuba · św. Krzysztofa","namedays":"Walentyny, Krzysztofa","title":"Jakub i Krzysztof","subtitle":"patron drogi","story":"Święty Krzysztof przenosił ludzi przez rzekę i według legendy przeniósł na ramionach małego Jezusa. Jest patronem podróżnych i kierowców. Dziś w wielu parafiach święci się samochody. Święty Jakub był pielgrzymem, a jego muszla wyznacza szlaki do Santiago de Compostela. Dobry dzień, by pomyśleć o drodze.","practice":"• Przed podróżą dotknij kierownicy albo drzwi i wypowiedz życzenie.\n• Zaplanuj krótką wędrówkę.\n• Pomyśl, dokąd zmierzasz w tym roku.","extraTitle":"Pytanie na niedzielę","extra":"Dokąd naprawdę idę i kto mnie niesie przez rzekę?","whisper":"Najważniejsza droga to ta, którą idziesz świadomie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":268}],["2027-07-26","start","☽ w Baranie, od 12:27 w Byku","III kwadra",false,{"phase":"III kwadra o 18:55","nextPhase":"nów za 7 dni","illumination":53.0,"moonAndBiodynamic":"☽ w Baranie, od 12:27 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 12:27 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 09:43 do 12:27: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ we Lwie · ☿ w Raku · ♀ w Raku · ♂ w Wadze. Pytanie tygodnia: Co sprawia Ci prawdziwą radość?\n♃ Jowisz wchodzi w Pannę (06:49): Na około rok Jowisz, planeta szczęścia i rozwoju, gości w znaku Panny. Wzrost przychodzi przez dbałość o zdrowie, nawyki i codzienną pracę. Nagradza tych, którzy działają systematycznie. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów. Uważaj na krytykanctwo i przemęczenie.\n♂☍♆ Mars naprzeciw Neptuna (15:24): Zmęczenie i dezorientacja. Ktoś może grać nieczysto. Uwaga: nie podejmuj walki, gdy nie widzisz całej sytuacji.","sourceText":{"holiday":"św. Anny","namedays":"Anny, Mirosławy","title":"Kozłek lekarski","subtitle":"na świętą Annę","story":"Dziś święta Anna, babcia Jezusa, patronka babć, matek i gospodyń. Mówiono, że od Anny zimne noce i ranki. Zioło dnia to kozłek lekarski, czyli waleriana. Jego korzeń pachnie tak, że koty szaleją, a ludzie zasypiają. Babcie trzymały krople walerianowe na nerwy. Dziś też ostatnia kwadra: czas na spokój.","practice":"• Zadzwoń do babci albo pomyśl o niej.\n• Wypij napar z kozłka przed snem.\n• Odpuść jedno zmartwienie.","extraTitle":"Przysłowie","extra":"„Od świętej Anny zimne wieczory i ranki.”","whisper":"Spokój babci jest lekarstwem, którego nie sprzedają w aptece.","caution":"Kozłek nasila działanie leków nasennych i alkoholu. Nie prowadź po większej dawce.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":269}],["2027-07-27","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":42.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus wchodzi w Lwa (14:30): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie serca, twórczości, radości i widoczności. Rada: pokaż, co umiesz, i baw się. Uważaj na dumę i potrzebę poklasku.","sourceText":{"holiday":"","namedays":"Celestyna, Lilii","title":"Bób z masłem","subtitle":"lipcowy przysmak","story":"Bób to warzywo lipca. Młody, zielony, ugotowany w osolonej wodzie z koprem i polany masłem, był przysmakiem na wsi i w mieście. Jadano go z ręki, wyłuskując ze skórki, przy rozmowie na ganku. Bób był znany w Polsce długo przed fasolą, która przyszła z Ameryki. Dawni Słowianie jedli go na co dzień.","practice":"• Ugotuj bób w osolonej wodzie z gałązką kopru przez 10 minut.\n• Odcedź i polej roztopionym masłem.\n• Jedz z ręki, wyłuskując ze skórki.","extraTitle":"Ciekawostka","extra":"Bób to jedno z najstarszych warzyw Europy, uprawiane od czasów neolitu.","whisper":"Najlepsze rozmowy toczą się przy jedzeniu z ręki.","caution":"Nie przy fawizmie, czyli niedoborze enzymu G6PD.","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":270}],["2027-07-28","finances","☽ w Byku, od 18:10 w Bliźniętach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Byku, od 18:10 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 18:10 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu do 18:10: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Aidy, Innocentego","title":"Jezioro o świcie","subtitle":"zimna woda, jasna głowa","story":"Lipcowy świt nad jeziorem jest cichy i mglisty. Woda jest wtedy najcieplejsza w porównaniu z powietrzem i paruje, jakby oddychała. Kąpiel o świcie była dawniej rytuałem zdrowia i siły, ale też miłości: dziewczęta wierzyły, że w porannej wodzie zobaczą twarz ukochanego. Woda o świcie jest lustrem.","practice":"• Jeśli możesz, wstań wcześnie i wyjdź nad wodę.\n• Zanurz dłonie i przemyj twarz.\n• Popatrz na swoje odbicie i powiedz sobie coś dobrego.","extraTitle":"Ciekawostka","extra":"Mgła nad jeziorem o świcie powstaje, gdy ciepła woda paruje do chłodnego powietrza.","whisper":"Woda o świcie pokazuje twarz, zanim nałożysz na nią dzień.","caution":"Nie pływaj sama o świcie, gdy nikt cię nie widzi.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":271}],["2027-07-29","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉☍♇ Słońce naprzeciw Plutona (08:47): Walka o wpływ i kontrolę w relacjach. Uwaga: nie wchodź w grę o władzę.\n☉△♆ Słońce trygon Neptun (23:43): Dobry dzień na intuicję, sztukę, medytację i pomoc innym.","sourceText":{"holiday":"","namedays":"Olafa, Marty","title":"Czarny kot","subtitle":"pech czy strażnik?","story":"Czarny kot przebiegający drogę wróżył nieszczęście. Trzeba było splunąć przez lewe ramię, zawrócić albo poczekać, aż ktoś inny przejdzie pierwszy. Czarny kot był towarzyszem czarownic. Ale w wielu domach był też strażnikiem przed złymi duchami i myszami. Babci Jadze kot zawsze pomagał, nawet jeśli kradł jej kartki.","practice":"• Gdy zobaczysz czarnego kota, uśmiechnij się do niego.\n• Pogłaszcz kota, jeśli ci pozwoli.\n• Pomyśl o jakimś „pechu”, który okazał się szczęściem.","extraTitle":"Ciekawostka","extra":"W Wielkiej Brytanii i Japonii czarny kot przynosi szczęście.","whisper":"Pech i szczęście często chodzą w tym samym futrze.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":272}],["2027-07-30","conversation","☽ w Bliźniętach, od 20:24 w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 20:24 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 20:24 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 16:48 do 20:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂△♅ Mars w harmonii z Uranem (18:59): Szybkie, odważne, nieszablonowe działanie. Rada: spróbuj nowej metody albo trasy.","sourceText":{"holiday":"","namedays":"Julity, Piotra","title":"Lustro przy wejściu","subtitle":"odbij złe","story":"Lustro powieszone naprzeciw drzwi odbijało złe spojrzenia i złe moce, które próbowały wejść do domu. W czasie żałoby zasłaniano lustra, by dusza zmarłego się w nich nie zagubiła. Rozbite lustro wróżyło siedem lat nieszczęścia. Lustro było progiem między światami, a nie tylko szkłem.","practice":"• Spójrz w lustro przy wejściu, zanim wyjdziesz z domu.\n• Uśmiechnij się do siebie.\n• Przetrzyj lustro, by odbijało wyraźnie.","extraTitle":"Ciekawostka","extra":"Przesąd o siedmiu latach pecha za rozbite lustro pochodzi od Rzymian, którzy wierzyli, że życie odnawia się co siedem lat.","whisper":"Najlepsza ochrona przed złym spojrzeniem to dobre spojrzenie na siebie.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":273}],["2027-07-31","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Ignacego, Lubomira","title":"Młode jaskółki","subtitle":"pierwsze loty","story":"Pod koniec lipca młode jaskółki uczą się latać. Siedzą rzędem na drutach i czekają, aż rodzice przyniosą muchę. Potem nieśmiało próbują same. Jaskółki wychowują w sezonie zwykle dwa lęgi. Za miesiąc zaczną się zbierać do odlotu. Lato jest już w pełni, ale ptaki wiedzą, że się kończy.","practice":"• Popatrz na jaskółki na drutach i policz młode.\n• Zauważ, jak uczą się latać.\n• Pomyśl, czego ty się teraz uczysz.","extraTitle":"Ciekawostka","extra":"Jaskółka dymówka przelatuje do Afryki na zimę ponad 10 tysięcy kilometrów.","whisper":"Każdy, kto dziś lata wysoko, kiedyś siedział na drucie i bał się skoczyć.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":274}],["2027-08-01","home","☽ w Raku, od 20:24 we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Raku, od 20:24 we Lwie · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 20:24 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 17:54 do 20:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀☍♇ Wenus opozycja Pluton (09:13): Napięcie między planetami. Można je wykorzystać na głębokie uczucia, intymność i odnowę w relacjach. Uważaj na zazdrość i zaborczość.\n☿□♄ Merkury kwadratura Saturn (10:47): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.\n☉✶♅ Słońce sekstyl Uran (16:18): Dobry dzień na nowości, zmianę rutyny i odważne pomysły.\n♀△♆ Wenus trygon Neptun (21:32): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.","sourceText":{"holiday":"","namedays":"Alfonsa, Nadii","title":"Żytnia baba","subtitle":"ta, która mieszka w zbożu","story":"W dojrzałym zbożu mieszkała żytnia baba, zwana też zbożową matką. Pilnowała kłosów i porywała dzieci, które wchodziły w łan i deptały zboże. Dzieciom mówiono: nie chodź w żyto, bo cię żytnia baba złapie. W ostatnim snopie miała się ukrywać do końca żniw. Opowieść chroniła i dzieci, i chleb.","practice":"• Na spacerze nie wchodź w łan, idź miedzą.\n• Pomyśl o opowieści, którą straszono cię w dzieciństwie, by cię chronić.\n• Podziękuj w myślach komuś, kto cię wtedy pilnował.","extraTitle":"Pytanie na niedzielę","extra":"Jaką granicę ktoś postawił mi dawno temu, a dziś rozumiem, po co była?","whisper":"Niektóre strachy były tylko inną formą troski.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":275}],["2027-08-02","creative","☽ we Lwie","nów",false,{"phase":"nów o 12:05","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ we Lwie · ☿ w Raku · ♀ we Lwie · ♂ w Wadze. Pytanie tygodnia: Co sprawia Ci prawdziwą radość?\n🌑 Nów i zaćmienie Słońca we Lwie (12:05): Czas zasiewu w sprawach: radość, twórczość, dzieci, miłość. Zaćmienie wzmacnia ten początek: to, co zasiejesz teraz, rośnie przez pół roku. Rada: zapisz intencję na ten księżycowy miesiąc.\n☿ Merkury wchodzi w Lwa (12:52): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie serca, twórczości, radości i widoczności. Rada: pokaż, co umiesz, i baw się. Uważaj na dumę i potrzebę poklasku.","sourceText":{"holiday":"częściowe zaćmienie Słońca, maksimum ok. 11:17","namedays":"Kariny, Gustawa","title":"Zaćmienie Słońca","subtitle":"Księżyc zakrywa dzień","story":"Dziś przed południem Księżyc przesunie się przed Słońcem. W Polsce zaćmienie będzie częściowe, z maksimum około 11:17. Dawniej zaćmienia budziły grozę: mówiono, że smok albo wilk pożera Słońce, bito w garnki, modlono się. Dziś nów, a jednocześnie pokaz tego, jak precyzyjnie porusza się niebo. Patrz tylko przez specjalne okulary.","practice":"• Zdobądź okulary do obserwacji Słońca z certyfikatem ISO 12312-2.\n• Około 11:17 spójrz na sierp Słońca przez okulary.\n• Popatrz na cienie pod drzewem: zobaczysz w nich małe sierpy.","extraTitle":"Księżyc","extra":"nów 2 VIII, 12:05 · pełnia 17 VIII, 09:28","whisper":"Nawet Słońce czasem znika na chwilę. Wraca zawsze.","caution":"Nigdy nie patrz na Słońce gołym okiem, przez okulary przeciwsłoneczne, aparat ani lornetkę bez filtra.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":276}],["2027-08-03","creative","☽ we Lwie, od 19:57 w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":1.0,"moonAndBiodynamic":"☽ we Lwie, od 19:57 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 19:57 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 16:30 do 19:57: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Lidii, Augusta","title":"Chleb z nowej mąki","subtitle":"pierwszy bochenek żniw","story":"Po żniwach z pierwszego zboża mielono mąkę i pieczono pierwszy chleb. Był wyjątkowy: jedzono go z modlitwą, dzielono się nim z sąsiadami i dawano kawałek zwierzętom. Mówiono, że kto zje chleb z nowej mąki, ten przez rok nie zazna głodu. Zakwas żytni, mąka, woda, sól i czas. Nic więcej nie potrzeba.","practice":"• Wymieszaj 200 g aktywnego zakwasu z 500 g mąki żytniej, 400 ml wody i łyżką soli.\n• Przełóż do formy i odstaw na 4–6 godzin do wyrośnięcia.\n• Piecz 60 minut w 220 °C, z naczyniem wody w piekarniku.","extraTitle":"Ciekawostka","extra":"Na zakwasie chleb żytni nie potrzebuje drożdży. Zakwas sam w sobie jest żywą kulturą drożdży i bakterii.","whisper":"Pierwszy chleb z nowego zboża smakuje jak wdzięczność.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":277}],["2027-08-04","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 10:46 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀✶♅ Wenus sekstyl Uran (01:53): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku.\n☉✶♂ Słońce sekstyl Mars (17:15): Dobry dzień na odważne decyzje, sport i ruszanie spraw z miejsca.","sourceText":{"holiday":"","namedays":"Dominika, Jana","title":"Suszenie owoców","subtitle":"krążki jabłek na nitce","story":"W sierpniu na strychach i nad piecem wisiały nici z krążkami jabłek, gruszek i śliwek. Suszono je na zimę: do kompotu z suszu, do kaszy, do pierników. Krojenie owoców w krążki i nawlekanie ich na nić to spokojna, powtarzalna praca. Dom pachniał wtedy jesienią na długo przed jej przyjściem.","practice":"• Pokrój dwa jabłka w cienkie krążki i usuń gniazda nasienne.\n• Nawlecz je na nitkę albo rozłóż na kratce.\n• Susz w przewiewnym miejscu albo w piekarniku w 50 °C z uchylonymi drzwiczkami.","extraTitle":"Ciekawostka","extra":"Kompot z suszu na Wigilię gotowano właśnie z owoców suszonych latem.","whisper":"Lato można powiesić na nitce i zdjąć w grudniu.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":278}],["2027-08-05","organize","☽ w Pannie, od 20:54 w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Pannie, od 20:54 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 20:54 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu do 20:54: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿☍♇ Merkury opozycja Pluton (08:44): Napięcie między planetami. Można je wykorzystać na dociekliwość, badania, terapię i szczere rozmowy. Uważaj na obsesyjne myśli i słowne manipulacje.\n☿△♆ Merkury trygon Neptun (16:35): Dobry dzień na pisanie, poezję, muzykę i rozmowy o duchowości.","sourceText":{"holiday":"","namedays":"Marii, Oswalda","title":"Przepiórka","subtitle":"ostatni snop","story":"Na końcu żniw zostawiano na polu kępkę niezżętego zboża. Nazywano ją przepiórką, brodą albo pępkiem. Związywano kłosy, kładziono pod nimi chleb i sól. Wierzono, że w ostatnich kłosach chowa się duch urodzaju, który musi przetrwać do następnego roku. Ścięcie ostatniego kłosa bez obrzędu mogło sprowadzić nieurodzaj.","practice":"• Zostaw dziś coś niedokończonego, celowo.\n• Pomyśl, czego nie musisz zabierać do końca.\n• Podziel się czymś z ptakami.","extraTitle":"Ciekawostka","extra":"W niektórych regionach z ostatniego snopa robiono wieniec dożynkowy.","whisper":"Nie zbieraj wszystkiego do ostatniego kłosa. Zostaw coś dla przyszłego roku.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":279}],["2027-08-06","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Sławy, Jakuba","title":"Ruta","subtitle":"ziele panieńskie","story":"Ruta była ziołem panien i ochrony. Gałązkę ruty wplatano w wianek ślubny jako znak dziewictwa, a potem, gdy oczepiano pannę młodą, zdejmowano ją. Ruta chroniła przed urokiem, zarazą i złym spojrzeniem. Śpiewano: oj, ruto, ruto, zielona ruto. Ma gorzki zapach i niebieskozielone liście.","practice":"• Jeśli masz rutę, powieś gałązkę w oknie.\n• Przypomnij sobie piosenkę, którą śpiewały kobiety w twojej rodzinie.\n• Pomyśl, co w tobie jest czyste i warte ochrony.","extraTitle":"Ciekawostka","extra":"Ruta była tak ważna w ludowej kulturze, że stała się narodowym kwiatem Litwy.","whisper":"Czystość nie znaczy słabość. Ruta chroni, choć jest delikatna.","caution":"Ruta jest toksyczna, uczula na słońce i może wywołać poronienie. Nie stosuj wewnętrznie.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":280}],["2027-08-07","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":30.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 21:04 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿✶♅ Merkury sekstyl Uran (01:22): Dobry dzień na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania.\n♀✶♂ Wenus sekstyl Mars (23:47): Dobry dzień na namiętność, randki, taniec i twórczą energię.","sourceText":{"holiday":"","namedays":"Klaudii, Kajetana","title":"Wrzosy","subtitle":"fioletowy sierpień","story":"W sierpniu wrzosowiska zaczynają kwitnąć na fioletowo. Wrzos rośnie na piaskach i w suchych borach, tam, gdzie mało co chce rosnąć. Pszczoły zbierają z niego ciemny, aromatyczny miód. Dawniej z wrzosu robiono miotły i posłania. Wrzos to kwiat końca lata i znak, że jesień idzie.","practice":"• Wybierz się na wrzosowisko albo do suchego boru.\n• Połóż się na chwilę wśród wrzosów.\n• Kup miód wrzosowy i porównaj jego smak z lipowym.","extraTitle":"Ciekawostka","extra":"Miód wrzosowy jest tak gęsty, że w plastrach zastyga w galaretę i trudno go odwirować.","whisper":"Najpiękniejsze kwiaty kwitną tam, gdzie inni nie chcą rosnąć.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":281}],["2027-08-08","honesty","☽ w Wadze do 00:52, potem w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":41.0,"moonAndBiodynamic":"☽ w Wadze do 00:52, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 00:52 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Cypriana, Dominika","title":"Król węży","subtitle":"złota korona w trawie","story":"Wierzono, że węże mają swojego króla, który nosi złotą koronkę na głowie. Kto zdobędzie jego koronę, będzie rozumiał mowę zwierząt i znajdzie każdy skarb. Ale król węży jest groźny, a jego poddani bronią go do śmierci. W domach żył też wąż domowy, którego nie wolno było zabić, bo chronił gospodarstwo.","practice":"• Na spacerze rozglądaj się uważnie w trawie.\n• Jeśli zobaczysz węża, zatrzymaj się i daj mu odejść.\n• Pomyśl, jaki skarb jest strzeżony w twoim życiu.","extraTitle":"Pytanie na niedzielę","extra":"Jaki skarb chcę zdobyć i kogo musiałabym wtedy pokonać?","whisper":"Najcenniejsze korony są strzeżone najmocniej.","caution":"Żmija zygzakowata jest jadowita i chroniona. Nie zbliżaj się, nie dotykaj.","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":282}],["2027-08-09","honesty","☽ w Skorpionie","I kwadra",false,{"phase":"I kwadra o 06:54","nextPhase":"pełnia za 8 dni","illumination":52.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 06:54 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ we Lwie · ☿ we Lwie · ♀ we Lwie · ♂ w Wadze. Pytanie tygodnia: Co sprawia Ci prawdziwą radość?\n♄ Saturn rusza wstecz w Baranie (20:05): Na kilka miesięcy wracają lekcje odpowiedzialności. Czas sprawdzić fundamenty, zanim zbudujesz piętro wyżej. Rada: dokończ zobowiązania i popraw to, co postawiłaś na szybko.\n☿✶♂ Merkury sekstyl Mars (21:47): Dobry dzień na szybkie decyzje, debatę i załatwienie zaległości.","sourceText":{"holiday":"","namedays":"Romana, Ryszarda","title":"Wrotycz","subtitle":"złote guziczki","story":"Wrotycz kwitnie w sierpniu na przydrożach i nasypach. Jego żółte kwiaty wyglądają jak małe guziczki, a liście pachną ostro i kamforowo. Wieszano go w domach i oborach przeciw muchom, pchłom i molom. Dawniej podawano go na robaki, ale jest silnie toksyczny. Dziś pierwsza kwadra: rośnie to, co ostre.","practice":"• Rozpoznaj wrotycz po złotych guziczkach i pierzastych liściach.\n• Zawieś pęczek w spiżarni przeciw owadom.\n• Nie pij naparu z wrotyczu.","extraTitle":"Ciekawostka","extra":"Wrotycz był w średniowieczu dodawany do pościeli, by odstraszać pchły.","whisper":"Niektóre zioła chronią z daleka. Z bliska są za mocne.","caution":"Wrotycz jest toksyczny. Nie stosuj wewnętrznie, nie w ciąży, nie przy dzieciach i zwierzętach.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":283}],["2027-08-10","travel","☽ w Skorpionie do 08:35, potem w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":62.0,"moonAndBiodynamic":"☽ w Skorpionie do 08:35, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 08:35 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu do 08:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"św. Wawrzyńca","namedays":"Bogdana, Borysa","title":"Placek ze śliwkami","subtitle":"łzy świętego Wawrzyńca","story":"Dziś święty Wawrzyniec. W nocy spadają Perseidy, zwane jego łzami. Na stoły trafiają pierwsze śliwki węgierki. Placek drożdżowy ze śliwkami i kruszonką to smak końca lata w całej Polsce. Ciasto wyrasta, śliwki puszczają sok i karmelizują się w piekarniku. Pachnie cały dom.","practice":"• Zagnieć ciasto drożdżowe z 500 g mąki, 25 g drożdży, mleka, jajek i masła.\n• Rozwałkuj na blachę, ułóż gęsto połówki śliwek.\n• Posyp kruszonką i piecz 35 min w 180 °C.","extraTitle":"Ciekawostka","extra":"Wawrzyniec był diakonem w Rzymie, zamęczonym na rozżarzonej kracie w 258 roku.","whisper":"Łzy, które spadają z nieba w sierpniu, są życzeniami.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":284}],["2027-08-11","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":71.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿☌♀ Merkury koniunkcja Wenus (08:29): Dobry dzień na miłe rozmowy, komplementy, negocjacje i pisanie. Uważaj tylko na pustą uprzejmość i niezałatwione sprawy.\n☉☌☿ Słońce koniunkcja Merkury (13:02): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"","namedays":"Klary, Lidii","title":"Spiżarnia","subtitle":"zapasy na zimę","story":"Sierpień to czas zapasów. W spiżarni rosną rzędy słoików: ogórki, dżemy, kompoty, grzyby. Dawniej od tego zależało przetrwanie zimy. Robienie przetworów to rytuał: obieranie, krojenie, gotowanie, zakręcanie. Kiedy słoik pyknie przy zakręcaniu, wiesz, że się udało. To dźwięk przezorności.","practice":"• Zrób dziś choć jeden słoik przetworów.\n• Podpisz go datą i nazwą.\n• Postaw go w spiżarni i popatrz na swoją zimową przyszłość.","extraTitle":"Ciekawostka","extra":"Pasteryzacja nazwę zawdzięcza Ludwikowi Pasteurowi, który w XIX wieku opisał, jak ciepło zabija drobnoustroje.","whisper":"Przezorność nie jest lękiem. Jest troską o tę, którą będziesz w styczniu.","caution":"Wyparzaj słoiki i wieczka. Wybrzuszone wieczko oznacza zepsuty przetwór.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":285}],["2027-08-12","travel","☽ w Strzelcu, od 19:34 w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":79.0,"moonAndBiodynamic":"☽ w Strzelcu, od 19:34 w Koziorożcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 19:34 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 15:18 do 19:34: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉☌♀ Słońce koniunkcja Wenus (02:20): Dobry dzień na spotkania, randki, urodę, sztukę i przyjemności. Uważaj tylko na próżność i wydawanie na pokaz.","sourceText":{"holiday":"","namedays":"Lecha, Euzebii","title":"Spadająca gwiazda","subtitle":"dusza albo życzenie","story":"Dzisiejszej nocy, z 12 na 13 sierpnia, maksimum Perseid. Spadających gwiazd może być kilkadziesiąt na godzinę. Dawniej wierzono, że spadająca gwiazda to dusza, która właśnie odchodzi, i trzeba za nią westchnąć modlitwą. Później zaczęto wypowiadać życzenia. Trzeba zdążyć, zanim gwiazda zgaśnie, i nikomu go nie zdradzać.","practice":"• Po północy wyjdź z dala od świateł miasta.\n• Połóż się na kocu i patrz w niebo przez godzinę.\n• Przy każdej gwieździe wypowiedz w myślach życzenie.","extraTitle":"Ciekawostka","extra":"W idealnych warunkach Perseidy dają do około 100 meteorów na godzinę.","whisper":"Życzenie wypowiedziane w ciemności i przemilczane ma największą moc.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":286}],["2027-08-13","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":86.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Diany, Hipolita","title":"Bukiet na Zielną","subtitle":"przygotowanie ziół","story":"Przed świętem Matki Boskiej Zielnej kobiety zbierały zioła do bukietu. Musiało być ich dużo, często dziewięć lub więcej rodzajów: bylica, wrotycz, krwawnik, rumianek, mięta, dziurawiec, macierzanka, kłosy zbóż, makówki, marchew, jabłko. Każda rzecz miała moc. Poświęcony bukiet chronił dom przez cały rok.","practice":"• Zbierz dziś zioła, kłosy i owoce na bukiet.\n• Zwiąż je mocno lnianym sznurkiem.\n• Postaw w wodzie do niedzieli.","extraTitle":"Ciekawostka","extra":"Bukiety zielne różnią się w zależności od regionu. Na Kurpiach są wysokie jak drzewka.","whisper":"Bukiet to apteczka i modlitwa w jednym.","caution":"Uważaj, by nie zbierać roślin chronionych.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":287}],["2027-08-14","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":92.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Alfreda, Euzebiusza","title":"Pierwsze prawdziwki","subtitle":"las po deszczu","story":"Po sierpniowych deszczach w lasach pojawiają się grzyby. Prawdziwki, koźlarze, kurki, podgrzybki. Grzybobranie to polska namiętność: wychodzi się wcześnie rano, z nożykiem i koszykiem. Zbieracze strzegą swoich miejsc jak skarbu. Las pachnie wtedy mchem, igliwiem i ziemią.","practice":"• Wybierz się do lasu rano po deszczu.\n• Zbieraj tylko grzyby, które znasz na pewno.\n• Wykręcaj grzyb delikatnie, przykryj miejsce ściółką.","extraTitle":"Ciekawostka","extra":"Grzyb, który zbieramy, to tylko owocnik. Prawdziwy organizm to grzybnia pod ziemią, która może mieć kilometry.","whisper":"Las daje temu, kto przychodzi cicho i wcześnie.","caution":"Nie jedz grzybów, których nie znasz. Muchomor sromotnikowy zabija. W razie wątpliwości idź do sanepidu.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":288}],["2027-08-15","social","☽ w Koziorożcu do 08:19, potem w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Koziorożcu do 08:19, potem w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 08:19 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 03:57 do 08:19: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"Wniebowzięcie NMP · Matki Boskiej Zielnej","namedays":"Marii, Napoleona","title":"Matki Boskiej Zielnej","subtitle":"święcenie ziół i zbóż","story":"Dziś Wniebowzięcie, ludowo Matki Boskiej Zielnej. W kościołach święci się bukiety z ziół, kwiatów, zbóż, owoców i warzyw. Po powrocie zawieszano je za obrazem, pod strzechą albo w oborze. W chorobie dodawano zioła do naparów, w burzy palono je w piecu. Ziarno z bukietu dodawano do siewu jesiennego. To święto całej mądrości zielarskiej.","practice":"• Zanieś bukiet do kościoła albo postaw go w domu na stole.\n• Zawieś go w kuchni do suszenia.\n• Zachowaj trochę ziarna na jesienny siew.","extraTitle":"Pytanie na niedzielę","extra":"Jaka wiedza moich babek mogłaby mi dziś pomóc?","whisper":"Zioła poświęcone ręką kobiety mają w sobie pamięć wielu pokoleń.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":289}],["2027-08-16","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":99.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ we Lwie · ☿ we Lwie · ♀ we Lwie · ♂ w Wadze. Pytanie tygodnia: Co sprawia Ci prawdziwą radość?\n☿△♄ Merkury trygon Saturn (04:07): Dobry dzień na skupioną pracę, umowy, planowanie i dokumenty.","sourceText":{"holiday":"","namedays":"Stefana, Rocha","title":"Mak","subtitle":"makówka w bukiecie","story":"Makówki, czyli suche torebki nasienne maku, były ważną częścią zielnego bukietu. Mak był rośliną snu, zapomnienia i obfitości: w jednej makówce jest kilka tysięcy ziaren. Na Wigilię jadano kutię i makowiec, by rok był obfity. Rozsypywano mak wokół domu, by czarownice musiały go liczyć do rana i nie zdążyły wejść.","practice":"• Wysyp ziarna z makówki i policz je na chybił trafił.\n• Zachowaj trochę maku do wigilijnego makowca.\n• Pomyśl, co w twoim życiu jest tak liczne jak ziarna maku.","extraTitle":"Ciekawostka","extra":"Mak spożywczy w Polsce to odmiany niskomorfinowe. Ziarna są bezpieczne, ale niedojrzałe makówki zawierają alkaloidy.","whisper":"Obfitość nie zawsze jest głośna. Czasem mieści się w małej, suchej makówce.","caution":"Nie rób naparów z makówek. To niebezpieczne i nielegalne.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":290}],["2027-08-17","social","☽ w Wodniku, od 21:11 w Rybach","pełnia",false,{"phase":"pełnia o 09:28","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Wodniku, od 21:11 w Rybach · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 21:11 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 16:48 do 21:11: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿ Merkury wchodzi w Pannę (06:43): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie porządku, zdrowia, codziennej pracy i szczegółu. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów. Uważaj na krytykanctwo i przemęczenie.\n🌕 Pełnia w Wodniku (09:28): Kulminacja w sprawach: przyjaciele, marzenia o przyszłości, wolność. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Anity, Elizy","title":"Powidła śliwkowe","subtitle":"gotowane do zmierzchu","story":"Dziś pełnia. W sierpniu dojrzewają węgierki, a z nich robi się powidła. Gotuje się je długo, nawet przez dwa, trzy dni, bez cukru, mieszając drewnianą łopatką, aż staną się czarne i gęste. Powidła były skarbem na zimę: do pierogów, naleśników, pączków. Mówiło się, że dobre powidła stoją na łyżce.","practice":"• Wydryluj 3 kg węgierek, przełóż do garnka z grubym dnem.\n• Smaż na małym ogniu, mieszając, przez kilka godzin dziennie przez 2–3 dni.\n• Gorące powidła przełóż do słoików i zakręć.","extraTitle":"Księżyc","extra":"pełnia 17 VIII, 09:28 · III kwadra 25 VIII, 04:27","whisper":"Cierpliwość ma ciemny kolor i słodki smak.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":291}],["2027-08-18","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 16:32 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Ilony, Klary","title":"Mówienie do roślin","subtitle":"ogród słucha","story":"Dawni ogrodnicy rozmawiali z roślinami. Prosili jabłoń o owoce, grozili leniwej śliwie siekierą w Wigilię, chwalili kwiaty. Wierzono, że rośliny słyszą i czują. Dziś wiemy, że rośliny reagują na dotyk, dźwięk i zapach otoczenia. Rozmowa z rośliną to przede wszystkim uważność dla tego, co rośnie obok.","practice":"• Podejdź do swojej rośliny i przyjrzyj się jej liściom.\n• Powiedz jej coś miłego.\n• Sprawdź, czego potrzebuje: wody, światła, nowej doniczki.","extraTitle":"Ciekawostka","extra":"Rośliny reagują na wibracje, a niektóre badania sugerują, że nawet na dźwięk gryzącej je gąsienicy.","whisper":"Kto rozmawia z roślinami, ten widzi więcej niż ten, kto je tylko podlewa.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":292}],["2027-08-19","rest","☽ w Rybach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀△♄ Wenus trygon Saturn (03:08): Dobry dzień na trwałe zobowiązania, inwestycje i porządki w finansach.","sourceText":{"holiday":"","namedays":"Jana, Bolesława","title":"Czarcie kręgi","subtitle":"gdzie tańczyły wiedźmy","story":"W lesie i na łąkach grzyby wyrastają czasem w kręgu. Mówiono, że to miejsce, gdzie tańczyły czarownice albo diabły. Kto wszedł do środka, mógł zostać porwany do świata duchów albo tańczyć do śmierci. Dziś wiemy, że grzybnia rośnie promieniście od środka, a owocniki pojawiają się na jej krawędzi.","practice":"• Na spacerze poszukaj kręgu grzybów.\n• Nie wchodź do środka, tylko popatrz.\n• Pomyśl, w jakie kręgi ty wchodzisz bez namysłu.","extraTitle":"Ciekawostka","extra":"Niektóre czarcie kręgi mają kilkaset lat i kilkadziesiąt metrów średnicy.","whisper":"Nie każdy krąg jest zaproszeniem do tańca.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":293}],["2027-08-20","start","☽ w Rybach do 08:54, potem w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Rybach do 08:54, potem w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Do 08:54 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu do 08:54: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿☌♃ Merkury koniunkcja Jowisz (00:46): Dobry dzień na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości. Uważaj tylko na obietnice bez pokrycia i przeoczone szczegóły.\n♀ Wenus wchodzi w Pannę (21:42): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie porządku, zdrowia, codziennej pracy i szczegółu. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów. Uważaj na krytykanctwo i przemęczenie.","sourceText":{"holiday":"","namedays":"Bernarda, Samuela","title":"Korale jarzębiny","subtitle":"czerwona tarcza","story":"W sierpniu dojrzewa jarzębina. Jej czerwone owoce nawlekano na nici i noszono jako korale. Wierzono, że jarzębina chroni przed czarami, urokiem i złymi duchami. Gałązki zatykano w oborach i na bramach. Mówiono, że dobry rok na jarzębinę zwiastuje ciężką zimę. Ptaki objadają ją do pierwszego śniegu.","practice":"• Nawlecz na nitkę kilka owoców jarzębiny.\n• Powieś korale w oknie albo przy drzwiach.\n• Zostaw resztę na krzewie dla ptaków.","extraTitle":"Ciekawostka","extra":"Surowe owoce jarzębiny są gorzkie i lekko toksyczne. Po przemrożeniu albo gotowaniu stają się jadalne.","whisper":"Czerwień, którą nosisz, mówi światu: tu jest granica.","caution":"Nie jedz surowych owoców jarzębiny.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":294}],["2027-08-21","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":84.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☉△♄ Słońce trygon Saturn (02:40): Dobry dzień na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach.","sourceText":{"holiday":"","namedays":"Franciszka, Joanny","title":"Bocianie sejmiki","subtitle":"pożegnanie przed odlotem","story":"Pod koniec sierpnia bociany zbierają się na łąkach w duże stada. Nazywano je sejmikami. Wierzono, że bociany radzą nad odlotem, a te, które są chore albo słabe, zostają zadziobane, by nie opóźniały wyprawy. Potem odlatują do Afryki. Puste gniazdo na dachu to znak, że lato się kończy.","practice":"• Popatrz na łąki i poszukaj bocianich sejmików.\n• Pożegnaj bociany w myślach.\n• Zapisz, co chcesz zabrać ze sobą w jesień.","extraTitle":"Ciekawostka","extra":"Bociany z Polski lecą do Afryki dwiema trasami: przez Bosfor albo przez Gibraltar.","whisper":"Każde pożegnanie łatwiej znieść, gdy wiesz, że ptaki wrócą.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":295}],["2027-08-22","start","☽ w Baranie, od 18:32 w Byku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":76.0,"moonAndBiodynamic":"☽ w Baranie, od 18:32 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 18:32 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 17:15 do 18:32: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿□♅ Merkury kwadratura Uran (11:14): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.","sourceText":{"holiday":"","namedays":"Marii, Cezarego","title":"Smok Wawelski","subtitle":"pod Wzgórzem","story":"Pod Wawelem w jaskini mieszkał smok. Pożerał owce i panny, a nikt nie mógł go pokonać. Szewczyk Dratewka napchał owczą skórę siarką i podrzucił smokowi. Smok zjadł, poczuł ogień w brzuchu, pił wodę z Wisły, aż pękł. Legenda uczy, że spryt jest silniejszy od miecza. Smocza Jama istnieje do dziś.","practice":"• Pomyśl o problemie, który wydaje się nie do pokonania.\n• Zastanów się, czy nie da się go przechytrzyć zamiast walczyć.\n• Zapisz jeden sprytny ruch.","extraTitle":"Pytanie na niedzielę","extra":"Gdzie zamiast siły mogłabym użyć sprytu?","whisper":"Smoki rzadko giną od miecza. Częściej od własnej łapczywości.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":296}],["2027-08-23","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":67.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 16:42 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Pannie · ☿ w Pannie · ♀ w Pannie · ♂ w Wadze. Pytanie tygodnia: Co możesz usprawnić w codzienności?\n☉ Słońce wchodzi w Pannę (10:14): Na miesiąc cały świat nabiera barw znaku Panny: czas porządku, zdrowia, codziennej pracy i szczegółu. Rada: posprzątaj jedną rzecz i dopilnuj szczegółów.","sourceText":{"holiday":"","namedays":"Róży, Apolinarego","title":"Ostropest","subtitle":"oset dla wątroby","story":"Ostropest plamisty to oset z białymi żyłkami na liściach. Legenda mówi, że to mleko Matki Bożej, które skapnęło na liście. Jego nasiona chronią wątrobę: od wieków podawano je przy zatruciach, chorobach wątroby i po ciężkich posiłkach. Dziś to jedno z najlepiej zbadanych ziół w medycynie.","practice":"• Zmiel łyżkę nasion ostropestu i dodaj do jogurtu.\n• Posadź ostropest w ogrodzie. Pszczoły go kochają.\n• Pomyśl, co w twoim życiu jest kłujące, a lecznicze.","extraTitle":"Ciekawostka","extra":"Sylimaryna z ostropestu jest stosowana w szpitalach przy zatruciach muchomorem sromotnikowym.","whisper":"Najlepsza ochrona często jest kłująca z zewnątrz i miękka w środku.","caution":"Nie przy uczuleniu na astrowate. Przy chorobach wątroby skonsultuj z lekarzem.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":297}],["2027-08-24","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 7 dni","illumination":57.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Cały dzień Księżyc jest bez kursu: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Bartłomieja","namedays":"Emilii, Jerzego","title":"Miód z orzechami","subtitle":"na Bartłomieja","story":"Święty Bartłomiej był patronem pszczelarzy. W jego dzień zaczynano miodobranie, czyli wybieranie miodu z uli. Pszczelarze dzielili się pierwszym miodem z sąsiadami i z kościołem. Miód z orzechami był przysmakiem i lekarstwem: dawał siłę na zimę i leczył gardło. Wystarczy słoik miodu i garść orzechów.","practice":"• Uprażaj garść orzechów włoskich na suchej patelni.\n• Przełóż do słoika i zalej płynnym miodem.\n• Odstaw na tydzień. Jedz łyżeczkę rano.","extraTitle":"Ciekawostka","extra":"Słowo bartnik pochodzi od barci, czyli dziupli w drzewie, w której mieszkały dzikie pszczoły.","whisper":"Miód jest wspomnieniem lata, które pszczoły zostawiły dla nas.","caution":"Nie podawaj miodu dzieciom poniżej roku. Nie przy uczuleniu na orzechy.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":298}],["2027-08-25","conversation","☽ w Byku do 01:26, potem w Bliźniętach","III kwadra",false,{"phase":"III kwadra o 04:27","nextPhase":"nów za 6 dni","illumination":46.0,"moonAndBiodynamic":"☽ w Byku do 01:26, potem w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Do 01:26 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Luizy, Ludwika","title":"Szafa przed jesienią","subtitle":"ostatnia kwadra","story":"Dziś nad ranem ostatnia kwadra. Księżyc maleje i podpowiada: odpuść. To dobry czas, by przejrzeć szafę przed jesienią. Odłożyć letnie rzeczy, wyjąć swetry, oddać to, czego nie nosisz. Dawniej przed zmianą pory roku wietrzono kufry i przekładano odzież lawendą. Robienie miejsca to też magia.","practice":"• Przejrzyj szafę i odłóż letnie ubrania.\n• Oddaj trzy rzeczy, których nie nosisz od roku.\n• Włóż do szafy woreczek z lawendą lub bylicą.","extraTitle":"Ciekawostka","extra":"Zwyczaj przekładania odzieży ziołami chronił wełnę przed molami, zanim wynaleziono naftalinę.","whisper":"Co oddajesz, robi miejsce na to, co przyjdzie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":299}],["2027-08-26","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":35.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀☌♃ Wenus spotyka Jowisza (04:59): Szczęśliwy dzień dla miłości, przyjemności i pieniędzy. Rada: spotkaj się z kimś, kogo lubisz. Uwaga: nie przesadzaj z zakupami.","sourceText":{"holiday":"","namedays":"Marii, Zefiryny","title":"Swędząca dłoń","subtitle":"pieniądze czy kłótnia?","story":"Kiedy swędzi cię prawa dłoń, mówiono, że będziesz witać gościa albo dostaniesz pieniądze. Kiedy lewa, będziesz pieniądze wydawać. Swędzący nos wróżył kłótnię albo wódkę, a ucho, że ktoś o tobie mówi. Ciało było mapą wróżb. Każde drgnięcie powieki coś znaczyło.","practice":"• Zauważ dziś, co cię swędzi.\n• Zapisz, co według przesądu oznacza.\n• Wieczorem sprawdź, czy się sprawdziło.","extraTitle":"Ciekawostka","extra":"Przesąd o swędzącej dłoni jest znany w niemal całej Europie i na Bliskim Wschodzie.","whisper":"Ciało mówi do ciebie przez cały dzień. Nie zawsze o pieniądzach.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":300}],["2027-08-27","home","☽ w Bliźniętach do 05:20, potem w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":24.0,"moonAndBiodynamic":"☽ w Bliźniętach do 05:20, potem w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Do 05:20 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Moniki, Cezarego","title":"Głóg","subtitle":"krzew przy granicy","story":"Głóg sadzono na granicach pól i przy domach. Jego kolce chroniły przed zwierzętami i złymi duchami. Wierzono, że korona cierniowa była z głogu, dlatego ma moc. Owoce głogu, czerwone i mączyste, leczyły serce. Na Wyspach Brytyjskich głóg był drzewem wróżek, którego nie wolno ścinać.","practice":"• Znajdź krzew głogu i przyjrzyj się jego owocom.\n• Zbierz kilka do suszenia, gdy dojrzeją.\n• Pomyśl, kto w twoim życiu chroni twoje serce.","extraTitle":"Ciekawostka","extra":"Wyciągi z głogu są stosowane we współczesnej fitoterapii przy łagodnych zaburzeniach pracy serca.","whisper":"Serce chroni to, co ma kolce i czerwone owoce.","caution":"Głóg nasila działanie leków nasercowych. Skonsultuj z lekarzem.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":301}],["2027-08-28","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":15.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀□♅ Wenus kwadratura Uran (20:04): Napięcie między planetami. Można je wykorzystać na nowe znajomości, niespodzianki i zmianę wizerunku. Uważaj na nagłe zauroczenia i wydatki pod wpływem chwili.","sourceText":{"holiday":"","namedays":"Patrycji, Wyszomira","title":"Babie lato","subtitle":"srebrne nitki w powietrzu","story":"Pod koniec sierpnia i we wrześniu w powietrzu unoszą się srebrne nitki pajęczyn. Nazywa się je babim latem. To młode pająki, które wypuszczają nić i lecą z wiatrem. Mówiono, że to nici przędzione przez Matkę Bożą albo przez stare kobiety. Kiedy nitka przyczepi się do ubrania, ma przynieść szczęście.","practice":"• Wyjdź w ciepłe, słoneczne popołudnie na łąkę.\n• Wypatruj błyszczących nitek pod światło.\n• Jeśli nitka przyczepi się do ciebie, pomyśl życzenie.","extraTitle":"Ciekawostka","extra":"Niektóre pająki potrafią przelecieć na swojej nitce setki kilometrów.","whisper":"Kto umie czekać na wiatr, ten dolatuje dalej niż ten, kto biegnie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":302}],["2027-08-29","creative","☽ w Raku do 06:42, potem we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":7.0,"moonAndBiodynamic":"☽ w Raku do 06:42, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 06:42 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♂☍♄ Mars naprzeciw Saturna (09:35): Ktoś albo coś blokuje Twoje działania. Rada: cierpliwość i plan zamiast ataku. Uwaga: ostrożnie na drodze.","sourceText":{"holiday":"","namedays":"Beaty, Jana","title":"Ścięcie Jana","subtitle":"dzień bez okrągłych rzeczy","story":"Dziś wspomnienie ścięcia świętego Jana Chrzciciela. W wielu wsiach tego dnia nie jedzono rzeczy okrągłych, jak jabłka, kapusta czy ziemniaki, bo przypominały ściętą głowę. Nie krojono chleba nożem, tylko łamano go. Był to dzień postu i powagi. Takie zwyczaje uczą, że pamięć można nosić w codziennych gestach.","practice":"• Złam chleb rękami zamiast go kroić.\n• Zjedz dziś prosty posiłek.\n• Pomyśl o kimś, kto stracił życie za prawdę.","extraTitle":"Pytanie na niedzielę","extra":"Za jaką prawdę byłabym gotowa zapłacić?","whisper":"Pamięć nie musi być wielka. Wystarczy jeden złamany kawałek chleba.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":303}],["2027-08-30","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":2.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Pannie · ☿ w Pannie · ♀ w Pannie · ♂ w Wadze. Pytanie tygodnia: Co możesz usprawnić w codzienności?","sourceText":{"holiday":"","namedays":"Róży, Szczęsnego","title":"Chmiel","subtitle":"zielone szyszki","story":"Pod koniec sierpnia chmiel ma dojrzałe, zielone szyszki. Pachną gorzko i ziołowo, a w środku mają żółty pyłek, lupulinę. Chmiel nadaje piwu goryczkę i trwałość, a w ziołolecznictwie uspokaja i pomaga zasnąć. Na weselach śpiewano o chmielu, który pnie się wysoko, jak młoda para w życiu.","practice":"• Zbierz szyszki chmielu i wysusz je w cieniu.\n• Uszyj z nich poduszkę do spania.\n• Zaparz łyżeczkę w naparze z melisą.","extraTitle":"Ciekawostka","extra":"Pieśń „Oj, chmielu, chmielu” śpiewano podczas oczepin, gdy pannie młodej zdejmowano wianek.","whisper":"Kto pnie się powoli, wspina się najwyżej.","caution":"Chmiel nasila działanie leków uspokajających.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":304}],["2027-08-31","organize","☽ we Lwie do 06:43, potem w Pannie","nów",false,{"phase":"nów o 19:41","nextPhase":"pełnia za 16 dni","illumination":0.0,"moonAndBiodynamic":"☽ we Lwie do 06:43, potem w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Do 06:43 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉☌♃ Słońce spotyka Jowisza (09:29): Jeden z najszczęśliwszych dni roku: optymizm i szanse. Rada: poproś o coś, złóż ofertę, świętuj.\n🌑 Nów w Pannie (19:41): Czas zasiewu w sprawach: zdrowie, nawyki, praca. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Izabeli, Ramony","title":"Ogórki kiszone","subtitle":"zapas na całą zimę","story":"Dziś wieczorem nów. Koniec sierpnia to czas kiszenia ogórków na zimę. Duże ogórki układa się w beczce albo kamionkowym garnku z koprem, czosnkiem, chrzanem, liśćmi wiśni i dębu, zalewa solanką i zostawia na kilka tygodni. Mówiono, że kisić trzeba przy nowiu, bo ogórki są wtedy twardsze.","practice":"• Ułóż ciasno w słoju 2 kg ogórków z koprem, czosnkiem i chrzanem.\n• Zalej solanką: 2 łyżki soli na litr wody.\n• Zakręć i odstaw w chłodne miejsce na 3–4 tygodnie.","extraTitle":"Księżyc","extra":"nów 31 VIII, 19:41 · pełnia 16 IX, 01:03","whisper":"Przy nowiu wszystko zaczyna się od nowa. Nawet ogórki.","caution":"Dużo soli. Ostrożnie przy nadciśnieniu.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":305}],["2027-09-01","organize","☽ w Pannie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 15 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Idziego","namedays":"Bronisławy, Idziego","title":"Nowy zeszyt","subtitle":"początek roku nauki","story":"Pierwszy września to drugi Nowy Rok. Dla dzieci zaczyna się szkoła, ale dla dorosłych też jest coś w tym zapachu nowych zeszytów i zatemperowanych ołówków. To czas, by nauczyć się czegoś nowego. Dawniej jesienią, po żniwach, zaczynały się wieczorne prace: przędzenie, darcie pierza, opowieści. Wieczory uczyły więcej niż szkoła.","practice":"• Kup albo wyjmij nowy zeszyt.\n• Na pierwszej stronie zapisz, czego chcesz się nauczyć do grudnia.\n• Zaplanuj pierwszy krok na ten tydzień.","extraTitle":"Ciekawostka","extra":"Święty Idzi, patron dnia, był pustelnikiem z VII wieku. Jego kult w Polsce rozwinął się za Władysława Hermana.","whisper":"Nigdy nie jest za późno, by zacząć nowy zeszyt.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":306}],["2027-09-02","relationships","☽ w Pannie do 07:07, potem w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Pannie do 07:07, potem w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 07:07 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 03:28 do 07:07: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂ Mars wchodzi w Skorpiona (03:52): Na kilka tygodni energia i działanie płyną w rytmie głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej. Uważaj na zazdrość i podejrzliwość.\n☉□♅ Słońce kwadratura Uran (15:51): Napięcie między planetami. Można je wykorzystać na nowości, zmianę rutyny i odważne pomysły. Uważaj na nagłe zwroty i decyzje pod wpływem impulsu.","sourceText":{"holiday":"","namedays":"Juliana, Stefana","title":"Nie dawaj pieniędzy po zmroku","subtitle":"bo wyjdzie z domu szczęście","story":"Po zachodzie słońca nie oddawano długów ani nie pożyczano pieniędzy. Wierzono, że razem z monetą wynosi się z domu dostatek. Nie wolno też było liczyć pieniędzy w nocy ani zostawiać pustego portfela. Pod obrusem albo w kącie szafy trzymano zawsze jedną monetę, by pieniądze miały do czego wracać.","practice":"• Włóż monetę do pustego portfela albo słoika.\n• Zostaw ją tam na zawsze.\n• Zaplanuj płatności na jutro rano, nie na wieczór.","extraTitle":"Ciekawostka","extra":"Zwyczaj zostawiania monety w nowym portfelu, gdy się go komuś daje w prezencie, jest znany do dziś.","whisper":"Pieniądze lubią wracać tam, gdzie zostawiłaś im miejsce.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":307}],["2027-09-03","relationships","☽ w Wadze","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿ Merkury wchodzi w Wagę (13:36): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie relacji, piękna, kompromisu i umów. Rada: szukaj porozumienia i piękna. Uważaj na niezdecydowanie i zadowalanie wszystkich.","sourceText":{"holiday":"","namedays":"Izabeli, Szymona","title":"Dziewięćsił","subtitle":"słońce na drzwiach","story":"Dziewięćsił bezłodygowy rośnie w górach jak srebrne słońce przy ziemi. Górale przybijali jego kwiaty do drzwi chałup, by chroniły przed złymi duchami, piorunem i chorobą. Kwiat zamyka się przed deszczem, więc był też barometrem. Nazwa mówi, że ma siłę dziewięciu ziół. Jest pod ochroną i coraz rzadszy.","practice":"• Zobacz zdjęcie dziewięćsiłu i zapamiętaj jego kształt.\n• Narysuj go albo wytnij z papieru i przypnij na drzwiach.\n• Pomyśl, jaka siła w tobie ma moc dziewięciu.","extraTitle":"Ciekawostka","extra":"Korzeń dziewięćsiłu był dawniej jedzony jak karczoch. Jego kwiat jest do niego podobny.","whisper":"Słońce przybite do drzwi przypomina, że światło zawsze może wejść.","caution":"Dziewięćsił jest pod ścisłą ochroną. Nie zrywaj.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":308}],["2027-09-04","honesty","☽ w Wadze do 09:44, potem w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":16.0,"moonAndBiodynamic":"☽ w Wadze do 09:44, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 09:44 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 05:06 do 09:44: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Idy, Lilianny","title":"Jabłka","subtitle":"wrześniowy sad","story":"We wrześniu sady pachną jabłkami. Antonówki, papierówki, malinówki, kosztele. Stare odmiany mają smaki, których nie znajdziesz w supermarkecie. Jabłko było owocem wiedzy, miłości i zdrowia. Dawano je na wróżby, kładziono w Wigilię na stole, przynoszono na święconkę. Jabłko dziennie trzyma lekarza z dala, mówi przysłowie.","practice":"• Kup na targu jabłka starej odmiany.\n• Przekrój jedno w poprzek: zobaczysz gwiazdę.\n• Zjedz je powoli, ze skórką.","extraTitle":"Ciekawostka","extra":"W przekroju poprzecznym jabłko ma pięcioramienną gwiazdę z pestkami, symbol magii i zdrowia.","whisper":"Każde jabłko nosi w środku gwiazdę. Trzeba je tylko przeciąć w poprzek.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":309}],["2027-09-05","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":25.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 21:05 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Doroty, Wawrzyńca","title":"Bies","subtitle":"ten, który kusi","story":"Bies to stare słowiańskie słowo na złego ducha. Z niego wzięły się Bieszczady, mówi jedna z hipotez, i wyrażenie biesy, czyli diabelskie moce. Bies podkusza, mąci, sieje złość. Mówiono, że kto się wściekle złości, temu bies siedzi na karku. Bies nie atakuje silnych. Szuka tych, którzy są zmęczeni.","practice":"• Zauważ dziś, kiedy łapie cię złość.\n• Zatrzymaj się na trzy oddechy.\n• Zapytaj siebie: czy to ja, czy bies na moim karku?","extraTitle":"Pytanie na niedzielę","extra":"Kiedy jestem najbardziej podatna na złość i jak mogę się wtedy chronić?","whisper":"Biesy przychodzą do zmęczonych. Odpoczynek to najlepsza ochrona.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":310}],["2027-09-06","honesty","☽ w Skorpionie, od 16:01 w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":35.0,"moonAndBiodynamic":"☽ w Skorpionie, od 16:01 w Strzelcu · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 16:01 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu do 16:01: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Pannie · ☿ w Wadze · ♀ w Pannie · ♂ w Skorpionie. Pytanie tygodnia: Co możesz usprawnić w codzienności?\n☿△♇ Merkury trygon Pluton (22:55): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy.","sourceText":{"holiday":"","namedays":"Beaty, Eugeniusza","title":"Owoce czarnego bzu","subtitle":"granatowe grona","story":"We wrześniu czarny bez ma dojrzałe, granatowe owoce. Z nich robi się sok, syrop i konfitury, które od wieków leczyły przeziębienie i grypę. Syrop z czarnego bzu to babcina tarcza na zimę. Owoce trzeba ugotować, bo surowe są trujące. Ptaki je uwielbiają i roznoszą bez po całej okolicy.","practice":"• Zbierz dojrzałe, granatowe baldachy czarnego bzu.\n• Oddziel owoce widelcem od łodyżek.\n• Ugotuj z wodą i cukrem na sok.","extraTitle":"Ciekawostka","extra":"Badania sugerują, że wyciąg z owoców czarnego bzu może skracać czas trwania przeziębienia.","whisper":"Granatowe grona to zima zamknięta w lecie.","caution":"Surowe owoce, zielone części i nasiona są trujące. Zawsze gotuj.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":311}],["2027-09-07","travel","☽ w Strzelcu","I kwadra",false,{"phase":"I kwadra o 20:31","nextPhase":"pełnia za 9 dni","illumination":46.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿☍♆ Merkury naprzeciw Neptuna (10:11): Ktoś może mówić nie całą prawdę albo Ty sama widzisz to, co chcesz. Uwaga: przeczytaj drobny druk.","sourceText":{"holiday":"","namedays":"Reginy, Melchiora","title":"Szarlotka","subtitle":"jabłka i cynamon","story":"Szarlotka to polskie ciasto jabłkowe na kruchym spodzie, z kruszonką albo kratką. Pachnie cynamonem i całym domem. We wrześniu, gdy jabłek jest najwięcej, piecze się ją w każdej kuchni. Najlepsza jest z kwaśnych jabłek, jak szara reneta albo antonówka. Dziś pierwsza kwadra: dobry czas, by coś upiec dla innych.","practice":"• Zagnieć kruche ciasto z 300 g mąki, 200 g masła, 100 g cukru i 2 żółtek.\n• Wyłóż połową blachę, nałóż prażone jabłka z cynamonem.\n• Przykryj resztą ciasta startą na tarce, piecz 50 min w 180 °C.","extraTitle":"Ciekawostka","extra":"Nazwa szarlotka pochodzi prawdopodobnie od francuskiego charlotte, ale polska wersja ma niewiele wspólnego z oryginałem.","whisper":"Ciasto upieczone dla kogoś smakuje lepiej niż to dla siebie.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":312}],["2027-09-08","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":56.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 20:28 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Matki Boskiej Siewnej","namedays":"Marii, Adriany","title":"Matki Boskiej Siewnej","subtitle":"ziarno pod ochroną","story":"Dziś Narodzenie Matki Bożej, ludowo Siewna. W kościołach święcono ziarno do siewu ozimin, a gospodarze dodawali je do worka z resztą zboża. Mówiono, że od Siewnej zaczyna się siew jesienny. Ziarno było jak dziecko: kładziono je do ziemi, by przetrwało zimę i wzeszło na wiosnę. Dziś to także dobry dzień, by zasiać jesienne plany.","practice":"• Zasiej w doniczce coś na jesień: rzeżuchę, cebulę, czosnek.\n• Zapisz jeden plan, który chcesz posadzić na zimę.\n• Podziękuj za plony lata.","extraTitle":"Ciekawostka","extra":"Oziminy, czyli zboża siane jesienią, muszą przejść przez zimę, by dobrze wykłosić się wiosną.","whisper":"Niektóre ziarna muszą przezimować w ciemności, żeby wzejść.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":313}],["2027-09-09","work","☽ w Strzelcu do 02:11, potem w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":66.0,"moonAndBiodynamic":"☽ w Strzelcu do 02:11, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 02:11 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♂□♇ Mars w napięciu z Plutonem (20:38): Silna, czasem gwałtowna energia. Walka o władzę i kontrolę. Uwaga: nie daj się sprowokować, nie przeforsuj ciała.","sourceText":{"holiday":"","namedays":"Piotra, Sergiusza","title":"Zasady siewcy","subtitle":"milczenie i biała koszula","story":"Siewca wychodził w pole w czystej, białej koszuli, często boso i w milczeniu. Pierwszą garść ziarna rzucał na krzyż, a potem siał szerokim ruchem z płachty. Nie wolno było siać w piątek ani przy ubywającym Księżycu. Wierzono, że kto rozmawia podczas siewu, temu zboże wzejdzie rzadko. Siew był modlitwą ruchu.","practice":"• Rób dziś jedną rzecz w całkowitym milczeniu.\n• Zauważ, jak się wtedy czujesz.\n• Pomyśl, co w tobie wymaga skupienia, a nie słów.","extraTitle":"Ciekawostka","extra":"Siew ręczny z płachty wymagał rytmu: krok, rzut, krok, rzut. Dobry siewca był szanowany jak muzyk.","whisper":"Niektóre rzeczy rosną lepiej, gdy sieje się je w ciszy.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":314}],["2027-09-10","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":74.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿△♅ Merkury trygon Uran (07:17): Dobry dzień na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania.\n♃□♅ Jowisz w napięciu z Uranem (18:41): Nagłe szanse i nagłe zwroty. Kusi, by rzucić wszystko dla nowego. Uwaga: nie ryzykuj pieniędzmi pod wpływem chwili.","sourceText":{"holiday":"","namedays":"Łukasza, Mikołaja","title":"Cebula na parapecie","subtitle":"łapaczka chorób","story":"W okresie przeziębień kładziono na parapecie albo przy łóżku chorego przekrojoną cebulę. Wierzono, że łapie choroby i oczyszcza powietrze. Kiedy cebula czerniała, mówiono, że wchłonęła zło. Cebulę dodawano do syropów na kaszel i okładów na uszy. Nauka nie potwierdza, że cebula łapie wirusy, ale zapach i syrop działają dobrze.","practice":"• Zrób syrop z cebuli: pokrój cebulę, zasyp cukrem i zostaw na noc.\n• Rano zbierz sok i pij po łyżeczce.\n• Nie trzymaj długo przekrojonej cebuli. Lepiej ją zjeść.","extraTitle":"Ciekawostka","extra":"Syrop z cebuli był jednym z najpopularniejszych domowych leków na kaszel w Polsce.","whisper":"Nie każda ochrona działa tak, jak wierzymy. Ale troska działa zawsze.","caution":"","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":315}],["2027-09-11","work","☽ w Koziorożcu, od 14:49 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":82.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 14:49 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 14:49 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 08:42 do 14:49: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Jacka, Dagny","title":"Rykowisko","subtitle":"głos jeleni","story":"We wrześniu w lasach zaczyna się rykowisko. Jelenie ryczą, by przyciągnąć łanie i odstraszyć rywali. Ich głos niesie się po lesie, zwłaszcza o świcie i zmierzchu. Dawniej mówiono, że to głos leśnych duchów. Jeleń był symbolem siły, szlachetności i odrodzenia, bo co roku zrzuca i odnawia poroże.","practice":"• Wybierz się o zmierzchu na skraj lasu.\n• Zachowaj ciszę i posłuchaj.\n• Pomyśl, co w tobie co roku odrasta na nowo.","extraTitle":"Ciekawostka","extra":"Jeleń zrzuca poroże w lutym i marcu, a nowe odrasta do sierpnia.","whisper":"To, co zrzucasz, może odrosnąć silniejsze.","caution":"Nie zbliżaj się do jeleni na rykowisku. Mogą być agresywne.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":316}],["2027-09-12","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":89.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Radzimira, Gwidona","title":"Morowa dziewica","subtitle":"ta z czerwoną chustą","story":"Kiedy szła zaraza, mówiono, że po wsiach chodzi morowa dziewica. Wysoka, blada, w bieli, z czerwoną chustą. Gdzie machnęła chustą, tam ludzie umierali. Opowiadano o śmiałku, który odciął jej rękę razem z chustą i uratował wieś, choć sam zginął. Morowa dziewica to dawny obraz epidemii, przed którą nie było lekarstwa.","practice":"• Pomyśl o ludziach, którzy pomagają innym w czasie chorób.\n• Podziękuj komuś z ochrony zdrowia, kogo znasz.\n• Umyj dziś ręce z uwagą, jak dawniej obmywano je przed zarazą.","extraTitle":"Pytanie na niedzielę","extra":"Przed czym chroniłabym moich bliskich, gdyby przyszła zaraza?","whisper":"Zaraza boi się odwagi i czystych rąk.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":317}],["2027-09-13","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":94.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 21:19 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Pannie · ☿ w Wadze · ♀ w Pannie · ♂ w Skorpionie. Pytanie tygodnia: Co możesz usprawnić w codzienności?","sourceText":{"holiday":"","namedays":"Eugenii, Aureliusza","title":"Dzika róża","subtitle":"owoc pełen witaminy","story":"We wrześniu na krzewach dzikiej róży dojrzewają czerwone owoce, zwane owocami róży albo szypszyną. Mają dużo witaminy C. Dawniej robiono z nich herbatki, konfitury i wino, a dzieciom dawano na wzmocnienie. Środek owocu jest pełen włosków, które drapią. Kiedyś dzieci używały ich jako proszku na swędzenie.","practice":"• Zbierz owoce dzikiej róży po pierwszych przymrozkach albo teraz i zamroź.\n• Przekrój i usuń nasiona z włoskami.\n• Zaparz suszone owoce na herbatę.","extraTitle":"Ciekawostka","extra":"W czasie II wojny światowej w Wielkiej Brytanii dzieci zbierały owoce dzikiej róży na syrop witaminowy.","whisper":"Najwięcej siły ma owoc, który dojrzewa na kolczastym krzewie.","caution":"Włoski z wnętrza owocu podrażniają. Przecedź napar dokładnie.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":318}],["2027-09-14","rest","☽ w Wodniku do 03:38, potem w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":98.0,"moonAndBiodynamic":"☽ w Wodniku do 03:38, potem w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Do 03:38 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀ Wenus wchodzi w Wagę (02:24): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie relacji, piękna, kompromisu i umów. Rada: szukaj porozumienia i piękna. Uważaj na niezdecydowanie i zadowalanie wszystkich.","sourceText":{"holiday":"","namedays":"Roksany, Bernarda","title":"Grzyby marynowane","subtitle":"las w occie","story":"Grzyby marynowane były ozdobą każdej spiżarni i wigilijnego stołu. Małe prawdziwki, maślaki, podgrzybki gotowane w occie z przyprawami: liść laurowy, ziele angielskie, gorczyca, cebula. Ułożone w słoikach wyglądały jak kolekcja skarbów. Grzyby marynuje się tylko młode, jędrne i zdrowe.","practice":"• Oczyść 1 kg młodych grzybów i obgotuj w osolonej wodzie 10 minut.\n• Zagotuj zalewę z octu, wody, cukru, soli i przypraw.\n• Ułóż grzyby w słoikach, zalej gorącą zalewą, zakręć.","extraTitle":"Ciekawostka","extra":"Dawniej grzyby marynowano w drewnianych beczułkach, a ocet robiono z jabłek.","whisper":"To, co zebrane w lesie, zamknięte w słoiku, przynosi las do domu zimą.","caution":"Marynuj tylko grzyby, które znasz na pewno.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":319}],["2027-09-15","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♅ Uran rusza wstecz w Bliźniętach (11:09): Zmiany idą do środka. Bunt i potrzeba wolności przybierają postać wewnętrznych przemyśleń. Rada: zastanów się, z czego chcesz się uwolnić, zanim zrobisz gwałtowny ruch.","sourceText":{"holiday":"","namedays":"Albina, Nikodema","title":"Lista plonów","subtitle":"wdzięczność za lato","story":"Wrzesień to czas zbiorów i wdzięczności. Na wsi dziękowano za plony podczas dożynek, niosąc wieniec do dworu albo do kościoła. Ty też możesz zrobić swoje dożynki. Zapisz, co zebrałaś tego lata: doświadczenia, ludzi, chwile, nauki. Wdzięczność to sposób, by poczuć, że rok nie przeszedł obok.","practice":"• Zapisz dziesięć rzeczy, które przyniosło ci lato.\n• Przeczytaj je na głos.\n• Podziękuj komuś, kto był w tym ważny.","extraTitle":"Ciekawostka","extra":"Dożynki, zwane też wyżynkami albo obżynkami, kończyły okres żniw.","whisper":"Plon widać dopiero wtedy, gdy się go policzy.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":320}],["2027-09-16","rest","☽ w Rybach, od 14:56 w Baranie","pełnia",true,{"phase":"pełnia o 01:03","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Rybach, od 14:56 w Baranie · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 14:56 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 01:03 do 14:56: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌕 Pełnia w Rybach (01:03): Kulminacja w sprawach: intuicja, sny, odpoczynek, duchowość. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Edyty, Kornela","title":"Księżyc żniwiarzy","subtitle":"pełnia przed równonocą","story":"Dziś w nocy pełnia, najbliższa jesiennej równonocy. Nazywa się ją księżycem żniwiarzy, bo dawniej przy jej świetle kończono prace w polu do późna. Księżyc wschodzi wtedy kilka wieczorów z rzędu niemal o tej samej porze, zaraz po zachodzie Słońca. Wierzono, że przy pełni nie należy zaczynać nowych spraw, tylko je kończyć.","practice":"• Wieczorem popatrz, jak wschodzi pełnia.\n• Zakończ dziś jedną sprawę, która ciągnie się od tygodni.\n• Zapisz, co chcesz zebrać przed zimą.","extraTitle":"Księżyc","extra":"pełnia 16 IX, 01:03 · III kwadra 23 IX, 12:20","whisper":"Pełnia to czas zbiorów, nie siewu.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":321}],["2027-09-17","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":98.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Franciszka, Hildegardy","title":"Orzech włoski","subtitle":"nie śpij pod jego koroną","story":"Orzech włoski był drzewem silnym i niebezpiecznym. Mówiono, że kto śpi pod orzechem, temu rozboli głowa, a pod orzechem zbierają się czarownice. Liście orzecha odstraszały muchy i mole, dlatego wkładano je do szaf i wieszano w oborach. Z zielonych łupin robiono brązowy barwnik do tkanin i włosów.","practice":"• Zbierz kilka liści orzecha i włóż do szafy.\n• Nie odpoczywaj długo pod orzechem w upale.\n• Zebrane orzechy wysusz na zimę.","extraTitle":"Ciekawostka","extra":"Liście i korzenie orzecha wydzielają juglon, substancję hamującą wzrost innych roślin pod nim.","whisper":"Niektóre drzewa dają owoce, ale nie dają cienia na odpoczynek.","caution":"Zielone łupiny barwią skórę na brązowo na wiele dni.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":322}],["2027-09-18","start","☽ w Baranie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 17:40 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀△♇ Wenus trygon Pluton (02:10): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach.\n♀☍♆ Wenus opozycja Neptun (13:05): Napięcie między planetami. Można je wykorzystać na romantyzm, sztukę, muzykę i współczucie. Uważaj na idealizowanie ludzi i rozczarowania.","sourceText":{"holiday":"","namedays":"Irmy, Józefa","title":"Klucze żurawi","subtitle":"krzyk na niebie","story":"We wrześniu żurawie zbierają się w stada i odlatują na południe. Ich klucze na niebie i trąbiący krzyk słychać z daleka. Żuraw był symbolem czujności, długiego życia i wierności. Mówiono, że kiedy żurawie lecą wysoko, będzie piękna jesień, a kiedy nisko, zima przyjdzie wcześnie.","practice":"• Wypatruj na niebie klucza ptaków.\n• Posłuchaj ich krzyku i spróbuj rozpoznać, czy to żurawie, czy gęsi.\n• Pomyśl, dokąd ty chcesz polecieć.","extraTitle":"Ciekawostka","extra":"Żurawie lecą w kluczu, bo każdy ptak wykorzystuje wiry powietrza od ptaka przed sobą i oszczędza siły.","whisper":"Kto leci razem z innymi, leci dalej.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":323}],["2027-09-19","finances","☽ w Baranie do 00:05, potem w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":87.0,"moonAndBiodynamic":"☽ w Baranie do 00:05, potem w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Do 00:05 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Januarego, Konstancji","title":"Baba Jaga","subtitle":"ta, która mieszka na skraju","story":"Baba Jaga mieszka w chacie na kurzej stopce, na skraju lasu, między światem żywych i umarłych. Lata w moździerzu, zamiata ślady miotłą. Jest straszna i mądra. Bohaterów, którzy do niej przychodzą, może zjeść albo im pomóc, zależnie od tego, czy są uprzejmi i odważni. To ona daje próbę i wiedzę. Patronka tego kalendarza.","practice":"• Pomyśl, w jakim miejscu swojego życia stoisz na skraju.\n• Zapisz pytanie, które zadałabyś Babie Jadze.\n• Bądź dziś uprzejma, nawet dla tych, którzy straszą.","extraTitle":"Pytanie na niedzielę","extra":"Czego chcę się dowiedzieć, nawet jeśli odpowiedź mnie przestraszy?","whisper":"Do Baby Jagi chodzi się nie po pocieszenie, ale po prawdę.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":324}],["2027-09-20","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":80.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Pannie · ☿ w Wadze · ♀ w Wadze · ♂ w Skorpionie. Pytanie tygodnia: Co możesz usprawnić w codzienności?\n♂✶♃ Mars sekstyl Jowisz (02:28): Dobry dzień na odważne działanie, sport i duże projekty.","sourceText":{"holiday":"","namedays":"Filipiny, Eustachego","title":"Kalina","subtitle":"czerwone korale","story":"Kalina koralowa ma czerwone, błyszczące owoce, które wiszą do zimy. Była drzewem dziewczęcym i symbolem urody, miłości i tęsknoty. Śpiewano o niej w pieśniach weselnych i żałobnych. Kora kaliny łagodziła bóle miesiączkowe i skurcze. Owoce są gorzkie, ale po przemrożeniu i ugotowaniu nadają się na konfitury.","practice":"• Znajdź krzew kaliny w parku albo na skraju lasu.\n• Przyjrzyj się owocom pod światło.\n• Zaśpiewaj albo przypomnij sobie piosenkę o kalinie.","extraTitle":"Ciekawostka","extra":"Kalina jest symbolem narodowym Ukrainy, a jej czerwień pojawia się na tradycyjnych haftach.","whisper":"Uroda, która przetrwa zimę, jest najpiękniejsza.","caution":"Surowe owoce kaliny są lekko trujące. Jedz tylko gotowane.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":325}],["2027-09-21","conversation","☽ w Byku do 07:05, potem w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":71.0,"moonAndBiodynamic":"☽ w Byku do 07:05, potem w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Do 07:05 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 03:13 do 07:05: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Jonasza, Mateusza","title":"Zupa dyniowa","subtitle":"pomarańczowa jesień","story":"Dynia przyszła do Polski z Ameryki, ale szybko się zadomowiła. Na wsi gotowano z niej zupy mleczne z zacierkami, a dziś zupę krem z imbirem i czosnkiem. Dynia przechowuje się do wiosny w chłodnym miejscu. Jej pestki, suszone i prażone, były lekiem na robaki i przysmakiem na jesienne wieczory.","practice":"• Upiecz pokrojoną dynię z cebulą i czosnkiem w 200 °C przez 30 minut.\n• Zmiksuj z bulionem, dodaj starty imbir i gałkę muszkatołową.\n• Podawaj z prażonymi pestkami i śmietaną.","extraTitle":"Ciekawostka","extra":"Pestki dyni zawierają kukurbitynę, która ma działanie przeciwpasożytnicze.","whisper":"Pomarańczowe jedzenie w szare dni działa jak słońce.","caution":"","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":326}],["2027-09-22","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀△♅ Wenus trygon Uran (02:29): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku.","sourceText":{"holiday":"","namedays":"Tomasza, Maurycego","title":"Wieniec z jarzębiny","subtitle":"przed równonocą","story":"Jutro rano równonoc jesienna. Dzień i noc znów będą równe, ale tym razem ciemność zacznie wygrywać. To czas, by przygotować dom na jesień. Uwij wieniec z jarzębiny, liści i kłosów i powieś go na drzwiach. Dawniej wieńce dożynkowe wieszano w kościele albo w izbie aż do następnych żniw.","practice":"• Zbierz gałązki jarzębiny, kolorowe liście i kłosy.\n• Uwij z nich wieniec na drucie albo wiklinie.\n• Powieś go na drzwiach wejściowych.","extraTitle":"Ciekawostka","extra":"Wieniec to symbol koła roku: bez początku i końca.","whisper":"Koło roku się obraca. Ozdób drzwi, przez które wejdzie jesień.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":327}],["2027-09-23","conversation","☽ w Bliźniętach, od 12:02 w Raku","III kwadra",false,{"phase":"III kwadra o 12:20","nextPhase":"nów za 7 dni","illumination":50.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 12:02 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 12:02 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 05:35 do 12:02: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉ Słońce wchodzi w Wagę (08:01): Na miesiąc cały świat nabiera barw znaku Wagi: czas relacji, piękna, kompromisu i umów. Rada: szukaj porozumienia i piękna.\n☿☍♄ Merkury opozycja Saturn (12:14): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.","sourceText":{"holiday":"równonoc jesienna, 08:01","namedays":"Bogusława, Tekli","title":"Równonoc jesienna","subtitle":"ciemność zaczyna wygrywać","story":"Dziś o 8:01 równonoc jesienna. Dzień i noc są równe. Od jutra noce będą dłuższe aż do grudnia. Dziś też ostatnia kwadra: Księżyc i Słońce mówią to samo. Czas, by zwolnić, zebrać plony i przygotować się na ciemniejszą połowę roku. Dawniej po równonocy palono ognie i dziękowano za zbiory.","practice":"• Wyjdź o zachodzie Słońca i popatrz, gdzie zachodzi.\n• Zapisz, co chcesz zabrać ze sobą w ciemną połowę roku.\n• Zapal wieczorem świecę.","extraTitle":"Ciekawostka","extra":"Od teraz każdego dnia będzie około 3–4 minut światła mniej.","whisper":"Ciemność nie przychodzi nagle. Przychodzi po trochu, byś zdążyła zapalić świecę.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":328}],["2027-09-24","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":39.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Gerarda, Teodora","title":"Kasztan w kieszeni","subtitle":"na reumatyzm i szczęście","story":"Jesienią dzieci zbierają kasztany. Ludowa wiara mówi, że kasztan noszony w kieszeni chroni przed reumatyzmem, bólem stawów i złym. Trzeba go nosić tak długo, aż zrobi się twardy i pomarszczony. Nie ma na to dowodów, ale kasztan w dłoni to dobre przypomnienie o jesieni i o tym, że warto się poruszać.","practice":"• Zbierz kasztan i włóż do kieszeni płaszcza.\n• Obracaj go w palcach, gdy jesteś zdenerwowana.\n• Zrób z dziećmi kasztanowe ludziki.","extraTitle":"Ciekawostka","extra":"Kasztany jadalne to inne drzewo, kasztan jadalny. Kasztany z kasztanowca są niejadalne.","whisper":"Gładki kamień albo kasztan w dłoni uspokaja bardziej niż wiele słów.","caution":"Kasztanów z kasztanowca nie jedz.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":329}],["2027-09-25","home","☽ w Raku, od 15:00 we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":27.0,"moonAndBiodynamic":"☽ w Raku, od 15:00 we Lwie · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 15:00 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 12:03 do 15:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Aurelii, Władysława","title":"Kolorowe liście","subtitle":"dlaczego żółkną","story":"Pod koniec września liście zaczynają się przebarwiać. Klony czerwienieją, brzozy żółkną, dęby brązowieją. Drzewa przestają produkować zielony chlorofil, a wtedy widać barwniki, które były w liściach przez całe lato: żółte i pomarańczowe. Czerwienie powstają jesienią z cukrów. Drzewo przygotowuje się do snu.","practice":"• Zbierz kilka kolorowych liści.\n• Ułóż je od zielonego do brązowego.\n• Pomyśl, jakie twoje kolory pojawiają się, gdy odpoczywasz.","extraTitle":"Ciekawostka","extra":"Żółte barwniki, karotenoidy, są w liściach przez całe lato. Ukrywa je zielony chlorofil.","whisper":"Niektóre kolory pokazujesz dopiero wtedy, gdy przestajesz się spieszyć.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":330}],["2027-09-26","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":18.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Justyny, Cypriana","title":"Kikimora","subtitle":"ta z bagien i za pieca","story":"Kikimora była demonem kobiecym. Mieszkała na bagnach albo za piecem w chacie. Nocą przędła, płakała, tłukła garnki i straszyła dzieci. Kikimora z domu mogła być dobra, jeśli gospodyni była porządna, ale złośliwa, jeśli w domu panował bałagan. Na ochronę wieszano kamień z dziurą albo szyjkę rozbitego dzbana.","practice":"• Uporządkuj jedno miejsce w domu, które cię męczy.\n• Pomyśl, co cię nocą nie pozwala spać.\n• Zapisz to i odłóż na rano.","extraTitle":"Pytanie na niedzielę","extra":"Jaki bałagan w moim domu albo w głowie budzi mnie w nocy?","whisper":"Kikimory żyją w kątach, do których nie zaglądasz.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":331}],["2027-09-27","creative","☽ we Lwie, od 16:28 w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":10.0,"moonAndBiodynamic":"☽ we Lwie, od 16:28 w Pannie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 16:28 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 09:55 do 16:28: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wadze · ☿ w Skorpionie · ♀ w Wadze · ♂ w Skorpionie. Pytanie tygodnia: Gdzie szukasz równowagi?\n☿ Merkury wchodzi w Skorpiona (11:09): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej. Uważaj na zazdrość i podejrzliwość.","sourceText":{"holiday":"","namedays":"Damiana, Amadeusza","title":"Wrzos","subtitle":"kwiat jesieni","story":"Wrzos kwitnie do października. Jego drobne, fioletowe kwiaty były ziołem na nerki, pęcherz i bezsenność. Na wrzosowiskach zbierano go na miotły, posłania i do barwienia wełny. Wrzos jest symbolem samotności i wytrwałości: rośnie tam, gdzie inne rośliny nie chcą. Dziś jest kwiatem cmentarzy, bo kwitnie przed Wszystkimi Świętymi.","practice":"• Kup doniczkę wrzosu na balkon albo na grób bliskich.\n• Zbierz kilka gałązek do suszenia.\n• Pomyśl o miejscu, gdzie rośniesz, choć nikt inny nie chce.","extraTitle":"Ciekawostka","extra":"W Szkocji biały wrzos przynosi szczęście i jest wpinany do bukietów ślubnych.","whisper":"Wytrwałość ma fioletowy kolor i pachnie miodem.","caution":"Nie stosuj długo przy chorobach nerek.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":332}],["2027-09-28","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":4.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 21:48 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉△♇ Słońce trygon Pluton (06:33): Dobry dzień na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna.\n☉☍♆ Słońce naprzeciw Neptuna (16:18): Zmęczenie i rozczarowania, gdy złudzenia zderzają się z rzeczywistością. Rada: odpocznij, nie wierz obietnicom bez pokrycia.","sourceText":{"holiday":"","namedays":"Luby, Wacława","title":"Kiszenie kapusty","subtitle":"beczka na całą zimę","story":"Jesienią kisiło się kapustę w beczkach. Szatkowano ją, solono, ubijano nogami albo drewnianym tłuczkiem, aż puściła sok. Dodawano marchew, kminek, jabłka, żurawinę. Kiszona kapusta była podstawą zimowej diety i chroniła przed szkorbutem. Mówiono, że kisi się ją przy przybywającym Księżycu, by była chrupka.","practice":"• Poszatkuj 5 kg kapusty, wymieszaj z 100 g soli, marchwią i kminkiem.\n• Ugniataj, aż puści sok, ubijaj w kamionkowym garnku.\n• Przyciśnij talerzem z kamieniem, odstaw na 2 tygodnie w temperaturze pokojowej.","extraTitle":"Ciekawostka","extra":"Kapitan Cook zabierał w rejsy beczki kiszonej kapusty, by jego marynarze nie chorowali na szkorbut.","whisper":"Kwaśna siła zimy zaczyna się jesienią w beczce.","caution":"Dużo soli. Ostrożnie przy nadciśnieniu.","bibliography":"Kiszonki i fermentacja – przepisy, IZPiTN 2026","bookKey":""},"sourceRow":333}],["2027-09-29","organize","☽ w Pannie, od 17:30 w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Pannie, od 17:30 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 17:30 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu do 17:30: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Michała Archanioła","namedays":"Michała, Michaliny","title":"Święty Michał","subtitle":"ważenie dusz","story":"Święty Michał Archanioł pokonał smoka i waży dusze na sądzie. W jego dzień kończył się czas pasterzy: bydło zaganiano do obór, a pasterze dostawali zapłatę. Mówiono, że od świętego Michała noce są zimne i trzeba palić w piecu. Michał był też patronem walczących ze złem. Dobry dzień, by ocenić, co jest dobre w twoim życiu.","practice":"• Zrób bilans: co w twoim życiu jest dobre, a co ciężkie.\n• Postanów, z czym walczysz, a co akceptujesz.\n• Zapal wieczorem pierwszy jesienny ogień albo świecę.","extraTitle":"Ciekawostka","extra":"Michał to hebrajskie imię, które znaczy: któż jak Bóg.","whisper":"Waga nie kłamie. Ale trzeba mieć odwagę na nią spojrzeć.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":334}],["2027-09-30","relationships","☽ w Wadze","nów",false,{"phase":"nów o 04:36","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🌑 Nów w Wadze (04:36): Czas zasiewu w sprawach: związki, umowy, równowaga. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Wery, Honoriusza","title":"Strzyżenie przy Księżycu","subtitle":"włosy rosną z fazą","story":"Dziś nad ranem nów. Wierzono, że włosy obcięte przy przybywającym Księżycu rosną szybciej i gęściej, a przy ubywającym rosną wolniej, ale są mocniejsze. Obcięte włosy palono, by nie dostały się w ręce czarownicy albo by ptaki nie uwiły z nich gniazda, bo wtedy boli głowa. Włosy miały w sobie część duszy.","practice":"• Jeśli chcesz, zaplanuj strzyżenie według faz Księżyca.\n• Obcięte włosy wyrzuć od razu albo spal.\n• Zapisz intencję na nowy księżycowy miesiąc.","extraTitle":"Księżyc","extra":"nów 30 IX, 04:36 · pełnia 15 X, 15:47","whisper":"Włosy rosną cierpliwie. Ty też możesz.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":335}],["2027-10-01","relationships","☽ w Wadze, od 19:45 w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Wadze, od 19:45 w Skorpionie · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 19:45 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 12:24 do 19:45: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Danuty, Remigiusza","title":"Kurzy bożek","subtitle":"kamień z dziurą","story":"Kamień z naturalną dziurą był amuletem. Nazywano go kurzym bożkiem, bo wieszano go w kurnikach, by zmora nie męczyła kur, a kury dobrze się niosły. Przez dziurę w kamieniu można było podobno zobaczyć duchy i czarownice. Wieszano go też nad łóżkiem przeciw koszmarom. Kamień z dziurą to rzadki dar od wody.","practice":"• Na spacerze nad rzeką lub morzem poszukaj kamienia z dziurą.\n• Spójrz przez niego na świat.\n• Powieś go na sznurku tam, gdzie chcesz spokoju.","extraTitle":"Ciekawostka","extra":"Kamienie z dziurami powstają, gdy woda latami wymywa miękkie fragmenty skały.","whisper":"Ochrona, którą wyrzeźbiła woda, jest cierpliwsza niż każda inna.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":336}],["2027-10-02","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Teofila, Dionizego","title":"Jesienne mgły","subtitle":"świat w mleku","story":"W październiku rano doliny i łąki toną w mgle. Drzewa wyłaniają się z niej jak z innego świata. Mówiono, że we mgle chodzą duchy i błądzą dusze. Mgła powstaje, gdy wilgotne powietrze ochładza się w nocy. Kiedy słońce ją rozproszy, często przychodzi piękny dzień. Mgła uczy, że nie trzeba widzieć całej drogi, by iść.","practice":"• Wyjdź rano, gdy jest mgła, i przejdź się powoli.\n• Zauważ, jak brzmi świat we mgle.\n• Pomyśl o drodze, której nie widzisz do końca.","extraTitle":"Ciekawostka","extra":"Mgła to chmura, która leży przy ziemi.","whisper":"Nie musisz widzieć całej drogi. Wystarczą trzy kroki przed tobą.","caution":"Uważaj na drodze we mgle.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":337}],["2027-10-03","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 08:42 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉△♅ Słońce trygon Uran (08:10): Dobry dzień na nowości, zmianę rutyny i odważne pomysły.","sourceText":{"holiday":"","namedays":"Teresy, Heliodora","title":"Bebok","subtitle":"strach na niegrzeczne dzieci","story":"Na Śląsku dzieci straszono bebokiem. Mieszkał w ciemnych kątach, na strychu i w piwnicy, porywał dzieci, które nie słuchały albo chodziły same po zmroku. Nikt nie wiedział, jak wygląda, i to było najstraszniejsze. Bebok był sposobem dorosłych, by dzieci nie wchodziły tam, gdzie mogło być niebezpiecznie: do studni, na strych, do lasu.","practice":"• Pomyśl, jakim bebokiem straszono ciebie.\n• Zastanów się, przed czym naprawdę miał cię chronić.\n• Zapisz, jakiego „beboka” nosisz w sobie do dziś.","extraTitle":"Pytanie na niedzielę","extra":"Jakiego strachu z dzieciństwa wciąż słucham, choć już nie jestem dzieckiem?","whisper":"Najstraszniejsze potwory to te, których nigdy nie zobaczyłaś.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":338}],["2027-10-04","travel","☽ w Skorpionie do 00:55, potem w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Skorpionie do 00:55, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 00:55 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wadze · ☿ w Skorpionie · ♀ w Wadze · ♂ w Skorpionie. Pytanie tygodnia: Gdzie szukasz równowagi?\n♀☍♄ Wenus naprzeciw Saturna (14:29): Obowiązki wchodzą w drogę przyjemnościom. Dystans w relacjach. Rada: zadbaj o siebie, zamiast czekać na czułość.","sourceText":{"holiday":"","namedays":"Rozalii, Edwina","title":"Kocimiętka","subtitle":"na świętego Franciszka","story":"Dziś święty Franciszek, patron zwierząt. Zioło dnia to kocimiętka. Koty tarzają się w niej z zachwytem, bo jej zapach działa na nie jak narkotyk szczęścia. Ludzie pili napar z kocimiętki na przeziębienie, sen i niepokój. Dobry dzień, by zrobić coś dla zwierząt: dla swojego kota, psa albo dla ptaków za oknem.","practice":"• Daj swojemu kotu listek kocimiętki i popatrz.\n• Wsyp ziarno do karmnika.\n• Podziękuj zwierzęciu, które jest w twoim życiu.","extraTitle":"Ciekawostka","extra":"Na kocimiętkę reaguje około dwie trzecie kotów. Skłonność jest dziedziczna.","whisper":"Zwierzęta uczą radości bez powodu.","caution":"Nie w ciąży.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":339}],["2027-10-05","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":29.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Igora, Flawii","title":"Pieczone jabłka z miodem","subtitle":"zapach jesiennego wieczoru","story":"Pieczone jabłka to najprostszy deser jesieni. Wydrążone jabłko wypełnia się miodem, orzechami, rodzynkami i cynamonem, a potem piecze, aż skórka pęknie, a środek zrobi się miękki jak mus. Dawniej pieczono je w popiele pieca. Zapach pieczonych jabłek to jeden z najprzyjemniejszych zapachów świata.","practice":"• Wydrąż 4 kwaśne jabłka od góry.\n• Wypełnij miodem, posiekanymi orzechami i cynamonem.\n• Piecz 30 minut w 180 °C. Podawaj z jogurtem.","extraTitle":"Ciekawostka","extra":"Pieczone jabłka podawano dawniej chorym na kaszel i przeziębienie.","whisper":"Najprostsze desery pachną domem najmocniej.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":340}],["2027-10-06","work","☽ w Strzelcu do 09:59, potem w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":39.0,"moonAndBiodynamic":"☽ w Strzelcu do 09:59, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 09:59 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 05:01 do 09:59: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿□♇ Merkury kwadratura Pluton (02:31): Napięcie między planetami. Można je wykorzystać na dociekliwość, badania, terapię i szczere rozmowy. Uważaj na obsesyjne myśli i słowne manipulacje.","sourceText":{"holiday":"","namedays":"Artura, Brunona","title":"Wieczornice","subtitle":"opowieści przy świecy","story":"Jesienne i zimowe wieczory na wsi wypełniały wieczornice. Kobiety zbierały się w jednej chacie, przędły, darły pierze, a przy pracy opowiadały baśnie, legendy i plotki. Dzieci słuchały historii o duchach i czarownicach, aż bały się wyjść na podwórko. W ten sposób przekazywano wiedzę z pokolenia na pokolenie.","practice":"• Zaproś kogoś na wieczór bez ekranów.\n• Opowiedzcie sobie historie z dzieciństwa.\n• Zapisz jedną, której nie chcesz zapomnieć.","extraTitle":"Ciekawostka","extra":"Wiele baśni z kolekcji Kolberga przetrwało właśnie dzięki wieczornicom.","whisper":"Opowieść przekazana przy świecy żyje dłużej niż zapisana w książce.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":341}],["2027-10-07","work","☽ w Koziorożcu","I kwadra",false,{"phase":"I kwadra o 13:47","nextPhase":"pełnia za 8 dni","illumination":49.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury rusza wstecz w Skorpionie (16:37): Przez trzy tygodnie łatwiej o pomyłki w rozmowach, umowach, mailach i podróżach. To dobry czas na powroty: do starych projektów, ludzi i notatek. Rada: sprawdzaj dwa razy, nie podpisuj w pośpiechu, rób kopie.","sourceText":{"holiday":"","namedays":"Marii, Marka","title":"Kot się myje","subtitle":"będzie gość","story":"Gdy kot myje się łapką za uchem, wróżono gościa. Jeśli myje się w stronę drzwi, gość przyjdzie z daleka. Kot był domowym wróżbitą: kichający kot zapowiadał deszcz, kot śpiący z łapką na nosie mróz. Kot, który nie chciał wejść do domu, ostrzegał przed złym. Dziś pierwsza kwadra: czas, by kogoś zaprosić.","practice":"• Popatrz na swojego kota albo kota sąsiadów i zgadnij, co wróży.\n• Zaproś kogoś na herbatę w tym tygodniu.\n• Upiecz coś na przyjście gościa.","extraTitle":"Ciekawostka","extra":"Koty myją się często po jedzeniu i przed snem. Gość może więc przyjść, gdy ty też jesteś najedzona.","whisper":"Gość, na którego czekasz, przychodzi łatwiej, gdy go zaprosisz.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":342}],["2027-10-08","work","☽ w Koziorożcu, od 22:09 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":59.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 22:09 w Wodniku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 22:09 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 12:21 do 22:09: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus wchodzi w Skorpiona (05:59): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej. Uważaj na zazdrość i podejrzliwość.","sourceText":{"holiday":"","namedays":"Pelagii, Brygidy","title":"Miotła za drzwiami","subtitle":"strażniczka progu","story":"Miotła była narzędziem i strażniczką. Postawiona za drzwiami trzonkiem w dół odstraszała czarownice i nieproszonych gości. Wierzono, że czarownica nie przejdzie przez miotłę położoną na progu. Nowa miotła w nowym domu wymiatała stare nieszczęścia. Ale nie wolno było zamiatać po zmroku ani w stronę drzwi, by nie wymieść szczęścia.","practice":"• Postaw miotłę za drzwiami trzonkiem w dół.\n• Zamiataj dziś w stronę środka domu.\n• Pomyśl, kogo nie chcesz wpuszczać do swojego życia.","extraTitle":"Ciekawostka","extra":"Czarownice latały na miotłach, bo miotła była symbolem kobiecej pracy i domowej mocy.","whisper":"Ta, która zamiata dom, wie, co do niego wchodzi.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":343}],["2027-10-09","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":68.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿□♇ Merkury kwadratura Pluton (07:26): Napięcie między planetami. Można je wykorzystać na dociekliwość, badania, terapię i szczere rozmowy. Uważaj na obsesyjne myśli i słowne manipulacje.","sourceText":{"holiday":"","namedays":"Arnolda, Dionizego","title":"Opieńki","subtitle":"grzyby na pniach","story":"W październiku na starych pniach i korzeniach pojawiają się opieńki. Rosną kępami, miodowo-brązowe, czasem setkami. Grzybiarze zbierają je do marynat i sosów. Ale opieńka jest też pasożytem, który zabija drzewa. Jej grzybnia w nocy świeci słabym światłem, co mogło dawać początek legendom o świecącym drewnie.","practice":"• Na spacerze poszukaj kęp grzybów na pniach.\n• Przyjrzyj się, czy rosną na żywym drzewie, czy na martwym.\n• Nie zbieraj, jeśli nie jesteś pewna.","extraTitle":"Ciekawostka","extra":"Największy znany organizm na świecie to grzybnia opieńki w Oregonie, zajmująca prawie 10 km².","whisper":"Najwięksi mieszkańcy lasu często są niewidoczni.","caution":"Opieńki zawsze gotuj. Na surowo są toksyczne. Łatwo pomylić je z trującymi grzybami.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":344}],["2027-10-10","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":77.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Pauliny, Franciszka","title":"Rokita","subtitle":"diabeł od kontraktów","story":"Rokita był polskim diabłem od umów i podpisów krwią. Przychodził do zdesperowanych i oferował bogactwo, miłość albo szczęście w zamian za duszę. W legendzie o panu Twardowskim diabeł podpisuje kontrakt z czarnoksiężnikiem, który okazuje się sprytniejszy. Diabły w polskich opowieściach często przegrywają przez własną chciwość.","practice":"• Pomyśl o umowie, którą zawarłaś, a która cię męczy.\n• Przeczytaj ją jeszcze raz uważnie.\n• Zastanów się, czy możesz ją renegocjować.","extraTitle":"Pytanie na niedzielę","extra":"Jaką umowę zawarłam z kimś albo z samą sobą, a teraz za nią płacę?","whisper":"Diabeł zawsze zostawia drobny druk. Przeczytaj go.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":345}],["2027-10-11","rest","☽ w Wodniku do 11:01, potem w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":85.0,"moonAndBiodynamic":"☽ w Wodniku do 11:01, potem w Rybach · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Do 11:01 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 04:03 do 11:01: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wadze · ☿ w Skorpionie · ♀ w Skorpionie · ♂ w Skorpionie. Pytanie tygodnia: Gdzie szukasz równowagi?\n☿☌♀ Merkury koniunkcja Wenus (11:32): Dobry dzień na miłe rozmowy, komplementy, negocjacje i pisanie. Uważaj tylko na pustą uprzejmość i niezałatwione sprawy.","sourceText":{"holiday":"","namedays":"Emila, Aldony","title":"Łopian","subtitle":"korzeń, który pije ziemię","story":"Korzeń łopianu, zwanego też łopuchem, zbiera się jesienią w pierwszym roku wzrostu, gdy jest najgrubszy. W medycynie ludowej oczyszczał krew, leczył skórę i włosy. Olej łopianowy na łysienie zna każda babcia. Rzepy łopianu przyczepiają się do sierści zwierząt i ubrań. To z nich wymyślono rzep na ubrania.","practice":"• Rozpoznaj łopian po wielkich liściach i rzepach.\n• Przyczep rzep do swetra i obejrzyj, jak trzyma.\n• Wypróbuj olej łopianowy na skórę głowy.","extraTitle":"Ciekawostka","extra":"Szwajcar George de Mestral wymyślił rzep na ubrania po spacerze z psem, oglądając rzepy łopianu pod mikroskopem.","whisper":"Najlepsze pomysły przyczepiają się do ciebie same.","caution":"Nie w ciąży. Ostrożnie przy cukrzycy.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":346}],["2027-10-12","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♀□♇ Wenus kwadratura Pluton (01:52): Napięcie między planetami. Można je wykorzystać na głębokie uczucia, intymność i odnowę w relacjach. Uważaj na zazdrość i zaborczość.","sourceText":{"holiday":"","namedays":"Eustachego, Maksymiliana","title":"Bigos","subtitle":"danie, które dojrzewa","story":"Bigos to polska potrawa z kapusty i mięsa, gotowana długo i odgrzewana wiele razy. Każde odgrzanie czyni go lepszym. Do kapusty kiszonej i świeżej dodaje się mięsa, kiełbasę, grzyby, śliwki suszone, wino, ziele angielskie i liść laurowy. Mickiewicz opisał go w Panu Tadeuszu. Bigos to cierpliwość zamknięta w garnku.","practice":"• Ugotuj kiszoną i świeżą kapustę osobno, odciśnij.\n• Dodaj podsmażone mięso, kiełbasę, suszone grzyby i śliwki.\n• Duś na małym ogniu 2–3 godziny. Odgrzewaj przez 3 dni.","extraTitle":"Ciekawostka","extra":"Bigos był daniem myśliwskim. Zabierano go na polowania, bo nie psuł się i grzał w zimnie.","whisper":"Niektóre rzeczy są najlepsze dopiero po kilku dniach.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":347}],["2027-10-13","rest","☽ w Rybach, od 22:09 w Baranie","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Rybach, od 22:09 w Baranie · dzień liścia · ☿ retro","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 22:09 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 19:04 do 22:09: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Gerarda, Edwarda","title":"Mieszanka na zimę","subtitle":"własna herbata","story":"Jesienią zielarki składały mieszanki ziół na zimę. Z suszonych zapasów lata robiły herbatki na kaszel, na sen, na brzuch, na smutek. Każda miała swoje przepisy, przekazywane z matki na córkę. Skomponowanie własnej mieszanki to rytuał uważności: wąchasz, dotykasz, wybierasz.","practice":"• Rozłóż na stole suszone zioła, które masz.\n• Wymieszaj trzy, które lubisz: na przykład lipę, miętę i melisę.\n• Przesyp do słoika i nazwij swoją mieszankę.","extraTitle":"Ciekawostka","extra":"Mieszanki ziołowe najlepiej mają 3–5 składników. Więcej rozmywa ich działanie.","whisper":"Twoja mieszanka ma smak twojego lata.","caution":"Sprawdź przeciwwskazania każdego zioła.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":348}],["2027-10-14","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":99.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ☿ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Alana, Kaliksta","title":"Róg stołu","subtitle":"siedem lat panną","story":"Dziewczynie nie wolno było siadać na rogu stołu, bo nie wyjdzie za mąż przez siedem lat. Chłopak na rogu miał mieć złą teściową. Róg stołu był miejscem granicznym, tak jak próg. Stół był ołtarzem domu, a jego środek miejscem dla gospodarza i chleba. Dziś to przesąd, z którego się śmiejemy, ale rogu wciąż unikamy.","practice":"• Zauważ, gdzie siadasz przy stole.\n• Zaproponuj miejsce na rogu komuś, kto lubi ryzyko.\n• Uśmiechnij się do przesądu.","extraTitle":"Ciekawostka","extra":"Przesąd o rogu stołu jest znany w Polsce, Rosji, na Ukrainie i Litwie.","whisper":"Czasem lepiej usiąść na rogu i patrzeć na wszystkich, niż siedzieć w środku i nie widzieć nikogo.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":349}],["2027-10-15","start","☽ w Baranie","pełnia",false,{"phase":"pełnia o 15:47","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu · ☿ retro","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 20:37 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🌕 Pełnia w Baranie (15:46): Kulminacja w sprawach: odwaga, pierwszy krok, własna siła. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Teresy, Jadwigi","title":"Sól w czterech kątach","subtitle":"pełnia październikowa","story":"Dziś po południu pełnia. Dawniej, gdy w domu było niespokojnie, sypano szczyptę soli w każdy z czterech kątów izby. Sól oczyszczała dom ze złych duchów, kłótni i chorób. Po trzech dniach zamiatano ją i wynoszono za próg. Pełnia to dobry czas na oczyszczanie, bo wszystko jest wtedy widoczne.","practice":"• Wsyp szczyptę soli w cztery kąty pokoju, w którym śpisz.\n• Zostaw na trzy dni.\n• Zamieć i wynieś za próg.","extraTitle":"Księżyc","extra":"pełnia 15 X, 15:47 · III kwadra 22 X, 19:29","whisper":"Cztery kąty domu to cztery strony świata. Każdy zasługuje na ochronę.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":350}],["2027-10-16","finances","☽ w Baranie do 06:36, potem w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Baranie do 06:36, potem w Byku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na finanse","energy":"Do 06:36 Księżyc jest w Baranie, potem w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♂ Mars wchodzi w Strzelca (01:13): Na kilka tygodni energia i działanie płyną w rytmie podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się. Uważaj na przesadę i obietnice bez pokrycia.\n☿ Merkury cofa się do Wagi (09:36): Ruchem wstecznym Merkury wraca do znaku Wagi i każe dokończyć stare sprawy. Rada: wróć do rozpoczętych rozmów, zanim zaczniesz nowe.\n♆✶♇ Neptun i Pluton we współpracy (16:39): Długi, pokoleniowy układ, który teraz jest dokładny. Duchowość i głęboka przemiana idą w parze. Rada: pomyśl, w co wierzysz naprawdę i co chcesz zmienić na lata.","sourceText":{"holiday":"","namedays":"Gawła, Florentyny","title":"Wiewiórki","subtitle":"zapasy w ziemi","story":"W październiku wiewiórki zakopują orzechy i żołędzie na zimę. Robią setki kryjówek, a wielu z nich nigdy nie znajdą. Z zapomnianych zapasów wyrastają nowe drzewa. Wiewiórka była w wierzeniach posłanką między światami. W mitologii nordyckiej biegała po drzewie świata Yggdrasil i przenosiła wiadomości.","practice":"• Popatrz na wiewiórki w parku.\n• Zobacz, gdzie chowają zapasy.\n• Pomyśl, jakie „zapomniane zapasy” wyrosły w twoim życiu.","extraTitle":"Ciekawostka","extra":"Wiewiórki pamiętają większość swoich kryjówek, ale nie wszystkie. Tak sadzą lasy.","whisper":"To, co zapomniałaś zakopać, może kiedyś wyrosnąć w drzewo.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":351}],["2027-10-17","finances","☽ w Byku","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia · ☿ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 14:36 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Małgorzaty, Wiktora","title":"Dziwożona","subtitle":"dzika kobieta z gór","story":"W Tatrach i na Podhalu żyły dziwożony. Dzikie kobiety o długich włosach i wielkich piersiach, które zarzucały przez ramię. Mieszkały w jaskiniach i nad potokami. Kradły dzieci i podmieniały je na swoje, a młode kobiety wciągały do swego dzikiego świata. Dziwożona to też obraz kobiety, która nie dała się ujarzmić.","practice":"• Pomyśl o dzikiej części siebie.\n• Zastanów się, czy ją chowasz, czy jej słuchasz.\n• Zrób dziś coś nieokiełznanego, ale bezpiecznego.","extraTitle":"Pytanie na niedzielę","extra":"Gdzie w sobie mam dziwożonę, której nie pozwalam wyjść?","whisper":"Każda kobieta ma w sobie trochę dzikości. Mądrość to wiedzieć, kiedy ją wypuścić.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":352}],["2027-10-18","finances","☽ w Byku, od 12:46 w Bliźniętach","Księżyc ubywający",true,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":91.0,"moonAndBiodynamic":"☽ w Byku, od 12:46 w Bliźniętach · dzień korzenia · ☿ retro","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 12:46 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu do 12:46: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Wadze · ☿ w Wadze · ♀ w Skorpionie · ♂ w Strzelcu. Pytanie tygodnia: Gdzie szukasz równowagi?\n☉☍♄ Słońce naprzeciw Saturna (02:35): Ktoś stawia granice, ktoś ocenia. Może brakować energii. Rada: cierpliwość i dotrzymywanie słowa.\n♇ Pluton rusza naprzód w Wodniku (05:52): Wewnętrzna przemiana zaczyna być widoczna na zewnątrz. Rada: pozwól odejść temu, co się skończyło.","sourceText":{"holiday":"","namedays":"Juliusza, Łukasza","title":"Owoce tarniny","subtitle":"słodkie po przymrozku","story":"Pamiętasz białe krzewy tarniny z kwietnia? Teraz mają granatowe owoce z siwym nalotem. Są cierpkie i ściągające, ale po pierwszym przymrozku łagodnieją. Zbierano je na nalewki, powidła i lekarstwo na biegunkę. Dziś też święty Łukasz, patron lekarzy i malarzy. Mówiono, że od Łukasza zaczyna się prawdziwa jesień.","practice":"• Zbierz owoce tarniny po przymrozku albo zamroź je na noc.\n• Spróbuj jednego i poczuj, jak ściąga usta.\n• Zastanów się, co w tobie dojrzało dopiero po chłodzie.","extraTitle":"Ciekawostka","extra":"Tarnina jest przodkiem śliwy domowej, krzyżówką tarniny i ałyczy.","whisper":"Niektóre owoce słodnieją dopiero po mrozie. Niektórzy ludzie też.","caution":"Nie rozgryzaj pestek.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":353}],["2027-10-19","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":83.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉☌☿ Słońce koniunkcja Merkury (17:30): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"","namedays":"Pelagii, Piotra","title":"Placki ziemniaczane","subtitle":"po wykopkach","story":"Po wykopkach, gdy piwnice pełne były ziemniaków, na stołach pojawiały się placki. Ziemniaki starte na tarce, z cebulą, jajkiem i mąką, smażone na złoto na smalcu albo oleju. Jedzone ze śmietaną, cukrem albo gulaszem. Na wykopkach pieczono też ziemniaki w ognisku, w popiele, i jedzono gorące, osolone, z brudnymi rękami.","practice":"• Zetrzyj 1 kg ziemniaków i cebulę na drobnej tarce, odciśnij.\n• Dodaj jajko, 2 łyżki mąki, sól i pieprz.\n• Smaż na rozgrzanym tłuszczu na złoto z obu stron.","extraTitle":"Ciekawostka","extra":"Ziemniaki trafiły do Polski w XVII wieku, przywiezione podobno przez Jana III Sobieskiego spod Wiednia.","whisper":"Placki smakują najlepiej jedzone brudnymi rękami, przy ognisku.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":354}],["2027-10-20","conversation","☽ w Bliźniętach, od 17:24 w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":74.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 17:24 w Raku · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 17:24 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 11:48 do 17:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Ireny, Jana","title":"Kopiec dla jeży","subtitle":"liście nie do wyrzucenia","story":"Jesienne liście nie muszą trafiać do worków. Zgrabione w kupę w kącie ogrodu stają się schronieniem dla jeży, owadów i żab na zimę. Jeż szuka miejsca, by zapaść w sen zimowy, a sterta liści i gałęzi jest dla niego idealnym domem. Grabienie z myślą o zwierzętach to rytuał dobroci dla świata.","practice":"• Zgrab liście w jedną kupę w spokojnym kącie ogrodu.\n• Dodaj kilka gałęzi i zostaw do wiosny.\n• Nie pal liści, bo możesz spalić jeża.","extraTitle":"Ciekawostka","extra":"Jeż przesypia zimę od listopada do marca, a jego serce bije wtedy kilka razy na minutę.","whisper":"Nie wszystko, co spadło, jest śmieciem. Czasem to czyjś dom.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":355}],["2027-10-21","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":64.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia · ☿ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☿☍♄ Merkury opozycja Saturn (06:32): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.","sourceText":{"holiday":"","namedays":"Urszuli, Hilarego","title":"Ogień trzaska","subtitle":"gość w drodze","story":"Ogień w piecu mówił. Kiedy trzaskał i strzelał iskrami, zapowiadał gościa albo kłótnię. Kiedy syczał, ktoś cię obgadywał. Kiedy płomień był niebieski, w domu był duch. Kiedy ogień nie chciał się rozpalić, był to zły znak. Patrzenie w ogień było też sposobem na wróżenie przyszłości.","practice":"• Zapal świecę albo kominek i popatrz w ogień przez kilka minut.\n• Zauważ, co ci się przypomina.\n• Zapisz pierwszą myśl.","extraTitle":"Ciekawostka","extra":"Trzaskanie drewna w ogniu to pękające komórki pełne wody i żywicy.","whisper":"Ogień mówi do tych, którzy umieją w niego patrzeć.","caution":"Nie zostawiaj ognia bez nadzoru.","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":356}],["2027-10-22","home","☽ w Raku, od 21:02 we Lwie","III kwadra",false,{"phase":"III kwadra o 19:29","nextPhase":"nów za 7 dni","illumination":53.0,"moonAndBiodynamic":"☽ w Raku, od 21:02 we Lwie · dzień liścia · ☿ retro","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku, od 21:02 we Lwie. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 19:29 do 21:02: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♂△♆ Mars w harmonii z Neptunem (11:31): Działanie płynie z intuicji. Dobry dzień na taniec, jogę i pomoc innym. Rada: ruszaj się płynnie, rób coś dla kogoś.\n♂✶♇ Mars sekstyl Pluton (16:33): Dobry dzień na wielką siłę przebicia i zmierzenie się z trudnym.","sourceText":{"holiday":"","namedays":"Filipa, Korduli","title":"Ognisko domowe","subtitle":"serce, które nie gaśnie","story":"Dziś wieczorem ostatnia kwadra. Ogień w piecu był sercem domu. Rano rozdmuchiwano węgle pozostawione na noc i nigdy nie pozwalano, by ogień całkiem zgasł w zimowe dni. Na ogień nie pluto, nie rzucano śmieci, nie deptano węgli. Ogień był święty jak chleb. Dbając o ciepło domu, dbano o życie.","practice":"• Zadbaj dziś o ciepło w domu: sprawdź kaloryfery, okna, koc.\n• Zapal świecę na kolacji.\n• Pomyśl, kto jest ciepłym sercem twojego domu.","extraTitle":"Ciekawostka","extra":"Słowo ognisko oznaczało dawniej miejsce w izbie, gdzie palił się ogień, czyli serce domu.","whisper":"Dom jest ciepły nie przez kaloryfer, ale przez tych, którzy o niego dbają.","caution":"Sprawdź czujnik czadu przed sezonem grzewczym.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":357}],["2027-10-23","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":42.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu · ☿ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀✶♃ Wenus sekstyl Jowisz (06:50): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.\n☉ Słońce wchodzi w Skorpiona (17:32): Na miesiąc cały świat nabiera barw znaku Skorpiona: czas głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej.","sourceText":{"holiday":"","namedays":"Marleny, Seweryna","title":"Plejady","subtitle":"kwoka z kurczętami","story":"Jesienią wieczorem na wschodzie wschodzą Plejady, mała gromada gwiazd. Na polskiej wsi nazywano je kwoką, babami albo siedmioma siostrami. Widać gołym okiem sześć albo siedem gwiazd, zbitych jak kurczęta pod kwoką. Rolnicy patrzyli na nie, by wiedzieć, kiedy siać i kiedy przyjdzie zima.","practice":"• Po zmroku spójrz na wschód i poszukaj małej, zbitej grupy gwiazd.\n• Policz, ile widzisz.\n• Pomyśl o swoich „siostrach” i napisz do jednej.","extraTitle":"Ciekawostka","extra":"Plejady to gromada kilkuset gwiazd, odległa od Ziemi o około 440 lat świetlnych.","whisper":"Gwiazdy, które trzymają się razem, widać nawet z daleka.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":358}],["2027-10-24","creative","☽ we Lwie, od 23:53 w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":31.0,"moonAndBiodynamic":"☽ we Lwie, od 23:53 w Pannie · dzień owocu · ☿ retro","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie, od 23:53 w Pannie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 13:36 do 23:53: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Rafała, Marcina","title":"Rozstaje","subtitle":"gdzie spotykają się drogi i duchy","story":"Rozstaje dróg były miejscem niebezpiecznym. Tam czaiły się diabły, tam błąkały się dusze samobójców, tam czarownice zbierały ziemię do czarów. Na rozstajach stawiano krzyże i kapliczki, by chroniły podróżnych. Tam też zostawiano przedmioty po chorych, by choroba przeszła na kogoś, kto je podniesie. Rozstaje to miejsce wyboru.","practice":"• Gdy dojdziesz dziś do skrzyżowania, zatrzymaj się na chwilę.\n• Pomyśl o wyborze, który stoi przed tobą.\n• Nie podnoś rzeczy leżących na rozstajach.","extraTitle":"Pytanie na niedzielę","extra":"Na jakich rozstajach stoję i co mnie tam trzyma?","whisper":"Rozstaje nie są złe. Złe jest stanie na nich zbyt długo.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":359}],["2027-10-25","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":21.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ☿ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Wadze · ♀ w Skorpionie · ♂ w Strzelcu. Pytanie tygodnia: Co jest gotowe do przemiany?","sourceText":{"holiday":"","namedays":"Darii, Wilhelminy","title":"Żywokost","subtitle":"kość, która się zrasta","story":"Żywokost rośnie nad wodą, z dużymi, szorstkimi liśćmi i fioletowymi dzwonkami. Jego korzeń, zbierany jesienią, był najważniejszym ludowym lekiem na złamania, stłuczenia i bóle stawów. Okłady z żywokostu przykładano na kości, by szybciej się zrastały. Stąd jego nazwa: żywa kość.","practice":"• Rozpoznaj żywokost po szorstkich liściach i fioletowych kwiatach.\n• Kup maść z żywokostu na stłuczenia.\n• Pomyśl, co w tobie potrzebuje się zrosnąć.","extraTitle":"Ciekawostka","extra":"Łacińska nazwa Symphytum pochodzi od greckiego symphyo, czyli zrastać się.","whisper":"To, co złamane, może się zrosnąć. Trzeba tylko czasu i dobrego okładu.","caution":"Żywokost zawiera alkaloidy szkodliwe dla wątroby. Tylko zewnętrznie, na nieuszkodzoną skórę, krótko.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":360}],["2027-10-26","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":13.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia · ☿ retro","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 14:13 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Lucjana, Ewarysta","title":"Piernik staropolski","subtitle":"ciasto, które dojrzewa do świąt","story":"Piernik staropolski robi się na długo przed świętami. Ciasto z miodu, mąki żytniej, jajek i przypraw leżakuje w chłodnym miejscu przez kilka tygodni, czasem do dwóch miesięcy. Dopiero wtedy się je piecze. W Toruniu pierniki piekło się od średniowiecza. Mówiono, że dobry piernik musi dojrzewać jak wino.","practice":"• Zagotuj 500 g miodu z 250 g masła i cukrem, ostudź.\n• Dodaj 1 kg mąki, 3 jajka, sodę i przyprawy do piernika, wyrób ciasto.\n• Włóż do kamionkowego garnka, przykryj płótnem i odstaw w chłodne miejsce do grudnia.","extraTitle":"Ciekawostka","extra":"Przyprawa do piernika to cynamon, goździki, imbir, gałka muszkatołowa, kardamon, pieprz i anyż.","whisper":"Najlepsze rzeczy przygotowuje się długo przed świętem.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":361}],["2027-10-27","relationships","☽ w Pannie do 02:21, potem w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Pannie do 02:21, potem w Wadze · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 02:21 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Iwony, Sabiny","title":"Sprzątanie grobów","subtitle":"przed Wszystkimi Świętymi","story":"Przed Wszystkimi Świętymi rodziny idą na cmentarze, by posprzątać groby bliskich. Myją płyty, wyrywają chwasty, zmieniają kwiaty, stawiają nowe znicze. To nie tylko porządek. To rozmowa ze zmarłymi i z samą sobą. Dawniej mówiono, że w te dni dusze wracają, więc trzeba przygotować dla nich miejsce.","practice":"• Jeśli możesz, idź na cmentarz i posprzątaj grób bliskiej osoby.\n• Przynieś wrzos albo chryzantemę.\n• Powiedz zmarłemu coś, czego nie zdążyłaś powiedzieć.","extraTitle":"Ciekawostka","extra":"Zwyczaj palenia zniczy na grobach wywodzi się z dawnych ognisk, które palono, by ogrzać dusze.","whisper":"Kto sprząta groby, ten pamięta. Kto pamięta, ten kocha.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":362}],["2027-10-28","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":2.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu · ☿ retro","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 18:19 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. Merkury jest retro: sprawdzaj wiadomości dwa razy. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉□♇ Słońce kwadratura Pluton (12:26): Napięcie między planetami. Można je wykorzystać na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna. Uważaj na walkę o władzę i kontrolowanie innych.\n☿ Merkury rusza naprzód w Wadze (16:10): Komunikacja się odblokowuje, choć przez kilka dni sprawy jeszcze się dopinają. Rada: wyślij to, co czekało, ale daj sobie dwa, trzy dni zapasu.\n♂☍♅ Mars naprzeciw Urana (20:06): Napięcie wybucha nagle. Inni zaskakują. Uwaga: oddychaj, zanim zareagujesz.","sourceText":{"holiday":"św. Szymona i Judy","namedays":"Szymona, Tadeusza","title":"Szymon i Juda","subtitle":"pierwszy śnieg w drodze","story":"Na Szymona i Judę wróżono pogodę na zimę. Mówiono, że od tego dnia zima jest już w drodze, a pierwszy śnieg nie każe na siebie długo czekać. Jeśli tego dnia było pogodnie, zima miała być łagodna. Juda Tadeusz jest patronem spraw beznadziejnych. Dobry dzień, by nie tracić nadziei.","practice":"• Spójrz w niebo i zapisz, jaka jest pogoda.\n• Pomyśl o sprawie, która wydaje się beznadziejna.\n• Zrób w niej jeden mały krok.","extraTitle":"Ciekawostka","extra":"Juda Tadeusz to inny apostoł niż Judasz Iskariota. Dawniej mylono ich i dlatego mało kto modlił się do Judy, aż stał się patronem spraw ostatnich.","whisper":"Nie ma spraw beznadziejnych. Są tylko takie, które czekają na swój czas.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":363}],["2027-10-29","honesty","☽ w Wadze do 05:22, potem w Skorpionie","nów",false,{"phase":"nów o 15:36","nextPhase":"pełnia za 16 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Wadze do 05:22, potem w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Do 05:22 Księżyc jest w Wadze, potem w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🌑 Nów w Skorpionie (15:36): Czas zasiewu w sprawach: przemiana, wspólne pieniądze, bliskość. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"","namedays":"Euzebii, Wioletty","title":"Świeca w oknie","subtitle":"dla dusz w drodze","story":"Dziś po południu nów. Przed Dziadami w oknach stawiano zapalone świece, by dusze zmarłych trafiły do domu. Zostawiano dla nich jedzenie na stole i nie zamykano drzwi na noc. Nie wolno było wylewać wody przez okno ani prząść, by nie skaleczyć wracających dusz. Świeca w oknie to zaproszenie dla tych, którzy odeszli.","practice":"• Postaw na parapecie świecę albo lampion.\n• Zapal ją wieczorem.\n• Wypowiedz imiona tych, za którymi tęsknisz.","extraTitle":"Księżyc","extra":"nów 29 X, 15:36 · pełnia 14 XI, 04:26","whisper":"Światło w oknie mówi: pamiętam, wracaj, jest dla ciebie miejsce.","caution":"Świeca tylko pod nadzorem, z dala od firanek.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":364}],["2027-10-30","honesty","☽ w Skorpionie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 15 dni","illumination":1.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Zenobii, Przemysława","title":"Nagie drzewa","subtitle":"koniec października","story":"Pod koniec października drzewa tracą ostatnie liście. Las staje się przejrzysty, widać gniazda, które latem były ukryte. Ziemia pokrywa się szeleszczącym dywanem. Drzewa nie umierają. Odpoczywają i oszczędzają siły. W ich pąkach już czekają liście na przyszłą wiosnę. To lekcja odpuszczania.","practice":"• Na spacerze zobacz, ile gniazd widać na nagich drzewach.\n• Poszukaj pąków na gałązce.\n• Pomyśl, co ty możesz zrzucić, by przetrwać zimę.","extraTitle":"Ciekawostka","extra":"Pąki z przyszłorocznymi liśćmi tworzą się na drzewach już latem.","whisper":"Drzewo, które zrzuca liście, nie przegrywa. Oszczędza siły na wiosnę.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":365}],["2027-10-31","travel","☽ w Skorpionie do 09:24, potem w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Skorpionie do 09:24, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 09:24 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 07:00 do 09:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"wigilia Wszystkich Świętych · zmiana czasu na zimowy","namedays":"Urbana, Saturnina","title":"Wigilia Wszystkich Świętych","subtitle":"noc, kiedy zasłona jest cienka","story":"Dziś wieczór przed Wszystkimi Świętymi, na Zachodzie Halloween. Dawni Słowianie mieli swoje dziady, święto przodków, kiedy zmarli wracali do domów. Celtowie mieli Samhain. Wszędzie wierzono, że tej nocy zasłona między światami jest najcieńsza. Dziś też zmiana czasu na zimowy: noc jest o godzinę dłuższa.","practice":"• Przestaw zegarki o godzinę do tyłu.\n• Zapal świecę i wypowiedz imiona przodków.\n• Zjedz kolację w ciszy, z jednym pustym miejscem przy stole.","extraTitle":"Pytanie na niedzielę","extra":"Co chciałabym powiedzieć tym, którzy odeszli, gdyby mogli mnie dziś usłyszeć?","whisper":"Zmarli nie potrzebują wiele. Wystarczy, że ktoś wypowie ich imię.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":366}],["2027-11-01","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":8.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Wadze · ♀ w Strzelcu · ♂ w Strzelcu. Pytanie tygodnia: Co jest gotowe do przemiany?\n♀ Wenus wchodzi w Strzelca (08:34): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się. Uważaj na przesadę i obietnice bez pokrycia.","sourceText":{"holiday":"Wszystkich Świętych","namedays":"Juliana, Łukasza","title":"Wszyscy Święci","subtitle":"litania imion","story":"Dziś cmentarze świecą tysiącami zniczy. Wszyscy Święci to nie tylko ci z ołtarzy, ale wszyscy, którzy żyli dobrze i odeszli. Twoja prababka, sąsiad, nauczycielka, która w ciebie uwierzyła. Dawniej przy grobach odmawiano wypominki, czyli czytano na głos imiona zmarłych. Imię wypowiedziane na głos sprawia, że ktoś znowu jest obecny.","practice":"• Zapal znicz na grobie albo w oknie.\n• Wypowiedz na głos imiona swoich zmarłych, jedno po drugim.\n• Opowiedz komuś historię jednego z nich.","extraTitle":"Ciekawostka","extra":"Wypominki to wciąż żywy zwyczaj: w parafiach czyta się listy zmarłych przez cały listopad.","whisper":"Nikt nie umiera do końca, dopóki ktoś wypowiada jego imię.","caution":"Znicz tylko w bezpiecznym miejscu.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":367}],["2027-11-02","travel","☽ w Strzelcu, od 17:40 w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":15.0,"moonAndBiodynamic":"☽ w Strzelcu, od 17:40 w Koziorożcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu, od 17:40 w Koziorożcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 04:40 do 17:40: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Zaduszki · dziady jesienne","namedays":"Bohdany, Tobiasza","title":"Dziady","subtitle":"uczta dla dusz","story":"W noc Zaduszną dusze wracały do domów. Na Litwie, Białorusi i wschodzie Polski urządzano dziady: wieczerzę dla zmarłych. Na stole stawiano kaszę, miód, kutię, chleb i wódkę, a pierwszą łyżkę odlewano dla dusz. Nie sprzątano ze stołu do rana. Mickiewicz w Dziadach pokazał ten obrzęd jako rozmowę żywych z umarłymi.","practice":"• Postaw na stole dodatkowy talerz albo kubek.\n• Nałóż do niego łyżkę tego, co jesz.\n• Zostaw do rana i pomyśl o tych, którzy byli przy tym stole.","extraTitle":"Ciekawostka","extra":"Słowo dziady oznacza przodków, dziadów i pradziadów, a nie żebraków.","whisper":"Stół, przy którym jest miejsce dla zmarłych, jest pełniejszy niż stół bez pamięci.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":368}],["2027-11-03","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":22.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"św. Huberta, patrona myśliwych","namedays":"Sylwii, Huberta","title":"Cisza w lesie","subtitle":"na świętego Huberta","story":"Dziś święty Hubert, patron myśliwych i leśników. Legenda mówi, że Hubert polował w lesie, gdy ujrzał jelenia ze świetlistym krzyżem między rogami. Zostawił łuk i zmienił życie. To dobry dzień, by wejść do lasu bez celu, bez zdobyczy, bez telefonu. Las w listopadzie jest cichy i szczery, bez liści, bez ozdób.","practice":"• Wejdź dziś do lasu albo parku na 20 minut.\n• Zatrzymaj się i postój bez ruchu przez dwie minuty.\n• Zapisz, co zobaczyłaś, gdy przestałaś szukać.","extraTitle":"Ciekawostka","extra":"Japońska praktyka shinrin-yoku, czyli kąpieli leśnej, jest badana jako sposób na obniżenie stresu.","whisper":"Kiedy przestajesz polować, zaczynasz widzieć.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":369}],["2027-11-04","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":31.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 15:44 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿☍♄ Merkury opozycja Saturn (09:54): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.\n♀△♆ Wenus trygon Neptun (19:37): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.","sourceText":{"holiday":"","namedays":"Karola, Olgierda","title":"Dziadowie proszalni","subtitle":"modlitwa za kromkę","story":"Przy cmentarzach i na odpustach siedzieli dziadowie proszalni: wędrowni żebracy, którzy za jałmużnę modlili się za zmarłych z rodziny ofiarodawcy. Wierzono, że nie wolno ich odpędzać, bo mogą być przebranym świętym albo samą duszą zmarłego. Kto im odmówił, ściągał nieszczęście. Dziad wiedział też wiele pieśni i nowin.","practice":"• Daj dziś coś komuś, kto prosi, bez oceniania.\n• Wspomnij przy tym kogoś bliskiego, kto odszedł.\n• Pomyśl, kto w twoim życiu przynosi nowiny z daleka.","extraTitle":"Ciekawostka","extra":"Dziadowie proszalni przekazywali z wioski do wioski pieśni, legendy i wiadomości, jak żywa gazeta.","whisper":"Hojność wobec obcego bywa najstarszą formą modlitwy.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":370}],["2027-11-05","social","☽ w Koziorożcu do 05:13, potem w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":41.0,"moonAndBiodynamic":"☽ w Koziorożcu do 05:13, potem w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Do 05:13 Księżyc jest w Koziorożcu, potem w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀✶♇ Wenus sekstyl Pluton (05:50): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach.","sourceText":{"holiday":"","namedays":"Elżbiety, Sławomira","title":"Żywica","subtitle":"łzy sosny","story":"Żywica, którą sosna wydziela na zranionej korze, była lekarstwem i ochroną. Okadzano nią dom, by oczyścić powietrze i odpędzić złe. Przykładano ją na rany i czyraki. Z żywicy robiono maść na odciski i smółkę do łodzi. Pachnie lasem i słońcem nawet w listopadzie. Bursztyn to żywica sprzed milionów lat.","practice":"• Na spacerze znajdź na sośnie krople żywicy, ale nie odrywaj kory.\n• Powąchaj ją z bliska.\n• Zapal w domu kadzidło żywiczne albo świecę sosnową.","extraTitle":"Ciekawostka","extra":"Bursztyn bałtycki to skamieniała żywica drzew sprzed około 40 milionów lat.","whisper":"To, co drzewo wydziela na ranę, leczy też innych.","caution":"Żywica może uczulać skórę. Okadzaj przy otwartym oknie.","bibliography":"Drzewa i krzewy w kulturze ludowej, IZPiTN 2026","bookKey":""},"sourceRow":371}],["2027-11-06","social","☽ w Wodniku","I kwadra",false,{"phase":"I kwadra o 09:00","nextPhase":"pełnia za 8 dni","illumination":51.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Feliksa, Leonarda","title":"Jemiołuszki","subtitle":"goście z północy","story":"W listopadzie z dalekiej północy przylatują jemiołuszki. Mają czubek na głowie, czarną maseczkę i żółte końcówki ogonów, jakby pomalowane farbą. Siadają stadami na jarzębinach i objadają je do ostatniego owocu. Mówiono, że ich przylot zwiastuje mroźną zimę. Dziś pierwsza kwadra: czas gości.","practice":"• Wypatruj na jarzębinach stada ptaków z czubkami.\n• Zostaw owoce jarzębiny na krzaku, nie zrywaj wszystkich.\n• Pomyśl, jaki gość z daleka przyniósłby ci coś dobrego.","extraTitle":"Ciekawostka","extra":"W niektóre zimy jemiołuszek przylatuje bardzo dużo, w inne prawie wcale. Zależy to od urodzaju owoców na północy.","whisper":"Gość z daleka przychodzi wtedy, gdy u niego brakuje, a u ciebie jest dość.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":372}],["2027-11-07","social","☽ w Wodniku, od 18:08 w Rybach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 7 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Wodniku, od 18:08 w Rybach · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku, od 18:08 w Rybach. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 11:09 do 18:08: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Antoniego, Żytomira","title":"Pokutnik","subtitle":"dusza, która czeka","story":"Dusza pokutująca błąkała się po świecie, bo za życia zostawiła coś niezałatwionego: dług, krzywdę, przesuniętą miedzę, niedotrzymaną obietnicę. Ukazywała się nocą i prosiła o modlitwę albo o naprawienie winy. Dopiero wtedy mogła odejść. W tych opowieściach kryje się prosta mądrość: niezałatwione sprawy nie dają spokoju.","practice":"• Pomyśl o jednej niezałatwionej sprawie.\n• Zrób w niej dziś jeden krok: telefon, list, przeprosiny.\n• Zapisz, jak się po tym czujesz.","extraTitle":"Pytanie na niedzielę","extra":"Jaka niezałatwiona sprawa błąka się po moim życiu i prosi o koniec?","whisper":"Duchy odchodzą, gdy sprawy zostają zamknięte.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":373}],["2027-11-08","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":71.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Wadze · ♀ w Strzelcu · ♂ w Strzelcu. Pytanie tygodnia: Co jest gotowe do przemiany?\n♀☍♅ Wenus opozycja Uran (11:09): Napięcie między planetami. Można je wykorzystać na nowe znajomości, niespodzianki i zmianę wizerunku. Uważaj na nagłe zauroczenia i wydatki pod wpływem chwili.","sourceText":{"holiday":"","namedays":"Seweryna, Wiktora","title":"Szałwia","subtitle":"zioło, które ratuje","story":"Szałwia lekarska nie rośnie u nas dziko, ale od średniowiecza uprawiano ją w ogrodach klasztornych. Jej nazwa pochodzi od łacińskiego salvare, ratować. Płukano nią gardło, smarowano dziąsła, zatrzymywano nadmierne pocenie. Dym z szałwii oczyszczał izbę. Liście są srebrne, aksamitne i pachną mocno, jakby trochę gorzko.","practice":"• Zaparz napar z szałwii i przepłucz nim gardło.\n• Rozetrzyj świeży liść i powąchaj.\n• Wsadź doniczkę szałwii na parapet na zimę.","extraTitle":"Ciekawostka","extra":"Średniowieczne przysłowie pytało: dlaczego miałby umrzeć człowiek, w którego ogrodzie rośnie szałwia?","whisper":"Ratunek często rośnie w ogrodzie, a my szukamy go daleko.","caution":"Nie w ciąży, w czasie karmienia i przy padaczce. Nie pij długo.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":374}],["2027-11-09","rest","☽ w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":79.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 13:31 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Ursyna, Teodora","title":"Krupnik","subtitle":"zupa z kaszy na zimne dni","story":"Krupnik to zupa z kaszy jęczmiennej, warzyw i suszonych grzybów albo mięsa. Gęsta, sycąca, grzejąca. Nazwa pochodzi od krup, czyli kaszy. Była podstawą jesiennego i zimowego jadłospisu na wsi i w klasztorach. Krupnik gotowany w dużym garnku starczał na kilka dni i był lepszy z każdym odgrzaniem.","practice":"• Ugotuj bulion z warzyw i garścią suszonych grzybów.\n• Dodaj szklankę kaszy jęczmiennej i pokrojone ziemniaki.\n• Gotuj do miękkości, dopraw majerankiem i natką.","extraTitle":"Ciekawostka","extra":"Krupnik to też nazwa staropolskiego likieru z miodem i przyprawami, pitego na gorąco.","whisper":"Kasza w zupie to cierpliwość, która syci.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":375}],["2027-11-10","start","☽ w Rybach do 05:38, potem w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":87.0,"moonAndBiodynamic":"☽ w Rybach do 05:38, potem w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Do 05:38 Księżyc jest w Rybach, potem w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿ Merkury wchodzi w Skorpiona (01:26): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie głębi, tajemnic, intensywnych uczuć i przemiany. Rada: odważ się spojrzeć głębiej. Uważaj na zazdrość i podejrzliwość.","sourceText":{"holiday":"","namedays":"Leny, Ludomira","title":"Darcie pierza","subtitle":"wieczór kobiet","story":"Listopadowe wieczory to czas darcia pierza. Kobiety zbierały się w jednej izbie, oddzierały puch od gęsich piór, a przy tym śpiewały, plotkowały i opowiadały. Z puchu szyto pierzyny i poduszki dla panien na wydaniu. Darcie pierza kończyło się poczęstunkiem i zabawą. To była wspólnota rąk i głosów.","practice":"• Zaproś przyjaciółki na wieczór wspólnej pracy: szycia, robienia przetworów, pakowania prezentów.\n• Opowiadajcie sobie historie przy pracy.\n• Zakończcie herbatą i ciastem.","extraTitle":"Ciekawostka","extra":"Pierzyna z gęsiego puchu była najcenniejszą częścią posagu. Szyto ją latami.","whisper":"Ręce, które pracują razem, zawsze znajdą też czas na śmiech.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":376}],["2027-11-11","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"Narodowe Święto Niepodległości · św. Marcina","namedays":"Marcina, Bartłomieja","title":"Gęsia kość","subtitle":"wróżba na zimę","story":"Na świętego Marcina jedzono gęsinę. Po obiedzie oglądano mostek gęsi: jeśli kość była biała, zima miała być śnieżna, jeśli ciemna, błotnista i deszczowa. W Poznaniu piecze się rogale świętomarcińskie z białym makiem. Dziś też Święto Niepodległości: dzień, kiedy myślimy o wolności, za którą płacono.","practice":"• Zjedz dziś rogal albo coś z gęsiny.\n• Jeśli jesz gęś, obejrzyj kość i zapisz wróżbę.\n• Pomyśl, co dla ciebie znaczy wolność.","extraTitle":"Ciekawostka","extra":"Rogal świętomarciński ma chronione oznaczenie geograficzne. Prawdziwy pochodzi tylko z Wielkopolski.","whisper":"Wolność smakuje najlepiej, gdy pamięta się, ile kosztowała.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":377}],["2027-11-12","start","☽ w Baranie, od 13:57 w Byku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":97.0,"moonAndBiodynamic":"☽ w Baranie, od 13:57 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 13:57 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 00:16 do 13:57: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Renaty, Witolda","title":"Owcza wełna","subtitle":"ciepło, które leczy","story":"Wełna owcza nie tylko grzała. Czerwoną wełnianą nitkę wiązano na nadgarstku od uroku. Surową wełną, tłustą od lanoliny, owijano bolące stawy, szyję przy przeziębieniu i brzuch przy bólach. Pasterze zawsze nosili wełniany pas. Wełna była ochroną przed zimnem i przed złymi siłami jednocześnie.","practice":"• Załóż dziś wełniane skarpety albo szal.\n• Owiń bolące miejsce wełną.\n• Zawiąż na nadgarstku czerwoną wełnianą nitkę.","extraTitle":"Ciekawostka","extra":"Lanolina z owczej wełny jest dziś podstawą wielu maści i kremów.","whisper":"Ciepło, które cię otula, chroni bardziej niż zamek w drzwiach.","caution":"Nie przy uczuleniu na lanolinę.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":378}],["2027-11-13","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":100.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿□♇ Merkury kwadratura Pluton (10:38): Napięcie między planetami. Można je wykorzystać na dociekliwość, badania, terapię i szczere rozmowy. Uważaj na obsesyjne myśli i słowne manipulacje.","sourceText":{"holiday":"","namedays":"Mikołaja, Stanisława","title":"Pierwszy śnieg","subtitle":"świat bez kolorów","story":"W listopadzie może spaść pierwszy śnieg. Ziemia nagle robi się biała i cicha. Dzieci wybiegają, by złapać płatki na język. Dawniej mówiono, że pierwszy śnieg ma moc: kto umyje nim twarz, będzie zdrowy cały rok. Pierwszy śnieg często szybko topnieje, ale zapowiada, że zima naprawdę idzie.","practice":"• Gdy spadnie pierwszy śnieg, wyjdź na zewnątrz.\n• Złap płatek na rękaw i przyjrzyj się jego kształtowi.\n• Zapisz datę w kalendarzu.","extraTitle":"Ciekawostka","extra":"Każdy płatek śniegu ma sześć ramion, ale nie ma dwóch identycznych.","whisper":"Cisza po pierwszym śniegu jest najczystszą ciszą roku.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":379}],["2027-11-14","finances","☽ w Byku, od 19:14 w Bliźniętach","pełnia",true,{"phase":"pełnia o 04:26","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Byku, od 19:14 w Bliźniętach · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku, od 19:14 w Bliźniętach. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 06:06 do 19:14: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🌕 Pełnia w Byku (04:25): Kulminacja w sprawach: pieniądze, ciało, poczucie bezpieczeństwa. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"","namedays":"Rogera, Serafiny","title":"Złe oko","subtitle":"urok i spluwanie","story":"Rzucić urok można było spojrzeniem, pochwałą albo zazdrością. Dlatego kiedy ktoś chwalił dziecko, spluwano trzy razy przez ramię i mówiono: na psa urok. Dzieciom wiązano czerwone wstążki, a od uroku zamawiano węglem wrzucanym do wody. Dziś nad ranem pełnia, a urok to stara nazwa zazdrości, która potrafi zranić.","practice":"• Gdy cię dziś ktoś pochwali, podziękuj i uśmiechnij się.\n• Gdy sama poczujesz zazdrość, nazwij ją po imieniu.\n• Zamień ją na życzliwe słowo.","extraTitle":"Pytanie na niedzielę","extra":"Czyja zazdrość mnie dotyka i czyją zazdrość ja noszę w sobie?","whisper":"Najlepszą ochroną przed złym okiem jest dobre serce, które nie zazdrości.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":380}],["2027-11-15","conversation","☽ w Bliźniętach","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":98.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Skorpionie · ♀ w Strzelcu · ♂ w Strzelcu. Pytanie tygodnia: Co jest gotowe do przemiany?\n☉✶♃ Słońce sekstyl Jowisz (07:07): Dobry dzień na optymizm, prośby, oferty, naukę i podróże.\n♂△♄ Mars w harmonii z Saturnem (13:53): Wytrwała, uporządkowana energia. Świetna do ciężkiej pracy. Rada: zrób rzecz żmudną i ważną.","sourceText":{"holiday":"","namedays":"Alberta, Leopolda","title":"Kminek","subtitle":"ziarno trawienia","story":"Kminek rośnie dziko na łąkach, a jego ziarna dodaje się do chleba, kapusty i serów. Pito go na wzdęcia i bóle brzucha, a niemowlętom dawano wodę kminkową na kolki. Wierzono, że kminek zatrzymuje: miłość, złodzieja i kury, by nie uciekały. Wsypywano go do kieszeni ukochanego, by nie odszedł.","practice":"• Dodaj łyżeczkę kminku do kapusty albo pieczonych ziemniaków.\n• Zaparz napar z rozgniecionego kminku po ciężkim posiłku.\n• Wsyp szczyptę kminku do kieszeni, jeśli chcesz coś zatrzymać.","extraTitle":"Ciekawostka","extra":"Kminek należy do najstarszych przypraw Europy. Jego nasiona znaleziono w osadach sprzed 5 tysięcy lat.","whisper":"Małe ziarna trzymają to, co ważne, bliżej.","caution":"Nie w ciąży w dużych ilościach.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":381}],["2027-11-16","conversation","☽ w Bliźniętach, od 22:39 w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":93.0,"moonAndBiodynamic":"☽ w Bliźniętach, od 22:39 w Raku · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach, od 22:39 w Raku. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 10:40 do 22:39: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂□♃ Mars w napięciu z Jowiszem (05:06): Pośpiech, przesada i chęć postawienia na swoim. Uwaga: policz koszty, zanim ruszysz.","sourceText":{"holiday":"","namedays":"Gertrudy, Edmunda","title":"Kluski z dziurką","subtitle":"śląskie, okrągłe, z sosem","story":"Kluski śląskie robi się z ugotowanych ziemniaków i mąki ziemniaczanej. Formuje się okrągłe kulki i w każdej robi palcem dziurkę, w którą wleje się sos. Na Śląsku podaje się je w niedzielę z roladą i modrą kapustą. Kluski to sztuka: ciasto nie może się kleić ani rozpadać. Uczy się jej od babci.","practice":"• Przeciśnij 1 kg ugotowanych ziemniaków, wyrównaj w misce.\n• Usuń ćwierć, wsyp tyle mąki ziemniaczanej, dodaj ziemniaki z powrotem, jajko i sól.\n• Uformuj kulki z dziurką, gotuj 3 minuty po wypłynięciu.","extraTitle":"Ciekawostka","extra":"Dziurka w klusce nie jest tylko na sos. Dzięki niej kluska gotuje się równo w środku.","whisper":"Każda dziurka w klusce czeka na sos, tak jak każda pustka na coś dobrego.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":382}],["2027-11-17","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":86.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Grzegorza, Salomei","title":"Odwiedziny przed zimą","subtitle":"lista ludzi","story":"Dawniej przed zimą odwiedzano krewnych i sąsiadów, bo potem drogi stawały się nieprzejezdne. Zanoszono sobie przetwory, chleb, wieści. Teraz zimą też łatwo zamknąć się w domu. Zrób listę ludzi, których chcesz odwiedzić albo do których chcesz zadzwonić, zanim przyjdą długie noce. Bliskość też trzeba przygotować na zimę.","practice":"• Napisz listę pięciu osób, które chcesz zobaczyć przed świętami.\n• Umów się dziś z jedną z nich.\n• Zanieś komuś słoik swoich przetworów.","extraTitle":"Ciekawostka","extra":"Badania nad samotnością pokazują, że zimą ludzie częściej czują się samotni, zwłaszcza starsi.","whisper":"Bliskość, którą przygotujesz jesienią, ogrzeje cię zimą.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":383}],["2027-11-18","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":78.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 18:57 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Romana, Klaudyny","title":"Ptak w oknie","subtitle":"wieść z daleka","story":"Ptak, który uderzył w okno albo usiadł na parapecie i zaglądał do środka, przynosił wiadomość. Mówiono, że to dusza zmarłego, który chce się pożegnać albo przekazać coś ważnego. Sikora w oknie zapowiadała gościa, a wrona kłopoty. Ptak, który wleciał do domu, był znakiem zmiany.","practice":"• Zauważ dziś ptaki, które zbliżą się do twojego okna.\n• Zawieś przy oknie karmnik albo słoninę dla sikor.\n• Jeśli ktoś bliski przyjdzie ci na myśl, zadzwoń.","extraTitle":"Ciekawostka","extra":"Ptaki uderzają w szyby, bo widzą w nich odbicie nieba i drzew. Pomagają naklejki na szybach.","whisper":"Wiadomości przychodzą różnymi drogami. Czasem przez okno.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":384}],["2027-11-19","creative","☽ w Raku do 01:27, potem we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":68.0,"moonAndBiodynamic":"☽ w Raku do 01:27, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 01:27 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀△♄ Wenus trygon Saturn (03:51): Dobry dzień na trwałe zobowiązania, inwestycje i porządki w finansach.","sourceText":{"holiday":"","namedays":"Elżbiety, Seweryna","title":"Pająk ze słomy","subtitle":"żyrandol z kłosów","story":"W izbach pod belką wieszano pająki: ozdoby ze słomy, bibuły i grochu, przypominające kryształowe żyrandole. Robiono je zimą, przed świętami. Pająk obracał się w ciepłym powietrzu i chronił dom, łapiąc złe duchy jak w sieć. Był też symbolem urodzaju i porządku świata. To jedno z najpiękniejszych polskich rękodzieł.","practice":"• Zrób mały pająk ze słomek do picia albo z trawy i nitki.\n• Powieś go pod sufitem albo w oknie.\n• Patrz, jak obraca się w ciepłym powietrzu.","extraTitle":"Ciekawostka","extra":"Pająki robiono z żytniej słomy, kolorowej bibuły i grochu nawlekanego na nitkę.","whisper":"Ochrona może być lekka jak słoma i piękna jak kryształ.","caution":"","bibliography":"Rytuały magiczne w medycynie ludowej, IZPiTN 2026","bookKey":""},"sourceRow":385}],["2027-11-20","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":57.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀□♃ Wenus kwadratura Jowisz (04:35): Napięcie między planetami. Można je wykorzystać na relacje, randki, zakupy, umowy i świętowanie. Uważaj na rozrzutność i przejadanie się.","sourceText":{"holiday":"","namedays":"Anatola, Sędzimira","title":"Kruki i wrony","subtitle":"czarne ptaki zimy","story":"Zimą na polach i w miastach widać stada wron i gawronów. Kruki, większe i rzadsze, latają parami. Kruk był ptakiem mądrości i śmierci, posłańcem bogów. Wrona krakała na deszcz i nieszczęście. Te ptaki są niezwykle inteligentne: pamiętają twarze ludzi, używają narzędzi i rozmawiają ze sobą.","practice":"• Popatrz na wrony i spróbuj rozpoznać kruka po większym dziobie i głębszym głosie.\n• Zostaw im okruchy chleba.\n• Pomyśl, czego mogłabyś się nauczyć od mądrych ptaków.","extraTitle":"Ciekawostka","extra":"Badania pokazują, że wrony pamiętają twarz człowieka, który je skrzywdził, przez wiele lat.","whisper":"Mądrość często nosi czarne pióra i nie boi się zimy.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":386}],["2027-11-21","organize","☽ we Lwie do 04:25, potem w Pannie","III kwadra",false,{"phase":"III kwadra o 01:48","nextPhase":"nów za 7 dni","illumination":45.0,"moonAndBiodynamic":"☽ we Lwie do 04:25, potem w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Do 04:25 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Janusza, Konrada","title":"Biała dama","subtitle":"strażniczka zamków","story":"W polskich zamkach straszy biała dama. W Kórniku Teofila z Działyńskich, w Niedzicy księżniczka inkaska, w Malborku i Książu inne kobiety w bieli. Ukazują się nocą na schodach i krużgankach. Zazwyczaj nikogo nie krzywdzą. Strzegą rodu, przepowiadają śmierć albo czekają na sprawiedliwość. Dziś ostatnia kwadra: czas wspomnień.","practice":"• Pomyśl o kobiecie z twojej rodziny, której historia jest niedokończona.\n• Dowiedz się o niej czegoś nowego.\n• Zapisz jej imię i jedną rzecz, którą o niej wiesz.","extraTitle":"Pytanie na niedzielę","extra":"Czyja historia w mojej rodzinie wciąż chodzi po schodach i czeka na wysłuchanie?","whisper":"Duchy to opowieści, których nikt nie dokończył.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":387}],["2027-11-22","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":35.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Skorpionie · ☿ w Skorpionie · ♀ w Strzelcu · ♂ w Strzelcu. Pytanie tygodnia: Co jest gotowe do przemiany?\n☉ Słońce wchodzi w Strzelca (14:16): Na miesiąc cały świat nabiera barw znaku Strzelca: czas podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się.","sourceText":{"holiday":"","namedays":"Marka, Cecylii","title":"Pigwa","subtitle":"złoty owoc zimy","story":"Pigwa i pigwowiec dają twarde, żółte owoce, które pachną tak mocno, że wystarczy jeden, by wypełnić pokój zapachem. Na surowo są niejadalne, ale z nich robi się konfitury, syropy i nalewki. Plasterek pigwy do herbaty zamiast cytryny to polski zwyczaj zimy. Pigwa jest bogata w witaminę C i pektyny.","practice":"• Połóż jeden owoc pigwy na stole, by pachniał.\n• Pokrój pigwę w plastry, zasyp cukrem i odstaw na tydzień.\n• Dodawaj plasterki do herbaty.","extraTitle":"Ciekawostka","extra":"W starożytnej Grecji pigwa była owocem Afrodyty. Panna młoda jadła ją przed nocą poślubną.","whisper":"Twarde owoce najlepiej smakują, gdy się na nie poczeka.","caution":"Nie jedz pestek pigwy.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":388}],["2027-11-23","relationships","☽ w Pannie do 07:52, potem w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":24.0,"moonAndBiodynamic":"☽ w Pannie do 07:52, potem w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Do 07:52 Księżyc jest w Pannie, potem w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 04:26 do 07:52: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Adeli, Klemensa","title":"Zupa grzybowa z suszu","subtitle":"las w środku zimy","story":"Suszone grzyby z lata to skarb zimy. Zupa grzybowa z suszu pachnie lasem w środku listopada. Grzyby moczy się na noc, gotuje w tej samej wodzie, dodaje marchew, pietruszkę, cebulę i kaszę albo łazanki. Zabiela się śmietaną. W wielu domach to też zupa wigilijna.","practice":"• Namocz na noc garść suszonych prawdziwków w litrze wody.\n• Ugotuj w tej samej wodzie z warzywami.\n• Dodaj łazanki albo kaszę, zabiel śmietaną.","extraTitle":"Ciekawostka","extra":"Suszone prawdziwki mają bardziej intensywny smak niż świeże, bo suszenie koncentruje związki aromatyczne.","whisper":"Lato, które zasuszyłaś, wraca w zimie zapachem.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":389}],["2027-11-24","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":16.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Flory, Emmy","title":"Świece z wosku","subtitle":"światło od pszczół","story":"Woskowe świece były cenniejsze od łojowych, bo nie kopciły i pachniały miodem. Robiono je, maczając knot w roztopionym wosku raz za razem, aż świeca urosła. Gromnice i świece kościelne musiały być z wosku pszczelego. Pszczoła była świętym owadem, a jej wosk niósł światło. Zrobienie świecy to medytacja.","practice":"• Kup arkusz wosku pszczelego i knot.\n• Zwiń wosk ciasno wokół knota.\n• Zapal świecę wieczorem i poczuj zapach miodu.","extraTitle":"Ciekawostka","extra":"Do zrobienia kilograma wosku pszczoły zużywają kilka kilogramów miodu.","whisper":"Światło, które pachnie miodem, ma w sobie pracę tysięcy pszczół.","caution":"Świeca tylko pod nadzorem.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":390}],["2027-11-25","relationships","☽ w Wadze, od 12:10 w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":9.0,"moonAndBiodynamic":"☽ w Wadze, od 12:10 w Skorpionie · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 12:10 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 12:05 do 12:10: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀☌♂ Wenus spotyka Marsa (02:35): Pociąg, namiętność i nowy początek w uczuciach. Rada: okaż komuś uczucie wprost.\n♀ Wenus wchodzi w Koziorożca (12:59): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa. Uważaj na surowość wobec siebie i chłód.\n☿✶♃ Merkury sekstyl Jowisz (18:19): Dobry dzień na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości.\n♂ Mars wchodzi w Koziorożca (19:38): Na kilka tygodni energia i działanie płyną w rytmie obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa. Uważaj na surowość wobec siebie i chłód.","sourceText":{"holiday":"św. Katarzyny · wróżby kawalerów","namedays":"Katarzyny, Erazma","title":"Koło Katarzyny","subtitle":"los, który się obraca","story":"Święta Katarzyna Aleksandryjska miała zostać zamęczona na kole, które pękło, gdy go dotknęła. Stała się patronką kołodziejów, młynarzy i panien. W jej wigilię chłopcy wróżyli o żonie. Koło Katarzyny to symbol losu: raz jesteś na górze, raz na dole. Przesąd mówi, że w ten dzień nie wolno kręcić kołowrotkiem.","practice":"• Narysuj koło i podziel je na cztery części: co na górze, co na dole.\n• Zapisz, gdzie teraz jesteś.\n• Pomyśl, w którą stronę obraca się twoje koło.","extraTitle":"Ciekawostka","extra":"Fajerwerk w kształcie wirującego koła po angielsku nazywa się Catherine wheel, koło Katarzyny.","whisper":"Koło się obraca. Kto jest na dole, będzie na górze.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":391}],["2027-11-26","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":3.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉△♆ Słońce trygon Neptun (12:07): Dobry dzień na intuicję, sztukę, medytację i pomoc innym.","sourceText":{"holiday":"","namedays":"Delfiny, Sylwestra","title":"Bluszcz","subtitle":"zieleń, która trzyma","story":"Bluszcz jest zielony przez całą zimę i trzyma się murów tak mocno, że trudno go oderwać. Był symbolem wierności, przyjaźni i życia wiecznego. Bluszczem przystrajano domy na zimę i wianki weselne. Wierzono, że bluszcz na ścianie chroni dom przed czarami. Jest piękny, ale trujący, zwłaszcza owoce.","practice":"• Postaw w domu doniczkę z bluszczem albo gałązkę w wodzie.\n• Pomyśl o przyjaźni, która trzyma się jak bluszcz.\n• Napisz do tej przyjaciółki.","extraTitle":"Ciekawostka","extra":"Bluszcz kwitnie jesienią, a jego kwiaty są ostatnim pożywieniem dla pszczół przed zimą.","whisper":"Wierność jest jak bluszcz: zielona także zimą.","caution":"Bluszcz jest trujący dla ludzi i zwierząt. Sok może podrażniać skórę.","bibliography":"Ludowe nazwy ziół, IZPiTN 2026","bookKey":""},"sourceRow":392}],["2027-11-27","honesty","☽ w Skorpionie, od 18:00 w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":1.0,"moonAndBiodynamic":"☽ w Skorpionie, od 18:00 w Strzelcu · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie, od 18:00 w Strzelcu. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 12:21 do 18:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"☉✶♇ Słońce sekstyl Pluton (16:00): Dobry dzień na głęboką przemianę, odwagę w sprawach trudnych i badanie spraw do dna.","sourceText":{"holiday":"","namedays":"Waleriana, Wilgiusza","title":"Najkrótsze dni","subtitle":"osiem godzin światła","story":"Pod koniec listopada we Wrocławiu dzień trwa już tylko nieco ponad osiem godzin. Słońce wschodzi po siódmej i zachodzi przed szesnastą. Na wsi to był czas, gdy życie przenosiło się do izby: przędzenie, naprawy, opowieści. Krótki dzień nie jest wrogiem. Jest zaproszeniem do odpoczynku.","practice":"• Wyjdź na zewnątrz w najjaśniejszej porze dnia, choćby na 15 minut.\n• Zapal wieczorem świecę zamiast górnego światła.\n• Idź dziś spać wcześniej niż zwykle.","extraTitle":"Ciekawostka","extra":"Do przesilenia dzień skróci się jeszcze o mniej więcej pół godziny.","whisper":"Ciemność daje to, czego nie daje światło: odpoczynek.","caution":"Przy obniżonym nastroju zimą porozmawiaj z lekarzem o świetle i witaminie D.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":393}],["2027-11-28","travel","☽ w Strzelcu","nów",false,{"phase":"nów o 04:24","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🌑 Nów w Strzelcu (04:24): Czas zasiewu w sprawach: sens, podróże, nauka. Rada: zapisz intencję na ten księżycowy miesiąc.\n♀□♆ Wenus kwadratura Neptun (17:10): Napięcie między planetami. Można je wykorzystać na romantyzm, sztukę, muzykę i współczucie. Uważaj na idealizowanie ludzi i rozczarowania.","sourceText":{"holiday":"I niedziela Adwentu","namedays":"Lesława, Zdzisława","title":"Pierwsza niedziela Adwentu","subtitle":"roraty i lampiony","story":"Dziś zaczyna się Adwent, a nad ranem nów. Księżyc i kalendarz kościelny mówią to samo: nowy początek w ciemności. Na roraty, msze o świcie, dzieci idą z lampionami. Dawniej w Adwencie milkła muzyka, nie urządzano wesel ani zabaw. Był to czas czekania i wyciszenia przed narodzinami światła.","practice":"• Zapal pierwszą świecę na wieńcu albo zwykłą świecę na stole.\n• Zapisz intencję na Adwent i na nowy księżycowy miesiąc.\n• Zrób sobie lampion ze słoika i świeczki.","extraTitle":"Pytanie na niedzielę","extra":"Na co naprawdę czekam w tym roku?","whisper":"Światło, na które się czeka, świeci mocniej.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":394}],["2027-11-29","travel","☽ w Strzelcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 16:02 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Koziorożcu · ♂ w Koziorożcu. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☿ Merkury wchodzi w Strzelca (11:23): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie podróży, nauki, wiary i szerokich horyzontów. Rada: zaplanuj coś dalekiego i ucz się. Uważaj na przesadę i obietnice bez pokrycia.","sourceText":{"holiday":"andrzejki · wigilia św. Andrzeja","namedays":"Błażeja, Saturnina","title":"Andrzejki","subtitle":"jabłko i obierka","story":"W wigilię świętego Andrzeja dziewczęta wróżyły o przyszłym mężu. Leje się wosk przez klucz, ale były też inne wróżby. Obierano jabłko jedną długą obierką i rzucano ją przez ramię: jaką literę utworzy, na taką literę zacznie się imię ukochanego. Ustawiano buty od ściany do drzwi. Czyj pierwszy przekroczył próg, ta pierwsza wyjdzie za mąż.","practice":"• Obierz jabłko jedną obierką i rzuć ją przez ramię.\n• Zobacz, jaką literę przypomina.\n• Pośmiej się z przyjaciółkami z wróżby.","extraTitle":"Ciekawostka","extra":"Dawniej andrzejki były wróżbami tylko dla dziewcząt, a chłopcy wróżyli w wigilię świętej Katarzyny.","whisper":"Wróżba nie mówi, co się stanie. Mówi, czego pragniesz.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":395}],["2027-11-30","work","☽ w Strzelcu do 02:18, potem w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":5.0,"moonAndBiodynamic":"☽ w Strzelcu do 02:18, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 02:18 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉☍♅ Słońce naprzeciw Urana (10:21): Inni zaskakują. Plany mogą się nagle zmienić. Uwaga: zostaw sobie margines czasu.\n♂□♆ Mars w napięciu z Neptunem (23:23): Mniej siły, więcej mgły. Działania łatwo się rozmywają. Uwaga: uważaj na alkohol, leki i niejasne układy.","sourceText":{"holiday":"św. Andrzeja","namedays":"Maury, Andrzeja","title":"Kasza z grzybami","subtitle":"na święty Andrzej","story":"Dziś święty Andrzej. Po nim kończyły się zabawy i zaczynał adwentowy post. Na stołach była kasza: gryczana z grzybami i cebulą, jaglana z dynią, pęczak z warzywami. Kasza była podstawą jedzenia polskiej wsi przez wieki, zanim zastąpiły ją ziemniaki. Mówiono: kasza matka nasza.","practice":"• Ugotuj szklankę kaszy gryczanej na sypko.\n• Podsmaż cebulę z garścią namoczonych suszonych grzybów.\n• Wymieszaj z kaszą, dopraw solą i pieprzem.","extraTitle":"Ciekawostka","extra":"Andrzej był rybakiem i bratem Piotra. Ukrzyżowano go na krzyżu w kształcie litery X.","whisper":"Kasza nie jest wykwintna, ale nigdy cię nie zawiedzie.","caution":"","bibliography":"Z. Gloger, Encyklopedia staropolska","bookKey":""},"sourceRow":396}],["2027-12-01","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":10.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿△♆ Merkury trygon Neptun (22:52): Dobry dzień na pisanie, poezję, muzykę i rozmowy o duchowości.","sourceText":{"holiday":"","namedays":"Natalii, Eligiusza","title":"Własny kalendarz adwentowy","subtitle":"dwadzieścia cztery dobre gesty","story":"Kalendarz adwentowy wymyślono w XIX wieku w Niemczech, by dzieci mogły liczyć dni do Bożego Narodzenia. Ale możesz zrobić własny, dla dorosłych: zamiast czekoladek, dwadzieścia cztery małe gesty. Telefon do kogoś, kto jest sam. Wieczór bez telefonu. Spacer o świcie. Adwent to czekanie, które można wypełnić dobrem.","practice":"• Zapisz na 24 karteczkach drobne dobre gesty.\n• Złóż je i włóż do słoika.\n• Każdego ranka losuj jedną i zrób to, co na niej jest.","extraTitle":"Ciekawostka","extra":"Pierwsze drukowane kalendarze adwentowe pojawiły się w Niemczech na początku XX wieku.","whisper":"Czekanie wypełnione dobrem mija szybciej i zostawia więcej.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":397}],["2027-12-02","work","☽ w Koziorożcu, od 13:26 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 11 dni","illumination":17.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 13:26 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 13:26 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 03:17 do 13:26: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿✶♇ Merkury sekstyl Pluton (19:05): Dobry dzień na dociekliwość, badania, terapię i szczere rozmowy.","sourceText":{"holiday":"","namedays":"Balbiny, Bibianny","title":"Szron na oknie","subtitle":"obrazy mrozu","story":"Kiedy w nocy mróz malował na szybach paprocie i gwiazdy, dzieci i dziewczęta odczytywały z nich przyszłość. Gęsty szron wróżył dobry rok, kwiaty na szybie miłość, a ostre linie kłopoty. Mówiono, że to Mróz, dziadek zimy, rysuje palcem po oknach. Szron to woda, która od razu stała się lodem, bez kropli.","practice":"• Rano przyjrzyj się szronowi na szybie albo na trawie.\n• Opisz, co widzisz: paprocie, pióra, gwiazdy.\n• Zapisz, co by ci to wróżyło.","extraTitle":"Ciekawostka","extra":"Kwiaty mrozu na szybach tworzą się przez resublimację: para wodna zamienia się prosto w lód.","whisper":"Mróz rysuje tylko na tym, co jest ciepłe w środku.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":398}],["2027-12-03","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 10 dni","illumination":24.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Franciszka, Ksawerego","title":"Lniane płótno","subtitle":"tkanina z pola","story":"Len siano wiosną, rwano latem, moczono, suszono, międlono i przędzono zimą. Lniane płótno było białe, chłodne i trwałe. Wierzono, że chroni przed chorobą i urokiem, dlatego w lnianej koszuli rodziło się dziecko, w lnianej się brało ślub i w lnianej chowano zmarłych. Lniany obrus na Wigilię był świętością.","practice":"• Przygotuj na Wigilię biały, lniany obrus albo serwetkę.\n• Wypierz go i wyprasuj z uwagą.\n• Pomyśl o kobietach, które przędły len przez wieki.","extraTitle":"Ciekawostka","extra":"Len to jedna z najstarszych roślin włóknistych świata. Lniane tkaniny znaleziono w grobowcach egipskich.","whisper":"Płótno, które towarzyszy od narodzin do śmierci, ma w sobie całe życie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":399}],["2027-12-04","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 9 dni","illumination":33.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 08:46 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☿☍♅ Merkury opozycja Uran (09:46): Napięcie między planetami. Można je wykorzystać na olśnienia, technologię, nowe pomysły i nieoczywiste rozwiązania. Uważaj na nerwowość, rozkojarzenie i nagłe zmiany planów.","sourceText":{"holiday":"Barbórka · św. Barbary","namedays":"Barbary, Krystiana","title":"Barbórka","subtitle":"patronka górników","story":"Święta Barbara jest patronką górników, hutników i dobrej śmierci. Na Śląsku Barbórka to wielkie święto: górnicy w galowych mundurach z pióropuszami idą na mszę, a potem na karczmę piwną. Figurki Barbary stoją w kopalniach. Wierzono, że chroni przed nagłą śmiercią bez sakramentów, a górnicy schodzą pod ziemię, gdzie śmierć jest blisko.","practice":"• Pomyśl o ludziach, którzy pracują w ciemności i niebezpieczeństwie.\n• Zapal dla nich świecę.\n• Podziękuj komuś, czyja praca jest niewidoczna.","extraTitle":"Przysłowie","extra":"„Barbara po lodzie, Boże Narodzenie po wodzie.”","whisper":"Najwięcej światła potrzebują ci, którzy pracują w ciemności.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":400}],["2027-12-05","rest","☽ w Wodniku do 02:20, potem w Rybach","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 8 dni","illumination":43.0,"moonAndBiodynamic":"☽ w Wodniku do 02:20, potem w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Do 02:20 Księżyc jest w Wodniku, potem w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Saby, Kryspina","title":"Diabeł i anioł","subtitle":"orszak Mikołaja","story":"W wigilię Mikołajek na Podhalu i Śląsku chodził orszak: biskup Mikołaj, anioł i diabeł. Anioł pytał dzieci o pacierz i dobre uczynki, diabeł straszył łańcuchem i rózgą. Grzeczne dzieci dostawały jabłka i orzechy, niegrzeczne rózgę. Diabeł w tej opowieści nie był groźny. Był przypomnieniem, że czyny mają konsekwencje.","practice":"• Pomyśl o swoich dobrych uczynkach w tym roku.\n• Pomyśl też o tym, za co należałaby ci się rózga.\n• Zrób dziś jedno i naprawi drugie.","extraTitle":"Pytanie na niedzielę","extra":"Co zrobiłam w tym roku dobrze, a co chciałabym naprawić przed jego końcem?","whisper":"Diabeł i anioł chodzą razem. Ty wybierasz, kogo słuchasz.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":401}],["2027-12-06","rest","☽ w Rybach","I kwadra",true,{"phase":"I kwadra o 06:22","nextPhase":"pełnia za 7 dni","illumination":52.0,"moonAndBiodynamic":"☽ w Rybach · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Koziorożcu · ♂ w Koziorożcu. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?","sourceText":{"holiday":"Mikołajki","namedays":"Mikołaja, Jaremy","title":"Mikołaj z Miry","subtitle":"sakiewka przez okno","story":"Święty Mikołaj był biskupem w Mirze. Legenda mówi, że w nocy wrzucił przez okno trzy sakiewki złota ubogiemu ojcu, który nie miał posagu dla córek. Stąd zwyczaj dawania prezentów po kryjomu. Mikołaj nie chciał podziękowań. Dziś też pierwsza kwadra: czas, by coś zacząć dla kogoś innego.","practice":"• Zostaw komuś prezent anonimowo.\n• Nie mów, że to od ciebie.\n• Pomyśl, jak to jest dawać bez oczekiwania podziękowań.","extraTitle":"Ciekawostka","extra":"Szczątki świętego Mikołaja przeniesiono w XI wieku z Miry do Bari we Włoszech.","whisper":"Najpiękniejszy dar to ten, którego dawca pozostaje w ukryciu.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":402}],["2027-12-07","rest","☽ w Rybach, od 14:30 w Baranie","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 6 dni","illumination":63.0,"moonAndBiodynamic":"☽ w Rybach, od 14:30 w Baranie · dzień liścia","goodFor":"dobry dzień na odpoczynek","energy":"Księżyc w Rybach, od 14:30 w Baranie. Energia żeńska, przyjmująca. Dobry dzień na odpoczynek, sen, medytację, kąpiel, sztukę i pomoc innym. Unikaj ważnych podpisów i alkoholu. Faza: pierwsza kwadra, czas na decyzje i pokonywanie przeszkód. Księżyc bez kursu od 05:39 do 14:30: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Rybach rządzi: stopy. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Marcina, Ambrozego","title":"Pierniczki na choinkę","subtitle":"ozdoby, które pachną","story":"Pierniczki pieczone przed świętami wieszano na choince razem z jabłkami, orzechami i ozdobami ze słomy. Wycinano z ciasta gwiazdy, serca, koniki, aniołki. Dekorowano lukrem. Choinka pachniała miodem i przyprawami. Pierniczki można upiec już teraz, bo w puszce zmiękną i będą idealne na Wigilię.","practice":"• Zagnieć ciasto z 500 g mąki, 200 g miodu, jajka, 100 g masła, sody i przyprawy do piernika.\n• Rozwałkuj, wykrój kształty, zrób dziurkę na sznurek.\n• Piecz 10 min w 180 °C, udekoruj lukrem.","extraTitle":"Ciekawostka","extra":"Pierniczki twardnieją po upieczeniu, ale w szczelnej puszce z kawałkiem jabłka miękną w kilka dni.","whisper":"Choinka, która pachnie, jest bardziej świąteczna niż ta, która tylko świeci.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":403}],["2027-12-08","start","☽ w Baranie","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 5 dni","illumination":73.0,"moonAndBiodynamic":"☽ w Baranie · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Marii, Światozara","title":"Kartki pisane ręcznie","subtitle":"słowa z atramentem","story":"Dawniej przed świętami pisało się listy i kartki do rodziny i przyjaciół. Pisane ręcznie, czasem z rysunkiem, docierały pocztą przed Wigilią. Dziś to rzadkość, a przez to większy dar. Odręczne słowo ma w sobie coś, czego nie ma wiadomość w telefonie: ślad ręki, czas i uwagę.","practice":"• Kup lub zrób kilka kartek.\n• Napisz ręcznie trzy kartki do osób, które się nie spodziewają.\n• Wyślij je pocztą jeszcze w tym tygodniu.","extraTitle":"Ciekawostka","extra":"Pierwszą komercyjną kartkę bożonarodzeniową wydrukowano w Londynie w 1843 roku.","whisper":"Słowo napisane ręką zostaje w szufladzie na lata.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":404}],["2027-12-09","start","☽ w Baranie, od 23:35 w Byku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 4 dni","illumination":82.0,"moonAndBiodynamic":"☽ w Baranie, od 23:35 w Byku · dzień owocu","goodFor":"dobry dzień na nowe początki","energy":"Księżyc w Baranie, od 23:35 w Byku. Energia męska, działająca. Dobry dzień na nowe początki, sport i szybkie załatwianie spraw. Unikaj pośpiechu i kłótni. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 07:17 do 23:35: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Baranie rządzi: głowa. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Wiesława, Leokadii","title":"Twarz w pierwszym śniegu","subtitle":"zdrowie na cały rok","story":"Kiedy spadł pierwszy prawdziwy śnieg zimy, dziewczęta myły nim twarz, by być piękne i rumiane przez cały rok. Dzieci tarzały się w śniegu na zdrowie. Śniegiem nacierano odmrożenia, choć dziś wiemy, że to szkodzi. Mówiono, że śnieg, który leży długo, chroni oziminy jak pierzyna i zapowiada dobry urodzaj.","practice":"• Gdy spadnie śnieg, przemyj twarz garścią czystego śniegu.\n• Poczuj, jak skóra się rumieni.\n• Przypomnij sobie zabawę w śniegu z dzieciństwa.","extraTitle":"Ciekawostka","extra":"Pokrywa śnieżna izoluje ziemię. Pod 20 cm śniegu temperatura gleby może być o kilkanaście stopni wyższa niż w powietrzu.","whisper":"Śnieg nie tylko ziębi. Czasem otula.","caution":"Nie nacieraj odmrożeń śniegiem. Ogrzewaj je powoli.","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":405}],["2027-12-10","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 3 dni","illumination":89.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Julii, Danieli","title":"Zimowa kąpiel","subtitle":"sól i jałowiec","story":"Zimą kąpiel była rzadkością, ale gdy się zdarzała, dodawano do niej zioła i sól. Gałązki jałowca, sosny i jodły parzono we wrzątku i wlewano do balii. Taka kąpiel rozgrzewała, oczyszczała drogi oddechowe i chroniła przed chorobami. Para z igliwia pachnie lasem i otwiera płuca.","practice":"• Zaparz garść gałązek sosny lub jałowca w garnku wrzątku.\n• Wlej napar do wanny z garścią soli.\n• Leż w kąpieli 15 minut i oddychaj głęboko.","extraTitle":"Ciekawostka","extra":"Olejki eteryczne z sosny i jodły mają działanie wykrztuśne i lekko antyseptyczne.","whisper":"Las można zabrać do wanny. Ciało pamięta jego zapach.","caution":"Nie przy chorobach serca, nadciśnieniu i w ciąży bez konsultacji. Nie przy uczuleniu na olejki.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":406}],["2027-12-11","finances","☽ w Byku","Księżyc przybywający",true,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 2 dni","illumination":95.0,"moonAndBiodynamic":"☽ w Byku · dzień korzenia","goodFor":"dobry dzień na finanse","energy":"Księżyc w Byku. Energia żeńska, przyjmująca. Dobry dzień na finanse, gotowanie, masaż i pracę w ogrodzie. Unikaj wielkich zmian i upartego trzymania się swojego. Faza: garb przybywający, czas na dopracowywanie i cierpliwość. Księżyc bez kursu od 21:57 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Byku rządzi: szyja i gardło. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☉☌☿ Słońce koniunkcja Merkury (23:16): Dobry dzień na wyrażanie siebie, ważne rozmowy, pisanie i planowanie. Uważaj tylko na mówienie bez słuchania.","sourceText":{"holiday":"","namedays":"Damazego, Waldemara","title":"Gile na jarzębinie","subtitle":"czerwone piersi zimy","story":"Zimą na krzewach jarzębiny siadają gile. Samiec ma czerwoną pierś, samica szarobrązową. Siedzą spokojnie, objadając owoce i pąki. Gil był ptakiem zimy, a jego przylot zapowiadał mróz. Mówiono, że gil to dusza, która przylatuje do żywych w czasie świąt. Ich cichy gwizd słychać w zimowym powietrzu.","practice":"• Wypatruj czerwonych ptaków na jarzębinie albo bzach.\n• Wysyp ziarno słonecznika w karmniku.\n• Posłuchaj ich cichego gwizdania.","extraTitle":"Ciekawostka","extra":"Gile przylatują do Polski z północy i wschodu. Część populacji mieszka u nas przez cały rok.","whisper":"Czerwień na białym śniegu jest jak serce zimy.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":407}],["2027-12-12","conversation","☽ w Byku do 04:54, potem w Bliźniętach","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 1 dzień","illumination":98.0,"moonAndBiodynamic":"☽ w Byku do 04:54, potem w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Do 04:54 Księżyc jest w Byku, potem w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♀□♄ Wenus w napięciu z Saturnem (15:12): Chłód, poczucie samotności, ograniczony budżet. Uwaga: nie oceniaj związku w zły dzień.\n☿△♄ Merkury trygon Saturn (22:07): Dobry dzień na skupioną pracę, umowy, planowanie i dokumenty.","sourceText":{"holiday":"","namedays":"Dagmary, Aleksandry","title":"Dziki Gon","subtitle":"myśliwi nocy","story":"W najdłuższe noce roku nad ziemią przelatywał Dziki Gon: orszak upiornych myśliwych, psów i koni, prowadzony przez demona albo zmarłego króla. Słychać było wycie, tętent i trąbki w wietrze. Kto zobaczył Dziki Gon, mógł zostać porwany. Trzeba było paść na ziemię i zakryć oczy. Zimowa wichura w opowieściach miała twarz.","practice":"• Gdy wieje wiatr w nocy, posłuchaj go uważnie.\n• Spróbuj usłyszeć w nim głosy.\n• Zapisz, czego się dziś boisz, i odłóż kartkę do rana.","extraTitle":"Pytanie na niedzielę","extra":"Jaki wiatr porywa mnie w ciemne noce i dokąd mnie niesie?","whisper":"Wiatr w nocy jest głośny, ale rano zawsze cichnie.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":408}],["2027-12-13","conversation","☽ w Bliźniętach","pełnia",false,{"phase":"pełnia o 17:09","nextPhase":"nów za 14 dni","illumination":100.0,"moonAndBiodynamic":"☽ w Bliźniętach · dzień kwiatu","goodFor":"dobry dzień na rozmowy","energy":"Księżyc w Bliźniętach. Energia męska, działająca. Dobry dzień na rozmowy, telefony, naukę, pisanie i drobne sprawunki. Unikaj rozpraszania się i plotek. Faza: pełnia, czas na kulminację, zbiory i silne emocje. W tradycji Księżyc w Bliźniętach rządzi: ręce i płuca. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Strzelcu · ♀ w Koziorożcu · ♂ w Koziorożcu. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☉△♄ Słońce trygon Saturn (10:22): Dobry dzień na pracę wymagającą wytrwałości, plany długoterminowe i porządki w obowiązkach.\n🌕 Pełnia w Bliźniętach (17:08): Kulminacja w sprawach: rozmowy, nauka, rodzeństwo i sąsiedzi. Emocje są silniejsze. Rada: dokończ, podziękuj, odpuść to, co już nie służy.","sourceText":{"holiday":"św. Łucji","namedays":"Lucji, Otylii","title":"Pełnia najwyżej","subtitle":"Księżyc nad zimowym światem","story":"Dziś wieczorem pełnia. Zimowa pełnia wędruje najwyżej po niebie z całego roku, bo jest po przeciwnej stronie niż Słońce, a Słońce jest teraz najniżej. Księżyc świeci długo, nawet kilkanaście godzin, i oświetla śnieg tak, że można iść bez latarki. Dziś też święta Łucja, która niesie światło w najciemniejszym czasie.","practice":"• Wyjdź wieczorem i porównaj wysokość Księżyca z czerwcową pełnią.\n• Przejdź się w jego świetle.\n• Zapisz, co w tobie świeci najmocniej w ciemności.","extraTitle":"Księżyc","extra":"pełnia 13 XII, 17:09 · nów 27 XII, 21:12","whisper":"W najdłuższe noce Księżyc świeci najdłużej. Ciemność ma swoje światło.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":409}],["2027-12-14","home","☽ w Bliźniętach do 07:24, potem w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 13 dni","illumination":99.0,"moonAndBiodynamic":"☽ w Bliźniętach do 07:24, potem w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Do 07:24 Księżyc jest w Bliźniętach, potem w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: pełnia, czas na kulminację, zbiory i silne emocje. Księżyc bez kursu od 01:04 do 07:24: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"","sourceText":{"holiday":"","namedays":"Alfreda, Izydora","title":"Uszka z grzybami","subtitle":"małe uszy do barszczu","story":"Uszka to maleńkie pierogi z farszem z suszonych grzybów i cebuli, podawane w czerwonym barszczu na Wigilię. Lepienie uszek to rodzinny rytuał: jedni wałkują, inni nakładają farsz, inni sklejają. Im mniejsze, tym lepsza gospodyni, mówiono. Można je przygotować wcześniej i zamrozić.","practice":"• Ugotuj i zmiel namoczone suszone grzyby z podsmażoną cebulą.\n• Rozwałkuj cienko ciasto pierogowe, pokrój w małe kwadraty.\n• Nałóż farsz, złóż w trójkąt i sklej rogi, gotuj 3 minuty.","extraTitle":"Ciekawostka","extra":"Nazwa uszka pochodzi od kształtu: sklejone rogi przypominają małe ucho.","whisper":"Rzeczy robione razem smakują jak wspólnota.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":410}],["2027-12-15","home","☽ w Raku","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 12 dni","illumination":96.0,"moonAndBiodynamic":"☽ w Raku · dzień liścia","goodFor":"dobry dzień na dom","energy":"Księżyc w Raku. Energia żeńska, przyjmująca. Dobry dzień na dom, rodzinę, gotowanie i odpoczynek. Unikaj rozdrapywania starych ran. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc w Raku rządzi: piersi i żołądek. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♆ Neptun rusza naprzód w Baranie (10:06): Wraca natchnienie, intuicja i tęsknota za czymś większym. Rada: twórz, módl się, odpoczywaj nad wodą.","sourceText":{"holiday":"","namedays":"Niny, Celiny","title":"Stroik z gałęzi","subtitle":"zieleń na stole","story":"Przed świętami robiło się stroiki z gałązek jodły, świerku, szyszek, suszonych owoców i świec. Stawiano je na stole, na komodzie, na grobach. Zieleń zimą była symbolem życia, które nie umiera. Robienie stroiku własnymi rękami to cichy rytuał: dotykasz igliwia, wąchasz żywicę, układasz świat w miniaturze.","practice":"• Zbierz kilka gałązek iglaków, szyszek i suszonych plastrów pomarańczy.\n• Ułóż je na talerzu wokół świecy.\n• Postaw stroik tam, gdzie spędzasz wieczory.","extraTitle":"Ciekawostka","extra":"Suszone plastry pomarańczy pachną przez wiele tygodni i były luksusem zimowych stołów.","whisper":"Zieleń w grudniu jest obietnicą, że życie trwa.","caution":"Świeca w stroiku nigdy bez nadzoru.","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":411}],["2027-12-16","creative","☽ w Raku do 08:41, potem we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 11 dni","illumination":90.0,"moonAndBiodynamic":"☽ w Raku do 08:41, potem we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Do 08:41 Księżyc jest w Raku, potem we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 02:42 do 08:41: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"☿□♃ Merkury kwadratura Jowisz (05:45): Napięcie między planetami. Można je wykorzystać na naukę, spotkania biznesowe, wielkie plany i dobre wiadomości. Uważaj na obietnice bez pokrycia i przeoczone szczegóły.\n♀△♃ Wenus trygon Jowisz (21:52): Dobry dzień na relacje, randki, zakupy, umowy i świętowanie.","sourceText":{"holiday":"","namedays":"Albiny, Zdzisławy","title":"Kichnięcie","subtitle":"na zdrowie i na prawdę","story":"Kiedy ktoś kichnął, mówiono na zdrowie, bo wierzono, że przez kichnięcie mogła uciec dusza albo wejść choroba. Ale kichnięcie miało też inną moc: jeśli ktoś kichnął, gdy mówiłaś, to znaczyło, że mówisz prawdę. Mówiono: kichnął, to prawda. Kichnięcie było więc jak pieczęć na słowach.","practice":"• Gdy ktoś kichnie, powiedz mu na zdrowie z uśmiechem.\n• Zauważ, co mówiłaś, gdy ktoś kichnął.\n• Pomyśl, jaką prawdę chcesz dziś powiedzieć.","extraTitle":"Ciekawostka","extra":"Zwyczaj życzenia zdrowia po kichnięciu jest znany w niemal wszystkich kulturach świata.","whisper":"Prawda nie potrzebuje kichnięcia. Ale miło, gdy ktoś potwierdzi.","caution":"","bibliography":"O. Kolberg, Lud; wierzenia ludowe","bookKey":""},"sourceRow":412}],["2027-12-17","creative","☽ we Lwie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 10 dni","illumination":82.0,"moonAndBiodynamic":"☽ we Lwie · dzień owocu","goodFor":"dobry dzień na twórczość","energy":"Księżyc we Lwie. Energia męska, działająca. Dobry dzień na twórczość, randkę, występ i zabawę z dziećmi. Unikaj pychy i obrażania się. Faza: garb ubywający, czas na dzielenie się i wdzięczność. W tradycji Księżyc we Lwie rządzi: serce i plecy. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"","namedays":"Olimpii, Łazarza","title":"Kolorowy opłatek","subtitle":"dla zwierząt","story":"W Wigilię gospodarz zanosił zwierzętom kolorowy opłatek, różowy, żółty albo zielony. Dzielono się nim z krowami, końmi i owcami, by były zdrowe i spokojne cały rok. Wierzono, że zwierzęta są świadkami narodzin Jezusa w stajni i należy im się udział w święcie. Opłatek dla zwierząt był zaproszeniem do wspólnoty.","practice":"• Kup kolorowy opłatek albo przygotuj coś dobrego dla swojego zwierzęcia na Wigilię.\n• Pomyśl o zwierzętach, które są w twoim życiu.\n• Wesprzyj schronisko dla zwierząt przed świętami.","extraTitle":"Ciekawostka","extra":"Kolorowe opłatki dla zwierząt są wciąż sprzedawane w polskich parafiach przed Wigilią.","whisper":"Wspólnota, w której jest miejsce dla zwierząt, jest pełniejsza.","caution":"Nie karm zwierząt jedzeniem wigilijnym, które może im szkodzić.","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":413}],["2027-12-18","organize","☽ we Lwie do 10:16, potem w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 9 dni","illumination":72.0,"moonAndBiodynamic":"☽ we Lwie do 10:16, potem w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Do 10:16 Księżyc jest we Lwie, potem w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: garb ubywający, czas na dzielenie się i wdzięczność. Księżyc bez kursu od 09:56 do 10:16: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"☿ Merkury wchodzi w Koziorożca (12:58): Na kilka tygodni myśli, rozmowy i decyzje płyną w rytmie obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa. Uważaj na surowość wobec siebie i chłód.\n☉□♃ Słońce kwadratura Jowisz (18:42): Napięcie między planetami. Można je wykorzystać na optymizm, prośby, oferty, naukę i podróże. Uważaj na przesadę i obietnice ponad siły.","sourceText":{"holiday":"","namedays":"Gracjana, Bogusława","title":"Słońce nisko","subtitle":"najkrótsze dni","story":"Za kilka dni przesilenie. Słońce w południe wznosi się nad Wrocławiem tylko na około 15 stopni nad horyzontem. Cienie są długie przez cały dzień, a światło złote i miękkie, nawet w samo południe. Dzień trwa niecałe osiem godzin. To najciemniejszy czas, ale też czas najpiękniejszego, niskiego światła.","practice":"• Wyjdź w południe i zobacz, jak długi jest twój cień.\n• Zrób zdjęcie w złotym świetle.\n• Wieczorem zapal świecę i odpocznij.","extraTitle":"Ciekawostka","extra":"Po przesileniu dzień zaczyna się wydłużać najpierw od strony wieczoru, a dopiero później od strony poranka.","whisper":"Najpiękniejsze światło to to, które pada nisko.","caution":"","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":414}],["2027-12-19","organize","☽ w Pannie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 8 dni","illumination":61.0,"moonAndBiodynamic":"☽ w Pannie · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"♀ Wenus wchodzi w Wodnika (19:40): Na kilka tygodni miłość, przyjemności i pieniądze płyną w rytmie przyjaźni, wolności, nowości i wspólnoty. Rada: spotkaj się z ludźmi i spróbuj czegoś nowego. Uważaj na bunt dla buntu i dystans.","sourceText":{"holiday":"","namedays":"Gabrieli, Dariusza","title":"Urodzeni w Wigilię","subtitle":"wilkołaki i jasnowidze","story":"Wierzono, że dziecko urodzone w Wigilię będzie niezwykłe. Mogło zostać wilkołakiem, bo urodziło się w noc, gdy granice między światami są cienkie, albo jasnowidzem, który widzi duchy i przyszłość. Na ochronę od razu po porodzie chrzczono je i wiązano czerwoną nić. Ta wiara mówi o lęku i podziwie wobec tego, co inne.","practice":"• Pomyśl o kimś, kto jest „inny” w twoim otoczeniu.\n• Zastanów się, czy go się boisz, czy podziwiasz.\n• Zrób dla niego coś życzliwego.","extraTitle":"Pytanie na niedzielę","extra":"Co we mnie jest inne i czy pozwalam sobie to pokazać?","whisper":"Inność straszy tylko tych, którzy nie chcą jej zrozumieć.","caution":"","bibliography":"Demonologia ludowa a przyroda, IZPiTN 2026","bookKey":""},"sourceRow":415}],["2027-12-20","organize","☽ w Pannie, od 13:13 w Wadze","III kwadra",false,{"phase":"III kwadra o 10:11","nextPhase":"nów za 7 dni","illumination":49.0,"moonAndBiodynamic":"☽ w Pannie, od 13:13 w Wadze · dzień korzenia","goodFor":"dobry dzień na porządki","energy":"Księżyc w Pannie, od 13:13 w Wadze. Energia żeńska, przyjmująca. Dobry dzień na porządki, zdrowe jedzenie, planowanie i pracę nad szczegółami. Unikaj krytykowania siebie i innych. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. Księżyc bez kursu od 10:10 do 13:13: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Pannie rządzi: brzuch i jelita. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Strzelcu · ☿ w Koziorożcu · ♀ w Wodniku · ♂ w Koziorożcu. Pytanie tygodnia: Dokąd prowadzi Cię ciekawość?\n☿□♆ Merkury w napięciu z Neptunem (23:22): Nieporozumienia, zgubione wiadomości, niedopowiedzenia. Uwaga: sprawdzaj fakty, pytaj wprost.","sourceText":{"holiday":"","namedays":"Bogumiły, Dominika","title":"Goździki","subtitle":"przyprawa świąt","story":"Goździki to suszone pąki kwiatów drzewa z wysp korzennych. Przywożono je z dalekich krajów i były tak drogie, że trzymano je pod kluczem. Pachną świętami: dodaje się je do piernika, grzańca, kompotu z suszu i szynki. W medycynie ludowej znieczulały ból zęba. Dziś ostatnia kwadra: czas na ciepło, które usypia ból.","practice":"• Wbij goździki w pomarańczę i połóż ją w misce na stole.\n• Dodaj kilka goździków do herbaty.\n• Przy bólu zęba przyłóż goździk do dziąsła, a potem idź do dentysty.","extraTitle":"Ciekawostka","extra":"Pomarańcza nabita goździkami to dawny pomander, który odstraszał mole i zapachy w szafach.","whisper":"Ból łagodnieje, gdy ktoś da ci coś ciepłego i pachnącego.","caution":"Olejek goździkowy w dużych dawkach podrażnia. Nie dla małych dzieci.","bibliography":"Ziołolecznictwo ludowe, IZPiTN 2026","bookKey":""},"sourceRow":416}],["2027-12-21","relationships","☽ w Wadze","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 6 dni","illumination":39.0,"moonAndBiodynamic":"☽ w Wadze · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: ostatnia kwadra, czas na porządki i odpuszczanie. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Tomasza, Tomisława","title":"Pierogi z kapustą i grzybami","subtitle":"wigilijne pierożki","story":"Pierogi z kapustą i grzybami są na każdym wigilijnym stole. Kiszona kapusta, duszona długo z cebulą i suszonymi grzybami, zawinięta w cienkie ciasto. Lepi się je dzień albo dwa przed Wigilią, całą rodziną. Podaje się je okraszone cebulką albo smażone na złoto. Liczba pierogów jest zawsze za mała.","practice":"• Ugotuj i posiekaj kiszoną kapustę, duś z cebulą i namoczonymi grzybami.\n• Ostudź farsz, nałóż na krążki ciasta i sklej.\n• Gotuj 3 minuty, podawaj z cebulką.","extraTitle":"Ciekawostka","extra":"W niektórych regionach w jednym pierogu chowano monetę: kto ją znalazł, miał mieć szczęście cały rok.","whisper":"Pierogi lepione razem łączą lepiej niż wiele słów.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":417}],["2027-12-22","relationships","☽ w Wadze, od 18:00 w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 5 dni","illumination":29.0,"moonAndBiodynamic":"☽ w Wadze, od 18:00 w Skorpionie · dzień kwiatu","goodFor":"dobry dzień na rozmowy o związku","energy":"Księżyc w Wadze, od 18:00 w Skorpionie. Energia męska, działająca. Dobry dzień na rozmowy o związku, umowy, urodę i sztukę. Unikaj odkładania decyzji w nieskończoność. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 02:00 do 18:00: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wadze rządzi: nerki i biodra. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"☉ Słońce wchodzi w Koziorożca (03:42): Na miesiąc cały świat nabiera barw znaku Koziorożca: czas obowiązków, kariery, struktury i cierpliwości. Rada: zaplanuj krok po kroku i dotrzymaj słowa.\n♀✶♆ Wenus sekstyl Neptun (23:08): Dobry dzień na romantyzm, sztukę, muzykę i współczucie.","sourceText":{"holiday":"przesilenie zimowe, 03:42","namedays":"Zenona, Honoraty","title":"Noc czuwania","subtitle":"przesilenie zimowe","story":"Dziś o 3:42 nad ranem przesilenie zimowe. Najdłuższa noc roku właśnie się skończyła. Dawni Słowianie świętowali Szczodre Gody, odrodzenie słońca, paląc ognie i czuwając do świtu, by pomóc słońcu wrócić. Od jutra dni będą dłuższe. Zapal świecę wieczorem i pozwól jej płonąć długo, w podzięce za powrót światła.","practice":"• Wieczorem zapal świecę i pozwól jej palić się przez cały wieczór.\n• Zapisz, co chcesz zostawić w ciemności tego roku.\n• Zapisz, co chcesz wnieść w światło.","extraTitle":"Ciekawostka","extra":"Od jutra dzień będzie się wydłużał. Do końca stycznia zyska ponad godzinę.","whisper":"Słońce wraca zawsze. Nawet po najdłuższej nocy.","caution":"Świeca tylko pod nadzorem.","bibliography":"Dane astronomiczne 2027 (obliczenia dla Wrocławia)","bookKey":""},"sourceRow":418}],["2027-12-23","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 4 dni","illumination":20.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♂□♄ Mars w napięciu z Saturnem (05:00): Hamulec i gaz naraz. Frustracja, opór, zmęczenie. Uwaga: zwolnij, nie przepychaj spraw na siłę.","sourceText":{"holiday":"","namedays":"Wiktorii, Sławomiry","title":"Jaka Wigilia, taki cały rok","subtitle":"zasada dnia przed","story":"Wierzono, że wszystko, co dzieje się w Wigilię, będzie się powtarzać przez cały następny rok. Dlatego dzień przed nią kończono kłótnie, oddawano długi, sprzątano dom i niczego nie pożyczano z domu w samą Wigilię. Kto w Wigilię płakał, płakał cały rok. Kto był wesoły i spokojny, miał dobry rok.","practice":"• Oddaj dziś drobny dług albo pożyczkę.\n• Pogódź się z kimś albo napisz słowo zgody.\n• Zaplanuj Wigilię tak, by była spokojna, nie idealna.","extraTitle":"Ciekawostka","extra":"Pierwszy gość w Wigilię też był wróżbą: mężczyzna przynosił szczęście, kobieta kłopoty. Dziś z tego się śmiejemy.","whisper":"Spokój nie musi być idealny. Wystarczy, że jest.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":419}],["2027-12-24","honesty","☽ w Skorpionie","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 3 dni","illumination":12.0,"moonAndBiodynamic":"☽ w Skorpionie · dzień liścia","goodFor":"dobry dzień na szczere rozmowy","energy":"Księżyc w Skorpionie. Energia żeńska, przyjmująca. Dobry dzień na szczere rozmowy, terapię, bliskość i porządki w finansach. Unikaj zazdrości i gier o władzę. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. Księżyc bez kursu od 19:11 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Skorpionie rządzi: podbrzusze. Dzień liścia: sprzyja sałatom, ziołom liściastym i podlewaniu.","transits":"♄ Saturn rusza naprzód w Baranie (03:47): Struktury się stabilizują. To, co było w zawieszeniu, zaczyna mieć ramy. Rada: zapisz plan na najbliższe miesiące i trzymaj się go.\n♀☌♇ Wenus koniunkcja Pluton (11:55): Dobry dzień na głębokie uczucia, intymność i odnowę w relacjach. Uważaj tylko na zazdrość i zaborczość.","sourceText":{"holiday":"Wigilia Bożego Narodzenia","namedays":"Adama, Ewy","title":"Wigilia","subtitle":"opłatek i dwanaście potraw","story":"Gdy na niebie zabłyśnie pierwsza gwiazda, siada się do stołu. Najpierw opłatek: łamiesz go z każdym, patrzysz w oczy, składasz życzenia. Potem dwanaście potraw, tyle, ilu było apostołów i ile miesięcy w roku. Barszcz, karp, pierogi, kapusta z grochem, kutia, makowiec. Każdej potrawy trzeba spróbować, by w każdym miesiącu było dobrze.","practice":"• Przed kolacją wyjdź i poszukaj pierwszej gwiazdy.\n• Przełam się opłatkiem i powiedz każdemu jedno szczere życzenie.\n• Spróbuj każdej potrawy, choćby łyżkę.","extraTitle":"Ciekawostka","extra":"„Pierwsza gwiazda” to często wcale nie gwiazda, tylko jasna planeta, na przykład Wenus albo Jowisz.","whisper":"Życzenie wypowiedziane patrząc w oczy ma moc większą niż każde zaklęcie.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":420}],["2027-12-25","travel","☽ w Skorpionie do 00:50, potem w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 2 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Skorpionie do 00:50, potem w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Do 00:50 Księżyc jest w Skorpionie, potem w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: sierp ubywający, czas na odpoczynek, regenerację i oczyszczanie. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"♀△♅ Wenus trygon Uran (10:48): Dobry dzień na nowe znajomości, niespodzianki i zmianę wizerunku.\n☉□♆ Słońce kwadratura Neptun (23:12): Napięcie między planetami. Można je wykorzystać na intuicję, sztukę, medytację i pomoc innym. Uważaj na złudzenia, zmęczenie i niejasne sytuacje.","sourceText":{"holiday":"Boże Narodzenie","namedays":"Anastazji, Eugenii","title":"Boże Narodzenie","subtitle":"pasterka i szopka","story":"O północy z Wigilii na Boże Narodzenie odprawia się pasterkę, mszę pasterzy, na pamiątkę tych, którzy pierwsi przyszli do stajenki. W kościołach stoją szopki, a w Krakowie szopki krakowskie, wieżyczkowe, kolorowe, z postaciami z historii miasta. Dzień Bożego Narodzenia jest spokojny, rodzinny, bez pracy i gości. Czas bycia razem.","practice":"• Odwiedź szopkę w kościele albo zrób małą szopkę w domu.\n• Zostań dziś w domu z bliskimi.\n• Zaśpiewaj ulubioną kolędę.","extraTitle":"Ciekawostka","extra":"Szopkarstwo krakowskie zostało w 2018 roku wpisane na listę niematerialnego dziedzictwa ludzkości UNESCO.","whisper":"Narodziny światła świętuje się w ciszy, wśród bliskich.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":421}],["2027-12-26","travel","☽ w Strzelcu","Księżyc ubywający",false,{"phase":"Księżyc ubywający","nextPhase":"nów za 1 dzień","illumination":2.0,"moonAndBiodynamic":"☽ w Strzelcu · dzień owocu","goodFor":"dobry dzień na podróże","energy":"Księżyc w Strzelcu. Energia męska, działająca. Dobry dzień na podróże, naukę, spacer w plenerze i plany na przyszłość. Unikaj obietnic bez pokrycia. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Strzelcu rządzi: uda i wątroba. Dzień owocu: sprzyja pracom przy roślinach owocujących i siewie zbóż.","transits":"","sourceText":{"holiday":"drugi dzień Bożego Narodzenia · św. Szczepana","namedays":"Jana, Żanety","title":"Święty Szczepan","subtitle":"dzień nowej służby","story":"Na świętego Szczepana parobkowie i służące kończyli roczną służbę i mogli zmienić gospodarza. Był to dzień wolności i rozliczeń. Odwiedzano się, chodzono z kolędą, a w kościele obsypywano się owsem. Szczepan był pierwszym męczennikiem. Dzień po narodzinach przypomina, że życie to też wybór i odwaga.","practice":"• Zastanów się, czy chcesz coś zmienić w swojej „służbie”: pracy, roli, obowiązkach.\n• Zapisz to na kartce.\n• Odwiedź dziś kogoś bliskiego.","extraTitle":"Pytanie na niedzielę","extra":"Gdzie chcę zmienić gospodarza w swoim życiu?","whisper":"Każdy rok kończy się dniem, w którym można odejść albo zostać z wyboru.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":422}],["2027-12-27","work","☽ w Strzelcu do 09:50, potem w Koziorożcu","nów",false,{"phase":"nów o 21:12","nextPhase":"pełnia za 16 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Strzelcu do 09:50, potem w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Do 09:50 Księżyc jest w Strzelcu, potem w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 04:13 do 09:50: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"🗓 Tydzień pod niebem (tydzień): ☉ w Koziorożcu · ☿ w Koziorożcu · ♀ w Wodniku · ♂ w Koziorożcu. Pytanie tygodnia: Jaki cel budujesz krok po kroku?\n🌑 Nów w Koziorożcu (21:12): Czas zasiewu w sprawach: praca, ambicja, odpowiedzialność. Rada: zapisz intencję na ten księżycowy miesiąc.","sourceText":{"holiday":"św. Jana · święcenie wina","namedays":"Teofili, Godzisława","title":"Kielich świętego Jana","subtitle":"święty Jan i trucizna","story":"Dziś święty Jan Ewangelista. Legenda mówi, że podano mu kielich z trucizną, a on go pobłogosławił i trucizna wyszła z niego jak wąż. Dlatego w ten dzień święci się wino, które chroni przed truciznami i chorobą. Dziś też nów, ostatni w tym roku. Dobry dzień, by zapytać, co cię truje, i to pobłogosławić albo wylać.","practice":"• Pomyśl o czymś, co cię truje: nawyku, relacji, myśli.\n• Zapisz to i postanów, czy chcesz to przemienić, czy porzucić.\n• Zapisz intencję na ostatni księżycowy miesiąc roku.","extraTitle":"Ciekawostka","extra":"Na obrazach święty Jan często trzyma kielich, z którego wypełza mały wąż albo smok.","whisper":"Nie wszystko, co cię truje, trzeba wypić. Niektóre rzeczy wystarczy wylać.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":423}],["2027-12-28","work","☽ w Koziorożcu","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 15 dni","illumination":0.0,"moonAndBiodynamic":"☽ w Koziorożcu · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"Młodzianków","namedays":"Jana, Maksyma","title":"Młodzianki","subtitle":"rózga na zdrowie","story":"Dziś wspomnienie dzieci zamordowanych przez Heroda. Na wsi w ten dzień rodzice smagali dzieci rózgą, ale nie za karę, tylko na zdrowie, by rosły silne i nie chorowały. Mówiono przy tym: na zdrowie, na szczęście. Chodzono też po domach z życzeniami. Dzień pamięci o najbezbronniejszych stał się dniem błogosławieństwa dla dzieci.","practice":"• Pomyśl o dzieciach w twoim życiu i złóż im życzenia.\n• Wesprzyj organizację, która pomaga dzieciom.\n• Powiedz dziecku, które znasz, coś dobrego o nim.","extraTitle":"Ciekawostka","extra":"W niektórych regionach w Młodzianki dzieci mogły rządzić w domu przez cały dzień.","whisper":"Dzieci chroni się nie rózgą, ale błogosławieństwem.","caution":"","bibliography":"Z. Gloger, Rok polski w życiu, tradycyi i pieśni","bookKey":""},"sourceRow":424}],["2027-12-29","work","☽ w Koziorożcu, od 21:04 w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 14 dni","illumination":2.0,"moonAndBiodynamic":"☽ w Koziorożcu, od 21:04 w Wodniku · dzień korzenia","goodFor":"dobry dzień na pracę","energy":"Księżyc w Koziorożcu, od 21:04 w Wodniku. Energia żeńska, przyjmująca. Dobry dzień na pracę, sprawy urzędowe, plany długoterminowe i dyscyplinę. Unikaj zbytniej surowości wobec siebie. Faza: nów, czas na zasiew, ciszę i intencje. Księżyc bez kursu od 15:28 do 21:04: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Koziorożcu rządzi: kolana, kości i skóra. Dzień korzenia: sprzyja sadzeniu i zbiorom warzyw korzeniowych.","transits":"","sourceText":{"holiday":"","namedays":"Dawida, Tomasza","title":"Słoik dobrych chwil","subtitle":"zbiór roku","story":"Koniec roku to czas, by zebrać to, co było dobre. Wypisz na małych karteczkach dobre chwile tego roku, jedną na każdą kartkę. Wrzuć je do słoika. Możesz czytać je w trudne dni albo za rok w ostatnim tygodniu grudnia. Słoik dobrych chwil to przetwór, który nie psuje się nigdy.","practice":"• Wypisz na karteczkach dziesięć dobrych chwil tego roku.\n• Wrzuć je do słoika i zakręć.\n• Postaw słoik w widocznym miejscu.","extraTitle":"Ciekawostka","extra":"Zapisywanie dobrych wydarzeń jest jedną z najlepiej przebadanych praktyk poprawiających nastrój.","whisper":"Dobre chwile zapisane nie giną. Czekają na ciebie w słoiku.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":425}],["2027-12-30","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 13 dni","illumination":6.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"","sourceText":{"holiday":"","namedays":"Irminy, Eugeniusza","title":"Co w Sylwestra, to cały rok","subtitle":"ostatnie porządki","story":"Wierzono, że jak spędzisz ostatnie dni roku, tak spędzisz cały następny. Dlatego oddawano długi, by nie mieć ich przez cały rok, sprzątano dom, by nie wnosić bałaganu w nowy czas, i przygotowywano pełną spiżarnię. W kieszeni trzymano monetę albo łuskę karpia, by nie zabrakło pieniędzy.","practice":"• Oddaj ostatnie długi albo zaplanuj ich spłatę.\n• Posprzątaj jedno miejsce, które czeka od miesięcy.\n• Włóż do portfela łuskę karpia z Wigilii albo monetę.","extraTitle":"Ciekawostka","extra":"Zwyczaj noszenia łuski karpia w portfelu przetrwał w Polsce, Czechach i na Słowacji.","whisper":"Kto kończy rok porządkiem, ten zaczyna nowy z lekkością.","caution":"","bibliography":"Tradycja ludowa","bookKey":""},"sourceRow":426}],["2027-12-31","social","☽ w Wodniku","Księżyc przybywający",false,{"phase":"Księżyc przybywający","nextPhase":"pełnia za 12 dni","illumination":11.0,"moonAndBiodynamic":"☽ w Wodniku · dzień kwiatu","goodFor":"dobry dzień na spotkania z przyjaciółmi","energy":"Księżyc w Wodniku. Energia męska, działająca. Dobry dzień na spotkania z przyjaciółmi, nowe pomysły, technologię i wolontariat. Unikaj buntu dla buntu. Faza: sierp przybywający, czas na pierwsze kroki i odwagę. Księżyc bez kursu od 15:41 do nocy: nie zaczynaj wtedy nowych spraw i nie podpisuj ważnych umów. W tradycji Księżyc w Wodniku rządzi: łydki i krążenie. Dzień kwiatu: sprzyja roślinom kwitnącym i zbieraniu kwiatów ziół.","transits":"♂△♃ Mars w harmonii z Jowiszem (05:32): Dobry dzień na odważne działanie, sport i podróż. Rada: zrób krok, którego się bałaś.\n☿□♄ Merkury kwadratura Saturn (16:59): Napięcie między planetami. Można je wykorzystać na skupioną pracę, umowy, planowanie i dokumenty. Uważaj na ciężkie myśli, opóźnienia i krytykę.","sourceText":{"holiday":"Sylwester","namedays":"Melanii, Sylwestra","title":"Sylwester","subtitle":"ostatnia kartka Baby Jagi","story":"Dziś ostatnia kartka. Rok zatoczył koło: od listopadowych zniczy, przez zimowe przesilenie, wiosenne zielenie, letnie ognie Kupały, jesienne zbiory, aż tu. Babcia Jaga, która mieszka na skraju świata, pyta cię o jedno: czego się nauczyłaś? Zapisz to, zanim wybije północ. Za chwilę nowy kalendarz, nowe kartki, nowy kocioł.","practice":"• Przejrzyj kartki, które zachowałaś z tego kalendarza.\n• Zapisz trzy rzeczy, których się w tym roku nauczyłaś.\n• O północy pomyśl życzenie i wrzuć ostatnią kartkę do kociołka.","extraTitle":"Pytanie do dziennika","extra":"Czego nauczył mnie ten rok, czego nie wiedziałam rok temu?","whisper":"Koło się obraca. Kto słucha starej mądrości, nigdy nie zaczyna od zera.","caution":"","bibliography":"Tekst autorski Kalendarza Jagi","bookKey":""},"sourceRow":427}]],"chapters":{"2026-11-02":{"title":"Bylica pospolita","subtitle":"Artemisia vulgaris L. · rodzina astrowate","text":"Nazwy ludowe: bielica, belica, bulica, balica, na wschodzie czarnobyl. Marcin Siennik w XVI w. pisał, że „bylicę niektórzy zowią matką zielną, a to dla jej wielkiej mocy”. Nazwa pochodzi od prasłowiańskiego *bylь („roślina, ziele”), od czasownika „być” w znaczeniu „rosnąć, dojrzewać”.\n\nJak ją rozpoznać: Wysoka bylina, zwykle do 1,5–2 m. Łodyga sztywna, często czerwonawa. Liście pierzasto wcinane, z wierzchu ciemnozielone, od spodu srebrzystobiałe. To najpewniejszy znak, wystarczy odwrócić liść. Od lipca do września drobne żółtawe lub rdzawe koszyczki w wiechach. Rośnie przy drogach, rowach, na nieużytkach. Pachnie gorzko-ziołowo.\n\nW wierzeniach: „Matka wszystkich ziół” (mater herbarum). Święcona w zielnych bukietach na Matki Boskiej Zielnej, 15 sierpnia. Noszona przy sobie i trzymana w domu miała chronić przed złymi mocami i przed jadowitymi stworzeniami, zwłaszcza wężami. Zioło kobiet: już od XVI w. była podstawą dawnych środków na cykl, poród i „przypadłości kobiece”.\n\nZastosowanie: W kuchni: gorzkawa przyprawa do tłustych potraw. To klasyczny dodatek do pieczonej gęsi, kaczki i wieprzowiny, bo goryczka pomaga trawić tłuszcz. Bierze się szczyty pędów z pąkami, zanim kwiaty się otworzą.\nW domu: pęczek nad drzwiami, ziele do okadzania przy domowych rytuałach oczyszczenia.\nW dzisiejszej praktyce: saszetka pod poduszkę „na wyraziste sny”.\n\nZbiór i suszenie: Górne części pędów na początku kwitnienia, lipiec–sierpień, w suchy dzień, z dala od ruchliwych dróg. Suszyć w luźnych pęczkach, w cieniu i przewiewie. Przechowywać w papierze lub słoju, z dala od światła.","caution":"Nie w ciąży: bylica pobudza macicę i właśnie po to stosowano ją dawniej. Ostrożnie przy karmieniu piersią. Jej pyłek to jeden z najsilniejszych alergenów jesieni, więc osoby uczulone na rośliny astrowate (np. rumianek, arnikę) powinny uważać. Nie do długotrwałego picia.","quote":"","bibliography":"„Ludowe nazwy ziół”, Instytut Zielarstwa Polskiego i Terapii Naturalnych, 2026; M. Siennik, Herbarz, 1568."},"2026-11-03":{"title":"Pieprz ziołowy dawnych Słowian","subtitle":"co robi każdy składnik","text":"Skąd ta mieszanka: We wczesnym średniowieczu doprawiano solą, octem i roślinami uprawnymi oraz dzikimi: kminkiem, kolendrą, chrzanem, czosnkiem, gorczycą, miętą i jałowcem. Klasztory dołożyły rozmaryn i cząber. Skład dzisiejszego „pieprzu ziołowego” ze sklepu jest niemal identyczny.\n\nSkładniki i ich rola: Gorczyca: ostrość i ciepło, podstawa marynat i kiszonek.\nKolendra (owoce): cytrusowa nuta, dawniej do pieczywa i mięs.\nKminek: klasyk do kapusty, chleba i serów, ludowo „na wzdęcia”.\nMajeranek: zioło żuru, grochówki i kiełbas, pomaga przy ciężkich potrawach.\nCzosnek: w wierzeniach najsilniejsza ochrona przed złem, upiorami i urokami.\nChrzan: ostry korzeń, nieodzowny na wielkanocnym stole.\n\nWarianty: Na zimę dodaj szczyptę rozkruszonego jałowca (do dziczyzny i kapusty). Do kasz i strączków cząber i lubczyk, do pieczywa czarnuszkę.\n\nPrzechowywanie: W szczelnym, ciemnym słoiku do ok. 3 miesięcy. Najlepiej mielić małe porcje, bo aromat ulatnia się szybko.","caution":"Gorczyca należy do alergenów, które w UE muszą być oznaczane na etykietach. Owoce jałowca: z umiarem, nie w ciąży ani przy chorobach nerek.","quote":"","bibliography":"„Przyprawy w kuchni ludowej”, Instytut Zielarstwa Polskiego i Terapii Naturalnych, 2026."},"2026-11-04":{"title":"Rytuał ubywającego Księżyca","subtitle":"dlaczego działa i jak go pogłębić","text":"Logika ludowa: W kalendarzu ludowym przybywający Księżyc sprzyjał temu, co miało rosnąć, a ubywający temu, co miało maleć i odejść: odczynianiu, pozbywaniu się brodawek, wyrywaniu chwastów, porządkom. Nasz rytuał korzysta z tej samej logiki: najpierw domknąć, potem zacząć.\n\nKiedy: Najlepiej po zachodzie słońca (dziś 16:23), w dniach przed nowiem. Ten cykl kończy się nowiem 9 listopada o 8:02.\n\nWersje bez ognia: Woda: zapisz słowo ołówkiem na kartce, rozmocz ją w misce wody i wylej wodę do ziemi poza domem.\nZiemia: zapisz na suchym liściu i zakop pod drzewem.\nOddech: 9 oddechów z wydechem dwa razy dłuższym niż wdech, a z każdym wydechem wyobraź sobie, że rzecz robi się mniejsza, jak Księżyc.\n\nPytania do dziennika: Co zabiera mi najwięcej energii, a nic nie daje w zamian?\nCo robię z przyzwyczajenia, a nie z wyboru?\nZ czego zrezygnuję, żeby w nowiu było miejsce na coś nowego?","caution":"Świeca zawsze na stabilnej, niepalnej podstawce, z dala od firanek, nigdy bez nadzoru.","quote":"","bibliography":"Rytuał autorski na motywach ludowych wierzeń księżycowych."},"2026-11-05":{"title":"Len, mara i czwartkowe wieczory","subtitle":"Linum usitatissimum · roślina magiczna","text":"Kim była mara: Mara, zmora: nocny demon, który siadał śpiącym na piersi i dusił, plątał też włosy i grzywy koni. Wierzono, że zmorą może być nawet żywa osoba, której dusza nocą opuszcza ciało. Dlatego przy pracy w niebezpieczne wieczory sięgano po ochronę: chleb, znak krzyża, słowa modlitwy.\n\nWierzenia przy lnie: Przy przędzeniu w czwartek wieczorem trzymano w ustach skórkę chleba i kreślono znak krzyża nad pracą przeciw zmorze, kłobukowi i „innemu lichu”. Nie przędło się w święta ani gdy w domu było nieochrzczone dziecko. Osnowę przyniesioną z innej wsi przytrzaskiwano drzwiami i przekręcano klucz, żeby chronić wieś przed wilkami.\n\nLen w obrzędach: Uprawiany już w neolicie. W Egipcie powstawały z niego bandaże, w które owijano mumie. U nas białe płótno lniane symbolizowało doskonałość i życie wieczne, owijano nim zmarłych. Sezon przędzenia trwał jesienią i zimą: to wtedy powstawała przędza lniana, wełniana i konopna.\n\nKiedy siać: Len siano po zimnych ogrodnikach (12–14 maja), na Kielecczyźnie na św. Zofii, 15 maja, a na Mazurach na św. Medarda, 8 czerwca. Przysłowie: „Chcesz mieć kęs płótna dobrego, siej len na świętego Jerzego”.","caution":"","quote":"","bibliography":"„Palenie lnu w medycynie ludowej”, Instytut Zielarstwa Polskiego i Terapii Naturalnych, 2026."},"2026-11-06":{"title":"Dziurawiec zwyczajny","subtitle":"Hypericum perforatum L. · ziele świętojańskie","text":"Nazwy ludowe: przestrzelon, postrzelon, przezorek, krzyżowe ziele, krzyżowe drzewko, boża krewka, krew Chrystusa, ziele świętojańskie, dzwonki Panny Maryi. Łacińskie zielniki nazywały go fuga daemonum, czyli „ucieczka demonów”.\n\nJak go rozpoznać: Do ok. 60–80 cm. Liście naprzeciwległe, podłużnie jajowate. Pod światło widać w nich jasne kropki: to zbiorniczki olejku, stąd „dziurki”. Kwiaty złotożółte, pięciopłatkowe, z czarnymi kropkami na brzegach płatków. Roztarte barwią palce na czerwono, stąd „krew” w nazwach. Kwitnie VI–VIII, najpiękniej około św. Jana.\n\nW wierzeniach: Legenda mówi, że diabeł przestrzelił liście z zazdrości o ich moc. Noszony przy sobie i kurzony w domu był „lekarstwem przeciw nagrawaniu szatańskiemu”. Zbierany w noc świętojańską miał mieć największą siłę, wieszano go w oknach i nad drzwiami.\n\nZastosowanie: Czerwony olej: świeże kwiaty luźno w słoik, zalać olejem roślinnym, postawić w słońcu na 4–6 tygodni, aż olej zrobi się rubinowy, potem przecedzić. Tradycyjnie na skórę: drobne otarcia, zmęczone mięśnie.\nNapar: dawniej „na trawienie i na smutki”. Współczesna fitoterapia potwierdza jego działanie w łagodnym obniżeniu nastroju i właśnie dlatego to roślina silna, a nie niewinna herbatka.\n\nZbiór: Kwitnące szczyty pędów, czerwiec–lipiec, w słoneczne południe. Suszyć w cieniu, w cienkich warstwach.","caution":"Wchodzi w interakcje z wieloma lekami, m.in. antykoncepcją hormonalną (może ją osłabić), lekami przeciwzakrzepowymi, przeciwdepresyjnymi, immunosupresyjnymi, niektórymi lekami na serce i HIV. Uwrażliwia skórę na słońce, więc po naparze lub oleju unikaj opalania i solarium. Nie w ciąży i podczas karmienia. Przed piciem porozmawiaj z lekarzem lub farmaceutą.","quote":"","bibliography":"„Ludowe nazwy ziół”, Instytut Zielarstwa Polskiego i Terapii Naturalnych, 2026."},"2026-11-07":{"title":"Księżyc w kalendarzu ludowym","subtitle":"nów 9 XI, 8:02 · pełnia 24 XI, 15:53","text":"Cykl: Od nowiu do nowiu mija średnio 29,5 dnia. Nów, potem Księżyc przybywający, pierwsza kwadra, pełnia, a od pełni ubywający, ostatnia kwadra i znów nów. Listopadowa pełnia 2026 to superpełnia: Księżyc będzie wtedy wyjątkowo blisko Ziemi.\n\nWierzenia gospodarskie: To, co rośnie nad ziemią, siano przy przybywającym Księżycu, a warzywa korzeniowe przy ubywającym. Włosy strzyżono przy przybywającym, „żeby szybciej rosły”. Drewno na opał i budowę ścinano przy ubywającym, bo miało mniej pękać i dłużej służyć.\n\nFakt czy wiara?: Fazy Księżyca to astronomia, a powyższe reguły to wiedza ludowa. Część z nich nie ma potwierdzenia w badaniach, ale wszystkie mają jedną zaletę: każą żyć w rytmie, a nie w pośpiechu.\n\nNa nów: Zapisz jedną intencję na cykl, nie listę. Wróć do niej w pełni 24 listopada i zobacz, co się wydarzyło.","caution":"","quote":"","bibliography":"Daty faz Księżyca: czas polski (CET), listopad 2026."},"2026-11-08":{"title":"Błędne ogniki i inne zwodzące duchy","subtitle":"demonologia ludowa mokradeł i dróg","text":"Skąd „manowce”: Słowo wiąże się z prasłowiańskim czasownikiem mamić, czyli łudzić, zwodzić, oszukiwać. Pierwotnie manowce to były „błędne drogi, prowadzące donikąd”.\n\nRodzina zwodzicieli: Błędne ogniki: światła torfowisk, podmokłych łąk i cmentarzy.\nProwadnik: mylił szlaki wędrowców po zmroku, wabiąc ich głosem dziewczyny wołającej o pomoc albo kwileniem dziecka. Ratunek: położyć się na ziemi i przeczekać.\nBłędnica: wodziła w głąb boru. Jedyną obroną było przekupstwo.\nBełty: przy gościńcach powodowały nagłą utratę orientacji.\n\nCo mówi nauka: Światła nad mokradłami tłumaczy się najczęściej samozapłonem gazów z rozkładu materii organicznej (metanu i fosforowodoru). Zjawisko jest rzadko obserwowane i do dziś nie do końca wyjaśnione, więc trochę tajemnicy zostało.","caution":"","quote":"Za jakim światłem idę teraz w swoim życiu i czy ono prowadzi mnie do domu, czy na manowce?","bibliography":"„Demony ludowe a przyroda”, K. Czepiel, Instytut Zielarstwa Polskiego i Terapii Naturalnych, 2026."},"2026-11-09":{"title":"Jałowiec pospolity","subtitle":"Juniperus communis L. · rodzina cyprysowate","text":"Jak go rozpoznać: Krzew albo niewysokie drzewko o pokroju kolumny lub rozłożystej kępy. Igły są ostre, sztywne i kłujące. Wyrastają po trzy w okółku, a na ich wierzchu biegnie jeden biały pasek. Jałowiec jest dwupienny, więc „jagody” noszą tylko krzewy żeńskie. Botanicznie to nie jagody, lecz szyszki o zrośniętych, mięsistych łuskach. Dojrzewają dwa, a nawet trzy lata. Dlatego na jednej gałązce wiszą naraz zielone i granatowe, przyprószone siwym nalotem.\n\nDym, który leczył powietrze: Dawniej choroby zakaźne tłumaczono złym, „morowym” powietrzem. Skoro zło siedzi w powietrzu, trzeba je wykurzyć. Dym jałowca należał do najważniejszych środków tej obrony. Gałązki palono w izbach, w oborach, przy chorych i przy zmarłych. W wielu regionach okadzano nim dom także w czasie świąt, kiedy granica między światami była najcieńsza. Pod tym dawnym wierzeniem kryje się prawdziwa obserwacja: olejek jałowcowy działa odkażająco, a przewietrzona i okadzona izba była po prostu zdrowsza.\n\nW kuchni i spiżarni: Kilka rozgniecionych szyszkojagód zmienia potrawę. Dodaje się je do kiszonej kapusty, bigosu, dziczyzny i marynat, bo ich żywiczna, lekko słodka nuta przełamuje tłuszcz i ciężkość mięsa. Na jałowcu wędzono szynki i kiełbasy. Tak powstały wędliny „jałowcowe”, które do dziś są znakiem rozpoznawczym wielu regionów. Z owoców robiono też nalewkę, a ich aromat jest sercem dżinu. Wystarczają 3–4 owoce na garnek. Więcej to już przesada.\n\nW domowej praktyce: Jałowiec to roślina progu i przejścia. Nadaje się na dni, w których coś się kończy, a coś zaczyna, na przykład na nów, przeprowadzkę albo powrót z choroby. Najprostszy rytuał wygląda tak: otwórz szeroko okna, roztrzyj w dłoniach kilka owoców i przejdź z tym zapachem przez cały dom, od najdalszego kąta do drzwi. Nie chodzi o magię dymu, tylko o świadome „wymiecenie” starego powietrza. Zapach jałowca to czysty, chłodny i leśny sygnał, że zaczynasz od nowa.\n\nZbiór: Zbiera się tylko owoce dojrzałe, granatowe, jesienią i zimą. Najlepiej strząsać je na płachtę, w rękawicach, bo igły potrafią pokłuć do krwi. Suszy się je w przewiewnym, zacienionym miejscu i przechowuje w szczelnym słoju. Jałowiec rośnie powoli i dożywa kilkuset lat, więc zbieraj z umiarem i tylko z krzewów, które dobrze znasz.","caution":"Nie w ciąży, przy chorobach nerek ani przy stanach zapalnych dróg moczowych. Owoców nie stosuje się dłużej niż przez kilka tygodni. Nie myl go z jałowcem sabińskim, częstym w ogrodach. Ma drobne, łuskowate igły przylegające do gałązek i przykry zapach po roztarciu, a jest silnie trujący.","quote":"Zanim wpuścisz nowe, wypuść stare przez otwarte okno.","bibliography":"K. Moszyński, Kultura ludowa Słowian; Z. Gloger, Encyklopedia staropolska; monografia EMA Juniperi pseudo-fructus."},"2026-11-18":{"title":"Próg domu","subtitle":"granica, której się nie lekceważy","text":"Dlaczego próg: Dla dawnego człowieka dom nie był tylko budynkiem. Był małym, uporządkowanym światem, otoczonym światem dzikim, obcym i nieprzewidywalnym. Próg leżał dokładnie na ich styku. Każde jego przekroczenie oznaczało przejście z jednego porządku do drugiego. Dlatego wokół progu narosło tyle zakazów i gestów. Nie wynikały z lęku, tylko z szacunku dla granicy. Kto wie, gdzie kończy się jego dom, ten wie, co do niego wpuszcza.\n\nCo kryło się pod progiem: Pod próg nowego domu wkładano rzeczy, które miały go chronić: monety na dostatek, sól, święcone zioła, czasem kawałek żelaza. Według części wierzeń pod progiem przebywały dusze przodków, opiekunowie rodu. Dlatego nie wolno było na nim siadać, rąbać drewna ani wylewać na niego pomyj. Próg był więc trochę jak domowy ołtarz, po którym chodzi się codziennie.\n\nGesty przy progu: Przez próg nie podawano sobie rąk i nie witano się w drzwiach, bo taka rozmowa zaczynała się „między światami” i mogła przynieść kłótnię. Pannę młodą przenoszono przez próg, by nie potknęła się o nowy dom. Potknięcie wróżyło nieszczęście, a niesiona nie mogła go wnieść. Kiedy wynoszono zmarłego, trumną stukano trzy razy o próg. Było to pożegnanie z domem, żeby dusza wiedziała, że już tu nie wraca. Kobieta po porodzie nie przekraczała progu, dopóki nie przeszła wywodu w kościele.\n\nMiotła i zmierzch: Zamiatano zawsze od drzwi do środka izby, a śmieci wynoszono przed zmrokiem. Po zachodzie słońca nie wyrzucano niczego za próg, bo razem ze śmieciami wymiatało się szczęście i dobrobyt. Nie zamiatano też w dniu pogrzebu ani wtedy, gdy ktoś z domowników był w drodze. Ten zakaz można rozumieć dosłownie albo jako mądrość o rytmie dnia: wieczór jest od odpoczynku, nie od pozbywania się.\n\nTwój próg dzisiaj: Próg nie musi być drewniany, żeby działał. Zatrzymaj się przy drzwiach na jeden oddech, zanim wejdziesz do domu po pracy. Zostaw tam to, czego nie chcesz wnosić. Umyj próg i wycieraczkę, a pod wycieraczką możesz położyć gałązkę jałowca albo szczyptę soli. Najważniejszy jest jednak próg niewidzialny, czyli to, kogo i co wpuszczasz do swojego życia. Ludowa mądrość mówi tu jasno: pilnuj progu, a dom upilnuje się sam.","caution":"","quote":"Próg pierwszy wita i ostatni żegna. Warto o niego dbać.","bibliography":"K. Moszyński, Kultura ludowa Słowian; O. Kolberg, Lud; Z. Gloger, Encyklopedia staropolska."},"2026-11-23":{"title":"Głóg","subtitle":"Crataegus monogyna Jacq. · rodzina różowate","text":"Krzew miedzy i żywopłotu: Głóg rośnie wszędzie tam, gdzie człowiek wyznaczał granice: na miedzach, przy drogach, na skrajach pastwisk. Ma klapowane liście, mocne ciernie i drobne, białe kwiaty w baldachogronach. Kwiaty pachną dziwnie, mdło i trochę zwierzęco, bo zawierają związki obecne też w rozkładającym się mięsie. Jesienią krzew pokrywa się czerwonymi, mączystymi owocami. Utrzymują się na gałęziach długo w zimę i karmią ptaki, gdy wszystko inne już zniknęło.\n\nKolce, które strzegą: Cierniste krzewy we wszystkich kulturach Słowian miały moc odpędzania zła. Głóg należał do najsilniejszych. Jego gałęzie wtykano w okna i drzwi, kładziono przy oborach i na grobach tych, o których mówiono, że mogą „chodzić” po śmierci. W wielu opowieściach upiora można było unieszkodliwić tylko kołkiem z głogu albo osiki. Na Wyspach Brytyjskich samotny głóg był drzewem wróżek i nikt nie odważył się go wyciąć. Wszędzie powtarza się ta sama myśl: kolce są granicą, a głóg jej strażnikiem.\n\nZiele serca: To jedna z niewielu roślin ludowych, których działanie potwierdziła współczesna farmakologia. Kwiatostany z liśćmi i owoce zawierają flawonoidy i procyjanidyny. Delikatnie wspierają pracę serca i krążenie, a do tego uspokajają. Europejska Agencja Leków uznaje tradycyjne stosowanie głogu przy przejściowych dolegliwościach sercowych na tle nerwowym i przy łagodnym niepokoju. Głóg działa powoli: efekt pojawia się po kilku tygodniach regularnego picia, a nie po jednej filiżance.\n\nW kuchni: Owoce są mączyste i lekko słodkie, więc w dawnych przednówkach suszono je i mielono jako dodatek do mąki. Dziś robi się z nich konfiturę, syrop, ocet albo nalewkę, najlepiej po pierwszych przymrozkach, kiedy zmiękną. Pestki są twarde jak kamień, więc owoce trzeba przetrzeć przez sito. Herbata z suszonych owoców ma ciepły, różowy kolor i łagodny smak. To dobre towarzystwo na listopadowe wieczory.\n\nLekcja głogu: Głóg potrafi żyć kilkaset lat. Rośnie wolno, ma twarde drewno, kłuje i nikogo za to nie przeprasza. A jednak to właśnie on leczy serce. Jest w tym coś bardzo ludzkiego: delikatność często mieszka za kolcami. Głóg nie pyta, czy granica komuś się podoba. Po prostu ją trzyma i dzięki temu w środku może być bezpiecznie i spokojnie.","caution":"Przy lekach nasercowych, na ciśnienie lub na arytmię głóg tylko po konsultacji z lekarzem, bo może nasilać ich działanie. Kołatanie serca, ból w klatce piersiowej albo duszność wymagają pilnej diagnozy, nie ziół.","quote":"Serce, które ma kolce, nie zawsze jest złe. Czasem po prostu się broni.","bibliography":"Monografia EMA Crataegi folium cum flore; K. Moszyński, Kultura ludowa Słowian; „Drzewa i krzewy w kulturze ludowej”, IZPiTN 2026."},"2026-11-29":{"title":"Andrzejki","subtitle":"noc, w której wosk mówi kształtem","text":"Najdłuższa noc dla panien: Wigilia świętego Andrzeja, z 29 na 30 listopada, była wieczorem wróżb matrymonialnych dla dziewcząt. Chłopcy mieli swój wieczór kilka dni wcześniej, na świętą Katarzynę. Andrzejki zamykały rok obrzędowy przed Adwentem, czyli przed czasem ciszy, w którym nie urządzano zabaw ani wesel. To był ostatni głośny wieczór, ostatnia okazja do śmiechu i zajrzenia za zasłonę przyszłości. Jedna z najstarszych polskich wzmianek o laniu wosku pochodzi już z połowy XVI wieku.\n\nWosk i cień: Gorący wosk przelewa się przez ucho dużego klucza do miski z zimną wodą. Klucz otwiera drogę i zamyka to, co złe. Wosk zastyga w figurę. Ogląda się ją dwa razy: najpierw w dłoni, potem jej cień rzucony świecą na ścianę. Z cienia czytano zawód przyszłego męża, czyli łódź, konia, kłos albo pierścień. Najciekawsze jest to, że figura nic nie znaczy sama z siebie. To my nadajemy jej sens. Wróżba z wosku działa jak lustro pragnień, a nie jak przepowiednia.\n\nInne wróżby tej nocy: Dziewczęta ustawiały buty jeden za drugim od ściany do progu. Ta, której but pierwszy przekroczył drzwi, pierwsza miała wyjść za mąż. Obierkę jabłka rzucało się przez ramię, a jej kształt układał się w literę imienia. Liczyło się sztachety w płocie, „wdowiec, kawaler, wdowiec, kawaler”, aż do ostatniej. Pod poduszkę wkładało się kartki z imionami i rano wyciągało jedną. Na podłodze kładziono placki, a pies, który zjadł pierwszy, wskazywał przyszłą pannę młodą. Nasłuchiwano też pod oknami, bo pierwsze usłyszane imię miało być imieniem narzeczonego.\n\nŚwięty Andrzej: Apostoł Andrzej, brat Piotra, był rybakiem znad Jeziora Galilejskiego i według tradycji zginął na krzyżu w kształcie litery X. Jest patronem rybaków, Szkocji i Rusi. Do wróżb matrymonialnych trafił prawdopodobnie przypadkiem kalendarza, bo jego dzień wypadał tuż przed Adwentem. Dziewczęta prosiły go wprost: „Święty Andrzeju, daj mi znać, co mi się w przyszłości ma stać”.\n\nJak wróżyć dziś: Andrzejki nie muszą dotyczyć męża. Zadaj woskowi pytanie, które naprawdę cię zajmuje: o pracę, o zmianę, o rok, który nadchodzi. Zanim spojrzysz na figurę, zapisz pytanie. Potem zapisz pierwsze skojarzenie, zanim zacznie je tłumaczyć rozum. Tak powstaje rzetelna notatka o tym, czego pragniesz, a nie przepowiednia. Przeczytaj ją za rok, w kolejne Andrzejki. Wosk pokazuje kształt, a znaczenie nadajesz mu sama.","caution":"Wosk lej powoli, nad miską z wodą, z dala od dzieci i łatwopalnych tkanin. Klucz chwytaj szczypcami albo przez rękawicę, bo szybko się nagrzewa.","quote":"Święty Andrzeju, daj mi znać, co mi się w przyszłości ma stać.","bibliography":"Z. Gloger, Rok polski w życiu, tradycji i pieśni; O. Kolberg, Lud; M. Bielski, Komedyja Justyna i Konstancyjej (1557)."},"2026-12-04":{"title":"Gałązki świętej Barbary","subtitle":"kwiat wyhodowany w środku zimy","text":"Święta od ognia i ziemi: Barbara, według legendy męczennica z III wieku zamknięta przez ojca w wieży, jest patronką górników, hutników, artylerzystów i dobrej śmierci. Do niej modlili się ci, którzy pracowali w ciemności, pod ziemią albo przy ogniu. Na Śląsku i w Zagłębiu Barbórka do dziś jest wielkim świętem kopalń: z mszą, orkiestrą i karczmą piwną. Barbara jest jednak także świętą wiejskich izb. Jej dzień otwierał grudniowe czekanie na światło.\n\nGałązka, która zakwita na Wigilię: Czwartego grudnia ścina się gałązkę wiśni, czasem czereśni, jabłoni albo lipy, i wstawia ją do wody w ciepłym kącie izby. Jeśli zakwitnie na Wigilię, to dobry znak: urodzaj, zdrowie, a dla panny ślub w nadchodzącym roku. W niektórych domach każdy domownik miał swoją gałązkę, a pierwsza, która zakwitła, wskazywała szczęściarza. Białe kwiaty przy wigilijnym stole to symbol bardzo prosty i bardzo mocny: życie trwa, nawet gdy świat zamarza.\n\nDlaczego to działa: To nie cud, tylko botanika. Ludzie znali ją jednak na długo przed tym, zanim nazwali ją po imieniu. Pąki drzew owocowych potrzebują okresu chłodu, żeby wyjść ze spoczynku. Kilka tygodni temperatur bliskich zera przestawia w nich zegar. Gdy po takiej „zimie” trafią do ciepła i wody, uznają, że nadeszła wiosna. Około trzech tygodni to akurat czas od Barbary do Wigilii. Ludowy kalendarz był bardzo dokładnym kalendarzem przyrody.\n\nJak to zrobić: Wybierz gałązki z wieloma grubymi, okrągłymi pąkami. Pąki kwiatowe są pękatsze od liściowych. Jeśli jesień była ciepła i nie było mrozu, połóż gałązki na noc w chłodnym miejscu albo zanurz je na kilka godzin w zimnej wodzie. Potem zetnij je ukośnie ostrym nożem, rozgnieć lekko końcówki i wstaw do letniej wody. Co kilka dni podcinaj je i zmieniaj wodę. Spryskuj pąki, bo w ogrzewanym mieszkaniu powietrze jest suche. Postaw je w jasnym miejscu, ale nie przy kaloryferze.\n\nPogoda według Barbary: Barbara była też dniem obserwacji nieba. Mówiono: „Barbórka po lodzie, Boże Narodzenie po wodzie”. Mróz na Barbarę miał wróżyć odwilż w święta, a odwilż na Barbarę mróz na Gody. Takie przysłowia nie są prognozą w dzisiejszym sensie. Są zapisem pokoleń patrzenia w niebo, a w nich bywa więcej trafności, niż się wydaje.","caution":"","quote":"Barbórka po lodzie, Boże Narodzenie po wodzie.","bibliography":"Z. Gloger, Rok polski w życiu, tradycji i pieśni; O. Kolberg, Lud; „Kalendarz obrzędowy”, IZPiTN 2026."},"2026-12-10":{"title":"Mak","subtitle":"Papaver somniferum L. · ziarno snu i pamięci","text":"Roślina snu: Mak lekarski uprawiano w Polsce od wieków na ziarno i olej. Jego łacińska nazwa gatunkowa, somniferum, znaczy „przynoszący sen”. Starożytni Grecy przedstawiali boga snu Hypnosa i jego brata Tanatosa, czyli śmierć, z makówkami w dłoniach. Mak stoi na granicy snu i śmierci, odpoczynku i zapomnienia. To ta sama granica, którą w grudniowe noce przekraczały według wierzeń dusze zmarłych.\n\nUpiór, który musi liczyć: Wierzenie o upiorach jest jednym z najbardziej osobliwych w kulturze Słowian. Upiór, czyli zmarły, który nie zaznał spokoju, nie może przejść obok rozsypanych ziaren maku, dopóki ich nie policzy. Dlatego mak sypano do trumny, na grób, wokół domu i na progu. Liczenie trwało całą noc. Przychodził świt, piał kogut i upiór musiał wracać do grobu. W tej opowieści jest coś przejmującego: zła nie pokonuje się siłą, tylko je zajmuje, zatrzymuje i przeczekuje.\n\nMak na wigilijnym stole: Kutia, makowiec, kluski albo łamańce z makiem: Wigilia bez maku prawie nie istnieje. Ma to podwójny sens. Mak to ziarno niezliczone, więc obiecuje obfitość i dostatek na tyle lat, ile było ziarenek. Mak to także pokarm zmarłych. W wigilijny wieczór, gdy przodkowie odwiedzali dom, potrawy z makiem były dla nich zarówno ugoszczeniem, jak i ochroną dla żywych. Na wschodzie kutię stawiano dla dusz na noc na stole albo na parapecie.\n\nDawna przestroga: Mak ma też ciemną stronę, o której warto pamiętać. W dawnych domach płaczącym niemowlętom dawano „makowe mleczko” albo smoczek z utartym makiem, żeby spały. Zdarzało się, że dzieci już się nie budziły. Mleczny sok niedojrzałych makówek zawiera alkaloidy opium. Ziarno spożywcze jest bezpieczne, ale wywary z makówek to trucizna, a nie domowy środek na sen.\n\nMedytacja maku: Weź łyżeczkę maku i spróbuj policzyć ziarenka. Po minucie zrozumiesz, dlaczego upiór nie miał szans przed świtem. Potem zadaj sobie pytanie: co w twoim życiu zajmuje myśli jak liczenie maku? Jakie natrętne, drobne sprawy zatrzymują cię w progu i nie pozwalają pójść dalej? Czasem najlepszą obroną nie jest walka, tylko pozwolenie, żeby świt przyszedł sam.","caution":"Nie przygotowuj naparów ani wywarów z makówek. Zawierają morfinę i inne alkaloidy, są szczególnie groźne dla dzieci i mogą prowadzić do zatrucia. Ziarno spożywcze kupione w sklepie jest bezpieczne w zwykłych ilościach.","quote":"Nie każdy, kto puka w nocy, ma cierpliwość, by liczyć mak.","bibliography":"K. Moszyński, Kultura ludowa Słowian; O. Kolberg, Lud; Z. Gloger, Encyklopedia staropolska."},"2026-12-13":{"title":"Święta Łucja","subtitle":"dawna najdłuższa noc i dwanaście dni przepowiedni","text":"Najkrótszy dzień, który przestał nim być: Przysłowie mówi: „Święta Łucja dnia przyrzuca”. Dla nas brzmi to dziwnie, bo do przesilenia zostało jeszcze osiem dni. Ale przysłowie jest starsze niż nasz kalendarz. W kalendarzu juliańskim, używanym do 1582 roku, daty przesuwały się względem słońca. W średniowieczu 13 grudnia wypadał właśnie w okolicach przesilenia. Łucja, której imię pochodzi od łacińskiego lux, czyli światło, była więc świętą najdłuższej nocy i powrotu dnia. Reforma kalendarza przesunęła daty, a pamięć ludowa przechowała dawne niebo.\n\nNoc czarownic: Noc przed Łucją należała do mocy ciemności. Wierzono, że czarownice mogą wtedy odbierać krowom mleko, a ludziom zdrowie. Zamykano więc obory, smarowano drzwi czosnkiem i kreślono na nich krzyżyki. W krajach naszych sąsiadów, na Węgrzech i Słowacji, od Łucji do Wigilii robiono „stołek Łucji” z wielu rodzajów drewna, po kawałku dziennie. Kto stanął na nim podczas pasterki, mógł zobaczyć, kto w parafii jest czarownicą. Musiał jednak potem uciekać do domu i rozsypywać za sobą mak.\n\nDwanaście dni przepowiedni: Od Łucji do Wigilii jest dwanaście dni. Każdy z nich miał zapowiadać pogodę jednego miesiąca nowego roku: 13 grudnia styczeń, 14 grudnia luty i tak dalej aż do Wigilii, która odpowiadała grudniowi. Gospodarze zapisywali to kredą na belce albo węglem na ścianie. Podobnie odczytywano też dwanaście dni od Bożego Narodzenia do Trzech Króli. Cały ten czas był jedną długą przepowiednią.\n\nŁucja w koronie świec: W Szwecji Łucja jest dziś świętem światła. O świcie najstarsza córka w białej sukni i wieńcu z płonącymi świecami budzi domowników kawą i szafranowymi bułeczkami. U nas ta tradycja nie istniała, ale sens jest wspólny: w najciemniejszym czasie roku kobieta przynosi światło. Łucja jest też patronką oczu i wzroku. Modlono się do niej o zdrowe oczy i jasne widzenie, dosłownie i w przenośni.\n\nTwój dziennik dwunastu dni: Zacznij dziś krótki zeszyt. Przez dwanaście wieczorów zapisuj jedno zdanie o pogodzie i jedno o sobie: jak się czułaś, co cię zaskoczyło, co chciałabyś zabrać w nowy rok. W Wigilię przeczytaj całość. Może nie dowiesz się, czy maj będzie deszczowy, ale zobaczysz, co naprawdę zajmowało cię w ostatnich dniach roku. To bardzo dokładna przepowiednia.","caution":"","quote":"Święta Łucja dnia przyrzuca.","bibliography":"Z. Gloger, Rok polski w życiu, tradycji i pieśni; O. Kolberg, Lud; K. Moszyński, Kultura ludowa Słowian."},"2026-12-21":{"title":"Przesilenie zimowe","subtitle":"słońce stoi, a potem wraca","text":"Co dzieje się na niebie: Dziś o 21:50 Słońce osiąga najniższy punkt swojej rocznej drogi. Łacińskie solstitium znaczy dosłownie „słońce stoi”. Przez kilka dni punkty wschodu i zachodu na horyzoncie prawie się nie przesuwają, jakby Słońce zatrzymało się przed powrotem. We Wrocławiu dzień trwa dziś niecałe 7 godzin 53 minuty. Ciekawostka dla uważnych: najwcześniejszy zachód słońca był już około 13 grudnia, a najpóźniejszy wschód przyjdzie dopiero na przełomie roku. Dlatego wieczory zaczynają się wydłużać szybciej niż poranki.\n\nGody: Dawna polska nazwa Bożego Narodzenia to Gody, a czas od Wigilii do Trzech Króli nazywano Szczodrymi Godami. Słowo znaczyło pierwotnie „właściwy czas, pora”. Badacze od dawna spierają się, ile w polskich obrzędach świątecznych zostało z przedchrześcijańskich obchodów przesilenia. Pewne jest jedno: wiele zwyczajów tego okresu kręci się wokół ognia, światła, zmarłych przodków i wróżenia o urodzaju. Kościół ustanowił święto narodzin Chrystusa właśnie wtedy, gdy słońce zaczyna rosnąć.\n\nOgień w najdłuższą noc: W całej Europie ten czas witano ogniem. Na południu palono wielką kłodę, która miała tlić się przez święta. Jej popiół sypano potem na pola i przechowywano jako ochronę przed piorunem. W polskich domach w te dni nie wygaszano ognia w piecu, a żaru nie pożyczano sąsiadom. Ogień był sprzymierzeńcem słońca: podtrzymywał światło, kiedy słońce było najsłabsze.\n\nCzas zatrzymania: Przesilenie to dobry moment, żeby przestać się spieszyć. Natura nie przyspiesza w grudniu. Drzewa stoją, ziemia odpoczywa, nasiona czekają pod śniegiem. Najdłuższa noc nie jest porażką światła, tylko punktem zwrotnym. Od tej chwili każdy dzień jest odrobinę dłuższy, choć przez pierwsze tygodnie prawie tego nie widać. Tak bywa też z ważnymi zmianami w życiu: zaczynają się po cichu, długo przed tym, zanim stają się widoczne.\n\nRytuał na dziś: O zachodzie słońca zgaś wszystkie światła. Posiedź dziesięć minut w ciemności, bez telefonu. Zauważ, czego się boisz, co cię uspokaja, za czym tęsknisz. Potem zapal jedną świecę w oknie i zapisz jedną rzecz, którą chcesz wnieść w jaśniejszą połowę roku. Jedną, nie dziesięć. Słońce też wraca powoli, po minucie dziennie.","caution":"Świecę w oknie zostawiaj tylko pod nadzorem i z dala od firan.","quote":"Najdłuższa noc zawsze kończy się świtem. Taki jest porządek świata.","bibliography":"Dane astronomiczne 2026 (obliczenia dla Wrocławia); Z. Gloger, Rok polski w życiu, tradycji i pieśni; K. Moszyński, Kultura ludowa Słowian."},"2026-12-24":{"title":"Wigilia","subtitle":"noc, w której mówią zwierzęta","text":"Wieczór na granicy światów: Wigilia nie była dawniej tylko rodzinną kolacją. Była najważniejszym wieczorem w roku, na styku starego i nowego, żywych i umarłych. Wszystko, co działo się tego dnia, zapowiadało cały rok. Dlatego wstawano wcześnie, nie kłócono się, niczego nie pożyczano i starano się, by pierwszy gość był mężczyzną, bo to wróżyło szczęście. Wigilia była rodzajem modlitwy całym dniem.\n\nSiano, snop i puste miejsce: Pod obrus kładziono siano na pamiątkę żłobu, ale też na urodzaj. Po kolacji każdy wyciągał źdźbło. Długie i zielone wróżyło długie życie lub ślub, krótkie i zwiędłe chorobę albo samotność. W kącie izby stawiano snop zboża, w różnych regionach nazywany królem albo Godami. Później zastąpiła go zawieszona u powały podłaźniczka, a potem choinka. Pusty talerz czekał na zbłąkanego wędrowca, ale w starszym rozumieniu przede wszystkim na dusze zmarłych. Dlatego przed siadaniem lekko dmuchano na ławę, by nie usiąść na niewidzialnym gościu.\n\nOpłatek dla zwierząt: Po wieczerzy gospodarz szedł do obory z kolorowym opłatkiem, różowym, żółtym albo zielonym, i dzielił się nim ze zwierzętami. Były przecież przy narodzinach w stajence. Dostawały też resztki z wigilijnego stołu. Według wierzeń o północy zwierzęta przemawiały ludzkim głosem. Podsłuchiwać ich jednak nie wolno. Opowiadano o gospodarzu, który ukrył się w oborze i usłyszał, jak woły rozmawiają o jego rychłej śmierci. Przed świtem już nie żył.\n\nPełnia nad Wigilią: W tym roku Wigilia wypada w pełnię. To rzadkie spotkanie: pierwsza gwiazda i pełny Księżyc razem nad wieczerzą. W ludowym kalendarzu pełnia oznaczała dojrzałość, spełnienie i pełną spiżarnię. Wigilia w pełnię to dobry czas, by docenić to, co już jest, zamiast liczyć to, czego brakuje.\n\nWigilijna mądrość: Najważniejszym gestem Wigilii jest opłatek, czyli wybaczenie. Dzieli się nim także z tymi, z którymi było trudno, bo nikt nie powinien wchodzić w nowy rok z niezałatwioną urazą. Nie musisz od razu odzyskiwać zerwanych relacji. Wystarczy, że w sobie odłożysz kamień na bok. Pozostaw też miejsce przy stole albo w myślach dla tych, których już nie ma. Ich obecność jest w tradycji wigilijnej tak samo realna jak obecność żywych.","caution":"","quote":"Niektóre cuda dzieją się tylko wtedy, gdy nikt nie podsłuchuje.","bibliography":"Z. Gloger, Rok polski w życiu, tradycji i pieśni; O. Kolberg, Lud; K. Moszyński, Kultura ludowa Słowian."}},"phaseEvents":[{"date":"2026-11-01","kind":"III kwadra","time":"21:28","source":"Księga Yagi"},{"date":"2026-11-09","kind":"nów","time":"08:02","source":"Księga Yagi"},{"date":"2026-11-17","kind":"I kwadra","time":"12:47","source":"Księga Yagi"},{"date":"2026-11-24","kind":"pełnia","time":"15:53","source":"Księga Yagi"},{"date":"2026-12-01","kind":"III kwadra","time":"07:08","source":"Księga Yagi"},{"date":"2026-12-09","kind":"nów","time":"01:52","source":"Księga Yagi"},{"date":"2026-12-17","kind":"I kwadra","time":"06:42","source":"Księga Yagi"},{"date":"2026-12-24","kind":"pełnia","time":"02:28","source":"Księga Yagi"},{"date":"2026-12-30","kind":"III kwadra","time":"19:59","source":"Księga Yagi"},{"date":"2027-01-07","kind":"nów","time":"21:24","source":"Księga Yagi"},{"date":"2027-01-15","kind":"I kwadra","time":"21:34","source":"Księga Yagi"},{"date":"2027-01-22","kind":"pełnia","time":"13:17","source":"Księga Yagi"},{"date":"2027-01-29","kind":"III kwadra","time":"11:55","source":"Księga Yagi"},{"date":"2027-02-06","kind":"nów","time":"16:56","source":"Księga Yagi"},{"date":"2027-02-14","kind":"I kwadra","time":"08:58","source":"Księga Yagi"},{"date":"2027-02-21","kind":"pełnia","time":"00:23","source":"Księga Yagi"},{"date":"2027-02-28","kind":"III kwadra","time":"06:16","source":"Księga Yagi"},{"date":"2027-03-08","kind":"nów","time":"10:29","source":"Księga Yagi"},{"date":"2027-03-15","kind":"I kwadra","time":"17:25","source":"Księga Yagi"},{"date":"2027-03-22","kind":"pełnia","time":"11:43","source":"Księga Yagi"},{"date":"2027-03-30","kind":"III kwadra","time":"02:54","source":"Księga Yagi"},{"date":"2027-04-07","kind":"nów","time":"01:51","source":"Księga Yagi"},{"date":"2027-04-14","kind":"I kwadra","time":"00:56","source":"Księga Yagi"},{"date":"2027-04-21","kind":"pełnia","time":"00:27","source":"Księga Yagi"},{"date":"2027-04-28","kind":"III kwadra","time":"22:18","source":"Księga Yagi"},{"date":"2027-05-06","kind":"nów","time":"12:58","source":"Księga Yagi"},{"date":"2027-05-13","kind":"I kwadra","time":"06:43","source":"Księga Yagi"},{"date":"2027-05-20","kind":"pełnia","time":"12:59","source":"Księga Yagi"},{"date":"2027-05-28","kind":"III kwadra","time":"15:58","source":"Księga Yagi"},{"date":"2027-06-04","kind":"nów","time":"21:40","source":"Księga Yagi"},{"date":"2027-06-11","kind":"I kwadra","time":"12:56","source":"Księga Yagi"},{"date":"2027-06-19","kind":"pełnia","time":"02:44","source":"Księga Yagi"},{"date":"2027-06-27","kind":"III kwadra","time":"06:54","source":"Księga Yagi"},{"date":"2027-07-04","kind":"nów","time":"05:02","source":"Księga Yagi"},{"date":"2027-07-10","kind":"I kwadra","time":"20:39","source":"Księga Yagi"},{"date":"2027-07-18","kind":"pełnia","time":"17:45","source":"Księga Yagi"},{"date":"2027-07-26","kind":"III kwadra","time":"18:55","source":"Księga Yagi"},{"date":"2027-08-02","kind":"nów","time":"12:05","source":"Księga Yagi"},{"date":"2027-08-09","kind":"I kwadra","time":"06:54","source":"Księga Yagi"},{"date":"2027-08-17","kind":"pełnia","time":"09:28","source":"Księga Yagi"},{"date":"2027-08-25","kind":"III kwadra","time":"04:27","source":"Księga Yagi"},{"date":"2027-08-31","kind":"nów","time":"19:41","source":"Księga Yagi"},{"date":"2027-09-07","kind":"I kwadra","time":"20:31","source":"Księga Yagi"},{"date":"2027-09-16","kind":"pełnia","time":"01:03","source":"Księga Yagi"},{"date":"2027-09-23","kind":"III kwadra","time":"12:20","source":"Księga Yagi"},{"date":"2027-09-30","kind":"nów","time":"04:36","source":"Księga Yagi"},{"date":"2027-10-07","kind":"I kwadra","time":"13:47","source":"Księga Yagi"},{"date":"2027-10-15","kind":"pełnia","time":"15:47","source":"Księga Yagi"},{"date":"2027-10-22","kind":"III kwadra","time":"19:29","source":"Księga Yagi"},{"date":"2027-10-29","kind":"nów","time":"15:36","source":"Księga Yagi"},{"date":"2027-11-06","kind":"I kwadra","time":"09:00","source":"Księga Yagi"},{"date":"2027-11-14","kind":"pełnia","time":"04:26","source":"Księga Yagi"},{"date":"2027-11-21","kind":"III kwadra","time":"01:48","source":"Księga Yagi"},{"date":"2027-11-28","kind":"nów","time":"04:24","source":"Księga Yagi"},{"date":"2027-12-06","kind":"I kwadra","time":"06:22","source":"Księga Yagi"},{"date":"2027-12-13","kind":"pełnia","time":"17:09","source":"Księga Yagi"},{"date":"2027-12-20","kind":"III kwadra","time":"10:11","source":"Księga Yagi"},{"date":"2027-12-27","kind":"nów","time":"21:12","source":"Księga Yagi"},{"date":"2028-01-12","kind":"pełnia","time":"05:03","source":"US Naval Observatory"},{"date":"2028-01-26","kind":"nów","time":"16:12","source":"US Naval Observatory"}],"phaseBoundarySource":{"name":"US Naval Observatory","url":"https://aa.usno.navy.mil/calculated/moon/phases?year=2028","timeZone":"Europe/Warsaw","note":"Boundary phases only; daily interpretations remain those of Księga Yagi."}};if(typeof module==='object'&&module.exports)module.exports=data;else root.OktiInspirationData=data;})(globalThis);
